SYNC_OTB_DEVICE = "Syncstation"
SYNC_OTB_SUBTITLE = "AUX 2"
SYNC_OTB_LABEL = "Syncstation AUX 2 [V]"
# Convention as of the 2026-07 recordings: bare "2_Sync"/"3_Sync_50ms" labels
# (no "Voltage." device prefix). OTB4/C3D dedicated sync stays on channel 2;
# a dedicated third channel bridges TSV (biofeedback) recordings to C3D/OTB4.
SYNC_C3D_LABEL = "2_Sync"
SYNC_C3D_TSV_BRIDGE_LABEL = "3_Sync_50ms"
SYNC_TSV_EXACT_SUFFIX = "3_Sync_50ms [Volt] [sync]"
# OTB4-side counterpart of the channel-3 bridge (present on both OTB4 and C3D).
# Channel 2 is generated by the SyncStation itself and looped back to its own
# AUX2 input, so OTB4's channel-2 reading is inherently self-consistent; a
# channel-2 mismatch against C3D points to the separate cable run out to the
# Vicon Lock Lab, not an OTB4-side fault. Channel 3 is generated by a separate
# SyncMini (no loopback on either side) and used as a cross-machine fallback
# when channel 2 cannot be resolved (see _channel3_edge_alignment_fallback).
SYNC_OTB_TSV_BRIDGE_SUBTITLE = "AUX 3"
# Channel 1 is a session-bounds marker (one rising edge at start, one falling
# edge at end), not a pulse train like channels 2/3. It is diagnostic-only:
# used to log/sanity-check overall session bounds, never to gate matching.
SYNC_OTB_TTL_SUBTITLE = "AUX 1"
SYNC_C3D_TTL_LABEL = "1_TTL"
SYNC_TSV_TTL_SUFFIX = "1_TTL [Volt] [sync]"
TSV_RAW_SUFFIX = "[raw]"
_OTB4_PROBE_DIAG_CACHE: Dict[str, Dict[str, Any]] = {}
TRIPLET_SEED_LIMIT = 3

_SYNC_CHANNEL_DEFAULTS: Dict[str, str] = {
    "SYNC_OTB_DEVICE": SYNC_OTB_DEVICE,
    "SYNC_OTB_SUBTITLE": SYNC_OTB_SUBTITLE,
    "SYNC_OTB_LABEL": SYNC_OTB_LABEL,
    "SYNC_C3D_LABEL": SYNC_C3D_LABEL,
    "SYNC_C3D_TSV_BRIDGE_LABEL": SYNC_C3D_TSV_BRIDGE_LABEL,
    "SYNC_TSV_EXACT_SUFFIX": SYNC_TSV_EXACT_SUFFIX,
}


def _apply_sync_channel_overrides(match_options: Optional[Dict[str, Any]]) -> None:
    """Reassign the module-level sync-channel-name constants for this scan
    from a confirmed channel map (see `_resolve_sync_channel_roles` and
    match_files.py's Sync Channel Setup dialog, under
    `match_options["sync_channel_map"]`).

    Every function in this module that resolves a sync channel by name
    (`_extract_otb4_record`, `_extract_c3d_record`, `_extract_tsv_record`,
    `_read_otb4_scan_info`, the TSV-bridge lookups, and the MAT-export
    channel matching) reads these as bare module globals rather than
    receiving them as parameters, so reassigning them here once, before any
    extraction runs, is sufficient to make every one of those call sites
    respect a confirmed override -- without threading a parameter through
    ~30 call sites across the file.

    Always runs at the top of `analyze_folder`, unconditionally: with no
    override present it resets to today's hardcoded defaults, so results
    never depend on what a *previous* scan (of a different folder, with a
    different confirmed mapping) happened to leave configured. This is the
    single point where that global state is allowed to change.
    """
    global SYNC_OTB_DEVICE, SYNC_OTB_SUBTITLE, SYNC_OTB_LABEL
    global SYNC_C3D_LABEL, SYNC_C3D_TSV_BRIDGE_LABEL, SYNC_TSV_EXACT_SUFFIX

    channel_map = (match_options or {}).get("sync_channel_map") or {}
    otb4_c3d = channel_map.get("otb4_c3d_sync") or {}
    bridge = channel_map.get("tsv_bridge_sync") or {}

    if otb4_c3d.get("otb4_device") and otb4_c3d.get("otb4_subtitle"):
        SYNC_OTB_DEVICE = str(otb4_c3d["otb4_device"])
        SYNC_OTB_SUBTITLE = str(otb4_c3d["otb4_subtitle"])
        SYNC_OTB_LABEL = f"{SYNC_OTB_DEVICE} {SYNC_OTB_SUBTITLE} [V]"
    else:
        SYNC_OTB_DEVICE = _SYNC_CHANNEL_DEFAULTS["SYNC_OTB_DEVICE"]
        SYNC_OTB_SUBTITLE = _SYNC_CHANNEL_DEFAULTS["SYNC_OTB_SUBTITLE"]
        SYNC_OTB_LABEL = _SYNC_CHANNEL_DEFAULTS["SYNC_OTB_LABEL"]

    SYNC_C3D_LABEL = str(otb4_c3d.get("c3d_label") or _SYNC_CHANNEL_DEFAULTS["SYNC_C3D_LABEL"])

    if bridge.get("c3d_label"):
        SYNC_C3D_TSV_BRIDGE_LABEL = str(bridge["c3d_label"])
        # TSV's own column always carries this same fixed template appended
        # to the underlying channel name (established by the existing
        # "3_Sync_50ms [Volt] [sync]" convention) -- derive rather than
        # require a raw TSV column name to be threaded through separately.
        SYNC_TSV_EXACT_SUFFIX = f"{SYNC_C3D_TSV_BRIDGE_LABEL} [Volt] [sync]"
    else:
        SYNC_C3D_TSV_BRIDGE_LABEL = _SYNC_CHANNEL_DEFAULTS["SYNC_C3D_TSV_BRIDGE_LABEL"]
        SYNC_TSV_EXACT_SUFFIX = _SYNC_CHANNEL_DEFAULTS["SYNC_TSV_EXACT_SUFFIX"]


# Shared network location where the BiofeedbackUI application keeps its
# traceBio corridor/path TSV files (referenced by a recording's settings
# JSON via "SelectedPath"). These are protocol-level files reused across
# sessions, not per-session artifacts, so this fixed root is tried before
# falling back to the reactive per-match "browse for it" prompt.
TRACEBIO_PATHS_ROOT_DEFAULT = r"U:\Data_HP\BiofeedbackUi\BiofeedbackUI_latest\paths"
TRACEBIO_PATHS_ROOT: str = TRACEBIO_PATHS_ROOT_DEFAULT


def _apply_tracebio_paths_root_override(match_options: Optional[Dict[str, Any]]) -> None:
    """Reassign the module-level traceBio paths-folder root, mirroring
    `_apply_sync_channel_overrides`. Set from `match_options["tracebio_paths_root"]`
    (confirmed at startup by match_files.py's picker, only shown when the
    default network location isn't reachable) or reset to the hardcoded
    default. Must also be called directly from match_files.py's `main()`,
    not only from `analyze_folder`, because a reused cached scan skips
    `analyze_folder` entirely but still needs this for later traceBio export/
    review-time file resolution in the same process.
    """
    global TRACEBIO_PATHS_ROOT
    override = (match_options or {}).get("tracebio_paths_root")
    TRACEBIO_PATHS_ROOT = str(override) if override else TRACEBIO_PATHS_ROOT_DEFAULT


def _otb4_probe_diag_cache_key(path: str, step_sec: Optional[float] = None) -> str:
    suffix = "auto" if step_sec in (None, "") else f"{float(step_sec):.6f}"
    return f"{path}|step={suffix}"


def _track_prefers_voltage_units(track: Dict[str, Any]) -> bool:
    device = str(track.get("Device", "")).strip().lower()
    subtitle = str(track.get("SubTitle", "")).strip().lower()
    desc_name = str(track.get("DescriptionName", "")).strip().lower()
    sensor_type = str(track.get("SensorType", "")).strip().lower()
    if device == "syncstation" and subtitle.startswith("aux"):
        return True
    if "trigger" in desc_name:
        return True
    if "auxtrigger" in sensor_type:
        return True
    return False


def _track_base_conversion(track: Dict[str, Any]) -> float:
    nbits = int(track.get("ADC_Nbits", 0) or 0)
    gain = float(track.get("Gain", 1) or 1.0)
    adc_range = float(track.get("ADC_Range", 0) or 0.0)
    if nbits <= 0 or gain == 0:
        return 1.0
    return adc_range / (2 ** nbits) / gain


def _track_is_emg_grid(track: Dict[str, Any]) -> bool:
    grid_info = track.get("GridInfo") or {}
    ied = int(grid_info.get("IED", 0) or 0)
    electrodes = int(track.get("NumberOfChannels", 0) or 0)
    if bool(track.get("IsControl")):
        return False
    if str(track.get("Device", "")).strip().lower() == "syncstation":
        return False
    return ied > 1 or electrodes > 4


def _track_conversion_factor(track: Dict[str, Any]) -> float:
    conv = _track_base_conversion(track)
    if _track_prefers_voltage_units(track):
        return conv
    if _track_is_emg_grid(track):
        return conv * 1000.0
    return conv


def _track_label_prefix(track: Dict[str, Any]) -> str:
    device = str(track.get("Device", "")).strip()
    subtitle = str(track.get("SubTitle", "")).strip()
    desc_name = str(track.get("DescriptionName", "")).strip()
    muscle = track.get("Muscle")
    grid_info = track.get("GridInfo")
    if _track_is_emg_grid(track) and grid_info:
        ied = int(grid_info["IED"])
        rows = int(grid_info["NRow"])
        cols = int(grid_info["NColumn"])
        grid_pattern = f"HD{ied:02d}MM{rows:02d}{cols:02d}"
        base = f"{subtitle or device} {grid_pattern}".strip()
        if muscle:
            base += f" [MUSCLE:{muscle}]"
        return base
    parts = [part for part in (device, subtitle or desc_name) if part]
    return " ".join(parts).strip() or "Unknown"


def _track_display_unit(track: Dict[str, Any]) -> Optional[str]:
    if _track_prefers_voltage_units(track):
        return "V"
    return None


def _build_track_descriptions(track: Dict[str, Any]) -> List[str]:
    nchan = int(track.get("NumberOfChannels", 0) or 0)
    prefix = _track_label_prefix(track)
    unit = _track_display_unit(track)
    labels: List[str] = []
    for idx in range(nchan):
        label = f"{prefix} ch{idx + 1}" if nchan > 1 else prefix
        if unit:
            label += f" [{unit}]"
        labels.append(label)
    return labels


def _now_iso() -> str:
    return datetime.now().isoformat(timespec="seconds")


def _parse_timestamp_from_name(path: Path) -> Optional[datetime]:
    m = re.search(r"_(\d{8})_(\d{6})", path.stem)
    if not m:
        return None
    try:
        return datetime.strptime(m.group(1) + m.group(2), "%Y%m%d%H%M%S")
    except Exception:
        return None


def _file_numeric_index(path_or_text: Any) -> Optional[int]:
    stem = Path(str(path_or_text or "")).stem
    m = re.match(r"file[_-]?0*(\d+)(?:_|$)", stem, flags=re.IGNORECASE)
    if m:
        try:
            return int(m.group(1))
        except Exception:
            return None
    return None


def _c3d_setting_number(path_or_text: Any) -> Optional[int]:
    """Trial number embedded in a Vicon C3D filename, e.g. Setting_12.c3d -> 12.

    Distinct from _file_numeric_index (which only recognizes the OTB4/TSV
    "File_" naming convention): C3D files here use "Setting_NN", and its
    number corresponds 1:1 with the TSV "File_0NN" number -- it does NOT
    correspond to the OTB4 "File_NN" number (OTB4 and C3D numbering run
    independently; e.g. OTB4 File_02 pairs with C3D Setting_01).
    """
    stem = Path(str(path_or_text or "")).stem
    m = re.search(r"setting[_-]?0*(\d+)(?:_|$)", stem, flags=re.IGNORECASE)
    if m:
        try:
            return int(m.group(1))
        except Exception:
            return None
    return None


# Old OTB4 naming convention with no number field between "File" and the
# capture timestamp, e.g. "File__20260707_143120_451.otb4" (double
# underscore). Current convention inserts a sequence number there, e.g.
# "File_12_20260707_143120_451.otb4".
_OTB4_UNNUMBERED_RE = re.compile(r"^(File)__(\d{8}_\d{6}.*)$")


def _otb4_unnumbered_files(paths: Sequence[Path]) -> List[Path]:
    return [p for p in paths if _OTB4_UNNUMBERED_RE.match(p.stem)]


def _otb4_autonumber_plan(paths: Sequence[Path]) -> List[Tuple[Path, Path]]:
    """Chronological (by parsed capture timestamp) 2-digit renumbering plan
    for OTB4 files still in the old unnumbered "File__TIMESTAMP..." format
    -- e.g. File__20260707_143120_451.otb4 -> File_01_20260707_143120_451.otb4.
    Only ever includes files matching that exact old pattern; already
    numbered files are left untouched. This never renames anything itself
    -- see _apply_otb4_autonumber -- and is not used by the matcher, which
    never depends on filename numbers; it's purely for the file list to be
    easier to cross-reference by eye against C3D/TSV filenames.
    """
    candidates = _otb4_unnumbered_files(paths)

    def _sort_key(p: Path) -> Tuple[bool, datetime, str]:
        ts = _parse_timestamp_from_name(p)
        return (ts is None, ts or datetime.min, p.name)

    ordered = sorted(candidates, key=_sort_key)
    plan: List[Tuple[Path, Path]] = []
    for idx, path in enumerate(ordered, start=1):
        m = _OTB4_UNNUMBERED_RE.match(path.stem)
        if not m:
            continue
        new_stem = f"{m.group(1)}_{idx:02d}_{m.group(2)}"
        plan.append((path, path.with_name(new_stem + path.suffix)))
    return plan


def _apply_otb4_autonumber(plan: Sequence[Tuple[Path, Path]]) -> List[str]:
    """Executes a rename plan from _otb4_autonumber_plan. Skips (and
    reports) any rename whose destination already exists rather than
    overwriting -- this touches real capture data on a shared drive, so
    silently clobbering an existing file is not acceptable.
    """
    messages: List[str] = []
    for old_path, new_path in plan:
        if new_path.exists():
            messages.append(f"Skipped {old_path.name} -> {new_path.name}: destination already exists.")
            continue
        try:
            old_path.rename(new_path)
            messages.append(f"Renamed {old_path.name} -> {new_path.name}")
        except Exception as exc:
            messages.append(f"Failed to rename {old_path.name} -> {new_path.name}: {exc}")
    return messages


def _filename_clock_offset_sec(path: Path) -> Optional[float]:
    ts = _parse_timestamp_from_name(path)
    if ts is None:
        return None
    try:
        return float(path.stat().st_mtime - ts.timestamp())
    except Exception:
        return None


def _extract_otb4_tracks(path: Path) -> Tuple[Path, List[Dict[str, Any]]]:
    tmpdir = Path(tempfile.mkdtemp(prefix="otb4_sync_"))
    try:
        if tarfile.is_tarfile(path):
            with tarfile.open(path, "r") as handle:
                handle.extractall(path=tmpdir)
        elif zipfile.is_zipfile(path):
            with zipfile.ZipFile(path, "r") as handle:
                handle.extractall(path=tmpdir)
        else:
            raise ValueError(f"Unrecognized OTB4 archive format: {path}")
        tracks = parse_otb4_tracks_xml(str(tmpdir / "Tracks_000.xml"))
        return tmpdir, tracks
    except Exception:
        shutil.rmtree(tmpdir, ignore_errors=True)
        raise


def _release_otb4_tmpdir(tmpdir: Path) -> None:
    shutil.rmtree(tmpdir, ignore_errors=True)


def _otb4_track_offsets(tracks: Sequence[Dict[str, Any]], signal_path: str) -> List[Tuple[int, Dict[str, Any]]]:
    offsets: List[Tuple[int, Dict[str, Any]]] = []
    running = 0
    for track in tracks:
        if track["SignalStreamPath"] == signal_path:
            offsets.append((running, track))
            running += int(track["NumberOfChannels"])
    return offsets


def _load_otb4_aux_channel(path: Path, *, device: str, subtitle: str) -> Tuple[np.ndarray, np.ndarray, Dict[str, Any]]:
    tmpdir, tracks = _extract_otb4_tracks(path)
    try:
        target = next(
            (
                track
                for track in tracks
                if str(track.get("Device")) == device and str(track.get("SubTitle")) == subtitle
            ),
            None,
        )
        if target is None:
            raise ValueError(f"Missing OTB4 track {device} {subtitle}")

        signal_path = str(target["SignalStreamPath"])
        offsets = _otb4_track_offsets(tracks, signal_path)
        target_offset = next((offset for offset, track in offsets if track is target), None)
        if target_offset is None:
            raise ValueError(f"Unable to locate track offset for {device} {subtitle}")

        sig_file = tmpdir / signal_path
        raw = np.fromfile(sig_file, dtype=np.int16)
        total_channels = sum(int(track["NumberOfChannels"]) for _offset, track in offsets)
        if total_channels <= 0 or raw.size % total_channels != 0:
            raise ValueError(f"Invalid OTB4 signal layout for {signal_path}")
        samples = raw.size // total_channels
        data = raw.reshape((total_channels, samples), order="F").astype(np.float64)

        bits = int(target["ADC_Nbits"])
        gain = float(target["Gain"])
        adc_range = float(target["ADC_Range"])
        conv_v = adc_range / (2 ** bits) / gain if bits > 0 and gain != 0 else 1.0
        x = data[target_offset, :] * conv_v
        fs = float(target["SamplingFrequency"])
        t = np.arange(len(x), dtype=float) / fs
        meta = {
            "label": SYNC_OTB_LABEL,
            "sampling_frequency": fs,
            "device": device,
            "subtitle": subtitle,
            "conversion_v_per_count": conv_v,
            "signal_path": signal_path,
            "channel_offset": target_offset,
        }
        return t, x, meta
    finally:
        _release_otb4_tmpdir(tmpdir)


def _read_otb4_scan_info(path: Path) -> Tuple[np.ndarray, Dict[str, Any], List[str]]:
    tmpdir, tracks = _extract_otb4_tracks(path)
    try:
        labels: List[str] = []
        for track in tracks:
            labels.extend(_build_track_descriptions(track))
        target = next(
            (
                track
                for track in tracks
                if str(track.get("Device")) == SYNC_OTB_DEVICE and str(track.get("SubTitle")) == SYNC_OTB_SUBTITLE
            ),
            None,
        )
        if target is None:
            raise ValueError(f"Missing OTB4 track {SYNC_OTB_DEVICE} {SYNC_OTB_SUBTITLE}")
        signal_path = str(target["SignalStreamPath"])
        offsets = _otb4_track_offsets(tracks, signal_path)
        target_offset = next((offset for offset, track in offsets if track is target), None)
        if target_offset is None:
            raise ValueError(f"Unable to locate track offset for {SYNC_OTB_DEVICE} {SYNC_OTB_SUBTITLE}")
        sig_file = tmpdir / signal_path
        raw = np.fromfile(sig_file, dtype=np.int16)
        total_channels = sum(int(track["NumberOfChannels"]) for _offset, track in offsets)
        if total_channels <= 0 or raw.size % total_channels != 0:
            raise ValueError(f"Invalid OTB4 signal layout for {signal_path}")
        samples = raw.size // total_channels
        data = raw.reshape((total_channels, samples), order="F").astype(np.float64)
        x = data[target_offset, :] * float(_track_conversion_factor(target))
        fs = float(target["SamplingFrequency"])
        meta = {
            "label": SYNC_OTB_LABEL,
            "sampling_frequency": fs,
            "device": SYNC_OTB_DEVICE,
            "subtitle": SYNC_OTB_SUBTITLE,
            "signal_path": signal_path,
            "channel_offset": target_offset,
        }
        return np.asarray(x, dtype=float).reshape(-1), meta, labels
    finally:
        _release_otb4_tmpdir(tmpdir)


def _to_ascending_ramp(ramp: np.ndarray) -> np.ndarray:
    ramp = np.asarray(ramp, dtype=np.int64).reshape(-1)
    if ramp.size == 0:
        return ramp.copy()
    prod = ramp[:-1] * ramp[1:]
    prod = prod.copy()
    prod[(prod < 0) & (ramp[1:] > 0)] = 1
    jump_indexes = np.flatnonzero(prod < 0)
    out = np.empty_like(ramp, dtype=np.int64)
    start = 0
    for jump_count, idx in enumerate(jump_indexes, start=1):
        out[start:idx + 1] = ramp[start:idx + 1] + jump_count * 65536
        start = idx + 1
    out[start:] = ramp[start:] + len(jump_indexes) * 65536
    return out


def _logical_groups(logical_array: np.ndarray) -> List[Tuple[int, int]]:
    idx = np.flatnonzero(np.asarray(logical_array, dtype=bool))
    if idx.size == 0:
        return []
    dif = np.diff(idx)
    starts = np.r_[0, np.flatnonzero(dif != 1) + 1]
    lengths = np.r_[np.diff(starts), idx.size - starts[-1]]
    return [(int(idx[s]), int(length)) for s, length in zip(starts, lengths)]


def _find_holes_and_jumpbacks(reference_signal: np.ndarray) -> Dict[str, Any]:
    ref = np.asarray(reference_signal, dtype=np.int64).reshape(-1)
    logical_holes = (np.diff(ref) != 1) & ((np.mod(ref[:-1], 65536)) == 0)
    hole_indexes = np.flatnonzero(logical_holes)
    ref_clean = np.delete(ref, hole_indexes)

    difference = np.diff(ref_clean)
    discrepancies = np.flatnonzero(difference <= 0)
    logical_remove = np.zeros(ref_clean.shape[0], dtype=bool)
    for discrepancy_index in discrepancies:
        restarting_point = ref_clean[discrepancy_index + 1]
        involved_difference = restarting_point - ref_clean[:discrepancy_index + 1]
        logical_remove[:discrepancy_index + 1] |= (involved_difference <= 0)

    jumpback_indexes = np.flatnonzero(logical_remove)
    return {
        "hole_indexes": hole_indexes.tolist(),
        "hole_groups": _logical_groups(logical_holes),
        "jumpback_indexes": jumpback_indexes.tolist(),
        "jumpback_groups": _logical_groups(logical_remove),
        "cleaned_ramp": np.delete(ref_clean, jumpback_indexes),
    }


def _find_discrepancy_zones(reference_signal: np.ndarray) -> List[Tuple[int, int]]:
    diff = np.diff(np.asarray(reference_signal, dtype=np.int64))
    discrepancy_indexes = np.flatnonzero(diff > 1).astype(np.int64)
    if discrepancy_indexes.size == 0:
        return []
    deltas = diff[discrepancy_indexes]
    zones: List[Tuple[int, int]] = []
    for i in range(discrepancy_indexes.size):
        hole_dim = int(deltas[i] - 1)
        if hole_dim > 0:
            zones.append((int(discrepancy_indexes[i]), hole_dim))
            if i + 1 < discrepancy_indexes.size:
                discrepancy_indexes[i + 1:] += hole_dim
    return zones


def _is_counter_track(track: Dict[str, Any], raw_track: np.ndarray) -> bool:
    subtitle = str(track.get("SubTitle") or "")
    device = str(track.get("Device") or "")
    if subtitle == "Ramp":
        return True
    if device != "Syncstation" or subtitle:
        return False
    y = np.asarray(raw_track, dtype=np.int64).reshape(-1)
    if y.size < 8:
        return False
    asc = _to_ascending_ramp(y)
    diff = np.diff(asc)
    return bool(np.mean(diff == 1) > 0.8)


def _insert_nan_holes_signal(signal: np.ndarray, zones: Sequence[Tuple[int, int]]) -> np.ndarray:
    out = np.asarray(signal, dtype=float).reshape(-1)
    offset = 0
    for start_idx, hole_dim in zones:
        if int(hole_dim) <= 0:
            continue
        insert_at = int(start_idx) + 1 + offset
        out = np.concatenate([out[:insert_at], np.full(int(hole_dim), np.nan), out[insert_at:]])
        offset += int(hole_dim)
    return out


def _insert_nan_holes_matrix(matrix: np.ndarray, zones: Sequence[Tuple[int, int]]) -> np.ndarray:
    arr = np.asarray(matrix, dtype=float)
    return np.vstack([_insert_nan_holes_signal(row, zones) for row in arr])


def _edge_error_ms(a: Sequence[float], b: Sequence[float]) -> Tuple[Optional[float], Optional[float], int]:
    n = min(len(a), len(b))
    if n <= 0:
        return None, None, 0
    aa = np.asarray(a[:n], dtype=float)
    bb = np.asarray(b[:n], dtype=float)
    delta_ms = np.abs(aa - bb) * 1000.0
    return float(np.mean(delta_ms)), float(np.max(delta_ms)), int(n)


def _load_otb4_track_data(path: Path) -> List[Tuple[int, Dict[str, Any], np.ndarray]]:
    tmpdir, tracks = _extract_otb4_tracks(path)
    try:
        signal_paths = sorted({str(track.get("SignalStreamPath") or "") for track in tracks})
        out: List[Tuple[int, Dict[str, Any], np.ndarray]] = []
        for signal_path in signal_paths:
            if not signal_path:
                continue
            offsets = _otb4_track_offsets(tracks, signal_path)
            raw = np.fromfile(tmpdir / signal_path, dtype=np.int16)
            total_channels = sum(int(track["NumberOfChannels"]) for _off, track in offsets)
            if total_channels <= 0 or raw.size % total_channels != 0:
                continue
            samples = raw.size // total_channels
            data = raw.reshape((total_channels, samples), order="F")
            for offset, track in offsets:
                nchan = int(track.get("NumberOfChannels") or 0)
                out.append((offset, track, data[offset:offset + nchan].copy()))
        return out
    finally:
        _release_otb4_tmpdir(tmpdir)


def _detect_otb4_repair_candidates(path: Path, base_edges: Sequence[float], c3d_edges: Sequence[float], fs: float) -> List[Dict[str, Any]]:
    _t_aux, aux2, _meta = _load_otb4_aux_channel(path, device=SYNC_OTB_DEVICE, subtitle=SYNC_OTB_SUBTITLE)
    base_mean_ms, base_max_ms, base_matched = _edge_error_ms(base_edges, c3d_edges)
    candidates: List[Dict[str, Any]] = []
    for track_offset, track, raw_arr in _load_otb4_track_data(path):
        raw_track = raw_arr[0]
        if not _is_counter_track(track, raw_track):
            continue
        holes = _find_holes_and_jumpbacks(_to_ascending_ramp(raw_track))
        zones = _find_discrepancy_zones(holes["cleaned_ramp"])
        if not zones:
            continue
        repaired_aux = _insert_nan_holes_signal(aux2, zones)
        repaired_edges = _collapse_edge_pairs(_binary_edges(np.nan_to_num(repaired_aux, nan=float(np.nanmedian(repaired_aux))), 0.5 * (float(np.nanmin(np.nan_to_num(repaired_aux, nan=0.0))) + float(np.nanmax(np.nan_to_num(repaired_aux, nan=0.0))))), max_gap_samples=2)
        repaired_edge_times = [float(v) / float(fs) for v in repaired_edges.tolist()]
        mean_ms, max_ms, matched = _edge_error_ms(repaired_edge_times, c3d_edges)
        candidates.append(
            {
                "track_offset": int(track_offset),
                "device": str(track.get("Device") or ""),
                "subtitle": str(track.get("SubTitle") or "") or "Control",
                "hole_groups": [{"start_index": int(s), "length": int(l)} for s, l in holes["hole_groups"]],
                "jumpback_groups": [{"start_index": int(s), "length": int(l)} for s, l in holes["jumpback_groups"]],
                "zones": [{"start_index": int(s), "hole_samples": int(d)} for s, d in zones],
                "samples_added": int(sum(dim for _start, dim in zones)),
                "repaired_edge_times_sec": repaired_edge_times,
                "mean_abs_ms": mean_ms,
                "max_abs_ms": max_ms,
                "matched_edges": matched,
                "base_mean_abs_ms": base_mean_ms,
                "base_max_abs_ms": base_max_ms,
                "base_matched_edges": base_matched,
                "improved": (
                    base_mean_ms is not None
                    and mean_ms is not None
                    and mean_ms + 1.0 < base_mean_ms
                ),
            }
        )
    candidates.sort(
        key=lambda item: (
            1e9 if item["mean_abs_ms"] is None else float(item["mean_abs_ms"]),
            1e9 if item["max_abs_ms"] is None else float(item["max_abs_ms"]),
        )
    )
    return candidates


def _detect_otb4_edges_with_zones(path: Path, zones: Sequence[Tuple[int, int]], fs: float) -> List[float]:
    _t_aux, aux2, _meta = _load_otb4_aux_channel(path, device=SYNC_OTB_DEVICE, subtitle=SYNC_OTB_SUBTITLE)
    repaired_aux = _insert_nan_holes_signal(aux2, _merge_index_zones(zones))
    threshold = 0.5 * (
        float(np.nanmin(np.nan_to_num(repaired_aux, nan=0.0)))
        + float(np.nanmax(np.nan_to_num(repaired_aux, nan=0.0)))
    )
    repaired_edges = _collapse_edge_pairs(
        _binary_edges(np.nan_to_num(repaired_aux, nan=float(np.nanmedian(repaired_aux))), threshold),
        max_gap_samples=2,
    )
    return [float(v) / float(fs) for v in repaired_edges.tolist()]


def _best_edge_alignment_summary(
    otb_edges: Sequence[float],
    c3d_edges: Sequence[float],
    *,
    max_skip_otb: int = 2,
    max_skip_c3d: int = 2,
    ttl_shift_sec: Optional[float] = None,
    ttl_tol_sec: float = 1.0,
) -> Dict[str, Any]:
    """`ttl_shift_sec`, when given, additionally requires a candidate's
    implied shift to land within `ttl_tol_sec` of the channel-1 TTL anchor
    (see `_match_ttl_anchor`) to count as quality-passing. The repeating
    decrement pattern on channels 2/3 can otherwise produce a deceptively
    good residual at the wrong point in the cycle (a multi-second error) --
    TTL fires once per session and isn't vulnerable to that ambiguity.
    """
    a = np.asarray(otb_edges, dtype=float)
    b = np.asarray(c3d_edges, dtype=float)
    best: Optional[Dict[str, Any]] = None
    for skip_otb in range(0, min(int(max_skip_otb), max(0, len(a) - 2)) + 1):
        for skip_c3d in range(0, min(int(max_skip_c3d), max(0, len(b) - 2)) + 1):
            aa = a[skip_otb:]
            bb = b[skip_c3d:]
            n = min(len(aa), len(bb))
            if n < 8:
                continue
            shift_sec = float(bb[0] - aa[0])
            delta_ms = (aa[:n] + shift_sec - bb[:n]) * 1000.0
            cand = {
                "otb4_skip": int(skip_otb),
                "c3d_skip": int(skip_c3d),
                "shift_sec": shift_sec,
                "mean_abs_ms": float(np.mean(np.abs(delta_ms))),
                "max_abs_ms": float(np.max(np.abs(delta_ms))),
                "matched_count": int(n),
            }
            if best is None:
                best = cand
                continue
            cur_ok = float(best["mean_abs_ms"]) <= 20.0 and float(best["max_abs_ms"]) <= 50.0
            new_ok = float(cand["mean_abs_ms"]) <= 20.0 and float(cand["max_abs_ms"]) <= 50.0
            if ttl_shift_sec is not None:
                cur_ok = cur_ok and abs(float(best["shift_sec"]) - float(ttl_shift_sec)) <= ttl_tol_sec
                new_ok = new_ok and abs(float(cand["shift_sec"]) - float(ttl_shift_sec)) <= ttl_tol_sec
            if new_ok and not cur_ok:
                best = cand
                continue
            if (new_ok == cur_ok) and (
                (float(cand["mean_abs_ms"]), float(cand["max_abs_ms"]), int(cand["otb4_skip"]) + int(cand["c3d_skip"]))
                < (float(best["mean_abs_ms"]), float(best["max_abs_ms"]), int(best["otb4_skip"]) + int(best["c3d_skip"]))
            ):
                best = cand
    if best is not None and ttl_shift_sec is not None:
        final_ok = (
            isinstance(best.get("mean_abs_ms"), (int, float))
            and isinstance(best.get("max_abs_ms"), (int, float))
            and float(best["mean_abs_ms"]) <= 20.0
            and float(best["max_abs_ms"]) <= 50.0
            and abs(float(best["shift_sec"]) - float(ttl_shift_sec)) <= ttl_tol_sec
        )
        if not final_ok:
            # No candidate satisfied both the residual quality bar and TTL
            # consistency -- report "nothing found" rather than risk a
            # caller that only re-checks the plain quality bar accepting a
            # TTL-inconsistent (likely wrong-cycle-locked) result.
            return {
                "otb4_skip": int(best.get("otb4_skip") or 0),
                "c3d_skip": int(best.get("c3d_skip") or 0),
                "shift_sec": best.get("shift_sec"),
                "mean_abs_ms": None,
                "max_abs_ms": None,
                "matched_count": 0,
            }
    return best or {
        "otb4_skip": 0,
        "c3d_skip": 0,
        "shift_sec": None,
        "mean_abs_ms": None,
        "max_abs_ms": None,
        "matched_count": 0,
    }


def _repair_application_block_reason(
    base_summary: Dict[str, Any],
    selected_row: Dict[str, Any],
    *,
    sample_count: int,
) -> Optional[str]:
    zones = selected_row.get("zones") or []
    if not zones:
        return None
    base_mean = base_summary.get("mean_abs_ms")
    base_max = base_summary.get("max_abs_ms")
    if not isinstance(base_mean, (int, float)) or not isinstance(base_max, (int, float)):
        return None
    base_skip_total = int(base_summary.get("otb4_skip") or 0) + int(base_summary.get("c3d_skip") or 0)
    sel_summary = selected_row.get("summary") or {}
    selected_skip_total = int(sel_summary.get("otb4_skip") or 0) + int(sel_summary.get("c3d_skip") or 0)
    base_matched = int(base_summary.get("matched_count") or 0)
    selected_matched = int(sel_summary.get("matched_count") or 0)
    samples_added = int(selected_row.get("samples_added") or 0)
    insertion_limit = max(50, int(max(0, sample_count) * 0.005))

    excellent_base = float(base_mean) <= 3.0 and float(base_max) <= 10.0
    strong_base = float(base_mean) <= 8.0 and float(base_max) <= 20.0

    reasons: List[str] = []
    if strong_base and selected_skip_total > base_skip_total:
        reasons.append(f"base sync is already strong ({base_mean:.3f}/{base_max:.3f} ms) and repair requires more skipped pulses")
    if strong_base and selected_matched < base_matched:
        reasons.append(f"base sync is already strong and repair reduces matched spikes ({selected_matched} < {base_matched})")
    if strong_base and samples_added > insertion_limit:
        reasons.append(f"base sync is already strong and repair inserts {samples_added} samples (> {insertion_limit})")
    if excellent_base and samples_added > 0:
        reasons.append(f"base sync is already excellent ({base_mean:.3f}/{base_max:.3f} ms) so no gap insertion is needed")

    if reasons:
        return "; ".join(reasons)
    return None


def _repair_info_for_match(match: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    alignment = match.get("alignment") or {}
    repair = alignment.get("otb4_repair")
    if isinstance(repair, dict):
        path = repair.get("json_path")
        if isinstance(path, str) and path and Path(path).exists():
            try:
                return json.loads(Path(path).read_text(encoding="utf-8"))
            except Exception:
                return repair
        return repair
    return None


def _otb_label_device(label: str) -> Optional[str]:
    m = re.match(r"^(Syncstation|Muovi\+?\s+\d+|Due\+\s+\d+)\b", str(label).strip())
    return m.group(1) if m else None


def _repair_entry_zones(repair: Optional[Dict[str, Any]]) -> List[Tuple[int, int]]:
    if not isinstance(repair, dict):
        return []
    zones = repair.get("zones") or []
    return [(int(z.get("start_index") or 0), int(z.get("hole_samples") or 0)) for z in zones if int(z.get("hole_samples") or 0) > 0]


def _merge_index_zones(zones: Sequence[Tuple[int, int]]) -> List[Tuple[int, int]]:
    intervals = sorted((int(start), int(start) + int(length)) for start, length in zones if int(length) > 0)
    if not intervals:
        return []
    merged: List[List[int]] = [[intervals[0][0], intervals[0][1]]]
    for start, end in intervals[1:]:
        if start <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], end)
        else:
            merged.append([start, end])
    return [(int(start), int(end - start)) for start, end in merged if end > start]


def _device_repairs_for_match(match: Dict[str, Any]) -> Dict[str, Dict[str, Any]]:
    repair_payload = _repair_info_for_match(match)
    if isinstance(repair_payload, dict) and isinstance(repair_payload.get("device_repairs"), dict):
        device_repairs = repair_payload.get("device_repairs") or {}
    else:
        alignment = match.get("alignment") or {}
        device_repairs = alignment.get("otb4_device_repairs") or {}
    if not isinstance(device_repairs, dict):
        return {}
    return {str(key): value for key, value in device_repairs.items() if isinstance(value, dict)}


def _repair_zones_for_match(match: Dict[str, Any], device: Optional[str] = None) -> List[Tuple[int, int]]:
    zones: List[Tuple[int, int]] = []
    repair = _repair_info_for_match(match)
    if repair:
        zones.extend(_repair_entry_zones(repair))
    if device:
        zones.extend(_repair_entry_zones(_device_repairs_for_match(match).get(device)))
    return _merge_index_zones(zones)


def _max_otb_repaired_length(match: Dict[str, Any], base_len: int, labels: Sequence[str]) -> int:
    lengths = [int(base_len)]
    global_zones = _repair_zones_for_match(match)
    lengths.append(int(base_len) + int(sum(length for _start, length in global_zones)))
    devices = {device for device in (_otb_label_device(label) for label in labels) if device}
    for device in devices:
        zones = _repair_zones_for_match(match, device=device)
        lengths.append(int(base_len) + int(sum(length for _start, length in zones)))
    return max(lengths)


def _binary_edges(x: np.ndarray, threshold: float) -> np.ndarray:
    b = (np.asarray(x, dtype=float).reshape(-1) > threshold).astype(np.int8)
    return np.flatnonzero(np.diff(b) != 0)


def _pulse_groups_from_signal(x: np.ndarray) -> List[Tuple[int, int]]:
    arr = np.asarray(x, dtype=float).reshape(-1)
    if arr.size == 0:
        return []
    med = float(np.nanmedian(arr)) if np.any(np.isfinite(arr)) else 0.0
    arr = np.nan_to_num(arr, nan=med)
    lo = float(np.nanmin(arr))
    hi = float(np.nanmax(arr))
    if not np.isfinite(lo) or not np.isfinite(hi) or hi == lo:
        return []
    use_high = abs(hi - med) >= abs(lo - med)
    thr = med + 0.5 * (hi - med) if use_high else med - 0.5 * (med - lo)
    active = arr >= thr if use_high else arr <= thr
    idx = np.flatnonzero(active)
    if idx.size == 0:
        return []
    groups: List[Tuple[int, int]] = []
    start = int(idx[0])
    prev = int(idx[0])
    for cur in idx[1:]:
        cur = int(cur)
        if cur != prev + 1:
            groups.append((start, prev - start + 1))
            start = cur
        prev = cur
    groups.append((start, prev - start + 1))
    return groups


def _infer_pulse_duration_ms(x: np.ndarray, sample_rate: float) -> Dict[str, Any]:
    fs = float(sample_rate or 0.0)
    if fs <= 0.0:
        return {"confirmed": False, "reason": "missing sample rate"}
    groups = _pulse_groups_from_signal(x)
    if not groups:
        return {"confirmed": False, "reason": "no pulse groups detected", "sample_rate_hz": fs}
    widths_samples = [int(length) for _start, length in groups if int(length) > 0]
    widths_ms = [float(length) / fs * 1000.0 for length in widths_samples]
    observed_mode_samples = max(set(widths_samples), key=widths_samples.count)
    observed_mode_ms = float(observed_mode_samples) / fs * 1000.0
    allowed_ms = np.asarray([0.2, 0.5, 1.0, 2.0, 5.0, 10.0, 20.0, 50.0, 100.0], dtype=float)
    nearest = allowed_ms[np.argmin(np.abs(allowed_ms - observed_mode_ms))]
    exact_observed = any(abs(float(w) - 1.0) <= 0.05 for w in widths_ms)
    # At 2 kHz, a 1 ms pulse can still alias to a single 0.5 ms sample depending on phase.
    ambiguous_alias = abs(observed_mode_ms - 0.5) <= 0.05 and fs <= 2500.0
    confirmed = exact_observed and not ambiguous_alias
    candidates: List[float] = []
    if confirmed:
        candidates = [1.0]
    else:
        candidates.append(float(nearest))
        if ambiguous_alias:
            candidates.append(1.0)
        candidates = sorted({round(v, 3) for v in candidates})
    return {
        "confirmed": bool(confirmed),
        "sample_rate_hz": fs,
        "group_count": len(widths_samples),
        "observed_width_samples_mode": int(observed_mode_samples),
        "observed_width_ms_mode": round(float(observed_mode_ms), 6),
        "all_widths_ms": [round(float(v), 6) for v in widths_ms],
        "nearest_allowed_ms": float(nearest),
        "candidate_durations_ms": candidates,
        "reason": (
            "1 ms confirmed from sampled pulse width"
            if confirmed
            else "single-sample pulse at current sample rate cannot distinguish 0.5 ms from an aliased 1 ms TTL pulse"
            if ambiguous_alias
            else "sampled pulse width does not confirm 1 ms"
        ),
    }


def _sync_pulse_duration_ms_from_match(match: Dict[str, Any], diag: Optional[Dict[str, Any]] = None) -> Optional[float]:
    alignment = match.get("alignment") or {}
    configured = alignment.get("configured_sync_pulse_duration_ms")
    if configured not in (None, ""):
        try:
            value = float(configured)
            if value > 0.0:
                return value
        except Exception:
            pass
    if diag is None:
        diag = _otb4_probe_sync_diagnostics(match)
    for info in (
        (diag.get("control_pulse_duration_info") or {}),
        (diag.get("aux2_pulse_duration_info") or {}),
    ):
        try:
            candidates = [float(v) for v in (info.get("candidate_durations_ms") or []) if float(v) > 0.0]
        except Exception:
            candidates = []
        if candidates:
            if any(abs(v - 1.0) <= 1e-9 for v in candidates):
                return 1.0
            return float(candidates[0])
    return None


def _sync_decrement_ms_from_match(match: Dict[str, Any]) -> Optional[float]:
    alignment = match.get("alignment") or {}
    configured = alignment.get("configured_sync_decrement_ms")
    if configured not in (None, ""):
        try:
            value = float(configured)
            if value > 0.0:
                return value
        except Exception:
            pass
    return None


def _sync_pattern_match_tolerance_sec(match: Dict[str, Any], diag: Optional[Dict[str, Any]] = None) -> float:
    if diag is None:
        diag = _otb4_probe_sync_diagnostics(match)
    pulse_ms = _sync_pulse_duration_ms_from_match(match, diag=diag)
    sample_periods_sec: List[float] = []
    ambiguous_alias = False
    for info in (
        (diag.get("control_pulse_duration_info") or {}),
        (diag.get("aux2_pulse_duration_info") or {}),
    ):
        try:
            fs = float(info.get("sample_rate_hz") or 0.0)
        except Exception:
            fs = 0.0
        if fs > 0.0:
            sample_periods_sec.append(1.0 / fs)
        candidates = [float(v) for v in (info.get("candidate_durations_ms") or []) if float(v) > 0.0]
        if len(candidates) >= 2 and any(abs(v - 0.5) <= 0.05 for v in candidates) and any(abs(v - 1.0) <= 0.05 for v in candidates):
            ambiguous_alias = True
    sample_period_sec = max(sample_periods_sec) if sample_periods_sec else 0.0
    pulse_sec = max(float(pulse_ms or 0.0) / 1000.0, sample_period_sec)
    tolerance_sec = max(0.002, (2.0 * sample_period_sec) + (0.5 * pulse_sec))
    if ambiguous_alias:
        tolerance_sec += max(sample_period_sec, 0.0005)
    return min(0.006, tolerance_sec)


def _collapse_edge_pairs(edges: np.ndarray, max_gap_samples: int = 2) -> np.ndarray:
    if len(edges) == 0:
        return edges
    pulses = [int(edges[0])]
    for e in edges[1:]:
        if int(e) - pulses[-1] <= max_gap_samples:
            continue
        pulses.append(int(e))
    return np.asarray(pulses, dtype=int)


def _normalize_trace(x: np.ndarray) -> np.ndarray:
    x = np.asarray(x, dtype=float).reshape(-1)
    med = np.nanmedian(x) if np.any(np.isfinite(x)) else 0.0
    x = np.nan_to_num(x, nan=med)
    lo, hi = np.nanpercentile(x, [1, 99])
    if not np.isfinite(lo) or not np.isfinite(hi) or hi - lo < 1e-12:
        return np.zeros_like(x)
    x = np.clip(x, lo, hi)
    return (x - lo) / (hi - lo)


def _normalize_unit_interval(x: np.ndarray) -> np.ndarray:
    arr = np.asarray(x, dtype=float).reshape(-1)
    med = np.nanmedian(arr) if np.any(np.isfinite(arr)) else 0.0
    arr = np.nan_to_num(arr, nan=med)
    lo = float(np.nanmin(arr))
    hi = float(np.nanmax(arr))
    if not np.isfinite(lo) or not np.isfinite(hi) or hi - lo < 1e-12:
        return np.zeros_like(arr)
    return (arr - lo) / (hi - lo)


def _dtw_distance(a: Sequence[float], b: Sequence[float]) -> float:
    if len(a) < 1 or len(b) < 1:
        return float("inf")
    aa = np.asarray(a, dtype=float)
    bb = np.asarray(b, dtype=float)
    ma = np.median(aa) if np.median(aa) != 0 else 1.0
    mb = np.median(bb) if np.median(bb) != 0 else 1.0
    aa = aa / ma
    bb = bb / mb
    n, m = len(aa), len(bb)
    dp = np.full((n + 1, m + 1), np.inf, dtype=float)
    dp[0, 0] = 0.0
    for i in range(1, n + 1):
        ai = aa[i - 1]
        for j in range(1, m + 1):
            cost = abs(ai - bb[j - 1])
            dp[i, j] = cost + min(dp[i - 1, j], dp[i, j - 1], dp[i - 1, j - 1])
    return float(dp[n, m] / (n + m))


def _orient_signal(x: np.ndarray) -> np.ndarray:
    x = np.asarray(x, dtype=float).reshape(-1)
    med = float(np.nanmedian(x)) if np.any(np.isfinite(x)) else 0.0
    pos = np.nan_to_num(x - med, nan=0.0)
    neg = np.nan_to_num(med - x, nan=0.0)
    return pos if float(np.nanmax(pos)) >= float(np.nanmax(neg)) else neg


def _interval_cv(times_sec: Sequence[float]) -> float:
    arr = np.asarray(times_sec, dtype=float)
    if arr.size < 3:
        return float("inf")
    diff = np.diff(arr)
    med = float(np.median(diff))
    if med <= 0:
        return float("inf")
    return float(np.std(diff) / med)


def _detect_sparse_spikes(
    x: np.ndarray,
    sample_rate: float,
    prominence_grid: Sequence[float],
    distance_grid_sec: Sequence[float],
    time_axis: Optional[np.ndarray] = None,
) -> List[float]:
    sig = _orient_signal(x)
    best_score = float("inf")
    best_times: List[float] = []
    axis = np.asarray(time_axis, dtype=float) if time_axis is not None else None
    for prominence in prominence_grid:
        if prominence <= 0:
            continue
        for distance_sec in distance_grid_sec:
            distance = max(1, int(sample_rate * distance_sec))
            peaks, _ = find_peaks(sig, prominence=float(prominence), distance=distance)
            if len(peaks) < 4:
                continue
            times = axis[peaks].tolist() if axis is not None else (peaks / sample_rate).tolist()
            cv = _interval_cv(times)
            count_penalty = 0.0 if 6 <= len(times) <= 24 else abs(len(times) - 16) * 0.2
            score = cv + count_penalty
            if score < best_score:
                best_score = score
                best_times = [float(v) for v in times]
    return best_times


def _detect_tsv_spikes_with_template(x: np.ndarray, t_rel: np.ndarray, template_intervals: Optional[Sequence[float]] = None) -> List[float]:
    sig = _orient_signal(x)
    dt = np.diff(t_rel)
    dt = dt[np.isfinite(dt) & (dt > 0)]
    sample_rate = float(1.0 / np.median(dt)) if len(dt) else 1.0
    std = float(np.std(sig))
    amp = float(np.max(sig)) if len(sig) else 0.0
    prominence_grid = [v for v in [std * 1.5, std * 2.0, std * 2.5, std * 3.0, amp * 0.15, amp * 0.2, amp * 0.25] if v > 0]
    distance_grid = [0.8, 1.0, 1.5, 2.0, 2.5, 3.0]
    best_score = float("inf")
    best_times: List[float] = []
    template = list(template_intervals or [])
    for prominence in prominence_grid:
        for distance_sec in distance_grid:
            distance = max(1, int(sample_rate * distance_sec))
            peaks, _ = find_peaks(sig, prominence=float(prominence), distance=distance)
            if len(peaks) < 4:
                continue
            times = [float(t_rel[int(i)]) for i in peaks if int(i) < len(t_rel)]
            if len(times) < 4:
                continue
            cv = _interval_cv(times)
            if template:
                score = _dtw_distance(np.diff(times), template) + 0.05 * abs(len(times) - (len(template) + 1))
            else:
                score = cv + 0.05 * abs(len(times) - 16)
            if score < best_score:
                best_score = score
                best_times = times
    return best_times


def _tsv_raw_channels(record: Dict[str, Any]) -> List[str]:
    return [c for c in (record.get("channel_names") or []) if str(c).lower().endswith(TSV_RAW_SUFFIX)]


def _analog_time_from_c3d(c3d_file: ezc3d.c3d) -> np.ndarray:
    point_rate = float(c3d_file["parameters"]["POINT"]["RATE"]["value"][0])
    analog_rate = float(c3d_file["parameters"]["ANALOG"]["RATE"]["value"][0])
    actual_start = int(c3d_file["parameters"]["TRIAL"]["ACTUAL_START_FIELD"]["value"][0])
    n_point_frames = c3d_file["data"]["points"].shape[2]
    point_frames = np.arange(n_point_frames) + actual_start
    time_c3d = point_frames / point_rate - 1.0 / point_rate
    analog_first = int(c3d_file["header"]["analogs"]["first_frame"])
    analog_last = int(c3d_file["header"]["analogs"]["last_frame"])
    n_analog_frames = analog_last - analog_first + 1
    return np.arange(n_analog_frames, dtype=float) / analog_rate + time_c3d[0]


def _unit_scale_to_meters(unit_value: Any) -> float:
    text = str(unit_value).strip().lower()
    if text in {"m", "meter", "meters"}:
        return 1.0
    if text in {"mm", "millimeter", "millimeters"}:
        return 1e-3
    if text in {"cm", "centimeter", "centimeters"}:
        return 1e-2
    return 1.0


def _classify_tsv_raw_channel(raw_col: str) -> Optional[Dict[str, str]]:
    text = str(raw_col).strip()
    lower = text.lower()
    if "/cop/cx " in lower:
        return {"tsv_channel": text, "c3d_kind": "cop", "c3d_channel": "copx", "axis": "x", "label_match": "exact_cop"}
    if "/cop/cy " in lower:
        return {"tsv_channel": text, "c3d_kind": "cop", "c3d_channel": "copy", "axis": "y", "label_match": "exact_cop"}
    return None


def _normalized_label_token(text: str) -> str:
    base = re.sub(r"\s+\[(raw|offset|sync)\]\s*$", "", str(text), flags=re.IGNORECASE)
    base = re.sub(r"\s+\[[^\]]+\]", "", base)
    return re.sub(r"[^a-z0-9]+", "", base.lower())


def _exact_raw_pair_candidates(tsv_record: Dict[str, Any], c3d_record: Dict[str, Any]) -> List[Dict[str, str]]:
    out: List[Dict[str, str]] = []
    for raw_col in _tsv_raw_channels(tsv_record):
        cop = _classify_tsv_raw_channel(raw_col)
        if cop is not None:
            out.append(cop)
            continue
        raw_token = _normalized_label_token(raw_col)
        if not raw_token:
            continue
        for label in c3d_record.get("channel_names") or []:
            if raw_token == _normalized_label_token(label):
                out.append(
                    {
                        "tsv_channel": str(raw_col),
                        "c3d_kind": "analog",
                        "c3d_channel": str(label),
                        "axis": "",
                        "label_match": "exact_label",
                    }
                )
                break
    return out


def _normalize_global_pair_specs(specs: Optional[Sequence[Dict[str, Any]]]) -> List[Dict[str, str]]:
    out: List[Dict[str, str]] = []
    for spec in specs or []:
        kind = str((spec or {}).get("kind") or "").strip().lower()
        if kind != "raw":
            continue
        tsv_channel = str((spec or {}).get("tsv_channel") or "").strip()
        c3d_channel = str((spec or {}).get("c3d_channel") or "").strip()
        c3d_kind = str((spec or {}).get("c3d_kind") or "analog").strip().lower() or "analog"
        if not tsv_channel or not c3d_channel:
            continue
        out.append(
            {
                "kind": "raw",
                "tsv_channel": tsv_channel,
                "c3d_channel": c3d_channel,
                "c3d_kind": c3d_kind,
                "label_match": str((spec or {}).get("label_match") or "preferred_global"),
            }
        )
    return out


def _preferred_raw_pair_candidates(
    tsv_record: Dict[str, Any],
    c3d_record: Dict[str, Any],
    preferred_pairs: Optional[Sequence[Dict[str, Any]]],
) -> List[Dict[str, str]]:
    tsv_names = {str(name) for name in (tsv_record.get("channel_names") or [])}
    c3d_analog = {str(name) for name in (c3d_record.get("channel_names") or [])}
    c3d_points = {str(name) for name in (c3d_record.get("point_channel_names") or [])}
    out: List[Dict[str, str]] = []
    seen: set[Tuple[str, str, str]] = set()
    for spec in _normalize_global_pair_specs(preferred_pairs):
        if spec["tsv_channel"] not in tsv_names:
            continue
        if spec["c3d_kind"] == "analog" and spec["c3d_channel"] not in c3d_analog:
            continue
        if spec["c3d_kind"] == "point":
            base = str(spec["c3d_channel"]).split(".", 1)[0]
            if base not in c3d_points:
                continue
        key = (spec["tsv_channel"], spec["c3d_channel"], spec["c3d_kind"])
        if key in seen:
            continue
        seen.add(key)
        out.append(dict(spec))
    return out


def _available_global_pair_options(folder: Path) -> List[Dict[str, Any]]:
    folder = Path(folder)
    c3d_paths = _iter_source_files(folder, ".c3d", excluded_dir_names=("matched", "accepted", "__pycache__", ".git"))
    tsv_paths = _iter_source_files(folder, ".tsv", excluded_dir_names=("matched", "accepted", "__pycache__", ".git"))
    if not c3d_paths or not tsv_paths:
        return [{"label": "Auto detect exact raw/sync pairs", "kind": "auto"}]
    try:
        c3d_record = _extract_c3d_record(c3d_paths[0]).to_json()
        tsv_record = _extract_tsv_record(tsv_paths[0]).to_json()
    except Exception:
        return [{"label": "Auto detect exact raw/sync pairs", "kind": "auto"}]
    options: List[Dict[str, Any]] = [{"label": "Auto detect exact raw/sync pairs", "kind": "auto"}]
    if c3d_record.get("sync_present") and c3d_record.get("sync_channel") and tsv_record.get("sync_present") and tsv_record.get("sync_channel"):
        options.append(
            {
                "label": f"Shared sync: {c3d_record.get('sync_channel')} <-> {tsv_record.get('sync_channel')}",
                "kind": "sync",
            }
        )
    for pair in _exact_raw_pair_candidates(tsv_record, c3d_record):
        label = f"Raw: {pair['c3d_channel']} <-> {pair['tsv_channel']}"
        options.append({**pair, "kind": "raw", "label": label})
    return options


@lru_cache(maxsize=128)
def _c3d_forceplat_metadata(path: Path) -> Dict[str, Any]:
    c3d = ezc3d.c3d(str(path), extract_forceplat_data=True)
    return {
        "c3d": c3d,
        "analog_time": _analog_time_from_c3d(c3d),
    }


@lru_cache(maxsize=256)
def _load_c3d_cop_channel(path: Path, channel_name: str) -> Tuple[np.ndarray, np.ndarray]:
    meta = _c3d_forceplat_metadata(path)
    c3d = meta["c3d"]
    platforms = c3d["data"].get("platform", [])
    if not platforms:
        raise ValueError("No force-platform data found in C3D file.")
    platform = platforms[0]
    cop = np.asarray(platform["center_of_pressure"], dtype=float)
    if cop.shape[0] < 2:
        raise ValueError("C3D center_of_pressure does not contain x/y data.")
    idx = {"copx": 0, "copy": 1, "copz": 2}.get(channel_name.lower())
    if idx is None or idx >= cop.shape[0]:
        raise ValueError(f"Unsupported C3D CoP channel: {channel_name}")
    scale = _unit_scale_to_meters(platform.get("unit_position", "m"))
    return np.asarray(meta["analog_time"], dtype=float), np.asarray(cop[idx], dtype=float) * scale


def _load_c3d_series(path: Path, kind: str, channel_name: str) -> Tuple[np.ndarray, np.ndarray]:
    if kind == "cop":
        return _load_c3d_cop_channel(path, channel_name)
    if kind == "point":
        return _load_c3d_point_channel(path, channel_name)
    return _load_c3d_analog_channel(path, channel_name)


def _resample_shifted_pair(
    t_ref: np.ndarray,
    y_ref: np.ndarray,
    t_mov: np.ndarray,
    y_mov: np.ndarray,
    shift_sec: float,
    step_sec: float = 0.01,
) -> Optional[Tuple[np.ndarray, np.ndarray]]:
    start = max(float(np.nanmin(t_ref)), float(np.nanmin(t_mov + shift_sec)))
    end = min(float(np.nanmax(t_ref)), float(np.nanmax(t_mov + shift_sec)))
    if not np.isfinite(start) or not np.isfinite(end) or end - start < 10.0:
        return None
    grid = np.arange(start, end, step_sec, dtype=float)
    if len(grid) < 100:
        return None
    a = np.interp(grid, t_ref, y_ref)
    b = np.interp(grid - shift_sec, t_mov, y_mov)
    a = np.nan_to_num(a, nan=float(np.nanmedian(a)))
    b = np.nan_to_num(b, nan=float(np.nanmedian(b)))
    a = a - float(np.mean(a))
    b = b - float(np.mean(b))
    sd_a = float(np.std(a))
    sd_b = float(np.std(b))
    if sd_a > 0:
        a = a / sd_a
    if sd_b > 0:
        b = b / sd_b
    return a, b


def _best_shifted_corr(
    t_ref: np.ndarray,
    y_ref: np.ndarray,
    t_mov: np.ndarray,
    y_mov: np.ndarray,
    *,
    max_shift_sec: float,
    step_sec: float = 0.01,
) -> Dict[str, Any]:
    best_corr: Optional[float] = None
    best_shift: Optional[float] = None
    best_samples = 0
    max_steps = int(max_shift_sec / step_sec)
    for shift_steps in range(-max_steps, max_steps + 1):
        shift_sec = shift_steps * step_sec
        pair = _resample_shifted_pair(t_ref, y_ref, t_mov, y_mov, shift_sec, step_sec=step_sec)
        if pair is None:
            continue
        a, b = pair
        if len(a) < 100:
            continue
        corr = float(np.corrcoef(a, b)[0, 1]) if np.std(a) > 0 and np.std(b) > 0 else float("nan")
        if not np.isfinite(corr):
            continue
        if best_corr is None or abs(corr) > abs(best_corr):
            best_corr = corr
            best_shift = shift_sec
            best_samples = int(len(a))
    return {"corr": best_corr, "shift_sec": best_shift, "samples": best_samples}


def _best_shifted_corr_refined(
    t_ref: np.ndarray,
    y_ref: np.ndarray,
    t_mov: np.ndarray,
    y_mov: np.ndarray,
    *,
    max_shift_sec: float,
    coarse_step_sec: float = 0.01,
    fine_window_sec: float = 0.3,
    fine_step_sec: float = 0.001,
) -> Dict[str, Any]:
    coarse = _best_shifted_corr(
        t_ref,
        y_ref,
        t_mov,
        y_mov,
        max_shift_sec=max_shift_sec,
        step_sec=coarse_step_sec,
    )
    coarse_shift = coarse.get("shift_sec")
    if coarse_shift is None:
        return coarse
    lo = max(-float(max_shift_sec), float(coarse_shift) - float(fine_window_sec))
    hi = min(float(max_shift_sec), float(coarse_shift) + float(fine_window_sec))
    best_corr = coarse.get("corr")
    best_shift = float(coarse_shift)
    best_samples = int(coarse.get("samples") or 0)
    shift = lo
    while shift <= hi + 1e-12:
        pair = _resample_shifted_pair(t_ref, y_ref, t_mov, y_mov, shift, step_sec=0.01)
        if pair is not None:
            a, b = pair
            if len(a) >= 100:
                corr = float(np.corrcoef(a, b)[0, 1]) if np.std(a) > 0 and np.std(b) > 0 else float("nan")
                if np.isfinite(corr) and (best_corr is None or abs(corr) > abs(float(best_corr))):
                    best_corr = corr
                    best_shift = float(round(shift, 6))
                    best_samples = int(len(a))
        shift += float(fine_step_sec)
    return {"corr": best_corr, "shift_sec": best_shift, "samples": best_samples}


def _raw_quality(abs_corr: float, abs_shift_sec: float) -> str:
    if abs_corr >= 0.999 and abs_shift_sec <= 0.25:
        return "excellent"
    if abs_corr >= 0.995 and abs_shift_sec <= 1.0:
        return "good"
    if abs_corr >= 0.95 and abs_shift_sec <= 5.0:
        return "fair"
    return "poor"


def _effective_raw_quality(raw_result: Dict[str, Any], edge_align: Optional[Dict[str, Any]] = None) -> str:
    quality = str(raw_result.get("quality") or "missing")
    corr = raw_result.get("corr")
    if not isinstance(corr, (int, float)):
        return quality
    if (edge_align or {}).get("basis") == "late_c3d_raw_bridge":
        abs_corr = abs(float(corr))
        if abs_corr >= 0.999:
            return "excellent"
        if abs_corr >= 0.995:
            return "good"
    return quality


def _best_tsv_raw_alignment(
    tsv_record: Dict[str, Any],
    c3d_record: Dict[str, Any],
    preferred_pairs: Optional[Sequence[Dict[str, Any]]] = None,
) -> Dict[str, Any]:
    pairs = _preferred_raw_pair_candidates(tsv_record, c3d_record, preferred_pairs) + _exact_raw_pair_candidates(tsv_record, c3d_record)
    dedup: List[Dict[str, str]] = []
    seen_pairs: set[Tuple[str, str, str]] = set()
    for pair in pairs:
        key = (str(pair.get("tsv_channel") or ""), str(pair.get("c3d_channel") or ""), str(pair.get("c3d_kind") or "analog"))
        if key in seen_pairs:
            continue
        seen_pairs.add(key)
        dedup.append(pair)
    pairs = dedup
    if not pairs:
        return {
            "quality": "missing",
            "corr": None,
            "lag_sec": None,
            "tsv_channel": None,
            "c3d_channel": None,
            "c3d_kind": None,
            "label_matched": False,
            "samples": 0,
        }

    best: Optional[Dict[str, Any]] = None
    for pair in pairs:
        try:
            t_tsv, y_tsv = _load_tsv_channel(Path(tsv_record["path"]), pair["tsv_channel"])
            t_c3d, y_c3d = _load_c3d_series(Path(c3d_record["path"]), pair["c3d_kind"], pair["c3d_channel"])
        except Exception:
            continue
        result = _best_shifted_corr_refined(
            np.asarray(t_c3d, dtype=float),
            np.asarray(y_c3d, dtype=float),
            np.asarray(t_tsv, dtype=float),
            np.asarray(y_tsv, dtype=float),
            max_shift_sec=2.0,
            coarse_step_sec=0.05,
            fine_window_sec=0.05,
            fine_step_sec=0.005,
        )
        corr = result.get("corr")
        shift_sec = result.get("shift_sec")
        if corr is None or shift_sec is None:
            continue
        abs_corr = abs(float(corr))
        candidate = {
            "quality": _raw_quality(abs_corr, abs(float(shift_sec))),
            "corr": round(float(corr), 6),
            "lag_sec": round(float(shift_sec), 6),
            "tsv_channel": pair["tsv_channel"],
            "c3d_channel": pair["c3d_channel"],
            "c3d_kind": pair["c3d_kind"],
            "label_matched": True,
            "label_match": pair["label_match"],
            "samples": int(result.get("samples") or 0),
        }
        cur_key = (
            0 if str(pair.get("label_match") or "").startswith("preferred") else 1,
            -abs_corr,
            abs(float(shift_sec)),
        )
        best_key = (
            0 if best and str(best.get("label_match") or "").startswith("preferred") else 1,
            -abs(float(best["corr"])) if best and best.get("corr") is not None else float("inf"),
            abs(float(best.get("lag_sec") or 0.0)) if best else float("inf"),
        )
        if best is None or cur_key < best_key:
            best = candidate
    if best is None:
        return {
            "quality": "missing",
            "corr": None,
            "lag_sec": None,
            "tsv_channel": None,
            "c3d_channel": None,
            "c3d_kind": None,
            "label_matched": False,
            "samples": 0,
        }
    return best


def _format_file_stamp(dt: Optional[datetime] = None) -> str:
    return (dt or datetime.now()).strftime("%Y%m%d_%H%M%S")


def _source_display_name(record: Dict[str, Any]) -> str:
    return Path(record["path"]).name


def _source_sync_offset(record: Dict[str, Any]) -> float:
    edges = record.get("edge_times_sec") or []
    return float(edges[0]) if edges else 0.0


def _sync_edge_skip_count(match: Dict[str, Any], source: str) -> int:
    skips = ((match.get("alignment") or {}).get("sync_edge_skips") or {})
    try:
        return max(0, int(skips.get(source) or 0))
    except Exception:
        return 0


def _source_sync_offset_for_match(match: Dict[str, Any], source: str) -> float:
    if source in ("otb4", "c3d"):
        # Some alignment bases (channel-3 cross-machine fallback, TTL anchor)
        # find their anchor in an edge array *other* than
        # match[source]["edge_times_sec"] (which is always channel 2) -- an
        # explicit native-time anchor avoids misapplying that basis's skip
        # count to the wrong array. Bases that search channel 2 directly
        # (first_visible_sync/channel2_refined/late_c3d_raw_bridge) don't set
        # this and fall through to the skip-indexed lookup below unchanged.
        edge_align = (match.get("alignment") or {}).get("otb4_c3d_edge_alignment") or {}
        anchor = edge_align.get(f"{source}_anchor_sec")
        if isinstance(anchor, (int, float)):
            return float(anchor)
    record = match.get(source) or {}
    edges = np.asarray(record.get("edge_times_sec") or [], dtype=float)
    if edges.size == 0:
        return 0.0
    skip = _sync_edge_skip_count(match, source)
    if skip < edges.size:
        return float(edges[skip])
    return float(edges[0])


def _sync_overlay_summary(match: Dict[str, Any]) -> str:
    parts = []
    for key in ("otb4", "c3d", "tsv"):
        rec = match.get(key)
        if rec:
            parts.append(f"{key.upper()}: {_source_display_name(rec)}")

    alignment = match.get("alignment") or {}
    quality = alignment.get("dedicated_sync_quality") or alignment.get("sync_triplet_quality") or "unknown"
    mean_ms = alignment.get("dedicated_sync_mean_abs_ms")
    max_ms = alignment.get("dedicated_sync_max_abs_ms")
    raw_corr = alignment.get("raw_alignment_corr")
    raw_q = alignment.get("raw_alignment_quality")
    raw_tsv = alignment.get("raw_label_match_tsv")
    raw_c3d = alignment.get("raw_label_match_c3d")
    tsv_sync_missing = quality == "missing_tsv_sync"
    raw_text = f"raw={raw_q or 'missing'}"
    if isinstance(raw_corr, (int, float)):
        raw_text += f" corr={raw_corr:.3f}"
    if raw_tsv and raw_c3d:
        raw_tsv_text = Path(str(raw_tsv)).name if "\\" in str(raw_tsv) else str(raw_tsv)
        raw_text += f" [{raw_tsv_text} -> {raw_c3d}]"
    if mean_ms is None or max_ms is None:
        metrics = f"dedicated_sync={quality} {raw_text}"
    else:
        metrics = f"dedicated_sync={quality} mean_abs={mean_ms:.3f} ms max_abs={max_ms:.3f} ms {raw_text}"
    if tsv_sync_missing:
        metrics += f" otb4/c3d={alignment.get('dedicated_sync_pair_quality') or 'n/a'}"
    return " | ".join(["Sync overlay", metrics] + parts)


def _otb4_probe_sync_diagnostics(match: Dict[str, Any]) -> Dict[str, Any]:
    record = match.get("otb4") or {}
    diag = dict(record.get("probe_sync_diagnostics") or {})
    if diag:
        return diag
    path = str(record.get("path") or "")
    if not path:
        return {}
    configured_step_ms = _sync_decrement_ms_from_match(match)
    configured_step_sec = float(configured_step_ms) / 1000.0 if configured_step_ms not in (None, "") else None
    cache_key = _otb4_probe_diag_cache_key(path, configured_step_sec)
    cached = _OTB4_PROBE_DIAG_CACHE.get(cache_key)
    if cached:
        record["probe_sync_diagnostics"] = dict(cached)
        return dict(cached)
    try:
        computed = _extract_otb4_probe_sync_diagnostics(
            Path(path),
            default_step_sec=configured_step_sec,
            candidate_step_secs=[configured_step_sec] if configured_step_sec else None,
        )
    except Exception:
        computed = {}
    if computed:
        _OTB4_PROBE_DIAG_CACHE[cache_key] = dict(computed)
        record["probe_sync_diagnostics"] = dict(computed)
        return dict(computed)
    return {}


def _otb4_probe_sync_summary_text(match: Dict[str, Any]) -> str:
    diag = _otb4_probe_sync_diagnostics(match)
    probes = list(diag.get("probes") or [])
    if not probes:
        return "OTB4 probe sync: unavailable"
    ref_source = str(diag.get("reference_source") or "control")
    ref_expected = int((diag.get("reference_pattern") or {}).get("expected_event_count") or 0)
    synced = int(diag.get("synced_probe_count") or 0)
    total = len(probes)
    non_sync = [probe for probe in probes if probe.get("non_sync")]
    repairable = sum(1 for probe in non_sync if "repairable from ramp" in str(probe.get("sample_status") or ""))
    bits = [
        f"OTB4 probe sync: ref={ref_source} expected={ref_expected}",
        f"synced={synced}/{total}",
        f"non-sync={len(non_sync)}",
    ]
    pulse_info = (diag.get("aux2_pulse_duration_info") or {}) if ref_source == "aux2" else (diag.get("control_pulse_duration_info") or {})
    if pulse_info:
        if pulse_info.get("confirmed"):
            bits.append("TTL=1.0 ms confirmed")
        else:
            candidates = pulse_info.get("candidate_durations_ms") or []
            if candidates:
                bits.append("TTL~" + "/".join(f"{float(v):g} ms" for v in candidates))
    configured_pulse_ms = _sync_pulse_duration_ms_from_match(match, diag=diag)
    if configured_pulse_ms is not None:
        bits.append(f"cfg={configured_pulse_ms:g} ms")
    configured_step_ms = _sync_decrement_ms_from_match(match)
    if configured_step_ms is not None:
        bits.append(f"step={configured_step_ms:g} ms")
    bits.append(f"mark tol={_sync_pattern_match_tolerance_sec(match, diag=diag) * 1000.0:.1f} ms")
    if repairable:
        bits.append(f"repairable={repairable}")
    if non_sync:
        detail = []
        for probe in non_sync[:3]:
            ref_summary = probe.get("reference_summary") or {}
            detail.append(
                f"{probe.get('device')} {int(ref_summary.get('matched_count') or 0)}/{ref_expected}"
            )
        bits.append("off-pattern=" + ", ".join(detail))
    return " | ".join(bits)


def _otb4_probe_sync_annotation_text(match: Dict[str, Any]) -> str:
    diag = _otb4_probe_sync_diagnostics(match)
    probes = list(diag.get("probes") or [])
    if not probes:
        return "OTB4 peripheral probe sync unavailable."
    lines = [_otb4_probe_sync_summary_text(match)]
    for label, info in (("control TTL", diag.get("control_pulse_duration_info") or {}), ("AUX2 TTL", diag.get("aux2_pulse_duration_info") or {})):
        if not info:
            continue
        if info.get("confirmed"):
            lines.append(f"{label}: 1.0 ms confirmed from sampled pulse width.")
        else:
            candidates = info.get("candidate_durations_ms") or []
            if candidates:
                lines.append(
                    f"{label}: sampled width={float(info.get('observed_width_ms_mode') or 0.0):.3f} ms, "
                    f"candidate configured durations={', '.join(f'{float(v):g} ms' for v in candidates)} | {info.get('reason')}"
                )
    ref_note = str((diag.get("reference_pattern") or {}).get("note") or "").strip()
    if ref_note:
        lines.append(f"Reference pattern: {ref_note}")
    for probe in probes:
        if not probe.get("non_sync"):
            continue
        ref_summary = probe.get("reference_summary") or {}
        lines.append(
            f"{probe.get('device')}: {probe.get('sync_status')} | aligned={int(ref_summary.get('matched_count') or 0)}/{int((diag.get('reference_pattern') or {}).get('expected_event_count') or 0)} | "
            f"missing={int(ref_summary.get('unmatched_ref') or 0)} | extra={int(ref_summary.get('unmatched_other') or 0)} | "
            f"shift={float(probe.get('optimal_lag_sec') or 0.0) * 1000.0:.1f} ms | {probe.get('sample_status')}"
        )
    return "\n".join(lines)


def _expected_sync_markers(match: Dict[str, Any], device: Optional[str] = None, tolerance_sec: Optional[float] = None) -> List[Dict[str, Any]]:
    diag = _otb4_probe_sync_diagnostics(match)
    match_tolerance_sec = float(tolerance_sec if tolerance_sec is not None else _sync_pattern_match_tolerance_sec(match, diag=diag))
    expected = np.asarray(diag.get("expected_times_sec") or [], dtype=float)
    if expected.size == 0:
        return []
    if device:
        probe = next((item for item in (diag.get("probes") or []) if str(item.get("device") or "") == str(device)), None)
        observed = np.asarray((((probe or {}).get("shifted_event_times_sec")) or ((probe or {}).get("event_times_sec")) or []), dtype=float)
        markers: List[Dict[str, Any]] = []
        for event_sec in expected:
            status = "confirmed" if observed.size and np.any(np.abs(observed - float(event_sec)) <= match_tolerance_sec) else "missing"
            markers.append({"time_sec": float(event_sec), "status": status})
        return markers

    control_obs = np.asarray(diag.get("control_observed_times_sec") or [], dtype=float)
    aux2_obs = np.asarray(diag.get("aux2_observed_times_sec") or [], dtype=float)
    markers = []
    for event_sec in expected:
        ctrl_ok = bool(control_obs.size and np.any(np.abs(control_obs - float(event_sec)) <= match_tolerance_sec))
        aux_ok = bool(aux2_obs.size and np.any(np.abs(aux2_obs - float(event_sec)) <= match_tolerance_sec))
        if ctrl_ok and (not aux2_obs.size or aux_ok):
            status = "confirmed"
        elif ctrl_ok or aux_ok:
            status = "partial"
        else:
            status = "missing"
        markers.append({"time_sec": float(event_sec), "status": status})
    return markers


def _channel3_match_markers(match: Dict[str, Any], tolerance_sec: float = 0.05) -> List[Dict[str, Any]]:
    """Per-pulse OTB4<->C3D match status for channel 3 (3_Sync_50ms): for
    each OTB4 channel-3 pulse (in OTB4's own native time -- same convention
    as _expected_sync_markers), "confirmed" if a C3D channel-3 pulse falls
    within `tolerance_sec` of it once both are placed on the common aligned
    time axis (via _match_plot_shifts), else "missing". This is the sync
    diagnosis for channel 3 specifically, independent of which basis
    (channel 2, channel 3, or TTL) the overall OTB4<->C3D alignment used.
    """
    otb_path = (match.get("otb4") or {}).get("path")
    c3d_path = (match.get("c3d") or {}).get("path")
    if not otb_path or not c3d_path:
        return []
    otb_ch3 = sorted(_otb4_channel_edge_times(Path(otb_path), SYNC_OTB_DEVICE, SYNC_OTB_TSV_BRIDGE_SUBTITLE))
    c3d_ch3 = sorted(_c3d_channel_edge_times(Path(c3d_path), SYNC_C3D_TSV_BRIDGE_LABEL))
    if not otb_ch3:
        return []
    shifts = _match_plot_shifts(match)
    otb_shift = float(shifts.get("otb4", 0.0))
    c3d_shift = float(shifts.get("c3d", 0.0))
    c3d_aligned = np.asarray(c3d_ch3, dtype=float) + c3d_shift
    markers: List[Dict[str, Any]] = []
    for t in otb_ch3:
        aligned_t = float(t) + otb_shift
        confirmed = bool(c3d_aligned.size and np.any(np.abs(c3d_aligned - aligned_t) <= tolerance_sec))
        markers.append({"time_sec": float(t), "status": "confirmed" if confirmed else "missing"})
    return markers


def _triplet_spike_agreement(records: Sequence[Dict[str, Any]]) -> Dict[str, Any]:
    usable: List[Tuple[str, np.ndarray]] = []
    for rec in records:
        edges = np.asarray(rec.get("edge_times_sec") or [], dtype=float)
        if edges.size >= 2:
            usable.append((str(rec.get("kind", "unknown")), edges - edges[0]))

    if len(usable) < 2:
        return {
            "quality": "insufficient",
            "source_count": len(usable),
            "spike_count": 0,
            "mean_abs_delta_ms": None,
            "max_abs_delta_ms": None,
            "pairwise": {},
        }

    spike_count = min(len(edges) for _kind, edges in usable)
    if spike_count <= 1:
        return {
            "quality": "insufficient",
            "source_count": len(usable),
            "spike_count": spike_count,
            "mean_abs_delta_ms": None,
            "max_abs_delta_ms": None,
            "pairwise": {},
        }

    pairwise: Dict[str, Dict[str, float]] = {}
    pair_deltas: List[np.ndarray] = []
    for i in range(len(usable)):
        for j in range(i + 1, len(usable)):
            name_i, a = usable[i]
            name_j, b = usable[j]
            n = min(len(a), len(b))
            delta = (a[:n] - b[:n]) * 1000.0
            pairwise[f"{name_i}_vs_{name_j}"] = {
                "mean_abs_ms": round(float(np.mean(np.abs(delta))), 6),
                "max_abs_ms": round(float(np.max(np.abs(delta))), 6),
                "count": int(n),
            }
            pair_deltas.append(delta)

    if pair_deltas:
        spread_ms = np.concatenate([np.abs(delta) for delta in pair_deltas])
        mean_abs = float(np.mean(spread_ms))
        max_abs = float(np.max(spread_ms))
    else:
        mean_abs = float("inf")
        max_abs = float("inf")

    if max_abs <= 1.0 and mean_abs <= 0.25:
        quality = "excellent"
    elif max_abs <= 5.0 and mean_abs <= 1.0:
        quality = "good"
    elif max_abs <= 20.0:
        quality = "fair"
    else:
        quality = "poor"

    return {
        "quality": quality,
        "source_count": len(usable),
        "spike_count": spike_count,
        "mean_abs_delta_ms": round(mean_abs, 6),
        "max_abs_delta_ms": round(max_abs, 6),
        "pairwise": pairwise,
    }


def _match_plot_shifts(match: Dict[str, Any]) -> Dict[str, float]:
    c3d_ref = _source_sync_offset_for_match(match, "c3d")
    shifts = {
        "c3d": -c3d_ref,
        "otb4": -_source_sync_offset_for_match(match, "otb4"),
        "tsv": -_source_sync_offset(match.get("tsv") or {}),
    }
    raw_shift = (match.get("alignment") or {}).get("raw_alignment_lag_sec")
    if raw_shift is not None:
        shifts["tsv"] = float(raw_shift) - c3d_ref
    return shifts


def _record_native_time_range(record: Dict[str, Any]) -> Optional[Tuple[float, float]]:
    kind = str(record.get("kind", ""))
    if kind == "tsv":
        duration = record.get("duration_sec")
        if isinstance(duration, (int, float)) and np.isfinite(duration) and duration > 0:
            return 0.0, float(duration)
        return None
    sample_rate = record.get("sample_rate")
    sample_count = record.get("sample_count")
    if isinstance(sample_rate, (int, float)) and isinstance(sample_count, int) and sample_rate and sample_count > 0:
        return 0.0, float(max(sample_count - 1, 0)) / float(sample_rate)
    return None


def _build_inner_merge_alignment(match: Dict[str, Any]) -> Dict[str, Any]:
    shifts = _match_plot_shifts(match)
    source_ranges: Dict[str, Dict[str, Any]] = {}
    aligned_starts: List[float] = []
    aligned_ends: List[float] = []
    aligned_edges: Dict[str, List[float]] = {}

    for source in ("otb4", "c3d", "tsv"):
        record = match.get(source)
        if not record:
            continue
        native_range = _record_native_time_range(record)
        shift_sec = float(shifts.get(source, 0.0))
        sync_anchor_native = _source_sync_offset_for_match(match, source)
        if native_range is None:
            continue
        native_start, native_end = native_range
        aligned_start = native_start + shift_sec
        aligned_end = native_end + shift_sec
        source_ranges[source] = {
            "native_start_sec": round(native_start, 6),
            "native_end_sec": round(native_end, 6),
            "aligned_start_sec": round(aligned_start, 6),
            "aligned_end_sec": round(aligned_end, 6),
            "shift_sec": round(shift_sec, 6),
            "sync_anchor_native_sec": round(sync_anchor_native, 6),
            "sync_anchor_aligned_sec": round(sync_anchor_native + shift_sec, 6),
            "sync_channel": record.get("sync_channel"),
        }
        aligned_starts.append(aligned_start)
        aligned_ends.append(aligned_end)
        edges = np.asarray(record.get("edge_times_sec") or [], dtype=float)
        aligned_edges[source] = [round(float(v), 6) for v in (edges + shift_sec).tolist()]

    overlap_start = max(aligned_starts) if aligned_starts else None
    overlap_end = min(aligned_ends) if aligned_ends else None
    overlap_duration = None
    if overlap_start is not None and overlap_end is not None and overlap_end > overlap_start:
        overlap_duration = overlap_end - overlap_start

    alignment_channels = {
        "otb4_sync": (match.get("otb4") or {}).get("sync_channel"),
        "c3d_sync": (match.get("c3d") or {}).get("sync_channel"),
        "tsv_sync": (match.get("tsv") or {}).get("sync_channel"),
        "tsv_raw": (match.get("alignment") or {}).get("raw_label_match_tsv"),
        "c3d_raw": (match.get("alignment") or {}).get("raw_label_match_c3d"),
        "c3d_raw_kind": (match.get("alignment") or {}).get("raw_label_match_c3d_kind"),
    }

    return {
        "formula": "aligned_time_sec = source_time_sec + shift_sec",
        "shift_basis": "plot_time_shifts_sec",
        "source_time_ranges": source_ranges,
        "aligned_sync_edges_sec": aligned_edges,
        "inner_merge_start_sec": round(float(overlap_start), 6) if overlap_start is not None else None,
        "inner_merge_end_sec": round(float(overlap_end), 6) if overlap_end is not None else None,
        "inner_merge_duration_sec": round(float(overlap_duration), 6) if overlap_duration is not None else None,
        "channels": alignment_channels,
    }


def _aligned_sync_edges(match: Dict[str, Any], source: str) -> np.ndarray:
    rec = match.get(source) or {}
    edges = np.asarray(rec.get("edge_times_sec") or [], dtype=float)
    if edges.size == 0:
        return edges
    return edges + float(_match_plot_shifts(match).get(source, 0.0))


def _spike_match_count(a: np.ndarray, b: np.ndarray, tol_sec: float = 0.05) -> int:
    if a.size == 0 or b.size == 0:
        return 0
    i = 0
    j = 0
    matched = 0
    while i < len(a) and j < len(b):
        delta = float(a[i] - b[j])
        if abs(delta) <= tol_sec:
            matched += 1
            i += 1
            j += 1
        elif delta < 0:
            i += 1
        else:
            j += 1
    return matched


def _otb4_control_vs_aux2_note(otb_path: Path) -> Optional[str]:
    """Compare the SyncStation's internal digital control-buffer event log
    against its own AUX2 analog loopback capture -- the same generated
    channel-2 pulse train, read two different ways inside the OTB4 file
    itself (before any cable to C3D is involved).

    Checked whether this distinguishes well-aligned from poorly-aligned
    OTB4<->C3D pairs: it does not. A handful of pulses missing from one side
    or the other shows up on essentially every OTB4 recording, including
    ones whose channel-2 alignment against C3D is fine, so it is reported
    here for transparency but should not be read as the explanation for a
    cross-machine mismatch -- it looks like differing detection sensitivity
    between analog threshold detection (AUX2) and digital buffer logging
    (control), not a fault specific to any one recording.
    """
    try:
        diag = _extract_otb4_probe_sync_diagnostics(otb_path)
    except Exception:
        return None
    control_t = np.asarray(diag.get("control_observed_times_sec") or [], dtype=float)
    aux2_t = np.asarray(diag.get("aux2_observed_times_sec") or [], dtype=float)
    if control_t.size < 2 or aux2_t.size < 2:
        return None
    tol = 0.01
    missing_in_aux2 = int(sum(1 for t in control_t if np.min(np.abs(aux2_t - t)) > tol))
    missing_in_control = int(sum(1 for t in aux2_t if np.min(np.abs(control_t - t)) > tol))
    if missing_in_aux2 == 0 and missing_in_control == 0:
        return None
    return (
        f"OTB4-internal check: the AUX2 loopback and the SyncStation's internal control-buffer event log "
        f"differ ({missing_in_aux2} pulse(s) in the control buffer missing from AUX2, {missing_in_control} "
        f"pulse(s) in AUX2 missing from the control buffer). This also occurs on well-aligned OTB4/C3D pairs, "
        f"so it does not by itself explain the cross-machine mismatch above."
    )


def _channel3_edge_alignment_fallback(match: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    """Establish the OTB4<->C3D cross-machine alignment anchor via channel 3.

    Channel 3 (from the independent, radio-silent SyncMini, 50ms pulse width)
    is the main cross-machine confirmation signal: its detection margin at
    2000Hz is roughly 100 samples per pulse, vs channel 2's roughly 2 samples
    per pulse, so it is far less susceptible to the long-cable signal
    degradation that can intermittently drop channel-2 pulses. This function
    is only reached from `_select_otb4_c3d_edge_alignment` when channel 2
    could not find any genuinely matching pulses of its own (its quality-gated
    leading-edge search found nothing clearing the bar) -- channel 2 refines
    the alignment whenever it has real matching pulses to work with; channel
    3 carries it, on its own coarser numbers, when channel 2 has none.

    Site wiring (as described by the user): channel 2 is generated by the
    SyncStation itself -- its AuxOut is T-split to its own AUX2 input (a
    loopback: OTB4's channel-2 reading is just the SyncStation recording its
    own output, so it is inherently self-consistent) and, over the same
    T-split, to the Vicon Lock Lab feeding C3D's "2_Sync". The SyncStation
    also fires a simultaneous but electrically separate 433MHz "fire and
    forget" RF burst to the wireless EMG probes at the same instant -- that
    RF link carries no bearing on this cable signal. Channel 3 is generated
    by a separate, radio-silent SyncMini, T-split the same way to
    SyncStation AUX3 and Lock Lab channel 3, but with no loopback on either
    side (both OTB4 and C3D are independent external receivers of it).

    Because OTB4's channel-2 reading is a loopback of its own generator, a
    channel-2 mismatch against C3D is far more likely to be a cable/connector
    problem on the branch from the T-split to the Vicon Lock Lab input than
    an OTB4-side fault -- and is unrelated to the RF probe-sync link. A clean
    channel-3 alignment existing where channel 2 does not confirms the OTB4
    laptop and C3D/Vicon PC really do correspond for this recording, and
    narrows the channel-2 problem to that one cable run.
    """
    otb_path = (match.get("otb4") or {}).get("path")
    c3d_path = (match.get("c3d") or {}).get("path")
    if not otb_path or not c3d_path:
        return None
    otb_ch3 = sorted(_otb4_channel_edge_times(Path(otb_path), SYNC_OTB_DEVICE, SYNC_OTB_TSV_BRIDGE_SUBTITLE))
    c3d_ch3 = sorted(_c3d_channel_edge_times(Path(c3d_path), SYNC_C3D_TSV_BRIDGE_LABEL))
    if len(otb_ch3) < 2 or len(c3d_ch3) < 2:
        return None
    ttl_anchor = _match_ttl_anchor(match)
    ttl_shift_sec = (ttl_anchor[1] - ttl_anchor[0]) if ttl_anchor is not None else None
    summary = _best_edge_alignment_summary(
        otb_ch3, c3d_ch3, max_skip_otb=10, max_skip_c3d=10, ttl_shift_sec=ttl_shift_sec
    )
    mean_ms = summary.get("mean_abs_ms")
    max_ms = summary.get("max_abs_ms")
    if not (
        isinstance(mean_ms, (int, float))
        and isinstance(max_ms, (int, float))
        and float(mean_ms) <= 20.0
        and float(max_ms) <= 50.0
        and int(summary.get("matched_count") or 0) >= 6
    ):
        return None
    note = (
        "Channel 3 (from the independent, radio-silent SyncMini -- the main cross-machine sync signal) "
        f"anchors this alignment (mean={mean_ms:.1f}ms, max={max_ms:.1f}ms, "
        f"{int(summary.get('matched_count') or 0)} edges matched). Channel 2 (1ms) had no pulses near that "
        "anchor precise enough to refine it further. OTB4's channel-2 reading is a loopback of the "
        "SyncStation's own generated signal, so it is inherently self-consistent -- this points to a "
        "cable/connector issue on the SyncStation-to-Vicon-Lock-Lab run for this recording (the C3D-side "
        "branch of that T-split), not an OTB4-side fault, and is unrelated to the separate 433MHz RF link "
        "to the wireless probes."
    )
    control_note = _otb4_control_vs_aux2_note(Path(otb_path))
    if control_note:
        note = f"{note} {control_note}"
    otb4_skip = int(summary.get("otb4_skip") or 0)
    c3d_skip = int(summary.get("c3d_skip") or 0)
    return {
        "otb4_skip": otb4_skip,
        "c3d_skip": c3d_skip,
        "shift_sec": summary.get("shift_sec"),
        "mean_abs_ms": mean_ms,
        "max_abs_ms": max_ms,
        "matched_count": summary.get("matched_count"),
        "basis": "channel3_crossmachine_fallback",
        "diagnostic_note": note,
        # These skip indices are into the channel-3 edge arrays, not the
        # channel-2 arrays carried on match["otb4"/"c3d"]["edge_times_sec"] --
        # export/plot code must use these explicit native-time anchors
        # (see _source_sync_offset_for_match) rather than re-indexing
        # channel-2's edge_times_sec with these skip counts.
        "otb4_anchor_sec": float(otb_ch3[otb4_skip]) if otb4_skip < len(otb_ch3) else None,
        "c3d_anchor_sec": float(c3d_ch3[c3d_skip]) if c3d_skip < len(c3d_ch3) else None,
    }


def _select_otb4_c3d_edge_alignment(match: Dict[str, Any]) -> Dict[str, Any]:
    otb_edges = np.asarray(((match.get("otb4") or {}).get("edge_times_sec") or []), dtype=float)
    c3d_edges = np.asarray(((match.get("c3d") or {}).get("edge_times_sec") or []), dtype=float)
    if otb_edges.size < 2 or c3d_edges.size < 2:
        return {
            "otb4_skip": 0,
            "c3d_skip": 0,
            "shift_sec": None,
            "mean_abs_ms": None,
            "max_abs_ms": None,
            "matched_count": 0,
            "basis": "insufficient_edges",
            "late_c3d_supported": False,
        }

    alignment = match.get("alignment") or {}
    raw_quality = str(alignment.get("raw_alignment_quality") or "")
    raw_corr = alignment.get("raw_alignment_corr")
    raw_lag = alignment.get("raw_alignment_lag_sec")
    tsv = match.get("tsv") or {}
    late_c3d_supported = bool(
        tsv
        and isinstance(raw_corr, (int, float))
        and abs(float(raw_corr)) >= 0.999
        and isinstance(raw_lag, (int, float))
        and float(raw_lag) <= -1.0
    )

    def _eval(drop_otb: int, drop_c3d: int) -> Optional[Dict[str, Any]]:
        if drop_otb >= otb_edges.size or drop_c3d >= c3d_edges.size:
            return None
        n = min(len(otb_edges) - drop_otb, len(c3d_edges) - drop_c3d)
        if n < 2:
            return None
        shift_sec = float(c3d_edges[drop_c3d] - otb_edges[drop_otb])
        delta_ms = (otb_edges[drop_otb:drop_otb + n] + shift_sec - c3d_edges[drop_c3d:drop_c3d + n]) * 1000.0
        mean_abs_ms = float(np.mean(np.abs(delta_ms)))
        max_abs_ms = float(np.max(np.abs(delta_ms)))
        lag_penalty = abs(float(raw_lag) - shift_sec) * 30.0 if isinstance(raw_lag, (int, float)) else 0.0
        drop_penalty = 15.0 * float(drop_otb) + 25.0 * float(drop_c3d)
        return {
            "otb4_skip": int(drop_otb),
            "c3d_skip": int(drop_c3d),
            "shift_sec": shift_sec,
            "mean_abs_ms": mean_abs_ms,
            "max_abs_ms": max_abs_ms,
            "matched_count": int(n),
            "score": mean_abs_ms + lag_penalty + drop_penalty,
        }

    base = _eval(0, 0)
    if base is None:
        return {
            "otb4_skip": 0,
            "c3d_skip": 0,
            "shift_sec": None,
            "mean_abs_ms": None,
            "max_abs_ms": None,
            "matched_count": 0,
            "basis": "insufficient_edges",
            "late_c3d_supported": late_c3d_supported,
        }
    best = {**base, "basis": "first_visible_sync"}
    base_is_clearly_bad = bool(
        (
            isinstance(base.get("mean_abs_ms"), (int, float))
            and float(base["mean_abs_ms"]) > 80.0
        )
        or (
            isinstance(base.get("max_abs_ms"), (int, float))
            and float(base["max_abs_ms"]) > 120.0
        )
    )
    if late_c3d_supported and base_is_clearly_bad:
        best_late = best
        # Special case: C3D started late, so OTB4 can have one or more earlier pulses
        # that are absent in the C3D file. Do not skip C3D edges in this mode.
        for drop_otb in range(1, min(3, len(otb_edges) - 1) + 1):
            cand = _eval(drop_otb, 0)
            if cand is None:
                continue
            if cand["score"] < best_late["score"]:
                best_late = {**cand, "basis": "late_c3d_raw_bridge"}
        if (
            best_late["basis"] == "late_c3d_raw_bridge"
            and best_late["mean_abs_ms"] is not None
            and base["mean_abs_ms"] is not None
            and (
                float(best_late["mean_abs_ms"]) <= 25.0
                or float(best_late["mean_abs_ms"]) + 40.0 < float(base["mean_abs_ms"])
            )
        ):
            best = best_late

    if base_is_clearly_bad and best["basis"] != "late_c3d_raw_bridge":
        # Channel 1 (1_TTL) fires once, on a manual switch T-split to both
        # OTB4 and C3D simultaneously -- unlike a pulse train it can't be
        # ambiguous about *which* cycle position it's at, so where available
        # it's used to keep channel 2/3's search from locking onto the wrong
        # point in their repeating decrement pattern (a real failure mode:
        # a multi-second-wrong candidate can still show a deceptively good
        # residual over a short matched window).
        ttl_anchor = _match_ttl_anchor(match)
        ttl_shift_sec = (ttl_anchor[1] - ttl_anchor[0]) if ttl_anchor is not None else None
        ttl_tol_sec = 1.0

        # Channel 2's naive (skip 0,0) reading looks bad. Search for a wider
        # skip that clears a genuine quality bar (>=6 matched edges,
        # mean<=20ms, max<=50ms) *and*, when a TTL anchor is available, lands
        # within ttl_tol_sec of it -- this is channel 2 "refining on matching
        # pulses, if any". When channel 2 has no such matching pulses,
        # channel 3 (from the independent, radio-silent SyncMini -- the main
        # cross-machine confirmation signal, see
        # _channel3_edge_alignment_fallback) carries the alignment on its own,
        # coarser numbers instead. Channel 3 is tried first for that fallback
        # role rather than searched itself, since its own wide search can
        # just as easily lock onto the wrong cycle position when used as a
        # first resort -- channel 2's quality-gated search is the more
        # reliable of the two whenever it has real matching pulses to work
        # with.
        min_matched = 6
        max_skip = 10
        refined = None
        for drop_otb in range(0, min(max_skip, len(otb_edges) - 2) + 1):
            for drop_c3d in range(0, min(max_skip, len(c3d_edges) - 2) + 1):
                if drop_otb == 0 and drop_c3d == 0:
                    continue
                cand = _eval(drop_otb, drop_c3d)
                if cand is None or cand["matched_count"] < min_matched:
                    continue
                if not (
                    isinstance(cand.get("mean_abs_ms"), (int, float))
                    and isinstance(cand.get("max_abs_ms"), (int, float))
                    and float(cand["mean_abs_ms"]) <= 20.0
                    and float(cand["max_abs_ms"]) <= 50.0
                ):
                    continue
                if ttl_shift_sec is not None and abs(float(cand["shift_sec"]) - ttl_shift_sec) > ttl_tol_sec:
                    continue
                if refined is None or cand["score"] < refined["score"]:
                    refined = cand
        if refined is not None:
            best = {**refined, "basis": "channel2_refined"}
        else:
            ch3_anchor = _channel3_edge_alignment_fallback(match)
            if ch3_anchor is not None:
                best = {**best, **ch3_anchor}
            elif ttl_anchor is not None:
                # Neither dedicated sync channel produced a TTL-consistent
                # match (or channel 3 wasn't usable at all) -- fall back to
                # the TTL anchor itself. Coarser and not cross-validated by
                # multiple pulses, so this is never auto-acceptable (see
                # _dedicated_sync_agreement_for_edge_alignment), but it keeps
                # the reported/exported lag physically plausible instead of
                # an uncorroborated multi-second guess from a wrong-cycle-lock.
                otb_rise, c3d_rise = ttl_anchor
                best = {
                    "otb4_skip": 0,
                    "c3d_skip": 0,
                    "shift_sec": c3d_rise - otb_rise,
                    "mean_abs_ms": None,
                    "max_abs_ms": None,
                    "matched_count": 0,
                    "basis": "ttl_anchor",
                    "otb4_anchor_sec": otb_rise,
                    "c3d_anchor_sec": c3d_rise,
                    "diagnostic_note": (
                        "Aligned via channel 1 (1_TTL) -- the manual-switch signal both systems receive "
                        "simultaneously via the same T-split, and by far the most robust of the three (one "
                        "wide level transition rather than a pulse train, so it isn't vulnerable to the "
                        f"long-cable pulse degradation that can corrupt channels 2/3): lag {c3d_rise - otb_rise:.3f}s. "
                        "Channels 2 and 3 on this specific OTB4 recording are too degraded to independently "
                        "confirm or refine that further (their own widened searches only find "
                        "sawtooth-pattern coincidences at physically implausible multi-second lags, correctly "
                        "rejected against the TTL anchor) -- this reflects a cable/reception issue on this "
                        "recording, not doubt about the file pairing or the TTL lag itself. It is still a "
                        "single-point anchor, not cross-validated pulse-by-pulse like channels 2/3 normally "
                        "are, so treat the precision as coarser than a certain pair and confirm visually."
                    ),
                }
            else:
                note = (
                    "Neither channel 3 (from the independent SyncMini -- the main cross-machine sync signal) "
                    "nor channel 2 (SyncStation-generated) could be aligned between the OTB4 laptop and "
                    "C3D/Vicon PC for this pair, even after widening the search, and channel 1 (1_TTL) is "
                    "unavailable on one or both sides to sanity-check the result. Both channels 2/3 are "
                    "independently generated but T-split the same way to a Vicon Lock Lab input feeding C3D "
                    "-- both failing at once points more toward the C3D/Vicon/Lock-Lab side (or a session-wide "
                    "OTB4 clock/timing issue) than toward two unrelated generator-side faults. Confirm the "
                    "file pairing itself (e.g. via TSV bridge/CoP if available) before trusting it, and check "
                    "the Lock Lab input/cabling for this recording."
                )
                otb_path = (match.get("otb4") or {}).get("path")
                control_note = _otb4_control_vs_aux2_note(Path(otb_path)) if otb_path else None
                if control_note:
                    note = f"{note} {control_note}"
                best["diagnostic_note"] = note
    best["late_c3d_supported"] = late_c3d_supported
    return best


def _dedicated_sync_agreement_for_edge_alignment(
    match: Dict[str, Any], edge_align: Optional[Dict[str, Any]] = None
) -> Dict[str, Any]:
    """Wrapper around `_dedicated_sync_agreement` that substitutes the
    channel-3 cross-machine fallback's own numbers when that fallback was
    used for `otb4_c3d_edge_alignment`. `_dedicated_sync_agreement`'s generic
    comparison always applies `sync_edge_skips` to the channel-2 edge train
    (`match["otb4"/"c3d"]["edge_times_sec"]`); a channel-3-derived skip/shift
    would otherwise get silently misapplied to the wrong edges and report
    nonsense numbers.
    """
    if edge_align is None:
        edge_align = (match.get("alignment") or {}).get("otb4_c3d_edge_alignment") or {}
        if not edge_align and match.get("otb4") and match.get("c3d"):
            # Not every OTB4/C3D pair goes through the TSV-matching loop that
            # normally populates this (e.g. pairs with no TSV attached), so
            # the leading-edge/channel-3 diagnosis would otherwise never run
            # for them at all. Compute it lazily here so every place that
            # displays dedicated-sync quality (review UI included) benefits.
            edge_align = _select_otb4_c3d_edge_alignment(match)
            match.setdefault("alignment", {})["otb4_c3d_edge_alignment"] = edge_align
    if edge_align.get("basis") == "ttl_anchor":
        # A single-edge TTL anchor, not cross-validated pulse-by-pulse --
        # deliberately reports no pairwise spike counts (otb_c3d_count stays
        # 0 in _auto_accept_match) so this basis can never auto-accept.
        return {
            "quality": "fair",
            "pair_quality": "fair",
            "tsv_sync_missing": False,
            "source_count": 2,
            "spike_count": 0,
            "mean_abs_delta_ms": None,
            "max_abs_delta_ms": None,
            "pairwise": {},
            "basis": "ttl_anchor",
        }
    if edge_align.get("basis") != "channel3_crossmachine_fallback":
        return _dedicated_sync_agreement(match)
    mean_abs = edge_align.get("mean_abs_ms")
    max_abs = edge_align.get("max_abs_ms")
    if not (isinstance(mean_abs, (int, float)) and isinstance(max_abs, (int, float))):
        return _dedicated_sync_agreement(match)
    matched = int(edge_align.get("matched_count") or 0)
    if max_abs <= 1.0 and mean_abs <= 0.25:
        quality = "excellent"
    elif max_abs <= 5.0 and mean_abs <= 1.0:
        quality = "good"
    elif max_abs <= 20.0:
        quality = "fair"
    else:
        quality = "poor"
    return {
        "quality": quality,
        "pair_quality": quality,
        "tsv_sync_missing": False,
        "source_count": 2,
        "spike_count": matched,
        "mean_abs_delta_ms": round(float(mean_abs), 6),
        "max_abs_delta_ms": round(float(max_abs), 6),
        "pairwise": {
            "otb4_vs_c3d": {
                "mean_abs_ms": round(float(mean_abs), 6),
                "max_abs_ms": round(float(max_abs), 6),
                "count": matched,
                "matched_spikes_50ms": matched,
                "basis": "channel3_crossmachine_fallback",
            }
        },
        "basis": "channel3_crossmachine_fallback",
    }


def _dedicated_sync_agreement(match: Dict[str, Any]) -> Dict[str, Any]:
    if not match.get("otb4"):
        return {
            "quality": "not_applicable",
            "pair_quality": "not_applicable",
            "tsv_sync_missing": False,
            "source_count": 0,
            "spike_count": 0,
            "mean_abs_delta_ms": None,
            "max_abs_delta_ms": None,
            "pairwise": {},
            "basis": "raw_c3d_tsv_only",
        }

    usable: List[Tuple[str, np.ndarray]] = []
    for key in ("otb4", "c3d"):
        rec = match.get(key)
        if rec and rec.get("sync_present") and rec.get("sync_channel"):
            edges = _aligned_sync_edges(match, key)
            skip = _sync_edge_skip_count(match, key)
            if skip > 0 and skip < edges.size:
                edges = edges[skip:]
            if edges.size >= 2:
                usable.append((key, edges))

    if len(usable) < 2:
        quality = "insufficient"
    else:
        quality = "unknown"

    pairwise: Dict[str, Dict[str, Any]] = {}
    deltas: List[np.ndarray] = []
    spike_count = min((len(edges) for _name, edges in usable), default=0)
    for i in range(len(usable)):
        for j in range(i + 1, len(usable)):
            name_i, a = usable[i]
            name_j, b = usable[j]
            n = min(len(a), len(b))
            if n == 0:
                continue
            delta = (a[:n] - b[:n]) * 1000.0
            deltas.append(delta)
            pairwise[f"{name_i}_vs_{name_j}"] = {
                "mean_abs_ms": round(float(np.mean(np.abs(delta))), 6),
                "max_abs_ms": round(float(np.max(np.abs(delta))), 6),
                "count": int(n),
                "matched_spikes_50ms": int(_spike_match_count(a, b, tol_sec=0.05)),
            }

    mean_abs = None
    max_abs = None
    pair_quality = "insufficient"
    if deltas:
        spread_ms = np.concatenate([np.abs(delta) for delta in deltas])
        mean_abs = round(float(np.mean(spread_ms)), 6)
        max_abs = round(float(np.max(spread_ms)), 6)
        if max_abs <= 1.0 and mean_abs <= 0.25:
            pair_quality = "excellent"
        elif max_abs <= 5.0 and mean_abs <= 1.0:
            pair_quality = "good"
        elif max_abs <= 20.0:
            pair_quality = "fair"
        else:
            pair_quality = "poor"
        quality = pair_quality

    return {
        "quality": quality,
        "pair_quality": pair_quality,
        "tsv_sync_missing": False,
        "source_count": len(usable),
        "spike_count": int(spike_count),
        "mean_abs_delta_ms": mean_abs,
        "max_abs_delta_ms": max_abs,
        "pairwise": pairwise,
        "basis": "otb4_c3d_sync",
    }


def _detect_buffer_events_abs(values: np.ndarray, sample_rate: float) -> np.ndarray:
    x = np.abs(np.asarray(values, dtype=float).reshape(-1))
    if x.size == 0:
        return np.asarray([], dtype=int)
    x = np.nan_to_num(x, nan=0.0)
    q99 = float(np.nanpercentile(x, 99.0))
    max_abs = float(np.nanmax(x))
    if not np.isfinite(max_abs) or max_abs <= 0.0:
        return np.asarray([], dtype=int)
    if max_abs <= q99 * 4.0:
        return np.asarray([], dtype=int)
    threshold = max(max_abs * 0.5, float(np.nanpercentile(x, 99.99)))
    candidates = np.flatnonzero(x >= threshold)
    if candidates.size == 0:
        return np.asarray([], dtype=int)
    min_gap = max(1, int(round(float(sample_rate or 2000.0) * 0.15)))
    kept: List[int] = [int(candidates[0])]
    for idx in candidates[1:]:
        if int(idx) - kept[-1] >= min_gap:
            kept.append(int(idx))
    return np.asarray(kept, dtype=int)


def _schedule_interval_sec(start_interval_sec: float, step_sec: float, idx: int, min_interval_sec: float) -> float:
    start = float(start_interval_sec)
    step = float(step_sec)
    minimum = float(min_interval_sec)
    if step <= 0.0 or start <= minimum:
        return max(minimum, start)
    cycle_len = max(1, int(round((start - minimum) / step)) + 1)
    phase = int(idx) % cycle_len
    return max(minimum, start - step * float(phase))


def _schedule_gap_sec(start_interval_sec: float, step_sec: float, start_idx: int, span: int, min_interval_sec: float) -> float:
    return float(sum(_schedule_interval_sec(start_interval_sec, step_sec, start_idx + offset, min_interval_sec) for offset in range(int(span))))


def _extend_expected_times_cyclic(
    expected_times_sec: Sequence[float],
    *,
    start_interval_sec: Optional[float],
    start_phase_index: Optional[int],
    step_sec: Optional[float],
    min_interval_sec: float,
    target_start_sec: Optional[float] = None,
    target_end_sec: Optional[float] = None,
) -> List[float]:
    expected = [float(v) for v in expected_times_sec]
    if not expected:
        return expected
    if not isinstance(start_interval_sec, (int, float)) or not isinstance(start_phase_index, int) or not isinstance(step_sec, (int, float)):
        return expected
    start_interval = float(start_interval_sec)
    step = float(step_sec)
    phase0 = int(start_phase_index)
    slack_sec = max(0.2, 2.0 * abs(step))
    intervals_used = max(0, len(expected) - 1)
    next_idx = phase0 + intervals_used
    while target_end_sec is not None:
        next_time = float(expected[-1]) + _schedule_interval_sec(start_interval, step, next_idx, min_interval_sec)
        if next_time > float(target_end_sec) + slack_sec:
            break
        expected.append(next_time)
        next_idx += 1
    prev_idx = phase0 - 1
    while target_start_sec is not None and prev_idx >= 0:
        prev_time = float(expected[0]) - _schedule_interval_sec(start_interval, step, prev_idx, min_interval_sec)
        if prev_time < float(target_start_sec) - slack_sec:
            break
        expected.insert(0, prev_time)
        prev_idx -= 1
    return expected


def _fit_descending_sync_pattern(
    event_times_sec: Sequence[float],
    *,
    default_step_sec: float = 0.10,
    candidate_step_secs: Optional[Sequence[float]] = None,
    min_interval_sec: float = 3.0,
    max_missing_between: int = 4,
    cycle_start_sec: float = 5.0,
) -> Dict[str, Any]:
    observed = np.asarray(event_times_sec, dtype=float).reshape(-1)
    if observed.size == 0:
        return {
            "observed_event_count": 0,
            "expected_event_count": 0,
            "expected_times_sec": [],
            "start_interval_sec": None,
            "start_phase_index": None,
            "step_sec": None,
            "gap_mae_ms": None,
            "max_gap_error_ms": None,
            "inserted_missing_events": 0,
            "pattern_observed": False,
            "note": "no spikes detected",
        }
    if observed.size == 1:
        return {
            "observed_event_count": 1,
            "expected_event_count": 1,
            "expected_times_sec": [float(observed[0])],
            "start_interval_sec": None,
            "start_phase_index": None,
            "step_sec": None,
            "gap_mae_ms": None,
            "max_gap_error_ms": None,
            "inserted_missing_events": 0,
            "pattern_observed": False,
            "note": "single spike only",
        }

    gaps = np.diff(observed)
    start_interval_sec = float(cycle_start_sec)
    step_candidates = [float(v) for v in (candidate_step_secs or (0.05, float(default_step_sec))) if float(v) > 0.0]
    if not step_candidates:
        step_candidates = [float(default_step_sec or 0.10)]
    step_candidates = sorted({round(v, 6) for v in step_candidates})
    best: Optional[Tuple[Tuple[float, float, int, int, float], float, int, List[int], List[float]]] = None
    for step_sec in step_candidates:
        max_phase_idx = max(0, int(round(max(0.0, start_interval_sec - float(min_interval_sec)) / float(step_sec or 0.10))))
        for start_phase_idx in range(0, max_phase_idx + 1):
            gap_errors = []
            missing_between = []
            schedule_idx = int(start_phase_idx)
            for gap_sec in gaps:
                best_local: Optional[Tuple[float, int]] = None
                for missing_count in range(0, max_missing_between + 1):
                    predicted_gap_sec = _schedule_gap_sec(
                        start_interval_sec,
                        step_sec,
                        schedule_idx,
                        missing_count + 1,
                        min_interval_sec,
                    )
                    cost = abs(predicted_gap_sec - float(gap_sec))
                    cand = (cost, missing_count)
                    if best_local is None or cand < best_local:
                        best_local = cand
                assert best_local is not None
                gap_errors.append(float(best_local[0]))
                missing_between.append(int(best_local[1]))
                schedule_idx += int(best_local[1]) + 1
            score = (
                float(np.mean(gap_errors) * 1000.0),
                float(np.max(gap_errors) * 1000.0),
                int(sum(missing_between)),
                int(start_phase_idx),
                abs(float(step_sec) - float(default_step_sec)),
            )
            if best is None or score < best[0]:
                best = (score, float(step_sec), int(start_phase_idx), missing_between, gap_errors)

    assert best is not None
    score, step_sec, start_phase_idx, missing_between, gap_errors = best
    expected_times: List[float] = [float(observed[0])]
    schedule_idx = int(start_phase_idx)
    current_time = float(observed[0])
    for missing_count in missing_between:
        for _ in range(int(missing_count) + 1):
            current_time += _schedule_interval_sec(start_interval_sec, step_sec, schedule_idx, min_interval_sec)
            expected_times.append(float(current_time))
            schedule_idx += 1
    pattern_observed = bool(score[0] <= 80.0 and score[1] <= 160.0)
    return {
        "observed_event_count": int(observed.size),
        "expected_event_count": len(expected_times),
        "expected_times_sec": [float(v) for v in expected_times],
        "start_interval_sec": float(start_interval_sec),
        "start_phase_index": int(start_phase_idx),
        "step_sec": float(step_sec),
        "gap_mae_ms": float(score[0]),
        "max_gap_error_ms": float(score[1]),
        "inserted_missing_events": int(sum(missing_between)),
        "pattern_observed": pattern_observed,
        "note": (
            f"fixed cyclic 5.00->3.00 s pattern observed (step {int(round(step_sec * 1000.0))} ms, phase {int(start_phase_idx)})"
            if pattern_observed
            else f"fixed cyclic 5.00->3.00 s pattern not cleanly observed (step {int(round(step_sec * 1000.0))} ms, gap MAE {score[0]:.1f} ms, phase {int(start_phase_idx)})"
        ),
    }


def _expected_times_from_pattern_window(
    pattern: Optional[Dict[str, Any]],
    fallback_times_sec: Sequence[float],
    *,
    target_start_sec: Optional[float] = None,
    target_end_sec: Optional[float] = None,
) -> np.ndarray:
    if not pattern:
        return np.asarray(fallback_times_sec, dtype=float).reshape(-1)
    expected = _extend_expected_times_cyclic(
        pattern.get("expected_times_sec") or [],
        start_interval_sec=pattern.get("start_interval_sec"),
        start_phase_index=pattern.get("start_phase_index"),
        step_sec=pattern.get("step_sec"),
        min_interval_sec=3.0,
        target_start_sec=target_start_sec,
        target_end_sec=target_end_sec,
    )
    if expected:
        return np.asarray(expected, dtype=float)
    return np.asarray(fallback_times_sec, dtype=float).reshape(-1)


def _event_alignment_summary(
    other_times_sec: Sequence[float],
    ref_times_sec: Sequence[float],
    tolerance_sec: float = 0.15,
    *,
    trace_start_sec: Optional[float] = None,
    trace_end_sec: Optional[float] = None,
    edge_guard_sec: Optional[float] = None,
) -> Dict[str, Any]:
    other = np.asarray(other_times_sec, dtype=float).reshape(-1)
    ref = np.asarray(ref_times_sec, dtype=float).reshape(-1)
    if other.size == 0 or ref.size == 0:
        return {
            "matched_count": 0,
            "unmatched_other": int(other.size),
            "unmatched_ref": int(ref.size),
            "offset_sec": None,
            "mean_lag_ms": None,
            "mean_abs_residual_ms": None,
        }
    candidates = np.unique(np.round(np.append(0.0, (other[:, None] - ref[None, :]).reshape(-1)), 6))
    best_score: Optional[Tuple[int, float, float]] = None
    best_offset: Optional[float] = None
    best_lags_ms: List[float] = []
    best_abs_residual_ms: List[float] = []
    best_unmatched_other = int(other.size)
    best_unmatched_ref = int(ref.size)
    guard_sec = float(edge_guard_sec if edge_guard_sec is not None else max(0.02, tolerance_sec))
    for offset in candidates:
        shifted = other - float(offset)
        effective_ref = ref
        if trace_start_sec is not None and trace_end_sec is not None:
            shifted_start = float(trace_start_sec) - float(offset)
            shifted_end = float(trace_end_sec) - float(offset)
            mask = (ref >= (shifted_start - guard_sec)) & (ref <= (shifted_end + guard_sec))
            effective_ref = ref[mask]
            if effective_ref.size == 0:
                continue
        i = 0
        j = 0
        lags_ms: List[float] = []
        abs_residual_ms: List[float] = []
        while i < other.size and j < effective_ref.size:
            delta = float(shifted[i] - effective_ref[j])
            if abs(delta) <= tolerance_sec:
                raw_lag_sec = float(other[i] - effective_ref[j])
                lags_ms.append(raw_lag_sec * 1000.0)
                abs_residual_ms.append(abs(delta) * 1000.0)
                i += 1
                j += 1
                continue
            if delta < -tolerance_sec:
                i += 1
            else:
                j += 1
        unmatched_other = int(other.size - len(lags_ms))
        unmatched_ref = int(effective_ref.size - len(lags_ms))
        score = (len(lags_ms), -unmatched_ref, -unmatched_other, -float(sum(abs_residual_ms)), -abs(float(offset)))
        if best_score is None or score > best_score:
            best_score = score
            best_offset = float(offset)
            best_lags_ms = lags_ms
            best_abs_residual_ms = abs_residual_ms
            best_unmatched_other = unmatched_other
            best_unmatched_ref = unmatched_ref
    return {
        "matched_count": len(best_lags_ms),
        "unmatched_other": best_unmatched_other,
        "unmatched_ref": best_unmatched_ref,
        "offset_sec": best_offset,
        "mean_lag_ms": float(np.mean(best_lags_ms)) if best_lags_ms else None,
        "mean_abs_residual_ms": float(np.mean(best_abs_residual_ms)) if best_abs_residual_ms else None,
    }


def _otb4_pattern_quality_key(pattern: Optional[Dict[str, Any]], label: str) -> Tuple[int, float, float, int, int]:
    if not pattern:
        return (1, float("inf"), float("inf"), 1, 1)
    return (
        0 if bool(pattern.get("pattern_observed")) else 1,
        float(pattern.get("gap_mae_ms") if pattern.get("gap_mae_ms") is not None else float("inf")),
        float(pattern.get("max_gap_error_ms") if pattern.get("max_gap_error_ms") is not None else float("inf")),
        -int(pattern.get("expected_event_count") or 0),
        0 if label == "control" else 1,
    )


def _otb4_sync_status_from_alignment(summary: Dict[str, Any]) -> str:
    if int(summary.get("matched_count") or 0) <= 0:
        return "non-sync"
    if int(summary.get("unmatched_ref") or 0) == 0 and int(summary.get("unmatched_other") or 0) == 0 and float(summary.get("mean_abs_residual_ms") or 0.0) <= 25.0:
        return "synced"
    if int(summary.get("unmatched_ref") or 0) <= 1 and int(summary.get("unmatched_other") or 0) == 0:
        return "deviating"
    return "non-sync"


def _extract_otb4_probe_sync_diagnostics(
    path: Path,
    *,
    default_step_sec: Optional[float] = None,
    candidate_step_secs: Optional[Sequence[float]] = None,
) -> Dict[str, Any]:
    tracks = _load_otb4_track_data(path)
    control_buffer: Optional[Dict[str, Any]] = None
    aux2_trace: Optional[Dict[str, Any]] = None
    control_pulse_info: Optional[Dict[str, Any]] = None
    aux2_pulse_info: Optional[Dict[str, Any]] = None
    probe_buffers: Dict[str, Dict[str, Any]] = {}
    probe_ramps: Dict[str, Dict[str, Any]] = {}
    for _offset, track, raw_arr in tracks:
        if int(track.get("NumberOfChannels", 0) or 0) != 1:
            continue
        device = str(track.get("Device", "")).strip()
        subtitle = str(track.get("SubTitle", "")).strip()
        raw = np.asarray(raw_arr[0], dtype=float).reshape(-1)
        is_ramp = _is_counter_track(track, raw)
        fs = float(track.get("SamplingFrequency") or 0.0)
        t = np.arange(raw.size, dtype=float) / fs if fs > 0 else np.arange(raw.size, dtype=float)
        converted = raw * float(_track_conversion_factor(track))
        payload = {
            "device": device,
            "subtitle": subtitle,
            "sample_rate": fs,
            "time_sec": t.tolist(),
            "values": converted.tolist(),
            "raw_values": raw.tolist(),
        }
        if device == "Syncstation" and bool(track.get("IsControl")) and not subtitle and not is_ramp:
            events = _detect_buffer_events_abs(raw, fs)
            payload["event_indices"] = events.tolist()
            payload["event_times_sec"] = [float(v) for v in t[events]]
            control_buffer = payload
            control_pulse_info = _infer_pulse_duration_ms(raw, fs)
        elif device == "Syncstation" and subtitle == "AUX 2":
            events = _detect_buffer_events_abs(raw, fs)
            payload["event_indices"] = events.tolist()
            payload["event_times_sec"] = [float(v) for v in t[events]]
            aux2_trace = payload
            aux2_pulse_info = _infer_pulse_duration_ms(raw, fs)
        elif device != "Syncstation" and subtitle == "Buffer" and bool(track.get("IsControl")):
            events = _detect_buffer_events_abs(raw, fs)
            payload["event_indices"] = events.tolist()
            payload["event_times_sec"] = [float(v) for v in t[events]]
            probe_buffers[device] = payload
        elif device != "Syncstation" and (subtitle == "Ramp" or is_ramp):
            holes = _find_holes_and_jumpbacks(_to_ascending_ramp(raw))
            zones = _find_discrepancy_zones(holes["cleaned_ramp"])
            payload["ramp_zones"] = [{"start_index": int(start), "hole_samples": int(length)} for start, length in zones if int(length) > 0]
            payload["ramp_samples_added"] = int(sum(int(length) for _start, length in zones if int(length) > 0))
            probe_ramps[device] = payload

    fit_default_step_sec = float(default_step_sec) if default_step_sec not in (None, "") else 0.10
    fit_candidate_step_secs = [float(v) for v in (candidate_step_secs or []) if v not in (None, "")]
    fit_candidate_step_secs = fit_candidate_step_secs or None
    control_pattern = _fit_descending_sync_pattern(
        ((control_buffer or {}).get("event_times_sec") or []),
        default_step_sec=fit_default_step_sec,
        candidate_step_secs=fit_candidate_step_secs,
    )
    aux2_pattern = _fit_descending_sync_pattern(
        ((aux2_trace or {}).get("event_times_sec") or []),
        default_step_sec=fit_default_step_sec,
        candidate_step_secs=fit_candidate_step_secs,
    )
    reference_source, reference_pattern = min(
        [("control", control_pattern), ("aux2", aux2_pattern)],
        key=lambda item: _otb4_pattern_quality_key(item[1], item[0]),
    )
    window_start = None
    window_end = None
    observed_sets = []
    for payload in (control_buffer, aux2_trace):
        arr = np.asarray((payload or {}).get("event_times_sec") or [], dtype=float)
        if arr.size:
            observed_sets.append(arr)
    if observed_sets:
        window_start = float(min(arr[0] for arr in observed_sets))
        window_end = float(max(arr[-1] for arr in observed_sets))
    reference_expected = _expected_times_from_pattern_window(reference_pattern, (control_buffer or {}).get("event_times_sec") or [], target_start_sec=window_start, target_end_sec=window_end)
    control_expected = _expected_times_from_pattern_window(control_pattern, (control_buffer or {}).get("event_times_sec") or [], target_start_sec=window_start, target_end_sec=window_end)
    aux2_expected = _expected_times_from_pattern_window(aux2_pattern, (aux2_trace or {}).get("event_times_sec") or [], target_start_sec=window_start, target_end_sec=window_end)

    probes: List[Dict[str, Any]] = []
    for device in sorted(probe_buffers):
        buf = probe_buffers[device]
        ramp = probe_ramps.get(device)
        event_times = np.asarray(buf.get("event_times_sec") or [], dtype=float)
        probe_pattern = _fit_descending_sync_pattern(
            event_times.tolist(),
            default_step_sec=fit_default_step_sec,
            candidate_step_secs=fit_candidate_step_secs,
        )
        trace_time = np.asarray(buf.get("time_sec") or [], dtype=float)
        trace_start = float(trace_time[0]) if trace_time.size else None
        trace_end = float(trace_time[-1]) if trace_time.size else None
        ref_summary = _event_alignment_summary(event_times, reference_expected, trace_start_sec=trace_start, trace_end_sec=trace_end)
        control_summary = _event_alignment_summary(event_times, control_expected, trace_start_sec=trace_start, trace_end_sec=trace_end)
        aux2_summary = _event_alignment_summary(event_times, aux2_expected, trace_start_sec=trace_start, trace_end_sec=trace_end)
        optimal_lag_sec = ref_summary.get("offset_sec")
        shifted_event_times = (event_times - float(optimal_lag_sec or 0.0)).tolist()
        ramp_samples_added = int((ramp or {}).get("ramp_samples_added") or 0)
        ramp_zone_count = len((ramp or {}).get("ramp_zones") or [])
        sample_status = (
            f"repairable from ramp (+{ramp_samples_added} samples across {ramp_zone_count} zone(s))"
            if ramp_samples_added > 0
            else "all samples present (ramp clean)"
        )
        sync_status = _otb4_sync_status_from_alignment(ref_summary)
        probes.append(
            {
                "device": device,
                "buffer_channel": f"{device} Buffer",
                "ramp_channel": f"{device} Ramp",
                "event_count": int(event_times.size),
                "event_times_sec": [float(v) for v in event_times.tolist()],
                "shifted_event_times_sec": [float(v) for v in shifted_event_times],
                "optimal_lag_sec": float(optimal_lag_sec or 0.0),
                "sync_status": sync_status,
                "sample_status": sample_status,
                "pattern_observed_in_probe_spikes": bool(probe_pattern.get("pattern_observed")),
                "probe_pattern_note": str(probe_pattern.get("note") or ""),
                "reference_summary": ref_summary,
                "control_summary": control_summary,
                "aux2_summary": aux2_summary,
                "ramp_zone_count": ramp_zone_count,
                "ramp_samples_added": ramp_samples_added,
                "non_sync": sync_status != "synced",
            }
        )

    return {
        "reference_source": reference_source,
        "reference_pattern": reference_pattern,
        "control_pattern": control_pattern,
        "aux2_pattern": aux2_pattern,
        "control_observed_event_count": int(len((control_buffer or {}).get("event_times_sec") or [])),
        "control_observed_times_sec": [float(v) for v in ((control_buffer or {}).get("event_times_sec") or [])],
        "control_expected_event_count": int(control_pattern.get("expected_event_count") or 0),
        "aux2_observed_event_count": int(len((aux2_trace or {}).get("event_times_sec") or [])),
        "aux2_observed_times_sec": [float(v) for v in ((aux2_trace or {}).get("event_times_sec") or [])],
        "aux2_expected_event_count": int(aux2_pattern.get("expected_event_count") or 0),
        "expected_times_sec": [float(v) for v in reference_expected.tolist()],
        "configured_step_sec": float(fit_default_step_sec) if default_step_sec not in (None, "") else None,
        "candidate_step_secs": [float(v) for v in (fit_candidate_step_secs or [])],
        "control_pulse_duration_info": control_pulse_info or {},
        "aux2_pulse_duration_info": aux2_pulse_info or {},
        "probes": probes,
        "synced_probe_count": sum(1 for probe in probes if probe.get("sync_status") == "synced"),
        "non_sync_probe_count": sum(1 for probe in probes if probe.get("non_sync")),
    }


@dataclass
class SyncRecord:
    path: str
    kind: str
    sync_channel: Optional[str]
    sync_present: bool
    sync_quality: str
    sample_rate: Optional[float]
    sample_count: int
    threshold: Optional[float]
    edge_count: int
    edge_times_sec: List[float]
    intervals_sec: List[float]
    min_value: Optional[float]
    max_value: Optional[float]
    notes: List[str]
    timestamp: Optional[str] = None
    first_ts: Optional[float] = None
    last_ts: Optional[float] = None
    duration_sec: Optional[float] = None
    channel_names: Optional[List[str]] = None
    point_channel_names: Optional[List[str]] = None
    probe_sync_diagnostics: Optional[Dict[str, Any]] = None

    def to_json(self) -> Dict[str, Any]:
        return {
            "path": self.path,
            "kind": self.kind,
            "sync_channel": self.sync_channel,
            "sync_present": self.sync_present,
            "sync_quality": self.sync_quality,
            "sample_rate": self.sample_rate,
            "sample_count": self.sample_count,
            "threshold": self.threshold,
            "edge_count": self.edge_count,
            "edge_times_sec": self.edge_times_sec,
            "intervals_sec": self.intervals_sec,
            "min_value": self.min_value,
            "max_value": self.max_value,
            "notes": self.notes,
            "timestamp": self.timestamp,
            "first_ts": self.first_ts,
            "last_ts": self.last_ts,
            "duration_sec": self.duration_sec,
            "channel_names": self.channel_names or [],
            "point_channel_names": self.point_channel_names or [],
            "probe_sync_diagnostics": self.probe_sync_diagnostics or {},
        }


def _extract_otb4_record(path: Path, *, include_probe_sync_diagnostics: bool = False) -> SyncRecord:
    ts = _parse_timestamp_from_name(path)
    notes: List[str] = []
    probe_sync_diagnostics: Dict[str, Any] = {}
    try:
        x_aux, aux_meta, flat = _read_otb4_scan_info(path)
    except Exception as exc:
        return SyncRecord(
            path=str(path),
            kind="otb4",
            sync_channel=None,
            sync_present=False,
            sync_quality="missing",
            sample_rate=None,
            sample_count=0,
            threshold=None,
            edge_count=0,
            edge_times_sec=[],
            intervals_sec=[],
            min_value=None,
            max_value=None,
            notes=[f"Unable to read {SYNC_OTB_DEVICE} {SYNC_OTB_SUBTITLE}: {exc}"],
            timestamp=ts.isoformat(sep=" ") if ts else None,
            channel_names=flat,
            probe_sync_diagnostics=probe_sync_diagnostics,
        )

    x = np.asarray(x_aux, dtype=float).reshape(-1)
    sig = _orient_signal(x)
    amp = float(np.nanmax(sig))
    peaks_sec = _detect_sparse_spikes(
        x,
        float(aux_meta["sampling_frequency"]),
        prominence_grid=[max(float(np.std(sig)) * 6.0, 1e-4), max(amp * 0.15, 1e-4), max(amp * 0.25, 1e-4)],
        distance_grid_sec=[0.8, 1.0, 1.2],
    )
    intervals = np.diff(peaks_sec).tolist() if len(peaks_sec) >= 2 else []
    quality = "certain" if len(peaks_sec) >= 4 else "weak"
    notes.append(f"Selected OTB4 channel {SYNC_OTB_LABEL}.")
    notes.append("OTB4 sync extraction uses metadata-driven Syncstation AUX 2 track in volts.")
    notes.append("The generic OTB4 reader exposes duplicate control-style labels; those are ignored for sync extraction.")
    if len(peaks_sec) < 4:
        notes.append("Edge count is low; sync trace may be truncated or only partially visible.")
    if include_probe_sync_diagnostics:
        try:
            probe_sync_diagnostics = _extract_otb4_probe_sync_diagnostics(path)
            _OTB4_PROBE_DIAG_CACHE[_otb4_probe_diag_cache_key(str(path), None)] = dict(probe_sync_diagnostics)
            non_sync = int(probe_sync_diagnostics.get("non_sync_probe_count") or 0)
            total_probes = len(probe_sync_diagnostics.get("probes") or [])
            ref_source = str(probe_sync_diagnostics.get("reference_source") or "control")
            ref_expected = int((probe_sync_diagnostics.get("reference_pattern") or {}).get("expected_event_count") or 0)
            notes.append(
                f"Peripheral probe sync: reference={ref_source} expected={ref_expected} | synced={int(probe_sync_diagnostics.get('synced_probe_count') or 0)}/{total_probes} | non-sync={non_sync}."
            )
            repairable = [
                str(probe.get("device") or "")
                for probe in (probe_sync_diagnostics.get("probes") or [])
                if str(probe.get("sync_status") or "") != "synced" and "repairable from ramp" in str(probe.get("sample_status") or "")
            ]
            if repairable:
                notes.append(f"Non-sync but ramp-repairable probes: {', '.join(repairable)}.")
        except Exception as exc:
            notes.append(f"Peripheral probe sync diagnostics unavailable: {exc}")
    else:
        notes.append("Peripheral probe sync diagnostics deferred until review selection.")
    channel_names = [SYNC_OTB_LABEL] + [name for name in flat if name != SYNC_OTB_LABEL]
    return SyncRecord(
        path=str(path),
        kind="otb4",
        sync_channel=SYNC_OTB_LABEL,
        sync_present=True,
        sync_quality=quality,
        sample_rate=float(aux_meta["sampling_frequency"]),
        sample_count=int(len(x)),
        threshold=None,
        edge_count=int(len(peaks_sec)),
        edge_times_sec=[float(v) for v in peaks_sec],
        intervals_sec=[float(v) for v in intervals],
        min_value=float(np.nanmin(x)),
        max_value=float(np.nanmax(x)),
        notes=notes,
        timestamp=ts.isoformat(sep=" ") if ts else None,
        channel_names=channel_names,
        probe_sync_diagnostics=probe_sync_diagnostics,
    )


def _extract_c3d_record(path: Path) -> SyncRecord:
    c3d = _c3d_forceplat_metadata(path)["c3d"]
    labels = list(c3d["parameters"]["ANALOG"]["LABELS"]["value"])
    point_labels = list(c3d["parameters"].get("POINT", {}).get("LABELS", {}).get("value", []))
    if "LABELS2" in c3d["parameters"].get("POINT", {}):
        point_labels += list(c3d["parameters"]["POINT"]["LABELS2"]["value"])
    rate = float(c3d["parameters"]["ANALOG"]["RATE"]["value"][0])
    platform_notes: List[str] = ["C3D force-platform data is loaded on demand for raw alignment/export."]
    if SYNC_C3D_LABEL not in labels:
        ts = _parse_timestamp_from_name(path)
        return SyncRecord(
            path=str(path),
            kind="c3d",
            sync_channel=None,
            sync_present=False,
            sync_quality="missing",
            sample_rate=rate,
            sample_count=0,
            threshold=None,
            edge_count=0,
            edge_times_sec=[],
            intervals_sec=[],
            min_value=None,
            max_value=None,
            notes=[f"{SYNC_C3D_LABEL} not found in analog labels."] + platform_notes,
            timestamp=ts.isoformat(sep=" ") if ts else None,
            channel_names=labels,
            point_channel_names=point_labels,
        )

    idx = labels.index(SYNC_C3D_LABEL)
    arr = np.asarray(c3d["data"]["analogs"], dtype=float)
    subframes, n_channels, n_frames = arr.shape
    x = np.transpose(arr, (2, 0, 1)).reshape(n_frames * subframes, n_channels)[:, idx]
    sig = _orient_signal(x)
    peaks_sec = _detect_sparse_spikes(
        x,
        rate,
        prominence_grid=[max(float(np.std(sig)) * 6.0, 1e-6), max(float(np.max(sig)) * 0.15, 1e-6), max(float(np.max(sig)) * 0.25, 1e-6)],
        distance_grid_sec=[0.8, 1.0, 1.2],
    )
    quality = "certain" if len(peaks_sec) >= 4 else "weak"
    notes = [f"Selected C3D analog label {SYNC_C3D_LABEL}."] + platform_notes
    if len(peaks_sec) < 4:
        notes.append("Edge count is low; sync trace may be truncated or only partially visible.")
    return SyncRecord(
        path=str(path),
        kind="c3d",
        sync_channel=SYNC_C3D_LABEL,
        sync_present=True,
        sync_quality=quality,
        sample_rate=rate,
        sample_count=int(len(x)),
        threshold=None,
        edge_count=int(len(peaks_sec)),
        edge_times_sec=[float(v) for v in peaks_sec],
        intervals_sec=[float(v) for v in np.diff(peaks_sec).tolist()] if len(peaks_sec) >= 2 else [],
        min_value=float(np.nanmin(x)),
        max_value=float(np.nanmax(x)),
        notes=notes,
        timestamp=None,
        channel_names=labels,
        point_channel_names=point_labels,
    )


def _detect_pulse_center_edges(values: np.ndarray, sample_rate: float, *, min_width_sec: float = 0.005) -> List[float]:
    """Rise/fall threshold-crossing midpoint time (sec) for each rectangular
    pulse in a wide-plateau pulse train (e.g. channel 3's 50ms pulses) --
    the geometric center of the plateau, not its leading edge. For a 1ms
    pulse (channel 2, ~2 samples at 2kHz) leading-edge vs. center is a
    sub-ms difference that doesn't matter; for a 50ms pulse (channel 3,
    ~100 samples) it's tens of ms, which matters for overlay plots and for
    any cross-machine comparison that assumes both sides measure the "same"
    point of the pulse.
    """
    x = np.asarray(values, dtype=float).reshape(-1)
    fs = float(sample_rate or 0.0)
    if x.size < 3 or fs <= 0.0:
        return []
    sig = _orient_signal(x)
    baseline = float(np.median(sig))
    amp = float(np.nanmax(sig)) if sig.size else 0.0
    if not np.isfinite(amp) or amp <= baseline:
        return []
    threshold = baseline + (amp - baseline) * 0.5
    above = sig >= threshold
    if not np.any(above):
        return []
    change_idx = np.flatnonzero(np.diff(above.astype(np.int8)) != 0) + 1
    bounds = np.concatenate(([0], change_idx, [above.size]))
    min_width = max(1, int(round(fs * min_width_sec)))
    centers: List[float] = []
    for start, end in zip(bounds[:-1], bounds[1:]):
        if not above[start] or (end - start) < min_width:
            continue
        centers.append(((start + end - 1) / 2.0) / fs)
    return centers


@lru_cache(maxsize=64)
def _c3d_channel_edge_times(path: Path, channel_name: str) -> Tuple[float, ...]:
    """Edge times (sec, own C3D sample clock) for an arbitrary analog label
    -- the pulse-plateau center (see `_detect_pulse_center_edges`), with a
    fallback to the peak-detection settings used for the dedicated
    OTB4/C3D sync channel in `_extract_c3d_record` if thresholding doesn't
    find enough pulses (e.g. an unexpectedly noisy channel).

    Reuses `_c3d_forceplat_metadata`'s path-keyed cache for the raw parse
    instead of calling `ezc3d.c3d()` again here: this function is cached
    per (path, channel_name), so probing multiple channels on the same
    file (e.g. the channel-2 and channel-3 sync labels) used to reparse
    the whole file once per channel -- the dominant cost in analyze_folder
    once more candidates get probed per pair.
    """
    try:
        c3d = _c3d_forceplat_metadata(path)["c3d"]
        labels = list(c3d["parameters"]["ANALOG"]["LABELS"]["value"])
        if channel_name not in labels:
            return ()
        rate = float(c3d["parameters"]["ANALOG"]["RATE"]["value"][0])
        idx = labels.index(channel_name)
        arr = np.asarray(c3d["data"]["analogs"], dtype=float)
        subframes, n_channels, n_frames = arr.shape
        x = np.transpose(arr, (2, 0, 1)).reshape(n_frames * subframes, n_channels)[:, idx]
        centers_sec = _detect_pulse_center_edges(x, rate)
        if len(centers_sec) >= 4:
            return tuple(float(v) for v in centers_sec)
        sig = _orient_signal(x)
        peaks_sec = _detect_sparse_spikes(
            x,
            rate,
            prominence_grid=[max(float(np.std(sig)) * 6.0, 1e-6), max(float(np.max(sig)) * 0.15, 1e-6), max(float(np.max(sig)) * 0.25, 1e-6)],
            distance_grid_sec=[0.8, 1.0, 1.2],
        )
        return tuple(float(v) for v in peaks_sec)
    except Exception:
        return ()


def _level_edge_bounds(x: np.ndarray, fs: float) -> Dict[str, Optional[float]]:
    """Rising / falling transition times (sec) for a level-style marker
    signal (one edge up at session start, one edge down at session end),
    as opposed to a pulse train. Used for the channel-1 TTL session-bounds
    diagnostic only. Either edge may be absent (e.g. a file's own recording
    window ends before the TTL falls again) -- each is reported
    independently rather than requiring both to trust either.

    A median-centered amplitude threshold (as used for pulse trains) breaks
    down here: if the TTL stays high for nearly the whole file, the median
    itself sits at the "high" level, inverting which side looks like the
    peak. Instead this looks directly at the derivative for the single
    largest step up and single largest step down, which works regardless
    of which level dominates the file's duration.
    """
    x = np.asarray(x, dtype=float).reshape(-1)
    empty: Dict[str, Optional[float]] = {"rise_sec": None, "fall_sec": None}
    if x.size < 3 or fs is None or float(fs) <= 0.0:
        return empty
    d = np.diff(x)
    noise = float(np.std(d)) if d.size else 0.0
    if noise <= 0.0:
        return empty
    rise_idx = int(np.argmax(d))
    fall_idx = int(np.argmin(d))
    out = dict(empty)
    if float(d[rise_idx]) >= noise * 6.0:
        out["rise_sec"] = float(rise_idx + 1) / float(fs)
    if float(-d[fall_idx]) >= noise * 6.0:
        out["fall_sec"] = float(fall_idx + 1) / float(fs)
    if out["rise_sec"] is not None and out["fall_sec"] is not None and out["rise_sec"] >= out["fall_sec"]:
        # The two largest steps don't form a plausible rise-then-fall pair
        # (e.g. both are noise near the same transient) -- don't trust either.
        return empty
    return out


@lru_cache(maxsize=128)
def _ttl_channel_bounds(kind: str, path: Path) -> Dict[str, Optional[float]]:
    """Channel-1 (1_TTL) rise/fall bounds for one file, on that file's own
    local time axis. Shared by the diagnostic logger below and by the
    OTB4<->C3D alignment sanity check (`_match_ttl_anchor`) -- the rising
    edge is a single, session-wide level transition on a manual switch fed
    to both OTB4 and C3D via the same T-split, so unlike the ~2-sample-wide
    channel-2 pulses it is not vulnerable to the long-cable degradation that
    can corrupt individual dedicated-sync pulses; it is a reliable (if
    coarse, single-point) absolute time anchor.

    Cached: this is a pure function of on-disk file content (the underlying
    .otb4/.c3d/.tsv is never rewritten mid-session, only the in-memory match
    dict is mutated by repair), and it is called repeatedly for the same
    file -- once per TSV candidate evaluated for a pair (via
    `_match_ttl_anchor` inside `_select_otb4_c3d_edge_alignment`), plus once
    per diagnostic log line. Without caching, a full OTB4/C3D re-parse for
    every one of those calls dominated analyze_folder's runtime.
    """
    empty: Dict[str, Optional[float]] = {"rise_sec": None, "fall_sec": None}
    try:
        if kind == "otb4":
            _t, x, meta = _load_otb4_aux_channel(path, device=SYNC_OTB_DEVICE, subtitle=SYNC_OTB_TTL_SUBTITLE)
            fs = float(meta.get("sampling_frequency") or 0.0)
        elif kind == "c3d":
            c3d = _c3d_forceplat_metadata(path)["c3d"]
            labels = list(c3d["parameters"]["ANALOG"]["LABELS"]["value"])
            if SYNC_C3D_TTL_LABEL not in labels:
                return empty
            fs = float(c3d["parameters"]["ANALOG"]["RATE"]["value"][0])
            idx = labels.index(SYNC_C3D_TTL_LABEL)
            arr = np.asarray(c3d["data"]["analogs"], dtype=float)
            subframes, n_channels, n_frames = arr.shape
            x = np.transpose(arr, (2, 0, 1)).reshape(n_frames * subframes, n_channels)[:, idx]
        elif kind == "tsv":
            cols, df = _read_tsv_table(path)
            sync_cols = [c for c in cols if str(c).endswith(SYNC_TSV_TTL_SUFFIX)]
            if not sync_cols or "t_rel" not in df.columns:
                return empty
            t_rel = pd.to_numeric(df["t_rel"], errors="coerce").to_numpy(dtype=float)
            x = pd.to_numeric(df[sync_cols[0]], errors="coerce").to_numpy(dtype=float)
            finite = np.isfinite(t_rel) & np.isfinite(x)
            if int(np.sum(finite)) < 2:
                return empty
            t_rel = t_rel[finite]
            x = x[finite]
            dt = float(np.median(np.diff(t_rel))) if t_rel.size >= 2 else 0.0
            fs = 1.0 / dt if dt > 0 else 0.0
        else:
            return empty
        return _level_edge_bounds(x, fs)
    except Exception:
        return empty


def _match_ttl_anchor(match: Dict[str, Any]) -> Optional[Tuple[float, float]]:
    """(otb4_rise_sec, c3d_rise_sec) if channel 1's rising edge is available
    on both sides of this OTB4<->C3D pair, else None. Both systems receive
    the same manual-switch pulse simultaneously via a T-split, so these two
    numbers -- each on that file's own local time axis -- pin down the true
    OTB4<->C3D time offset to roughly detection precision (~ms), independent
    of the dedicated sync pulse trains and their repeating decrement pattern.
    """
    otb_path = (match.get("otb4") or {}).get("path")
    c3d_path = (match.get("c3d") or {}).get("path")
    if not otb_path or not c3d_path:
        return None
    otb_rise = _ttl_channel_bounds("otb4", Path(otb_path)).get("rise_sec")
    c3d_rise = _ttl_channel_bounds("c3d", Path(c3d_path)).get("rise_sec")
    if isinstance(otb_rise, (int, float)) and isinstance(c3d_rise, (int, float)):
        return float(otb_rise), float(c3d_rise)
    return None


def _log_ttl_session_bounds(kind: str, path: Path, log_lines: List[str]) -> None:
    """Best-effort channel-1 (1_TTL) session-bounds diagnostic logging. On
    the 2026-07 dataset most files only expose a single TTL edge, so a full
    start+end bound frequently cannot be validated; that is expected and
    logged as such rather than treated as an error. The rising edge alone
    (when present) is also used non-diagnostically -- see `_match_ttl_anchor`.
    """
    try:
        if kind == "c3d":
            c3d_check = _c3d_forceplat_metadata(path)["c3d"]
            if SYNC_C3D_TTL_LABEL not in list(c3d_check["parameters"]["ANALOG"]["LABELS"]["value"]):
                log_lines.append(f"[ttl] {path.name}: {SYNC_C3D_TTL_LABEL} channel not found; session bounds unavailable.")
                return
        elif kind == "tsv":
            cols, _df = _read_tsv_table(path)
            if not [c for c in cols if str(c).endswith(SYNC_TSV_TTL_SUFFIX)]:
                log_lines.append(f"[ttl] {path.name}: {SYNC_TSV_TTL_SUFFIX} column not found; session bounds unavailable.")
                return
        bounds = _ttl_channel_bounds(kind, path)
        start_sec, end_sec = bounds.get("rise_sec"), bounds.get("fall_sec")
        if start_sec is not None and end_sec is not None:
            log_lines.append(
                f"[ttl] {path.name}: session bounds start={start_sec:.3f}s end={end_sec:.3f}s "
                f"duration={end_sec - start_sec:.3f}s (diagnostic only)."
            )
        elif start_sec is not None:
            log_lines.append(
                f"[ttl] {path.name}: channel-1 rising edge at start={start_sec:.3f}s, but no falling edge was "
                f"found in this file (recording likely ends before session end)."
            )
        elif end_sec is not None:
            log_lines.append(
                f"[ttl] {path.name}: channel-1 falling edge at end={end_sec:.3f}s, but no rising edge was "
                f"found in this file (recording likely starts after session start)."
            )
        else:
            log_lines.append(f"[ttl] {path.name}: {kind} channel-1 edge not detected; session bounds unavailable.")
    except Exception as exc:
        log_lines.append(f"[ttl] {path.name}: session-bounds check unavailable ({exc}).")


def _tsv_bridge_sync_alignment(
    tsv_edges: Sequence[float],
    other_edges: Sequence[float],
    *,
    match_tol_sec: float = 0.03,
) -> Dict[str, Any]:
    """Best-lag agreement between a TSV dedicated-sync edge train and another
    file's edge train on the same physical bridge channel (e.g. C3D's
    SYNC_C3D_TSV_BRIDGE_LABEL channel).

    The BiofeedbackUI capture can drop an occasional pulse anywhere in the
    train (not just at the start/end), so a positional leading-skip search
    is not enough. Instead this probes candidate global shifts (aligning any
    of the first few TSV edges against any edge on the other side) and, for
    each candidate, greedily nearest-neighbor matches the remaining edges
    within `match_tol_sec`, picking the shift with the most matched edges
    (ties broken by lowest mean error). This tolerates arbitrary interior
    gaps on either side as long as enough edges survive to fix the shift.
    """
    tsv_arr = np.asarray(sorted(tsv_edges), dtype=float)
    other_arr = np.asarray(sorted(other_edges), dtype=float)
    if tsv_arr.size < 2 or other_arr.size < 2:
        return {"shift_sec": None, "mean_abs_ms": None, "max_abs_ms": None, "matched_count": 0, "quality": "insufficient"}

    n_probe = min(4, tsv_arr.size)
    candidate_shifts = {round(float(oj - tsv_arr[i]), 3) for i in range(n_probe) for oj in other_arr}

    def _score_shift(shift: float) -> Dict[str, Any]:
        shifted = tsv_arr + shift
        used_idx: set[int] = set()
        deltas: List[float] = []
        for t in shifted:
            j = int(np.argmin(np.abs(other_arr - t)))
            if j in used_idx or abs(other_arr[j] - t) > match_tol_sec:
                continue
            used_idx.add(j)
            deltas.append(abs(other_arr[j] - t) * 1000.0)
        if not deltas:
            return {"matched_count": 0, "mean_abs_ms": None, "max_abs_ms": None}
        return {
            "matched_count": len(deltas),
            "mean_abs_ms": float(np.mean(deltas)),
            "max_abs_ms": float(np.max(deltas)),
        }

    best: Optional[Dict[str, Any]] = None
    best_rank: Optional[Tuple[int, float]] = None
    for shift in candidate_shifts:
        cand = _score_shift(shift)
        if cand["matched_count"] == 0:
            continue
        rank = (-cand["matched_count"], cand["mean_abs_ms"])
        if best_rank is None or rank < best_rank:
            best_rank = rank
            best = {"shift_sec": float(shift), **cand}
    if best is None:
        return {"shift_sec": None, "mean_abs_ms": None, "max_abs_ms": None, "matched_count": 0, "quality": "insufficient"}

    # TSV timestamps come from a ~20 Hz biofeedback loop (median sample interval
    # commonly 40-50 ms), so edge-detection jitter of roughly half a sample is
    # the measurement noise floor, not a mismatch. Thresholds are calibrated to
    # that floor rather than to C3D/OTB4's much higher sample rates.
    min_n = min(tsv_arr.size, other_arr.size)
    if best["matched_count"] >= max(3, int(round(min_n * 0.6))) and best["max_abs_ms"] <= 60.0 and best["mean_abs_ms"] <= 30.0:
        quality = "certain"
    elif best["matched_count"] >= 3 and best["max_abs_ms"] <= 150.0:
        quality = "probable"
    else:
        quality = "weak"
    best["quality"] = quality
    return best


@lru_cache(maxsize=256)
def _read_tsv_table(path: Path) -> Tuple[List[str], pd.DataFrame]:
    with open(path, "r", encoding="utf-8-sig", newline="") as f:
        header = f.readline()
    cols = header.rstrip("\r\n").split("\t") if header else []
    df = pd.read_csv(path, sep="\t", decimal=",", encoding="utf-8-sig")
    return cols, df


def _tsv_channel_base_name(name: str) -> str:
    text = str(name).strip()
    for suffix in ("[raw]", "[offset]", "[sync]"):
        if text.lower().endswith(suffix.lower()):
            return text[: -len(suffix)].strip()
    return text


def _find_tsv_raw_offset_pair(columns: Sequence[str]) -> Tuple[Optional[str], Optional[str]]:
    raw_map = {_tsv_channel_base_name(col).lower(): str(col) for col in columns if str(col).lower().endswith("[raw]")}
    offset_map = {_tsv_channel_base_name(col).lower(): str(col) for col in columns if str(col).lower().endswith("[offset]")}
    for key, raw_col in raw_map.items():
        offset_col = offset_map.get(key)
        if offset_col:
            return raw_col, offset_col
    raw_col = next((str(col) for col in columns if str(col).lower().endswith("[raw]")), None)
    offset_col = next((str(col) for col in columns if str(col).lower().endswith("[offset]")), None)
    return raw_col, offset_col


def _tsv_numeric_column(df: pd.DataFrame, column: str) -> np.ndarray:
    if column not in df.columns:
        return np.asarray([], dtype=float)
    return pd.to_numeric(df[column], errors="coerce").to_numpy(dtype=float)


def _finite_count(values: np.ndarray) -> int:
    return int(np.sum(np.isfinite(np.asarray(values, dtype=float))))


def _fit_tsv_performed_model(desired: np.ndarray, offset: np.ndarray, performed: np.ndarray) -> Optional[Dict[str, Any]]:
    desired = np.asarray(desired, dtype=float)
    offset = np.asarray(offset, dtype=float)
    performed = np.asarray(performed, dtype=float)
    best: Optional[Dict[str, Any]] = None
    max_lag = max(0, min(12, len(performed) - 2))
    for lag in range(max_lag + 1):
        x_des = desired[:-lag] if lag else desired
        x_off = offset[:-lag] if lag else offset
        y = performed[lag:] if lag else performed
        mask = np.isfinite(x_des) & np.isfinite(x_off) & np.isfinite(y)
        if int(np.sum(mask)) < 10:
            continue
        A = np.column_stack([x_des[mask], x_off[mask], np.ones(int(np.sum(mask)), dtype=float)])
        coef, *_ = np.linalg.lstsq(A, y[mask], rcond=None)
        pred = A @ coef
        rmse = float(np.sqrt(np.mean((y[mask] - pred) ** 2)))
        cur = {
            "lag": int(lag),
            "coef": [float(v) for v in coef],
            "rmse": rmse,
            "sample_count": int(np.sum(mask)),
        }
        if best is None or rmse < float(best["rmse"]):
            best = cur
    return best


def _tsv_desired_signature(df: pd.DataFrame) -> Tuple[float, float]:
    desired = _tsv_numeric_column(df, "desired")
    desired = desired[np.isfinite(desired)]
    if desired.size == 0:
        return 0.0, 0.0
    return float(np.median(desired)), float(np.max(desired) - np.min(desired))


def _nearby_tsv_reference_dirs(path: Path) -> List[Path]:
    dirs: List[Path] = [path.parent]
    for ancestor in list(path.parents)[:4]:
        try:
            children = list(ancestor.iterdir())
        except Exception:
            children = []
        for child in children:
            if child.is_dir() and child.name.lower() == "biofeedbackapp":
                dirs.append(child)
    ordered: List[Path] = []
    seen: set[str] = set()
    for item in dirs:
        key = str(item.resolve())
        if key not in seen:
            seen.add(key)
            ordered.append(item)
    return ordered


@lru_cache(maxsize=256)
def _best_tsv_performed_model(path_str: str) -> Optional[Dict[str, Any]]:
    path = Path(path_str)
    if not path.exists():
        return None
    _cols, target_df = _read_tsv_table(path)
    raw_col, offset_col = _find_tsv_raw_offset_pair(list(target_df.columns))
    if offset_col is None:
        return None
    target_sig = _tsv_desired_signature(target_df)
    best: Optional[Dict[str, Any]] = None
    for ref_dir in _nearby_tsv_reference_dirs(path):
        for candidate in sorted(ref_dir.glob("*.tsv")):
            if candidate == path:
                continue
            try:
                _ref_cols, ref_df = _read_tsv_table(candidate)
            except Exception:
                continue
            if "performed" not in ref_df.columns or "desired" not in ref_df.columns:
                continue
            cand_raw_col, cand_offset_col = _find_tsv_raw_offset_pair(list(ref_df.columns))
            if cand_offset_col is None:
                continue
            if raw_col and cand_raw_col and _tsv_channel_base_name(cand_raw_col).lower() != _tsv_channel_base_name(raw_col).lower():
                continue
            if _tsv_channel_base_name(cand_offset_col).lower() != _tsv_channel_base_name(offset_col).lower():
                continue
            performed = _tsv_numeric_column(ref_df, "performed")
            if _finite_count(performed) < 10:
                continue
            model = _fit_tsv_performed_model(
                _tsv_numeric_column(ref_df, "desired"),
                _tsv_numeric_column(ref_df, cand_offset_col),
                performed,
            )
            if model is None:
                continue
            cand_sig = _tsv_desired_signature(ref_df)
            similarity = abs(cand_sig[0] - target_sig[0]) + 0.5 * abs(cand_sig[1] - target_sig[1])
            choice = {
                **model,
                "offset_col": offset_col,
                "similarity": float(similarity),
                "reference_path": str(candidate),
            }
            if best is None:
                best = choice
                continue
            best_key = (float(best["similarity"]), float(best["rmse"]))
            cur_key = (float(choice["similarity"]), float(choice["rmse"]))
            if cur_key < best_key:
                best = choice
    return best


def _synth_tsv_performed_values(path: Path, df: pd.DataFrame) -> Optional[np.ndarray]:
    model = _best_tsv_performed_model(str(path))
    if not model:
        return None
    offset_col = str(model.get("offset_col") or "")
    if not offset_col or offset_col not in df.columns or "desired" not in df.columns:
        return None
    desired = _tsv_numeric_column(df, "desired")
    offset = _tsv_numeric_column(df, offset_col)
    lag = int(model.get("lag") or 0)
    coef = np.asarray(model.get("coef") or [], dtype=float)
    if coef.size != 3:
        return None
    usable = len(df) - lag if lag else len(df)
    if usable <= 0:
        return None
    out = np.full(len(df), np.nan, dtype=float)
    A = np.column_stack([desired[:usable], offset[:usable], np.ones(usable, dtype=float)])
    pred = A @ coef
    if lag:
        out[lag:] = pred
        out[:lag] = float(pred[0])
    else:
        out[:] = pred
    return out


def _extract_tsv_record(path: Path) -> SyncRecord:
    cols, df = _read_tsv_table(path)
    ts = _parse_timestamp_from_name(path)
    ts_vals = pd.to_numeric(df["ts"], errors="coerce").to_numpy(dtype=float) if not df.empty and "ts" in df.columns else None
    first_ts = float(ts_vals[0]) if ts_vals is not None and len(ts_vals) else None
    last_ts = float(ts_vals[-1]) if ts_vals is not None and len(ts_vals) else None
    duration_sec = float(pd.to_numeric(df["t_rel"], errors="coerce").iloc[-1]) if not df.empty and "t_rel" in df.columns else None
    if df.empty or not cols:
        return SyncRecord(
            path=str(path),
            kind="tsv",
            sync_channel=None,
            sync_present=False,
            sync_quality="missing",
            sample_rate=None,
            sample_count=0,
            threshold=None,
            edge_count=0,
            edge_times_sec=[],
            intervals_sec=[],
            min_value=None,
            max_value=None,
            notes=["Empty or unreadable TSV file."],
            timestamp=ts.isoformat(sep=" ") if ts else None,
            first_ts=first_ts,
            last_ts=last_ts,
            duration_sec=duration_sec,
            channel_names=cols,
        )

    sync_cols = [c for c in df.columns if str(c).endswith(SYNC_TSV_EXACT_SUFFIX)]
    if not sync_cols:
        raw_cols = [c for c in df.columns if str(c).lower().endswith("[raw]")]
        return SyncRecord(
            path=str(path),
            kind="tsv",
            sync_channel=None,
            sync_present=False,
            sync_quality="missing",
            sample_rate=None,
            sample_count=int(len(df)),
            threshold=None,
            edge_count=0,
            edge_times_sec=[],
            intervals_sec=[],
            min_value=None,
            max_value=None,
            notes=["Sync column not present in TSV header."] + ([f"Available TSV raw column(s): {', '.join(raw_cols)}"] if raw_cols else []),
            timestamp=ts.isoformat(sep=" ") if ts else None,
            first_ts=first_ts,
            last_ts=last_ts,
            duration_sec=duration_sec,
            channel_names=list(df.columns),
        )

    col = sync_cols[0]
    x = pd.to_numeric(df[col], errors="coerce").to_numpy(dtype=float)
    med = np.nanmedian(x) if np.any(np.isfinite(x)) else 0.0
    x = np.nan_to_num(x, nan=med)
    minv = float(np.nanmin(x))
    maxv = float(np.nanmax(x))
    notes = [f"Selected TSV sync column {col}."]
    if maxv - minv < 0.05:
        notes.append("Low dynamic range detected; sync is likely weak or missing.")
    if "t_rel" in df.columns:
        t_rel = pd.to_numeric(df["t_rel"], errors="coerce").to_numpy(dtype=float)
        if len(t_rel) > 2 and np.all(np.isfinite(t_rel)) and np.median(np.diff(t_rel)) > 0:
            sample_rate = float(1.0 / np.median(np.diff(t_rel)))
        else:
            sample_rate = None
    else:
        t_rel = None
        sample_rate = None
    edge_axis = t_rel if t_rel is not None else np.arange(len(x), dtype=float)
    peaks_sec = _detect_tsv_spikes_with_template(x, edge_axis)
    if len(peaks_sec) < 2:
        notes.append("No reliable sync spikes found in TSV exact sync column.")
    quality = "certain" if len(peaks_sec) >= 4 and maxv - minv >= 0.01 else "weak"
    return SyncRecord(
        path=str(path),
        kind="tsv",
        sync_channel=col,
        sync_present=True,
        sync_quality=quality,
        sample_rate=sample_rate,
        sample_count=int(len(x)),
        threshold=None,
        edge_count=int(len(peaks_sec)),
        edge_times_sec=[float(v) for v in peaks_sec],
        intervals_sec=[float(v) for v in np.diff(peaks_sec).tolist()] if len(peaks_sec) >= 2 else [],
        min_value=minv,
        max_value=maxv,
        notes=notes,
        timestamp=ts.isoformat(sep=" ") if ts else None,
        first_ts=first_ts,
        last_ts=last_ts,
        duration_sec=duration_sec,
        channel_names=list(df.columns),
    )


def _pulse_train_signature_from_events(event_times_sec: Sequence[float]) -> Optional[Dict[str, Any]]:
    """Score an already-detected sequence of pulse-edge times for the
    descending-interval signature shared by SyncMini/Syncstation-style
    dedicated sync channels (2_Sync, 3_Sync_50ms), independent of the
    channel's name. Callers detect edges with whichever spike-detector
    already suits that source type (`_detect_sparse_spikes` for OTB4/C3D,
    `_detect_tsv_spikes_with_template` for TSV) so discovery scoring uses
    the exact same, already-proven detection machinery as real extraction
    rather than a cruder from-scratch edge finder.

    Real dedicated-sync channels occasionally drop a pulse (2_Sync's RF
    probe path is expected to -- "ok to miss some as long as the data is
    complete in between"), which merges two consecutive gaps into one and
    corrupts a naive linear trend correlation with ~2x outlier gaps. This
    instead looks at gap-to-gap ratios: a "continuation" (no pulse missed
    between the two gaps) has a ratio near 1; a missed pulse lands the
    ratio near an integer >= ~1.6. Only continuation transitions are used
    to judge the decrement trend, so occasional drops don't hide a real
    pattern or fabricate a fake one.
    """
    times = sorted(float(v) for v in event_times_sec)
    if len(times) < 5:
        return None
    gaps = np.diff(times)
    if len(gaps) < 4 or float(np.std(gaps)) < 1e-6:
        return None
    ratios = gaps[1:] / gaps[:-1]
    continuation = np.abs(ratios - 1.0) <= 0.3
    if int(continuation.sum()) < 3:
        return None
    diffs_ms = (gaps[1:] - gaps[:-1])[continuation] * 1000.0
    median_step_ms = float(np.median(diffs_ms))
    spread_ms = float(np.median(np.abs(diffs_ms - median_step_ms)))
    descending = bool(median_step_ms < -5.0 and spread_ms <= max(20.0, abs(median_step_ms) * 0.6))
    return {
        "edge_count": len(times),
        "decrement_ms": round(-median_step_ms, 3),
        "step_consistency_ms": round(spread_ms, 3),
        "skipped_transitions": int(continuation.size - continuation.sum()),
        "descending_pattern": descending,
    }


def _summarize_channel_candidates(scored: Dict[Any, Dict[str, Any]], *, label_fn) -> List[Dict[str, Any]]:
    out: List[Dict[str, Any]] = []
    for key, entry in scored.items():
        samples = entry.get("samples") or []
        if not samples:
            continue
        descending_votes = sum(1 for s in samples if s.get("descending_pattern"))
        descending_decrements = [float(s["decrement_ms"]) for s in samples if s.get("descending_pattern")]
        widths = [float(w) for w in (entry.get("pulse_widths_ms") or []) if w is not None]
        # Require the descending pattern in a majority of *and at least two*
        # sampled files before trusting it -- a single-file "1.0 confidence"
        # is not statistically meaningful and was producing false positives
        # on noisy/short channels (eye tracking, etc.).
        confidence = (descending_votes / len(samples)) if len(samples) >= 2 else 0.0
        out.append(
            {
                "label": label_fn(key, entry),
                "device": entry.get("device"),
                "subtitle": entry.get("subtitle"),
                "sample_count": len(samples),
                "descending_pattern_votes": descending_votes,
                "pulse_width_ms": round(float(np.median(widths)), 3) if widths else None,
                "decrement_ms": round(
                    float(np.median(descending_decrements or [s["decrement_ms"] for s in samples])), 3
                ),
                "median_edge_count": round(float(np.median([s["edge_count"] for s in samples])), 1),
                "confidence": round(confidence, 3),
                # Dedicated trigger inputs (e.g. Syncstation AUX N) are the
                # right channel for the OTB4<->C3D/TSV-bridge role even when
                # a probe's own Buffer/Ramp control channel shows the same
                # pattern by virtue of being locked to the same clock -- so
                # this outranks raw statistical confidence, not just ties.
                "is_trigger_like": bool(entry.get("is_trigger_like")),
            }
        )
    out.sort(
        key=lambda item: (
            0 if item["is_trigger_like"] else 1,
            -item["confidence"],
            -item["sample_count"],
            -item["median_edge_count"],
        )
    )
    return out


def _otb4_sync_channel_candidates(paths: Sequence[Path], *, sample_limit: int = 3) -> List[Dict[str, Any]]:
    scored: Dict[Tuple[str, str], Dict[str, Any]] = {}
    for path in list(paths)[:sample_limit]:
        try:
            tracks_data = _load_otb4_track_data(path)
        except Exception:
            continue
        for _offset, track, raw_arr in tracks_data:
            if int(track.get("NumberOfChannels", 0) or 0) != 1:
                continue
            raw = raw_arr[0]
            if _is_counter_track(track, raw):
                continue
            device = str(track.get("Device") or "").strip()
            subtitle = str(track.get("SubTitle") or "").strip()
            fs = float(track.get("SamplingFrequency") or 0.0)
            if fs <= 0.0:
                continue
            x = raw.astype(float)
            sig_x = _orient_signal(x)
            amp = float(np.nanmax(sig_x)) if sig_x.size else 0.0
            event_times_sec = _detect_sparse_spikes(
                x,
                fs,
                prominence_grid=[max(float(np.std(sig_x)) * 6.0, 1e-4), max(amp * 0.15, 1e-4), max(amp * 0.25, 1e-4)],
                distance_grid_sec=[0.8, 1.0, 1.2],
            )
            sig = _pulse_train_signature_from_events(event_times_sec)
            if sig is None:
                continue
            key = (device, subtitle)
            entry = scored.setdefault(
                key,
                {
                    "device": device,
                    "subtitle": subtitle,
                    "samples": [],
                    "pulse_widths_ms": [],
                    "is_trigger_like": _track_prefers_voltage_units(track),
                },
            )
            entry["samples"].append(sig)
            width_info = _infer_pulse_duration_ms(x, fs)
            if width_info.get("observed_width_ms_mode") is not None:
                entry["pulse_widths_ms"].append(float(width_info["observed_width_ms_mode"]))
    return _summarize_channel_candidates(scored, label_fn=lambda _k, v: f"{v['device']} {v['subtitle']}".strip())


def _c3d_sync_channel_candidates(paths: Sequence[Path], *, sample_limit: int = 3) -> List[Dict[str, Any]]:
    scored: Dict[str, Dict[str, Any]] = {}
    for path in list(paths)[:sample_limit]:
        try:
            c3d = _c3d_forceplat_metadata(path)["c3d"]
            labels = list(c3d["parameters"]["ANALOG"]["LABELS"]["value"])
            rate = float(c3d["parameters"]["ANALOG"]["RATE"]["value"][0])
            arr = np.asarray(c3d["data"]["analogs"], dtype=float)
        except Exception:
            continue
        subframes, n_channels, n_frames = arr.shape
        flat = np.transpose(arr, (2, 0, 1)).reshape(n_frames * subframes, n_channels)
        for idx, label in enumerate(labels):
            x = flat[:, idx]
            sig_x = _orient_signal(x)
            event_times_sec = _detect_sparse_spikes(
                x,
                rate,
                prominence_grid=[
                    max(float(np.std(sig_x)) * 6.0, 1e-6),
                    max(float(np.max(sig_x)) * 0.15, 1e-6) if sig_x.size else 1e-6,
                    max(float(np.max(sig_x)) * 0.25, 1e-6) if sig_x.size else 1e-6,
                ],
                distance_grid_sec=[0.8, 1.0, 1.2],
            )
            sig = _pulse_train_signature_from_events(event_times_sec)
            if sig is None:
                continue
            entry = scored.setdefault(label, {"label": label, "samples": [], "pulse_widths_ms": []})
            entry["samples"].append(sig)
            width_info = _infer_pulse_duration_ms(x, rate)
            if width_info.get("observed_width_ms_mode") is not None:
                entry["pulse_widths_ms"].append(float(width_info["observed_width_ms_mode"]))
    return _summarize_channel_candidates(scored, label_fn=lambda k, _v: str(k))


def _tsv_sync_channel_candidates(paths: Sequence[Path], *, sample_limit: int = 3) -> List[Dict[str, Any]]:
    scored: Dict[str, Dict[str, Any]] = {}
    for path in list(paths)[:sample_limit]:
        try:
            cols, df = _read_tsv_table(path)
        except Exception:
            continue
        if df.empty or "t_rel" not in df.columns:
            continue
        t_rel = pd.to_numeric(df["t_rel"], errors="coerce").to_numpy(dtype=float)
        if len(t_rel) < 3 or not np.all(np.isfinite(t_rel[:3])):
            continue
        for col in cols:
            col_l = str(col).lower()
            if "[sync]" not in col_l and "volt" not in col_l:
                continue
            x = pd.to_numeric(df[col], errors="coerce").to_numpy(dtype=float)
            med = float(np.nanmedian(x)) if np.any(np.isfinite(x)) else 0.0
            x = np.nan_to_num(x, nan=med)
            event_times_sec = _detect_tsv_spikes_with_template(x, t_rel)
            sig = _pulse_train_signature_from_events(event_times_sec)
            if sig is None:
                continue
            entry = scored.setdefault(str(col), {"label": str(col), "samples": [], "pulse_widths_ms": []})
            entry["samples"].append(sig)
    return _summarize_channel_candidates(scored, label_fn=lambda k, _v: str(k))


@lru_cache(maxsize=16)
def _discover_sync_channel_candidates(folder: Path, *, sample_limit: int = 3) -> Dict[str, Any]:
    """Scan a sample of files per source type and rank channels by how much
    they look like a dedicated sync pulse train (see
    `_pulse_train_signature_from_events`), independent of channel *name*. Surfaces
    candidates for the OTB4<->C3D dedicated-sync role and the TSV<->C3D/OTB4
    bridge role without assuming today's fixed labels, so a future device
    naming change can be caught (and picked from) instead of silently
    producing zero matches.

    Cached: this re-samples and re-scores files on every call, and multiple
    call sites (primary pairing fallback, weak-pair rescue) invoke it once
    per analyze_folder run for the same folder.
    """
    excluded = ("matched", "accepted", "__pycache__", ".git")
    otb4_paths = _iter_source_files(folder, ".otb4", excluded_dir_names=excluded)
    c3d_paths = _iter_source_files(folder, ".c3d", excluded_dir_names=excluded)
    tsv_paths = _iter_source_files(folder, ".tsv", excluded_dir_names=excluded)
    return {
        "otb4_candidates": _otb4_sync_channel_candidates(otb4_paths, sample_limit=sample_limit) if otb4_paths else [],
        "c3d_candidates": _c3d_sync_channel_candidates(c3d_paths, sample_limit=sample_limit) if c3d_paths else [],
        "tsv_candidates": _tsv_sync_channel_candidates(tsv_paths, sample_limit=sample_limit) if tsv_paths else [],
    }


def _best_channel_by_decrement(
    reference: Dict[str, Any], pool: Sequence[Dict[str, Any]], exclude_labels: set
) -> Optional[Dict[str, Any]]:
    """Find the candidate in `pool` whose decrement-interval is closest to
    `reference`'s -- the cross-source-type pairing signal used to match an
    OTB4 track to a C3D label, or a C3D label to a TSV column, without
    relying on any of them sharing a name.
    """
    ref_decrement = reference.get("decrement_ms")
    if ref_decrement is None:
        return None
    best, best_score = None, None
    for cand in pool:
        if cand.get("label") in exclude_labels or cand.get("decrement_ms") is None:
            continue
        score = abs(float(ref_decrement) - float(cand["decrement_ms"]))
        if best_score is None or score < best_score:
            best, best_score = cand, score
    return best if best_score is not None and best_score <= 10.0 else None


def _resolve_sync_channel_roles(discovery: Dict[str, Any]) -> Dict[str, Any]:
    """Pair up the best OTB4/C3D/TSV sync-channel candidates from
    `_discover_sync_channel_candidates` into the two roles the matcher
    actually needs: the OTB4<->C3D dedicated sync channel, and the
    TSV<->C3D/OTB4 bridge channel (present only if a matching TSV
    candidate exists). Candidates are paired by decrement-interval
    similarity, not by name, so this keeps working if the channel names
    change again -- it's the mechanism a Stage 2 confirmation dialog would
    pre-select from.
    """
    otb4_candidates = discovery.get("otb4_candidates") or []
    c3d_candidates = discovery.get("c3d_candidates") or []
    tsv_candidates = discovery.get("tsv_candidates") or []

    # Only consider OTB4 candidates that look like dedicated trigger inputs
    # (falls back to all candidates if none were classified as trigger-like,
    # e.g. a device naming scheme this heuristic doesn't recognize).
    trigger_candidates = [c for c in otb4_candidates if c.get("is_trigger_like")] or otb4_candidates

    used_c3d: set = set()
    paired: List[Dict[str, Any]] = []
    for otb4_cand in trigger_candidates:
        c3d_match = _best_channel_by_decrement(otb4_cand, c3d_candidates, used_c3d)
        if c3d_match is None:
            continue
        used_c3d.add(c3d_match["label"])
        # Annotate every paired candidate with its own TSV match (if any) up
        # front, not just the eventual recommendation -- a caller building a
        # full candidate list (e.g. a confirmation dialog) needs accurate
        # per-option info, not just the winner's.
        tsv_match = _best_channel_by_decrement(c3d_match, tsv_candidates, set())
        entry = {"otb4": otb4_cand, "c3d": c3d_match}
        if tsv_match is not None:
            entry["tsv"] = tsv_match
        paired.append(entry)

    bridge_pair = next((p for p in paired if "tsv" in p), None)
    non_bridge_pairs = [
        p for p in paired if bridge_pair is None or p["c3d"]["label"] != bridge_pair["c3d"]["label"]
    ]
    dedicated_pair = non_bridge_pairs[0] if non_bridge_pairs else (paired[0] if paired else None)

    return {
        "otb4_c3d_sync": dedicated_pair,
        "tsv_bridge_sync": bridge_pair,
        "all_paired_candidates": paired,
    }


def _apply_otb4_repairs(matches: List[Dict[str, Any]], log_lines: List[str]) -> None:
    for match in matches:
        if not (match.get("otb4") and match.get("c3d")):
            continue
        otb_path = Path(match["otb4"]["path"])
        fs = float(match["otb4"].get("sample_rate") or 2000.0)
        c3d_edges = match["c3d"].get("edge_times_sec") or []
        base_pairwise = ((_triplet_spike_agreement([match["otb4"], match["c3d"]]).get("pairwise") or {}).get("otb4_vs_c3d") or {})
        base_mean_ms = base_pairwise.get("mean_abs_ms")
        base_max_ms = base_pairwise.get("max_abs_ms")
        if isinstance(base_mean_ms, (int, float)) and isinstance(base_max_ms, (int, float)):
            if float(base_mean_ms) <= 20.0 and float(base_max_ms) <= 50.0:
                match.setdefault("alignment", {})["otb4_repair"] = {
                    "applied": False,
                    "repair_source": "skipped_good_base_sync",
                    "base_mean_abs_ms": base_mean_ms,
                    "base_max_abs_ms": base_max_ms,
                    "block_reason": "base_otb4_c3d_sync_already_good",
                    "zones": [],
                }
                continue
        candidates = _detect_otb4_repair_candidates(
            otb_path,
            match["otb4"].get("edge_times_sec") or [],
            c3d_edges,
            fs,
        )
        if not candidates:
            continue

        def _zones_to_infos(zones_in: Sequence[Tuple[int, int]], shift_sec: float) -> List[Dict[str, Any]]:
            out: List[Dict[str, Any]] = []
            for start_index, hole_samples in zones_in:
                if int(hole_samples) <= 0:
                    continue
                out.append(
                    {
                        "start_index": int(start_index),
                        "hole_samples": int(hole_samples),
                        "start_sec": round(int(start_index) / fs, 6),
                        "end_sec": round((int(start_index) + int(hole_samples)) / fs, 6),
                        "aligned_start_sec": round(int(start_index) / fs + float(shift_sec), 6),
                        "aligned_end_sec": round((int(start_index) + int(hole_samples)) / fs + float(shift_sec), 6),
                    }
                )
            return out

        device_repairs: Dict[str, Dict[str, Any]] = {}
        for candidate in candidates:
            device = str(candidate.get("device") or "").strip()
            if not device or device in device_repairs:
                continue
            device_repairs[device] = {
                "applied": False,
                "repair_source": "matlab_ramp_gap_detection",
                "device": device,
                "subtitle": candidate.get("subtitle"),
                "track_offset": candidate.get("track_offset"),
                "candidate_mean_abs_ms": candidate.get("mean_abs_ms"),
                "candidate_max_abs_ms": candidate.get("max_abs_ms"),
                "matched_edges": candidate.get("matched_edges"),
                "samples_added": candidate.get("samples_added"),
                "zones": _zones_to_infos(
                    _merge_index_zones(
                        [
                            (int(zone.get("start_index") or 0), int(zone.get("hole_samples") or 0))
                            for zone in (candidate.get("zones") or [])
                            if int(zone.get("hole_samples") or 0) > 0
                        ]
                    ),
                    float(_match_plot_shifts(match).get("otb4", 0.0)),
                ),
                "hole_groups": candidate.get("hole_groups") or [],
                "jumpback_groups": candidate.get("jumpback_groups") or [],
            }
        if device_repairs:
            match.setdefault("alignment", {})["otb4_device_repairs"] = device_repairs

        def _candidate_zone_tuples(candidate_in: Dict[str, Any]) -> List[Tuple[int, int]]:
            return _merge_index_zones(
                [
                    (int(zone.get("start_index") or 0), int(zone.get("hole_samples") or 0))
                    for zone in (candidate_in.get("zones") or [])
                    if int(zone.get("hole_samples") or 0) > 0
                ]
            )

        def _summary_key(summary_in: Dict[str, Any]) -> Tuple[float, float, float, int, int]:
            mean_val = summary_in.get("mean_abs_ms")
            max_val = summary_in.get("max_abs_ms")
            ok = (
                isinstance(mean_val, (int, float))
                and isinstance(max_val, (int, float))
                and float(mean_val) <= 20.0
                and float(max_val) <= 50.0
            )
            return (
                0.0 if ok else 1.0,
                float(mean_val) if isinstance(mean_val, (int, float)) else 1e9,
                float(max_val) if isinstance(max_val, (int, float)) else 1e9,
                int(summary_in.get("otb4_skip") or 0) + int(summary_in.get("c3d_skip") or 0),
                -int(summary_in.get("matched_count") or 0),
            )

        option_rows: List[Dict[str, Any]] = []
        base_summary = _best_edge_alignment_summary(match["otb4"].get("edge_times_sec") or [], c3d_edges)
        option_rows.append(
            {
                "name": "none",
                "zones": [],
                "summary": base_summary,
                "edges": list(match["otb4"].get("edge_times_sec") or []),
                "samples_added": 0,
                "components": [],
                "device": None,
                "subtitle": None,
                "track_offset": None,
                "hole_groups": [],
                "jumpback_groups": [],
            }
        )
        for candidate in candidates:
            zones = _candidate_zone_tuples(candidate)
            option_rows.append(
                {
                    "name": f"{candidate.get('device')} {candidate.get('subtitle')}",
                    "zones": zones,
                    "summary": _best_edge_alignment_summary(
                        _detect_otb4_edges_with_zones(otb_path, zones, fs),
                        c3d_edges,
                    ),
                    "edges": _detect_otb4_edges_with_zones(otb_path, zones, fs),
                    "samples_added": int(sum(length for _start, length in zones)),
                    "components": [candidate],
                    "device": candidate.get("device"),
                    "subtitle": candidate.get("subtitle"),
                    "track_offset": candidate.get("track_offset"),
                    "hole_groups": candidate.get("hole_groups") or [],
                    "jumpback_groups": candidate.get("jumpback_groups") or [],
                }
            )
        primary = candidates[0]
        primary_zones = _candidate_zone_tuples(primary)
        for extra in candidates[1:]:
            extra_zones = _candidate_zone_tuples(extra)
            zones = _merge_index_zones(primary_zones + extra_zones)
            edges = _detect_otb4_edges_with_zones(otb_path, zones, fs)
            option_rows.append(
                {
                    "name": f"{primary.get('device')}+{extra.get('device')}",
                    "zones": zones,
                    "summary": _best_edge_alignment_summary(edges, c3d_edges),
                    "edges": edges,
                    "samples_added": int(sum(length for _start, length in zones)),
                    "components": [primary, extra],
                    "device": f"{primary.get('device')} + {extra.get('device')}",
                    "subtitle": f"{primary.get('subtitle')} + {extra.get('subtitle')}",
                    "track_offset": [primary.get("track_offset"), extra.get("track_offset")],
                    "hole_groups": list(primary.get("hole_groups") or []) + list(extra.get("hole_groups") or []),
                    "jumpback_groups": list(primary.get("jumpback_groups") or []) + list(extra.get("jumpback_groups") or []),
                }
            )

        selected = min(option_rows, key=lambda row: _summary_key(row["summary"]))
        if selected["zones"]:
            selected_zone_set = set(selected["zones"])
            for candidate in candidates:
                extra_zones = _candidate_zone_tuples(candidate)
                if not extra_zones:
                    continue
                if set(extra_zones).issubset(selected_zone_set):
                    continue
                union_zones = _merge_index_zones(selected["zones"] + extra_zones)
                union_edges = _detect_otb4_edges_with_zones(otb_path, union_zones, fs)
                union_summary = _best_edge_alignment_summary(union_edges, c3d_edges)
                union_row = {
                    "name": f"{selected['name']}+{candidate.get('device')}",
                    "zones": union_zones,
                    "summary": union_summary,
                    "edges": union_edges,
                    "samples_added": int(sum(length for _start, length in union_zones)),
                    "components": list(selected.get("components") or []) + [candidate],
                    "device": " + ".join(
                        [
                            part
                            for part in [str(selected.get("device") or "").strip(), str(candidate.get("device") or "").strip()]
                            if part
                        ]
                    ),
                    "subtitle": " + ".join(
                        [
                            part
                            for part in [str(selected.get("subtitle") or "").strip(), str(candidate.get("subtitle") or "").strip()]
                            if part
                        ]
                    ),
                    "track_offset": [selected.get("track_offset"), candidate.get("track_offset")],
                    "hole_groups": list(selected.get("hole_groups") or []) + list(candidate.get("hole_groups") or []),
                    "jumpback_groups": list(selected.get("jumpback_groups") or []) + list(candidate.get("jumpback_groups") or []),
                }
                if _summary_key(union_summary) < _summary_key(selected["summary"]):
                    selected = union_row
        repair_block_reason = _repair_application_block_reason(
            base_summary,
            selected,
            sample_count=int(match["otb4"].get("sample_count") or 0),
        )
        if repair_block_reason:
            selected = option_rows[0]
        shift = float(_match_plot_shifts(match).get("otb4", 0.0))
        repair = {
            "applied": bool(selected["zones"]),
            "repair_source": "matlab_ramp_gap_detection",
            "device": selected.get("device"),
            "subtitle": selected.get("subtitle"),
            "track_offset": selected.get("track_offset"),
            "base_mean_abs_ms": base_mean_ms,
            "base_max_abs_ms": base_max_ms,
            "candidate_mean_abs_ms": ((candidates[0] if candidates else {}).get("mean_abs_ms")),
            "candidate_max_abs_ms": ((candidates[0] if candidates else {}).get("max_abs_ms")),
            "repaired_mean_abs_ms": selected["summary"].get("mean_abs_ms") if selected["zones"] else None,
            "repaired_max_abs_ms": selected["summary"].get("max_abs_ms") if selected["zones"] else None,
            "matched_edges": selected["summary"].get("matched_count"),
            "samples_added": selected["samples_added"],
            "zones": _zones_to_infos(selected["zones"], shift),
            "hole_groups": selected.get("hole_groups") or [],
            "jumpback_groups": selected.get("jumpback_groups") or [],
            "repaired_edge_times_sec": selected["edges"] if selected["zones"] else [],
            "selected_option": selected["name"],
            "selected_otb4_skip": selected["summary"].get("otb4_skip"),
            "selected_c3d_skip": selected["summary"].get("c3d_skip"),
            "selected_shift_sec": selected["summary"].get("shift_sec"),
            "selected_matched_count": selected["summary"].get("matched_count"),
            "component_devices": [str(comp.get("device") or "") for comp in selected.get("components") or []],
            "component_subtitles": [str(comp.get("subtitle") or "") for comp in selected.get("components") or []],
            "block_reason": repair_block_reason,
        }
        match.setdefault("alignment", {})["otb4_repair"] = repair
        if not repair["applied"]:
            best_candidate = candidates[0]
            best_candidate_zones = _candidate_zone_tuples(best_candidate)
            match["otb4"].setdefault("notes", []).append(
                f"OTB4 gap candidate detected from {best_candidate['device']} {best_candidate['subtitle']}: "
                f"{len(best_candidate_zones)} zones, +{best_candidate.get('samples_added')} samples, not auto-applied."
            )
            log_lines.append(
                f"[repair] match {match['match_id']:03d}: detected OTB4 gap candidate {candidates[0]['device']} {candidates[0]['subtitle']} "
                f"with {len(candidates[0].get('zones') or [])} zones and +{repair['samples_added']} samples, but kept mean_abs {candidates[0].get('mean_abs_ms')} ms "
                f"vs base {base_mean_ms} ms so it was not applied."
            )
            if repair_block_reason:
                match["otb4"].setdefault("notes", []).append(f"OTB4 repair blocked: {repair_block_reason}.")
                log_lines.append(
                    f"[repair] match {match['match_id']:03d}: blocked repair candidate because {repair_block_reason}."
                )
            continue
        match["otb4"]["edge_times_sec"] = list(repair["repaired_edge_times_sec"])
        match["otb4"]["edge_count"] = len(match["otb4"]["edge_times_sec"])
        match["otb4"]["intervals_sec"] = [float(v) for v in np.diff(np.asarray(match["otb4"]["edge_times_sec"], dtype=float)).tolist()] if len(match["otb4"]["edge_times_sec"]) >= 2 else []
        match["otb4"]["sample_count"] = int(match["otb4"].get("sample_count") or 0) + int(repair["samples_added"] or 0)
        match["otb4"].setdefault("notes", []).append(
            f"OTB4 repair applied from {repair['device']} {repair['subtitle']}: +{repair['samples_added']} NaN gap samples."
        )

        # selected["summary"] is only the alignment achieved by *this specific*
        # repair candidate at selection time (no skip search, used purely to
        # rank candidates against each other) -- it can be far worse than what
        # the general, TTL-gated search in _select_otb4_c3d_edge_alignment
        # finds once the repaired edge times are in place (e.g. a pair whose
        # OTB4 gap-repair fixed a dropped-packet gap but whose true alignment
        # still needs the widened channel-2/3/TTL search to resolve). Recompute
        # with the canonical method now that match["otb4"] reflects the repair,
        # rather than overwriting with the cruder candidate-ranking summary.
        final_edge_align = _select_otb4_c3d_edge_alignment(match)
        match["alignment"]["sync_edge_skips"] = {
            "otb4": int(final_edge_align.get("otb4_skip") or 0),
            "c3d": int(final_edge_align.get("c3d_skip") or 0),
            "tsv": int((((match.get("alignment") or {}).get("sync_edge_skips") or {}).get("tsv") or 0)),
        }
        match["alignment"]["otb4_c3d_edge_alignment"] = final_edge_align
        repair["zones"] = _zones_to_infos(selected["zones"], float(_match_plot_shifts(match).get("otb4", 0.0)))

        raw_result = {
            "quality": (match.get("alignment") or {}).get("raw_alignment_quality"),
            "corr": (match.get("alignment") or {}).get("raw_alignment_corr"),
            "lag_sec": (match.get("alignment") or {}).get("raw_alignment_lag_sec"),
        }
        match["alignment"]["raw_alignment_quality"] = _effective_raw_quality(raw_result, final_edge_align)
        dedicated = _dedicated_sync_agreement(match)
        match["alignment"]["dedicated_sync_quality"] = dedicated.get("quality")
        match["alignment"]["dedicated_sync_pair_quality"] = dedicated.get("pair_quality")
        match["alignment"]["dedicated_sync_mean_abs_ms"] = dedicated.get("mean_abs_delta_ms")
        match["alignment"]["dedicated_sync_max_abs_ms"] = dedicated.get("max_abs_delta_ms")
        match["alignment"]["dedicated_sync_spike_count"] = dedicated.get("spike_count")
        match["alignment"]["dedicated_sync_pairwise"] = dedicated.get("pairwise")
        match["alignment"]["plot_time_shifts_sec"] = _match_plot_shifts(match)
        match["alignment"]["inner_merge"] = _build_inner_merge_alignment(match)
        match["alignment"]["sync_triplet_quality"] = dedicated.get("quality")
        match["alignment"]["sync_triplet_spike_mean_abs_ms"] = dedicated.get("mean_abs_delta_ms")
        match["alignment"]["sync_triplet_spike_max_abs_ms"] = dedicated.get("max_abs_delta_ms")
        match["alignment"]["sync_triplet_spike_count"] = dedicated.get("spike_count")
        match["alignment"]["sync_triplet_pairwise"] = dedicated.get("pairwise")
        log_lines.append(
            f"[repair] match {match['match_id']:03d}: applied OTB4 repair using {repair['device']} {repair['subtitle']} "
            f"+{repair['samples_added']} samples, mean_abs {base_mean_ms} -> {repair['repaired_mean_abs_ms']} ms, "
            f"max_abs {base_max_ms} -> {repair['repaired_max_abs_ms']} ms."
        )


def _ensure_otb4_repair_applied(match: Dict[str, Any], log_lines: Optional[List[str]] = None) -> None:
    if not (match.get("otb4") and match.get("c3d")):
        return
    alignment = match.setdefault("alignment", {})
    if bool(alignment.get("otb4_repair_evaluated")):
        return
    _apply_otb4_repairs([match], log_lines or [])
    alignment["otb4_repair_evaluated"] = True


@lru_cache(maxsize=128)
def _otb4_channel_edge_times(path: Path, device: str, subtitle: str) -> Tuple[float, ...]:
    """Edge times (sec, own OTB4 sample clock) for an arbitrary AUX track --
    the pulse-plateau center (see `_detect_pulse_center_edges`), mirroring
    `_c3d_channel_edge_times` so a non-primary OTB4 sync channel (e.g. the
    3_Sync_50ms bridge track) can be probed with comparable detection
    quality to the dedicated channel-2 extraction. Falls back to
    peak-detection if thresholding doesn't find enough pulses.
    """
    try:
        _t, x, meta = _load_otb4_aux_channel(path, device=device, subtitle=subtitle)
    except Exception:
        return ()
    fs = float(meta.get("sampling_frequency") or 0.0)
    if fs <= 0.0:
        return ()
    centers_sec = _detect_pulse_center_edges(x, fs)
    if len(centers_sec) >= 4:
        return tuple(float(v) for v in centers_sec)
    sig = _orient_signal(x)
    amp = float(np.nanmax(sig)) if sig.size else 0.0
    peaks_sec = _detect_sparse_spikes(
        x,
        fs,
        prominence_grid=[max(float(np.std(sig)) * 6.0, 1e-4), max(amp * 0.15, 1e-4), max(amp * 0.25, 1e-4)],
        distance_grid_sec=[0.8, 1.0, 1.2],
    )
    return tuple(float(v) for v in peaks_sec)


def _channel3_pairing_fallback(
    otb4_records: Sequence[SyncRecord],
    c3d_records: Sequence[SyncRecord],
    already_paired: Sequence[Tuple[SyncRecord, SyncRecord, float]],
    folder: Path,
    log_lines: List[str],
) -> List[Tuple[SyncRecord, SyncRecord, float]]:
    """Secondary OTB4<->C3D pairing pass on the 50ms channel-3 bridge, used
    only to rescue records the primary 1ms channel-2 dedicated sync
    (`_pair_records` on `intervals_sec`) failed to pair. Channel 2 stays the
    primary basis; this never overrides a pair channel 2 already found.
    """
    paired_otb4_ids = {id(o) for o, _c, _cost in already_paired}
    paired_c3d_ids = {id(c) for _o, c, _cost in already_paired}
    leftover_otb4 = [r for r in otb4_records if id(r) not in paired_otb4_ids]
    leftover_c3d = [r for r in c3d_records if id(r) not in paired_c3d_ids]
    if not leftover_otb4 or not leftover_c3d:
        return []
    try:
        roles = _resolve_sync_channel_roles(_discover_sync_channel_candidates(folder))
    except Exception as exc:
        log_lines.append(f"[pairing] channel-3 fallback: sync channel discovery failed ({exc}); skipping.")
        return []
    bridge = roles.get("tsv_bridge_sync")
    if not bridge or "otb4" not in bridge or "c3d" not in bridge:
        log_lines.append(
            f"[pairing] channel-3 fallback: {len(leftover_otb4)} OTB4 / {len(leftover_c3d)} C3D record(s) left "
            f"unpaired by channel-2 sync, but no channel-3 bridge candidate could be resolved to attempt a fallback."
        )
        return []
    otb4_device = str(bridge["otb4"].get("device") or "")
    otb4_subtitle = str(bridge["otb4"].get("subtitle") or "")
    c3d_label = str(bridge["c3d"].get("label") or "")
    if not (otb4_device and otb4_subtitle and c3d_label):
        return []

    left_intervals: Dict[str, List[float]] = {}
    for rec in leftover_otb4:
        edges = sorted(_otb4_channel_edge_times(Path(rec.path), otb4_device, otb4_subtitle))
        if len(edges) >= 2:
            left_intervals[rec.path] = list(np.diff(edges))
    right_intervals: Dict[str, List[float]] = {}
    for rec in leftover_c3d:
        edges = sorted(_c3d_channel_edge_times(Path(rec.path), c3d_label))
        if len(edges) >= 2:
            right_intervals[rec.path] = list(np.diff(edges))
    if not left_intervals or not right_intervals:
        return []

    left_subs = [r for r in leftover_otb4 if r.path in left_intervals]
    right_subs = [r for r in leftover_c3d if r.path in right_intervals]
    left_view = [_dataclass_replace(r, intervals_sec=left_intervals[r.path]) for r in left_subs]
    right_view = [_dataclass_replace(r, intervals_sec=right_intervals[r.path]) for r in right_subs]
    fallback_pairs = _pair_records(left_view, right_view)
    by_path_otb4 = {r.path: r for r in left_subs}
    by_path_c3d = {r.path: r for r in right_subs}

    out: List[Tuple[SyncRecord, SyncRecord, float]] = []
    for o_view, c_view, cost in fallback_pairs:
        orig_o = by_path_otb4.get(o_view.path)
        orig_c = by_path_c3d.get(c_view.path)
        if orig_o is None or orig_c is None:
            continue
        # Channel-3 pairing cost only compares interval *shape*, not absolute
        # time, so a coincidental shape match between two unrelated files can
        # still score low. Cross-check against channel 2 (if both sides have
        # it) before trusting the fallback: if the best-possible channel-2
        # alignment between these two specific files still can't find a
        # plausible number of agreeing edges, this is very likely a spurious
        # shape match, not the same physical recording -- reject it.
        if orig_o.edge_times_sec and orig_c.edge_times_sec:
            cross_check = _tsv_bridge_sync_alignment(orig_c.edge_times_sec, orig_o.edge_times_sec, match_tol_sec=0.05)
            if cross_check.get("quality") in ("weak", "insufficient"):
                log_lines.append(
                    f"[pairing] channel-3 fallback: {Path(orig_o.path).name} <-> {Path(orig_c.path).name} "
                    f"REJECTED -- channel-3 shape cost was low (cost={cost:.4f}) but the best possible channel-2 "
                    f"cross-check only found {cross_check.get('matched_count')} agreeing edge(s) "
                    f"(quality={cross_check.get('quality')}); likely a coincidental shape match, not the same recording."
                )
                continue
        out.append((orig_o, orig_c, float(cost)))
        log_lines.append(
            f"[pairing] channel-3 fallback: {Path(orig_o.path).name} <-> {Path(orig_c.path).name} paired via "
            f"{otb4_device} {otb4_subtitle} <-> {c3d_label} (unpaired by channel-2 dedicated sync), cost={cost:.4f}."
        )
    return out


def _channel3_weak_pair_rescue(
    otb4_records: Sequence[SyncRecord],
    c3d_records: Sequence[SyncRecord],
    otb4_to_c3d: List[Tuple[SyncRecord, SyncRecord, float]],
    folder: Path,
    log_lines: List[str],
) -> List[Tuple[SyncRecord, SyncRecord, float]]:
    """Rescue primary (channel-2) pairs at the weakest confidence tier
    ("uncertain") by checking whether the dedicated channel-3 (50ms) bridge
    supports reassigning *both* sides of the pair to different,
    currently-unused records instead.

    Channel 2 alone can be too degraded to disambiguate near-tied
    candidates (seen on early-session recordings with poor probe sync), and
    channel 3's own repeating decrement pattern can alias between files a
    few trials apart (the wrong-cycle-lock seen earlier this session) -- so
    neither signal is trusted alone here. A swap only happens when *both*
    halves independently pass the same certain/probable-quality,
    near-zero-shift edge cross-check used elsewhere for bridge confirmation
    (a large shift means the "match" is a shape coincidence at the wrong
    point in the repeating pattern, not the same physical recording).
    """
    weak_pairs = [
        (o, c, cost) for o, c, cost in otb4_to_c3d
        if _summarize_pair_cost(cost) == "uncertain"
    ]
    if not weak_pairs:
        return otb4_to_c3d
    try:
        roles = _resolve_sync_channel_roles(_discover_sync_channel_candidates(folder))
    except Exception as exc:
        log_lines.append(f"[pairing] channel-3 weak-pair rescue: sync channel discovery failed ({exc}); skipping.")
        return otb4_to_c3d
    bridge = roles.get("tsv_bridge_sync") or {}
    otb4_device = str((bridge.get("otb4") or {}).get("device") or "")
    otb4_subtitle = str((bridge.get("otb4") or {}).get("subtitle") or "")
    c3d_label = str((bridge.get("c3d") or {}).get("label") or "")
    if not (otb4_device and otb4_subtitle and c3d_label):
        return otb4_to_c3d

    def ch3_edges_otb4(rec: SyncRecord) -> List[float]:
        return sorted(_otb4_channel_edge_times(Path(rec.path), otb4_device, otb4_subtitle))

    def ch3_edges_c3d(rec: SyncRecord) -> List[float]:
        return sorted(_c3d_channel_edge_times(Path(rec.path), c3d_label))

    def confirmed(otb_edges: List[float], c3d_edges: List[float]) -> Optional[Dict[str, Any]]:
        if len(otb_edges) < 2 or len(c3d_edges) < 2:
            return None
        check = _tsv_bridge_sync_alignment(c3d_edges, otb_edges, match_tol_sec=0.05)
        if check.get("quality") not in ("certain", "probable"):
            return None
        shift = check.get("shift_sec")
        if not isinstance(shift, (int, float)) or abs(float(shift)) > 2.0:
            return None
        return check

    result = list(otb4_to_c3d)
    used_otb_ids = {id(o) for o, _c, _cost in result}
    used_c3d_ids = {id(c) for _o, c, _cost in result}

    for o_weak, c_weak, cost_weak in weak_pairs:
        weak_check = confirmed(ch3_edges_otb4(o_weak), ch3_edges_c3d(c_weak))
        if weak_check is not None:
            continue  # channel 3 already agrees with the primary pairing -- nothing to rescue
        leftover_otb4 = [r for r in otb4_records if id(r) not in used_otb_ids]
        leftover_c3d = [r for r in c3d_records if id(r) not in used_c3d_ids]
        if not leftover_otb4 or not leftover_c3d:
            continue
        c_weak_edges = ch3_edges_c3d(c_weak)
        candidates_o = [
            (cand, chk) for cand in leftover_otb4
            if (chk := confirmed(ch3_edges_otb4(cand), c_weak_edges)) is not None
        ]
        if not candidates_o:
            continue
        best_o_alt, best_o_check = min(candidates_o, key=lambda item: abs(float(item[1].get("shift_sec") or 0.0)))
        o_weak_edges = ch3_edges_otb4(o_weak)
        candidates_c = [
            (cand, chk) for cand in leftover_c3d
            if (chk := confirmed(o_weak_edges, ch3_edges_c3d(cand))) is not None
        ]
        if not candidates_c:
            continue
        best_c_alt, best_c_check = min(candidates_c, key=lambda item: abs(float(item[1].get("shift_sec") or 0.0)))

        new_cost_a = _pair_cost_value(best_o_alt.intervals_sec, c_weak.intervals_sec, weak_pair_cost=0.25)
        new_cost_b = _pair_cost_value(o_weak.intervals_sec, best_c_alt.intervals_sec, weak_pair_cost=0.25)
        for idx, (o, c, _cost) in enumerate(result):
            if o is o_weak and c is c_weak:
                result[idx] = (best_o_alt, c_weak, float(new_cost_a) if new_cost_a is not None else 0.25)
                break
        result.append((o_weak, best_c_alt, float(new_cost_b) if new_cost_b is not None else 0.25))
        used_otb_ids.discard(id(o_weak))
        used_otb_ids.add(id(best_o_alt))
        used_c3d_ids.add(id(best_c_alt))
        log_lines.append(
            f"[pairing] channel-3 weak-pair rescue: primary pair {Path(o_weak.path).name}<->{Path(c_weak.path).name} "
            f"had weak channel-2 confidence (cost={cost_weak:.4f}) and channel 3 did not confirm it; reassigned to "
            f"{Path(best_o_alt.path).name}<->{Path(c_weak.path).name} (ch3 shift={best_o_check.get('shift_sec')}s "
            f"matched={best_o_check.get('matched_count')}) and {Path(o_weak.path).name}<->{Path(best_c_alt.path).name} "
            f"(ch3 shift={best_c_check.get('shift_sec')}s matched={best_c_check.get('matched_count')})."
        )
    return result


def _pair_records(left: List[SyncRecord], right: List[SyncRecord], skip_penalty: float = 0.25) -> List[Tuple[SyncRecord, SyncRecord, float]]:
    if not left or not right:
        return []
    n_left = len(left)
    n_right = len(right)
    cost = np.full((n_left, n_right), 1e6, dtype=float)
    for i, a in enumerate(left):
        for j, b in enumerate(right):
            cur_cost = _pair_cost_value(a.intervals_sec, b.intervals_sec, weak_pair_cost=float(skip_penalty))
            if cur_cost is None:
                continue
            cost[i, j] = float(cur_cost)

    # Preserve acquisition order: files were recorded sequentially, so pairings should not cross in time.
    dp = np.full((n_left + 1, n_right + 1), np.inf, dtype=float)
    move: List[List[Optional[Tuple[str, int, int]]]] = [[None] * (n_right + 1) for _ in range(n_left + 1)]
    dp[0, 0] = 0.0
    for i in range(n_left + 1):
        for j in range(n_right + 1):
            cur = float(dp[i, j])
            if not np.isfinite(cur):
                continue
            if i < n_left and cur + float(skip_penalty) < dp[i + 1, j]:
                dp[i + 1, j] = cur + float(skip_penalty)
                move[i + 1][j] = ("skip_left", i, j)
            if j < n_right and cur + float(skip_penalty) < dp[i, j + 1]:
                dp[i, j + 1] = cur + float(skip_penalty)
                move[i][j + 1] = ("skip_right", i, j)
            if i < n_left and j < n_right and cur + float(cost[i, j]) < dp[i + 1, j + 1]:
                dp[i + 1, j + 1] = cur + float(cost[i, j])
                move[i + 1][j + 1] = ("pair", i, j)

    i = n_left
    j = n_right
    out: List[Tuple[SyncRecord, SyncRecord, float]] = []
    while i > 0 or j > 0:
        step = move[i][j]
        if step is None:
            break
        kind, prev_i, prev_j = step
        if kind == "pair":
            out.append((left[prev_i], right[prev_j], float(cost[prev_i, prev_j])))
        i, j = prev_i, prev_j
    out.reverse()
    return out


def _pair_index_cost_matrix(cost: np.ndarray, skip_penalty: float = 0.25) -> List[Tuple[int, int, float]]:
    if cost.size == 0:
        return []
    n_left, n_right = cost.shape
    dp = np.full((n_left + 1, n_right + 1), np.inf, dtype=float)
    move: List[List[Optional[Tuple[str, int, int]]]] = [[None] * (n_right + 1) for _ in range(n_left + 1)]
    dp[0, 0] = 0.0
    for i in range(n_left + 1):
        for j in range(n_right + 1):
            cur = float(dp[i, j])
            if not np.isfinite(cur):
                continue
            if i < n_left and cur + float(skip_penalty) < dp[i + 1, j]:
                dp[i + 1, j] = cur + float(skip_penalty)
                move[i + 1][j] = ("skip_left", i, j)
            if j < n_right and cur + float(skip_penalty) < dp[i, j + 1]:
                dp[i, j + 1] = cur + float(skip_penalty)
                move[i][j + 1] = ("skip_right", i, j)
            if i < n_left and j < n_right and cur + float(cost[i, j]) < dp[i + 1, j + 1]:
                dp[i + 1, j + 1] = cur + float(cost[i, j])
                move[i + 1][j + 1] = ("pair", i, j)
    i = n_left
    j = n_right
    out: List[Tuple[int, int, float]] = []
    while i > 0 or j > 0:
        step = move[i][j]
        if step is None:
            break
        kind, prev_i, prev_j = step
        if kind == "pair":
            out.append((prev_i, prev_j, float(cost[prev_i, prev_j])))
        i, j = prev_i, prev_j
    out.reverse()
    return out


def _summarize_c3d_tsv_pair_certainty(eval_info: Dict[str, Any]) -> str:
    raw_result = eval_info.get("raw_result") or {}
    raw_corr = raw_result.get("corr")
    raw_lag = raw_result.get("lag_sec")
    if isinstance(raw_corr, (int, float)) and isinstance(raw_lag, (int, float)):
        abs_corr = abs(float(raw_corr))
        abs_lag = abs(float(raw_lag))
        if abs_corr >= 0.995 and abs_lag <= 1.0:
            return "certain"
        if abs_corr >= 0.95 and abs_lag <= 5.0:
            return "probable"
    if raw_result.get("basis") == "sync_bridge_3sync50ms":
        if raw_result.get("quality") == "excellent":
            return "certain"
        if raw_result.get("quality") == "fair":
            return "probable"
    if raw_result.get("basis") == "sync_bridge_3sync50ms_conflict":
        return "probable"
    return "uncertain"


def _evaluate_c3d_tsv_candidate(
    c3d_record: SyncRecord,
    tsv_record: SyncRecord,
    *,
    preferred_pairs: Optional[Sequence[Dict[str, Any]]] = None,
) -> Optional[Dict[str, Any]]:
    c3d_json = c3d_record.to_json()
    tsv_json = tsv_record.to_json()
    raw_result = dict(_best_tsv_raw_alignment(tsv_json, c3d_json, preferred_pairs=preferred_pairs))
    raw_corr = raw_result.get("corr")
    bridge: Optional[Dict[str, Any]] = None
    if tsv_record.sync_present and tsv_record.edge_times_sec:
        c3d_bridge_edges = _c3d_channel_edge_times(Path(c3d_record.path), SYNC_C3D_TSV_BRIDGE_LABEL)
        if c3d_bridge_edges:
            bridge = _tsv_bridge_sync_alignment(tsv_record.edge_times_sec, c3d_bridge_edges)
    bridge_ok = bool(bridge and bridge.get("quality") in ("certain", "probable"))
    used_bridge = False
    if bridge_ok:
        # The dedicated 3_Sync_50ms bridge channel is the required primary path
        # for TSV<->C3D alignment (it is present on every recording); raw CoP
        # correlation is only a fallback/confirmation, not the primary signal.
        raw_lag_orig = raw_result.get("lag_sec")
        raw_strong = isinstance(raw_corr, (int, float)) and abs(float(raw_corr)) >= 0.95
        bridge_cop_conflict = (
            isinstance(raw_lag_orig, (int, float))
            and abs(float(raw_lag_orig) - float(bridge["shift_sec"])) > 1.0
        )
        if bridge_cop_conflict:
            # Two independent signals disagree by >1s -- never auto-accept this,
            # regardless of how strong either signal looks alone. Surface for review.
            raw_result["cop_corr_diag"] = raw_result.get("corr")
            raw_result["cop_lag_diag"] = raw_lag_orig
            raw_result["lag_sec"] = bridge["shift_sec"]
            raw_result["corr"] = None
            raw_result["quality"] = "fair"
            raw_result["basis"] = "sync_bridge_3sync50ms_conflict"
            raw_result["bridge_info"] = bridge
            used_bridge = True
        elif bridge["quality"] == "certain":
            # Bridge is strong and not contradicted -- authoritative primary result.
            raw_result["cop_corr_diag"] = raw_result.get("corr")
            raw_result["cop_lag_diag"] = raw_lag_orig
            raw_result["lag_sec"] = bridge["shift_sec"]
            raw_result["corr"] = None
            raw_result["quality"] = "excellent"
            raw_result["basis"] = "sync_bridge_3sync50ms"
            raw_result["bridge_info"] = bridge
            used_bridge = True
        elif not raw_strong:
            # Bridge is only "probable" and raw CoP isn't strong enough to stand
            # on its own -- fall back to the bridge result as before.
            raw_result["cop_corr_diag"] = raw_result.get("corr")
            raw_result["cop_lag_diag"] = raw_lag_orig
            raw_result["lag_sec"] = bridge["shift_sec"]
            raw_result["corr"] = None
            raw_result["quality"] = "fair"
            raw_result["basis"] = "sync_bridge_3sync50ms"
            raw_result["bridge_info"] = bridge
            used_bridge = True
        # else: bridge only "probable" but raw CoP is strong and agrees -- keep
        # the raw result as primary; the bridge already confirmed it (no conflict).
    temp_match = {
        "otb4": None,
        "c3d": c3d_json,
        "tsv": tsv_json,
        "alignment": {
            "source_mode": "c3d_tsv",
            "raw_alignment_lag_sec": raw_result.get("lag_sec"),
            "raw_alignment_corr": raw_result.get("corr"),
            "raw_alignment_quality": raw_result.get("quality"),
            "otb4_c3d_edge_alignment": {"basis": "not_applicable"},
        },
    }
    dedicated = _dedicated_sync_agreement(temp_match)
    c3d_duration = float(c3d_record.sample_count or 0) / float(c3d_record.sample_rate or 1.0) if c3d_record.sample_rate else None
    tsv_duration = float(tsv_record.duration_sec) if tsv_record.duration_sec is not None else None
    duration_penalty = abs(float(c3d_duration or 0.0) - float(tsv_duration or 0.0)) * 0.1 if c3d_duration and tsv_duration else 0.0
    raw_lag = raw_result.get("lag_sec")
    if isinstance(raw_corr, (int, float)) and isinstance(raw_lag, (int, float)):
        raw_penalty = (1.0 - abs(float(raw_corr))) * 40.0 + 0.15 * abs(float(raw_lag))
    elif used_bridge:
        raw_penalty = (2.0 if raw_result.get("quality") == "excellent" else 6.0) + 0.15 * abs(float(raw_lag or 0.0))
    else:
        raw_penalty = 2.5
    score = float(duration_penalty + raw_penalty)
    if raw_result.get("corr") is None and not used_bridge:
        return None
    certainty = _summarize_c3d_tsv_pair_certainty({"raw_result": raw_result, "dedicated": dedicated})
    return {
        "c3d_json": c3d_json,
        "tsv_json": tsv_json,
        "raw_result": raw_result,
        "dedicated": dedicated,
        "score": score,
        "duration_penalty": duration_penalty,
        "certainty": certainty,
        "basis": "sync_bridge_3sync50ms" if used_bridge else "raw_only",
    }


def _build_c3d_tsv_match_from_eval(
    eval_info: Dict[str, Any],
    *,
    match_id: int,
) -> Dict[str, Any]:
    c3d_json = dict(eval_info["c3d_json"])
    tsv_json = dict(eval_info["tsv_json"])
    raw_result = dict(eval_info["raw_result"])
    dedicated = dict(eval_info["dedicated"])
    alignment = {
        "source_mode": "c3d_tsv",
        "sync_channel": "shared C3D/TSV",
        "tsv_match_status": "paired_without_otb4",
        "tsv_skip_reason": None,
        "tsv_alignment_basis": eval_info.get("basis"),
        "raw_alignment_corr": raw_result.get("corr"),
        "raw_alignment_lag_sec": raw_result.get("lag_sec"),
        "raw_alignment_samples": raw_result.get("samples"),
        "raw_label_match_tsv": raw_result.get("tsv_channel"),
        "raw_label_match_c3d": raw_result.get("c3d_channel"),
        "raw_label_match_c3d_kind": raw_result.get("c3d_kind"),
        "raw_label_based": raw_result.get("label_matched"),
        "raw_alignment_quality": raw_result.get("quality"),
        "sync_edge_skips": {"otb4": 0, "c3d": 0, "tsv": 0},
        "otb4_c3d_edge_alignment": {"basis": "not_applicable", "matched_count": 0},
        "dedicated_sync_quality": dedicated.get("quality"),
        "dedicated_sync_pair_quality": dedicated.get("pair_quality"),
        "dedicated_sync_mean_abs_ms": dedicated.get("mean_abs_delta_ms"),
        "dedicated_sync_max_abs_ms": dedicated.get("max_abs_delta_ms"),
        "dedicated_sync_spike_count": dedicated.get("spike_count"),
        "dedicated_sync_pairwise": dedicated.get("pairwise"),
    }
    match = {
        "match_id": int(match_id),
        "certainty": str(eval_info.get("certainty") or "uncertain"),
        "pair_cost": float(eval_info.get("score") or 0.0),
        "otb4": None,
        "c3d": c3d_json,
        "tsv": tsv_json,
        "alignment": alignment,
    }
    alignment["raw_alignment_quality"] = _effective_raw_quality(raw_result, alignment.get("otb4_c3d_edge_alignment"))
    alignment["plot_time_shifts_sec"] = _match_plot_shifts(match)
    alignment["inner_merge"] = _build_inner_merge_alignment(match)
    alignment["sync_triplet_quality"] = alignment["dedicated_sync_quality"]
    alignment["sync_triplet_spike_mean_abs_ms"] = alignment["dedicated_sync_mean_abs_ms"]
    alignment["sync_triplet_spike_max_abs_ms"] = alignment["dedicated_sync_max_abs_ms"]
    alignment["sync_triplet_spike_count"] = alignment["dedicated_sync_spike_count"]
    alignment["sync_triplet_pairwise"] = alignment["dedicated_sync_pairwise"]
    alignment["sync_triplet_waveform_quality"] = alignment["raw_alignment_quality"]
    alignment["sync_triplet_raw_corr_c3d_tsv"] = raw_result.get("corr")
    alignment["sync_triplet_waveform_pairwise"] = {
        "c3d_vs_tsv_raw": {"corr": raw_result.get("corr"), "lag_sec": raw_result.get("lag_sec")}
    }
    return match


def _summarize_pair_cost(cost: float) -> str:
    if cost < 0.02:
        return "certain"
    if cost < 0.05:
        return "probable"
    return "uncertain"


def _parse_record_dt(text: Optional[str]) -> Optional[datetime]:
    if not text:
        return None
    try:
        return datetime.fromisoformat(text)
    except Exception:
        return None


def _c3d_review_sort_key(match: Dict[str, Any]) -> Tuple[int, str]:
    c3d_path = Path(str((match.get("c3d") or {}).get("path") or ""))
    m = re.match(r"file_(\d+)$", c3d_path.stem, flags=re.IGNORECASE)
    if m:
        return (int(m.group(1)), c3d_path.name.lower())
    return (10**9, c3d_path.name.lower())


def _iter_source_files(folder: Path, suffix: str, excluded_dir_names: Optional[Sequence[str]] = None) -> List[Path]:
    excluded = {name.lower() for name in (excluded_dir_names or ("matched",))}
    results: List[Path] = []
    for root, dirs, files in os.walk(folder):
        dirs[:] = [d for d in dirs if d.lower() not in excluded]
        for file_name in files:
            if file_name.lower().endswith(suffix.lower()):
                results.append(Path(root) / file_name)
    results.sort()
    return results


def _pair_cost_value(
    left_intervals: Sequence[float],
    right_intervals: Sequence[float],
    *,
    weak_pair_cost: float = 0.25,
) -> Optional[float]:
    if not left_intervals or not right_intervals:
        if not left_intervals and not right_intervals:
            return float(weak_pair_cost)
        return None
    aa = np.asarray(left_intervals, dtype=float)
    bb = np.asarray(right_intervals, dtype=float)
    n = min(len(aa), len(bb))
    if n == 0:
        return None
    aa = aa[:n]
    bb = bb[:n]
    ma = np.median(aa) if np.median(aa) > 0 else 1.0
    mb = np.median(bb) if np.median(bb) > 0 else 1.0
    aa = aa / ma
    bb = bb / mb
    base = float(np.sqrt(np.mean((aa - bb) ** 2)))
    base += 0.01 * abs(len(left_intervals) - len(right_intervals))
    return base


def _infer_root_filename_clock_offset_sec(folder: Path) -> Optional[float]:
    samples: List[float] = []
    for suffix in (".tsv", ".otb4"):
        for path in _iter_source_files(folder, suffix, excluded_dir_names=("matched", "accepted", "__pycache__", ".git")):
            delta = _filename_clock_offset_sec(path)
            if delta is None:
                continue
            # Keep only plausible timezone-like offsets and ignore small write delays.
            if abs(delta) <= 18.0 * 3600.0:
                samples.append(float(delta))
    if not samples:
        return None
    return float(np.median(np.asarray(samples, dtype=float)))


def _auto_accept_match(match: Dict[str, Any]) -> bool:
    alignment = match.get("alignment") or {}
    raw_quality = alignment.get("raw_alignment_quality")
    raw_corr = alignment.get("raw_alignment_corr")
    edge_align = alignment.get("otb4_c3d_edge_alignment") or {}
    pairwise = alignment.get("dedicated_sync_pairwise") or {}
    otb_c3d = pairwise.get("otb4_vs_c3d") or pairwise.get("c3d_vs_otb4") or {}
    otb_c3d_count = int(otb_c3d.get("count") or 0)
    otb_c3d_matched = int(otb_c3d.get("matched_spikes_50ms") or 0)
    otb_c3d_mean = otb_c3d.get("mean_abs_ms")
    otb_c3d_max = otb_c3d.get("max_abs_ms")
    otb_c3d_sync_ok = False
    if otb_c3d_count > 0:
        if otb_c3d_matched >= otb_c3d_count:
            otb_c3d_sync_ok = True
        elif isinstance(otb_c3d_mean, (int, float)) and isinstance(otb_c3d_max, (int, float)):
            otb_c3d_sync_ok = float(otb_c3d_mean) <= 20.0 and float(otb_c3d_max) <= 50.0
    raw_ok = raw_quality == "excellent" or (
        raw_quality == "good" and isinstance(raw_corr, (int, float)) and abs(float(raw_corr)) >= 0.995
    )
    if not raw_ok and edge_align.get("basis") == "late_c3d_raw_bridge" and isinstance(raw_corr, (int, float)):
        raw_ok = abs(float(raw_corr)) >= 0.999
    if not match.get("otb4"):
        return match.get("certainty") == "certain" and raw_ok
    return (
        match.get("certainty") == "certain"
        and raw_ok
        and otb_c3d_sync_ok
    )


def _apply_review_defaults(match: Dict[str, Any]) -> None:
    review = dict(match.get("review") or {})
    auto_accept = bool(review.get("auto_accept")) if "auto_accept" in review else _auto_accept_match(match)
    if "user_decision" not in review:
        review["user_decision"] = None
    if "user_touched" not in review:
        review["user_touched"] = False
    review["auto_accept"] = auto_accept
    review["final_accept"] = bool(review["user_decision"]) if review["user_decision"] is not None else auto_accept
    review["reviewed"] = review["user_decision"] is not None
    review["status_key"] = _review_status_key_from_review(review)
    review["status_color"] = _review_status_color_from_review(review)
    review["status_text"] = _review_status_label_from_review(review)
    review["decision_source"] = "user" if review["user_decision"] is not None else "automatic"
    match["review"] = review
    match["accepted"] = review["final_accept"]


def _match_tsv_records(
    matches: List[Dict[str, Any]],
    tsv_records: List[SyncRecord],
    log_lines: List[str],
    *,
    filename_clock_offset_sec: float = 0.0,
    preferred_pairs: Optional[Sequence[Dict[str, Any]]] = None,
    initially_used_paths: Optional[Sequence[str]] = None,
    candidate_paths_by_match: Optional[Dict[int, Sequence[str]]] = None,
    restrict_to_hints: bool = False,
) -> List[Dict[str, Any]]:
    candidates: List[SyncRecord] = [
        rec
        for rec in tsv_records
        if rec.first_ts is not None
        and rec.last_ts is not None
        and rec.duration_sec is not None
        and rec.duration_sec >= 5.0
        and (rec.sync_present or any(str(c).lower().endswith("[raw]") for c in (rec.channel_names or [])))
    ]
    used: set[str] = {str(path) for path in (initially_used_paths or []) if str(path)}
    matched_tsv: List[Dict[str, Any]] = []
    for match in matches:
        if not (match.get("otb4") and match.get("c3d")):
            continue
        local_candidates = candidates
        hinted_paths = {
            str(path)
            for path in (candidate_paths_by_match or {}).get(int(match.get("match_id") or 0), [])
            if str(path)
        }
        if hinted_paths:
            local_candidates = [rec for rec in candidates if rec.path in hinted_paths]
        elif restrict_to_hints:
            match["alignment"]["tsv_match_status"] = "missing"
            match["alignment"]["tsv_skip_reason"] = "No hinted TSV triplet candidate was available for this pair."
            log_lines.append(
                f"[tsv-seed] match {match['match_id']:03d}: no hinted triplet TSV candidate available."
            )
            continue
        otb_dt = _parse_record_dt(match["otb4"].get("timestamp"))
        if otb_dt is None:
            continue
        otb_end = otb_dt.timestamp() + float(filename_clock_offset_sec or 0.0)
        otb_duration = float(match["otb4"].get("sample_count", 0) or 0.0) / float(match["otb4"].get("sample_rate") or 1.0)
        otb_start = otb_end - otb_duration
        c3d_duration = float(match["c3d"].get("sample_count", 0) or 0.0) / float(match["c3d"].get("sample_rate") or 1.0)
        otb_edges = list(match["otb4"].get("edge_times_sec") or [])
        c3d_edges = list(match["c3d"].get("edge_times_sec") or [])
        c3d_bridge_edges = _c3d_channel_edge_times(Path(match["c3d"]["path"]), SYNC_C3D_TSV_BRIDGE_LABEL)
        if otb_edges and c3d_edges:
            pair_span = float(max(otb_edges[-1], c3d_edges[-1]) - min(otb_edges[0], c3d_edges[0]))
        else:
            pair_span = float(max(otb_duration, c3d_duration))
        template_ref = []
        n_ref = min(len(otb_edges), len(c3d_edges))
        if n_ref >= 2:
            otb_rel = np.asarray(otb_edges[:n_ref], dtype=float)
            c3d_rel = np.asarray(c3d_edges[:n_ref], dtype=float)
            template_ref = (((otb_rel - otb_rel[0]) + (c3d_rel - c3d_rel[0])) / 2.0).tolist()

        expected_tsv_num = _c3d_setting_number(match["c3d"]["path"])

        ranked_candidates: List[Tuple[float, SyncRecord, float, float, float]] = []
        for rec in local_candidates:
            if rec.path in used:
                continue
            last_ts = rec.last_ts
            first_ts = rec.first_ts
            name_dt = _parse_record_dt(rec.timestamp)
            if last_ts is None:
                continue
            name_ts = (name_dt.timestamp() + float(filename_clock_offset_sec or 0.0)) if name_dt is not None else None
            if name_ts is not None and abs(name_ts - otb_start) > 180.0 and abs(last_ts - otb_end) > 180.0:
                continue
            end_anchor = name_ts if name_ts is not None else otb_end
            start_anchor = end_anchor - (rec.duration_sec or 0.0)
            start_delta = abs((first_ts if first_ts is not None else start_anchor) - otb_start)
            end_delta = abs(last_ts - otb_end)
            filename_delta = abs(end_anchor - otb_start) if name_dt is not None else 0.0
            duration_penalty = 0.1 * abs((rec.duration_sec or 0.0) - pair_span)
            cheap_score = start_delta + end_delta + duration_penalty + 0.01 * filename_delta
            ranked_candidates.append((cheap_score, rec, start_delta, end_delta, filename_delta))
        ranked_candidates.sort(key=lambda item: item[0])

        best: Optional[Tuple[Tuple[int, float], SyncRecord, float, Dict[str, Any], Dict[str, Any], Dict[str, Any], bool]] = None
        best_diag: Optional[Tuple[SyncRecord, float, Optional[float], Optional[float], Optional[float], str]] = None
        # Evaluate every candidate inside the coarse +/-180s time window, not just
        # the top-3 by timestamp proximity: a genuine TSV/C3D pair can have a large
        # apparent timestamp offset (TSV capture-PC clock drift on a specific file)
        # while still having near-perfect raw CoP correlation and sync-bridge
        # agreement -- capping the shortlist by timestamp score alone can silently
        # exclude the correct candidate before its content evidence is ever seen.
        shortlist = ranked_candidates
        for _cheap_score, rec, start_delta, end_delta, filename_delta in shortlist:
            rec_json = rec.to_json()
            raw_result = dict(_best_tsv_raw_alignment(rec_json, match["c3d"], preferred_pairs=preferred_pairs))
            raw_corr = raw_result.get("corr")
            bridge: Optional[Dict[str, Any]] = None
            if c3d_bridge_edges and rec.sync_present and rec.edge_times_sec:
                bridge = _tsv_bridge_sync_alignment(rec.edge_times_sec, c3d_bridge_edges)
            bridge_ok = bool(bridge and bridge.get("quality") in ("certain", "probable"))
            used_bridge = False
            bridge_cop_conflict = False
            if bridge_ok:
                # The dedicated 3_Sync_50ms bridge is the required primary path for
                # TSV<->C3D alignment (present on every recording); raw CoP
                # correlation is only a fallback/confirmation.
                raw_lag_orig = raw_result.get("lag_sec")
                raw_strong = isinstance(raw_corr, (int, float)) and abs(float(raw_corr)) >= 0.95
                bridge_cop_conflict = (
                    isinstance(raw_lag_orig, (int, float))
                    and abs(float(raw_lag_orig) - float(bridge["shift_sec"])) > 1.0
                )
                if bridge_cop_conflict:
                    # Two independent signals disagree by >1s: never auto-accept,
                    # regardless of how strong either signal looks alone -- flag for review.
                    raw_result["cop_corr_diag"] = raw_result.get("corr")
                    raw_result["cop_lag_diag"] = raw_lag_orig
                    raw_result["lag_sec"] = bridge["shift_sec"]
                    raw_result["corr"] = None
                    raw_result["quality"] = "fair"
                    raw_result["basis"] = "sync_bridge_3sync50ms_conflict"
                    raw_result["bridge_info"] = bridge
                    used_bridge = True
                elif bridge["quality"] == "certain":
                    # Bridge is strong and not contradicted -- authoritative primary result.
                    raw_result["cop_corr_diag"] = raw_result.get("corr")
                    raw_result["cop_lag_diag"] = raw_lag_orig
                    raw_result["lag_sec"] = bridge["shift_sec"]
                    raw_result["corr"] = None
                    raw_result["quality"] = "excellent"
                    raw_result["basis"] = "sync_bridge_3sync50ms"
                    raw_result["bridge_info"] = bridge
                    used_bridge = True
                elif not raw_strong:
                    # Bridge only "probable" and raw CoP isn't strong enough alone --
                    # fall back to the bridge result as before.
                    raw_result["cop_corr_diag"] = raw_result.get("corr")
                    raw_result["cop_lag_diag"] = raw_lag_orig
                    raw_result["lag_sec"] = bridge["shift_sec"]
                    raw_result["corr"] = None
                    raw_result["quality"] = "fair"
                    raw_result["basis"] = "sync_bridge_3sync50ms"
                    raw_result["bridge_info"] = bridge
                    used_bridge = True
                # else: bridge only "probable" but raw CoP is strong and agrees --
                # keep raw as primary; bridge already confirmed it (no conflict).
            diag_corr = abs(float(raw_corr)) if isinstance(raw_corr, (int, float)) else None
            diag_lag = abs(float(raw_result.get("lag_sec") or 0.0)) if raw_result.get("lag_sec") is not None else None
            duration_penalty = 0.1 * abs((rec.duration_sec or 0.0) - pair_span)
            diag_score = start_delta + end_delta + duration_penalty + 0.01 * filename_delta
            if (
                best_diag is None
                or (diag_corr is not None and best_diag[2] is not None and diag_corr > best_diag[2])
                or (diag_corr is not None and best_diag[2] is None)
            ):
                best_diag = (rec, diag_score, diag_corr, diag_lag, filename_delta, raw_result.get("quality") or "missing")
            if not used_bridge and (raw_corr is None or abs(float(raw_corr)) < 0.95):
                continue

            temp_match = {
                **match,
                "tsv": rec_json,
                "alignment": {
                    **(match.get("alignment") or {}),
                    "raw_alignment_lag_sec": raw_result.get("lag_sec"),
                    "raw_alignment_corr": raw_result.get("corr"),
                    "raw_alignment_quality": raw_result.get("quality"),
                },
            }
            edge_align = _select_otb4_c3d_edge_alignment(temp_match)
            temp_match["alignment"]["sync_edge_skips"] = {
                "otb4": int(edge_align.get("otb4_skip") or 0),
                "c3d": int(edge_align.get("c3d_skip") or 0),
                "tsv": 0,
            }
            temp_match["alignment"]["otb4_c3d_edge_alignment"] = edge_align
            temp_match["alignment"]["raw_alignment_quality"] = _effective_raw_quality(raw_result, edge_align)
            if isinstance(raw_corr, (int, float)):
                raw_penalty = (1.0 - abs(float(raw_corr))) * 40.0 + 0.15 * abs(float(raw_result.get("lag_sec") or 0.0))
            else:
                raw_penalty = (2.0 if raw_result.get("quality") == "excellent" else 6.0) + 0.15 * abs(float(raw_result.get("lag_sec") or 0.0))
            score = start_delta + end_delta + duration_penalty + 0.01 * filename_delta + raw_penalty
            # Content evidence (raw CoP correlation, sync-bridge shift) is far more
            # reliable than filename/timestamp proximity: the TSV capture PC's clock
            # can drift independently of the OTB4/C3D naming clock, inflating
            # start_delta/end_delta for an otherwise-correct match. A candidate whose
            # content evidence is strong AND uncontradicted is preferred outright over
            # any candidate that only looks good on timestamp proximity; score is only
            # used to break ties within the same confirmation tier.
            bridge_shift_val = bridge.get("shift_sec") if bridge else None
            strong_bridge = (
                bridge_ok
                and not bridge_cop_conflict
                and isinstance(bridge_shift_val, (int, float))
                and abs(float(bridge_shift_val)) <= 2.0
            )
            strong_raw = (
                not bridge_cop_conflict
                and isinstance(raw_corr, (int, float))
                and abs(float(raw_corr)) >= 0.95
            )
            content_confirmed = strong_bridge or strong_raw
            # The C3D "Setting_NN" <-> TSV "File_0NN" number correspondence is a
            # confirmed-correct ground truth for this recording convention (unlike
            # timestamp proximity, which can be thrown off by TSV capture-PC clock
            # drift on individual files). Raw CoP shape and even the sync bridge can
            # both be fooled by a repeated/cyclic protocol matching a *neighboring*
            # trial almost as well as the true one -- so a content-confirmed AND
            # number-matched candidate is preferred outright over a content-confirmed
            # candidate that only agrees by shape/bridge with the wrong trial.
            tsv_num = _file_numeric_index(rec.path)
            number_matched = (
                expected_tsv_num is not None and tsv_num is not None and tsv_num == expected_tsv_num
            )
            if number_matched and content_confirmed:
                tier = 0
            elif content_confirmed:
                tier = 1
            else:
                tier = 2
            sort_key = (tier, score)
            if best is None or sort_key < best[0]:
                best = (sort_key, rec, filename_delta, rec_json, raw_result, bridge, content_confirmed)
        if best is None:
            reason = "No TSV candidate passed the time-window and raw-match filters."
            if best_diag is not None:
                rec, _diag_score, diag_corr, diag_lag, filename_delta, diag_quality = best_diag
                reason = (
                    f"No TSV candidate passed the raw-match threshold. "
                    f"Best nearby TSV was {Path(rec.path).name} "
                    f"(raw={diag_quality}, abs_corr={diag_corr if diag_corr is not None else 'n/a'}, "
                    f"abs_lag_sec={diag_lag if diag_lag is not None else 'n/a'}, "
                    f"filename_delta_sec={filename_delta if filename_delta is not None else 'n/a'})."
                )
            match["alignment"]["tsv_match_status"] = "missing"
            match["alignment"]["tsv_skip_reason"] = reason
            log_lines.append(f"[tsv-match] match {match['match_id']:03d}: {reason}")
            continue
        sort_key, rec, filename_delta, rec_json, raw_result, best_bridge, best_content_confirmed = best
        score = sort_key[1]
        dedicated = _dedicated_sync_agreement(
            {
                **match,
                "tsv": rec_json,
                "alignment": {
                    **(match.get("alignment") or {}),
                    "raw_alignment_lag_sec": raw_result.get("lag_sec"),
                    "raw_alignment_corr": raw_result.get("corr"),
                    "raw_alignment_quality": raw_result.get("quality"),
                },
            }
        )
        if score > 8.0 and best_content_confirmed:
            log_lines.append(
                f"[tsv-content-confirmed] match {match['match_id']:03d}: {Path(rec.path).name} score={score:.3f} exceeded "
                f"the coarse time-window threshold, but raw CoP correlation and/or the dedicated "
                f"{SYNC_C3D_TSV_BRIDGE_LABEL} sync bridge (corr={raw_result.get('cop_corr_diag') if raw_result.get('cop_corr_diag') is not None else raw_result.get('corr')} "
                f"bridge_shift={best_bridge.get('shift_sec') if best_bridge else 'n/a'}) confirm this candidate uncontradicted -- "
                f"likely a source-clock offset between the TSV capture PC and the OTB4/C3D naming clock rather than a "
                f"wrong candidate. Accepting on content evidence."
            )
        elif score > 8.0:
            reason = (
                f"Best TSV {Path(rec.path).name} rejected because combined score={score:.3f} exceeded 8.000 "
                f"(raw={raw_result.get('quality')}, corr={raw_result.get('corr')}, lag={raw_result.get('lag_sec')}, "
                f"dedicated_sync={dedicated.get('quality')})."
            )
            match["alignment"]["tsv_match_status"] = "rejected"
            match["alignment"]["tsv_skip_reason"] = reason
            log_lines.append(
                f"[tsv-match] match {match['match_id']:03d}: {reason}"
            )
            continue
        used.add(rec.path)
        match["tsv"] = rec_json
        match["alignment"]["tsv_match_status"] = "matched"
        match["alignment"]["tsv_skip_reason"] = None
        match["alignment"]["tsv_start_ts"] = rec.first_ts
        match["alignment"]["tsv_end_ts"] = rec.last_ts
        match["alignment"]["tsv_duration_sec"] = rec.duration_sec
        match["alignment"]["tsv_end_minus_otb_sec"] = round(rec.last_ts - otb_end, 6) if rec.last_ts is not None else None
        match["alignment"]["tsv_start_minus_otb_start_sec"] = round(rec.first_ts - otb_start, 6) if rec.first_ts is not None else None
        match["alignment"]["tsv_score"] = round(score, 6)
        match["alignment"]["tsv_alignment_basis"] = raw_result.get("basis") or "raw_only"
        match["alignment"]["sync_edge_skips"] = temp_match["alignment"].get("sync_edge_skips") or {"otb4": 0, "c3d": 0, "tsv": 0}
        match["alignment"]["otb4_c3d_edge_alignment"] = temp_match["alignment"].get("otb4_c3d_edge_alignment") or {}
        match["alignment"]["raw_alignment_quality"] = _effective_raw_quality(raw_result, match["alignment"].get("otb4_c3d_edge_alignment"))
        match["alignment"]["raw_alignment_corr"] = raw_result.get("corr")
        match["alignment"]["raw_alignment_lag_sec"] = raw_result.get("lag_sec")
        match["alignment"]["raw_alignment_samples"] = raw_result.get("samples")
        match["alignment"]["raw_label_match_tsv"] = raw_result.get("tsv_channel")
        match["alignment"]["raw_label_match_c3d"] = raw_result.get("c3d_channel")
        match["alignment"]["raw_label_match_c3d_kind"] = raw_result.get("c3d_kind")
        match["alignment"]["raw_label_based"] = raw_result.get("label_matched")
        final_edge_align = _select_otb4_c3d_edge_alignment(match)
        match["alignment"]["sync_edge_skips"] = {
            "otb4": int(final_edge_align.get("otb4_skip") or 0),
            "c3d": int(final_edge_align.get("c3d_skip") or 0),
            "tsv": 0,
        }
        match["alignment"]["otb4_c3d_edge_alignment"] = final_edge_align
        match["alignment"]["raw_alignment_quality"] = _effective_raw_quality(raw_result, final_edge_align)
        if final_edge_align.get("diagnostic_note"):
            log_lines.append(f"[sync-diag] match {match['match_id']:03d}: {final_edge_align['diagnostic_note']}")
        # Recompute now that otb4_c3d_edge_alignment reflects final_edge_align
        # (possibly a non-zero skip found above) -- the earlier `dedicated`
        # was necessarily computed before that skip was known, so its
        # internal _sync_edge_skip_count lookup would otherwise silently
        # fall back to skip=0 and misreport dedicated-sync quality.
        dedicated = _dedicated_sync_agreement_for_edge_alignment(match, final_edge_align)
        match["alignment"]["dedicated_sync_quality"] = dedicated.get("quality")
        match["alignment"]["dedicated_sync_pair_quality"] = dedicated.get("pair_quality")
        match["alignment"]["dedicated_sync_mean_abs_ms"] = dedicated.get("mean_abs_delta_ms")
        match["alignment"]["dedicated_sync_max_abs_ms"] = dedicated.get("max_abs_delta_ms")
        match["alignment"]["dedicated_sync_spike_count"] = dedicated.get("spike_count")
        match["alignment"]["dedicated_sync_pairwise"] = dedicated.get("pairwise")
        match["alignment"]["plot_time_shifts_sec"] = _match_plot_shifts(match)
        match["alignment"]["inner_merge"] = _build_inner_merge_alignment(match)
        match["alignment"]["sync_triplet_quality"] = match["alignment"]["dedicated_sync_quality"]
        match["alignment"]["sync_triplet_spike_mean_abs_ms"] = match["alignment"]["dedicated_sync_mean_abs_ms"]
        match["alignment"]["sync_triplet_spike_max_abs_ms"] = match["alignment"]["dedicated_sync_max_abs_ms"]
        match["alignment"]["sync_triplet_spike_count"] = match["alignment"]["dedicated_sync_spike_count"]
        match["alignment"]["sync_triplet_pairwise"] = match["alignment"]["dedicated_sync_pairwise"]
        match["alignment"]["sync_triplet_waveform_quality"] = match["alignment"]["raw_alignment_quality"]
        match["alignment"]["sync_triplet_raw_corr_c3d_tsv"] = raw_result.get("corr")
        match["alignment"]["sync_triplet_waveform_pairwise"] = {
            "c3d_vs_tsv_raw": {"corr": raw_result.get("corr"), "lag_sec": raw_result.get("lag_sec")}
        }
        log_lines.append(
            f"[tsv-match] match {match['match_id']:03d}: {Path(rec.path).name} score={score:.3f} "
            f"start_delta={match['alignment']['tsv_start_minus_otb_start_sec']:.3f}s "
            f"end_delta={match['alignment']['tsv_end_minus_otb_sec']:.3f}s "
            f"filename_delta={filename_delta:.3f}s "
            f"basis={match['alignment']['tsv_alignment_basis']} "
            f"raw={match['alignment']['raw_alignment_quality']} corr={raw_result.get('corr')} lag={raw_result.get('lag_sec')}s "
            f"dedicated_sync_info={dedicated.get('quality')} mean_abs={dedicated.get('mean_abs_delta_ms')}ms max_abs={dedicated.get('max_abs_delta_ms')}ms"
        )
        if raw_result.get("basis") == "sync_bridge_3sync50ms":
            bridge_info = raw_result.get("bridge_info") or {}
            log_lines.append(
                f"[tsv-sync-bridge] match {match['match_id']:03d}: {Path(rec.path).name} aligned via "
                f"{SYNC_C3D_TSV_BRIDGE_LABEL} dedicated sync bridge (no usable raw CoP correlation) "
                f"matched={bridge_info.get('matched_count')} mean_abs={bridge_info.get('mean_abs_ms')}ms "
                f"max_abs={bridge_info.get('max_abs_ms')}ms shift={bridge_info.get('shift_sec')}s."
            )
        if raw_result.get("tsv_channel") and raw_result.get("c3d_channel"):
            log_lines.append(
                f"[raw-match] match {match['match_id']:03d}: TSV {raw_result['tsv_channel']} <-> C3D {raw_result['c3d_channel']} "
                f"kind={raw_result.get('c3d_kind')} corr={raw_result.get('corr')} lag={raw_result.get('lag_sec')} "
                f"label_match={raw_result.get('label_match')}"
            )
        else:
            log_lines.append(f"[raw-match] match {match['match_id']:03d}: no exact TSV [raw] to C3D match found.")
        if dedicated.get("pairwise"):
            log_lines.append(f"[sync-match] match {match['match_id']:03d}: {json.dumps(dedicated['pairwise'], ensure_ascii=False)}")
        if (match["alignment"].get("otb4_c3d_edge_alignment") or {}).get("basis") == "late_c3d_raw_bridge":
            info = match["alignment"]["otb4_c3d_edge_alignment"]
            log_lines.append(
                f"[sync-bridge] match {match['match_id']:03d}: raw C3D/TSV supports late C3D start; "
                f"skip otb4={info.get('otb4_skip')} c3d={info.get('c3d_skip')} "
                f"shift={info.get('shift_sec')}s mean_abs={info.get('mean_abs_ms')}ms max_abs={info.get('max_abs_ms')}ms"
            )
        if match["alignment"]["raw_alignment_quality"] in {"good", "excellent", "fair"} and dedicated.get("pair_quality") == "poor":
            log_lines.append(
                f"[diagnostic] match {match['match_id']:03d}: raw shape agrees better than sync pulses. "
                f"This suggests a truncated or missing sync spike in one recording rather than a better cross-file reassignment."
            )
        matched_tsv.append(rec_json)
    return matched_tsv


def _build_pair_match_from_records(
    otb4_record: Dict[str, Any],
    c3d_record: Dict[str, Any],
    *,
    match_id: int,
) -> Dict[str, Any]:
    pair_cost = _pair_cost_value(
        otb4_record.get("intervals_sec") or [],
        c3d_record.get("intervals_sec") or [],
        weak_pair_cost=0.25,
    )
    if pair_cost is None:
        pair_cost = 1.0
    certainty = _summarize_pair_cost(float(pair_cost))
    otb_edges = list(otb4_record.get("edge_times_sec") or [])
    c3d_edges = list(c3d_record.get("edge_times_sec") or [])
    overlap_start = 0.0
    overlap_end = 0.0
    if otb_edges and c3d_edges:
        overlap_start = max(float(otb_edges[0]), float(c3d_edges[0]))
        overlap_end = min(float(otb_edges[-1]), float(c3d_edges[-1]))
    alignment = {
        "sync_channel": "shared TTL",
        "overlap_start_sec": overlap_start,
        "overlap_end_sec": overlap_end,
    }
    triplet = _triplet_spike_agreement([otb4_record, c3d_record])
    alignment["sync_triplet_quality"] = triplet["quality"]
    alignment["sync_triplet_spike_mean_abs_ms"] = triplet["mean_abs_delta_ms"]
    alignment["sync_triplet_spike_max_abs_ms"] = triplet["max_abs_delta_ms"]
    alignment["sync_triplet_spike_count"] = triplet["spike_count"]
    alignment["sync_triplet_pairwise"] = triplet["pairwise"]
    return {
        "match_id": int(match_id),
        "certainty": certainty,
        "pair_cost": float(pair_cost),
        "otb4": dict(otb4_record),
        "c3d": dict(c3d_record),
        "tsv": None,
        "alignment": alignment,
    }


def _evaluate_manual_tsv_selection(
    match: Dict[str, Any],
    tsv_record: Dict[str, Any],
    *,
    filename_clock_offset_sec: float,
) -> Optional[Dict[str, Any]]:
    otb_dt = _parse_record_dt((match.get("otb4") or {}).get("timestamp"))
    if otb_dt is None:
        return None
    otb_end = otb_dt.timestamp() + float(filename_clock_offset_sec or 0.0)
    otb_duration = float((match.get("otb4") or {}).get("sample_count", 0) or 0.0) / float((match.get("otb4") or {}).get("sample_rate") or 1.0)
    otb_start = otb_end - otb_duration
    c3d_duration = float((match.get("c3d") or {}).get("sample_count", 0) or 0.0) / float((match.get("c3d") or {}).get("sample_rate") or 1.0)
    otb_edges = list((match.get("otb4") or {}).get("edge_times_sec") or [])
    c3d_edges = list((match.get("c3d") or {}).get("edge_times_sec") or [])
    if otb_edges and c3d_edges:
        pair_span = float(max(otb_edges[-1], c3d_edges[-1]) - min(otb_edges[0], c3d_edges[0]))
    else:
        pair_span = float(max(otb_duration, c3d_duration))
    template_ref: List[float] = []
    n_ref = min(len(otb_edges), len(c3d_edges))
    if n_ref >= 2:
        otb_rel = np.asarray(otb_edges[:n_ref], dtype=float)
        c3d_rel = np.asarray(c3d_edges[:n_ref], dtype=float)
        template_ref = (((otb_rel - otb_rel[0]) + (c3d_rel - c3d_rel[0])) / 2.0).tolist()

    rec_json = dict(tsv_record)
    last_ts = rec_json.get("last_ts")
    first_ts = rec_json.get("first_ts")
    duration_sec = rec_json.get("duration_sec")
    if last_ts is None or duration_sec is None:
        return None
    name_dt = _parse_record_dt(rec_json.get("timestamp"))
    name_ts = (name_dt.timestamp() + float(filename_clock_offset_sec or 0.0)) if name_dt is not None else None
    end_anchor = name_ts if name_ts is not None else otb_end
    start_anchor = end_anchor - float(duration_sec or 0.0)
    start_delta = abs((float(first_ts) if first_ts is not None else start_anchor) - otb_start)
    end_delta = abs(float(last_ts) - otb_end)
    filename_delta = abs(end_anchor - otb_start) if name_dt is not None else 0.0
    duration_penalty = 0.1 * abs(float(duration_sec or 0.0) - pair_span)

    raw_result = _best_tsv_raw_alignment(rec_json, match["c3d"])
    raw_corr = raw_result.get("corr")

    if rec_json.get("sync_present") and rec_json.get("sync_channel") and template_ref:
        try:
            _cols, df = _read_tsv_table(Path(rec_json["path"]))
            x = pd.to_numeric(df[rec_json["sync_channel"]], errors="coerce").to_numpy(dtype=float)
            t_rel = pd.to_numeric(df["t_rel"], errors="coerce").to_numpy(dtype=float)
            refined_peaks = _detect_tsv_spikes_with_template(x, t_rel, np.diff(template_ref))
            if len(refined_peaks) >= 2:
                rec_json["edge_times_sec"] = [float(v) for v in refined_peaks]
                rec_json["edge_count"] = len(refined_peaks)
                rec_json["intervals_sec"] = [float(v) for v in np.diff(refined_peaks).tolist()]
        except Exception:
            pass

    temp_match = {
        **match,
        "tsv": rec_json,
        "alignment": {
            **(match.get("alignment") or {}),
            "raw_alignment_lag_sec": raw_result.get("lag_sec"),
            "raw_alignment_corr": raw_result.get("corr"),
            "raw_alignment_quality": raw_result.get("quality"),
        },
    }
    edge_align = _select_otb4_c3d_edge_alignment(temp_match)
    temp_match["alignment"]["sync_edge_skips"] = {
        "otb4": int(edge_align.get("otb4_skip") or 0),
        "c3d": int(edge_align.get("c3d_skip") or 0),
        "tsv": 0,
    }
    temp_match["alignment"]["otb4_c3d_edge_alignment"] = edge_align
    temp_match["alignment"]["raw_alignment_quality"] = _effective_raw_quality(raw_result, edge_align)
    dedicated = _dedicated_sync_agreement_for_edge_alignment(temp_match, edge_align)
    corr_mag = abs(float(raw_corr)) if isinstance(raw_corr, (int, float)) else 0.0
    raw_penalty = (1.0 - corr_mag) * 40.0 + 0.15 * abs(float(raw_result.get("lag_sec") or 0.0))
    score = start_delta + end_delta + duration_penalty + 0.01 * filename_delta + raw_penalty
    return {
        "rec_json": rec_json,
        "raw_result": raw_result,
        "dedicated": dedicated,
        "score": float(score),
        "filename_delta": float(filename_delta),
        "otb_end": float(otb_end),
        "otb_start": float(otb_start),
        "start_delta": float(start_delta),
        "end_delta": float(end_delta),
    }


def _apply_manual_tsv_selection(
    match: Dict[str, Any],
    tsv_record: Dict[str, Any],
    *,
    filename_clock_offset_sec: float,
) -> bool:
    evaluated = _evaluate_manual_tsv_selection(match, tsv_record, filename_clock_offset_sec=filename_clock_offset_sec)
    if evaluated is None:
        return False
    rec_json = evaluated["rec_json"]
    raw_result = evaluated["raw_result"]
    dedicated = evaluated["dedicated"]
    score = evaluated["score"]
    filename_delta = evaluated["filename_delta"]
    otb_end = evaluated["otb_end"]
    otb_start = evaluated["otb_start"]
    rec_last_ts = rec_json.get("last_ts")
    rec_first_ts = rec_json.get("first_ts")
    match["tsv"] = rec_json
    alignment = match.setdefault("alignment", {})
    alignment["manual_selection"] = True
    alignment["tsv_match_status"] = "manual"
    alignment["tsv_skip_reason"] = "Manual TSV/OTB4 selection pending user review."
    alignment["tsv_start_ts"] = rec_first_ts
    alignment["tsv_end_ts"] = rec_last_ts
    alignment["tsv_duration_sec"] = rec_json.get("duration_sec")
    alignment["tsv_end_minus_otb_sec"] = round(float(rec_last_ts) - otb_end, 6) if rec_last_ts is not None else None
    alignment["tsv_start_minus_otb_start_sec"] = round(float(rec_first_ts) - otb_start, 6) if rec_first_ts is not None else None
    alignment["tsv_score"] = round(float(score), 6)
    alignment["tsv_alignment_basis"] = "manual_selection"
    alignment["raw_alignment_corr"] = raw_result.get("corr")
    alignment["raw_alignment_lag_sec"] = raw_result.get("lag_sec")
    alignment["raw_alignment_samples"] = raw_result.get("samples")
    alignment["raw_label_match_tsv"] = raw_result.get("tsv_channel")
    alignment["raw_label_match_c3d"] = raw_result.get("c3d_channel")
    alignment["raw_label_match_c3d_kind"] = raw_result.get("c3d_kind")
    alignment["raw_label_based"] = raw_result.get("label_matched")
    final_edge_align = _select_otb4_c3d_edge_alignment(match)
    alignment["sync_edge_skips"] = {
        "otb4": int(final_edge_align.get("otb4_skip") or 0),
        "c3d": int(final_edge_align.get("c3d_skip") or 0),
        "tsv": 0,
    }
    alignment["otb4_c3d_edge_alignment"] = final_edge_align
    alignment["raw_alignment_quality"] = _effective_raw_quality(raw_result, final_edge_align)
    dedicated = _dedicated_sync_agreement_for_edge_alignment(match, final_edge_align)
    alignment["dedicated_sync_quality"] = dedicated.get("quality")
    alignment["dedicated_sync_pair_quality"] = dedicated.get("pair_quality")
    alignment["dedicated_sync_mean_abs_ms"] = dedicated.get("mean_abs_delta_ms")
    alignment["dedicated_sync_max_abs_ms"] = dedicated.get("max_abs_delta_ms")
    alignment["dedicated_sync_spike_count"] = dedicated.get("spike_count")
    alignment["dedicated_sync_pairwise"] = dedicated.get("pairwise")
    alignment["plot_time_shifts_sec"] = _match_plot_shifts(match)
    alignment["inner_merge"] = _build_inner_merge_alignment(match)
    alignment["sync_triplet_quality"] = alignment["dedicated_sync_quality"]
    alignment["sync_triplet_spike_mean_abs_ms"] = alignment["dedicated_sync_mean_abs_ms"]
    alignment["sync_triplet_spike_max_abs_ms"] = alignment["dedicated_sync_max_abs_ms"]
    alignment["sync_triplet_spike_count"] = alignment["dedicated_sync_spike_count"]
    alignment["sync_triplet_pairwise"] = alignment["dedicated_sync_pairwise"]
    alignment["sync_triplet_waveform_quality"] = alignment["raw_alignment_quality"]
    alignment["sync_triplet_raw_corr_c3d_tsv"] = raw_result.get("corr")
    alignment["sync_triplet_waveform_pairwise"] = {
        "c3d_vs_tsv_raw": {"corr": raw_result.get("corr"), "lag_sec": raw_result.get("lag_sec")}
    }
    return True


def _match_c3d_tsv_records(
    c3d_records: List[SyncRecord],
    tsv_records: List[SyncRecord],
    log_lines: List[str],
    *,
    preferred_pairs: Optional[Sequence[Dict[str, Any]]] = None,
) -> List[Dict[str, Any]]:
    tsv_candidates = [
        rec for rec in tsv_records
        if rec.duration_sec is None or float(rec.duration_sec) >= 5.0
    ]
    if not c3d_records or not tsv_candidates:
        return []
    eval_matrix: List[List[Optional[Dict[str, Any]]]] = []
    cost = np.full((len(c3d_records), len(tsv_candidates)), 6.0, dtype=float)
    for i, c3d in enumerate(c3d_records):
        row: List[Optional[Dict[str, Any]]] = []
        for j, tsv in enumerate(tsv_candidates):
            eval_info = _evaluate_c3d_tsv_candidate(c3d, tsv, preferred_pairs=preferred_pairs)
            row.append(eval_info)
            if eval_info is not None:
                cost[i, j] = float(eval_info.get("score") or 6.0)
        eval_matrix.append(row)
    pairs = _pair_index_cost_matrix(cost, skip_penalty=4.0)
    matches: List[Dict[str, Any]] = []
    for match_id, (i, j, pair_cost) in enumerate(pairs, start=1):
        eval_info = eval_matrix[i][j]
        if eval_info is None:
            continue
        match = _build_c3d_tsv_match_from_eval(eval_info, match_id=match_id)
        _apply_review_defaults(match)
        matches.append(match)
        raw_result = eval_info.get("raw_result") or {}
        dedicated = eval_info.get("dedicated") or {}
        log_lines.append(
            f"[c3d-tsv-pair] {match_id:03d} c3d={Path(c3d_records[i].path).name} tsv={Path(tsv_candidates[j].path).name} "
            f"score={pair_cost:.3f} certainty={match.get('certainty')} basis={eval_info.get('basis')} "
            f"raw={raw_result.get('quality')} corr={raw_result.get('corr')} lag={raw_result.get('lag_sec')}s "
            f"sync={dedicated.get('quality')} mean_abs={dedicated.get('mean_abs_delta_ms')}ms max_abs={dedicated.get('max_abs_delta_ms')}ms"
        )
    return matches


def _build_triplet_seed_hints(
    pair_matches: Sequence[Dict[str, Any]],
    tsv_records: Sequence[SyncRecord],
) -> Dict[int, List[str]]:
    tsv_by_index: Dict[int, List[SyncRecord]] = {}
    for rec in tsv_records:
        idx = _file_numeric_index(rec.path)
        if idx is None:
            continue
        tsv_by_index.setdefault(idx, []).append(rec)
    out: Dict[int, List[str]] = {}
    for match in pair_matches:
        c3d_path = ((match.get("c3d") or {}).get("path") or "")
        idx = _file_numeric_index(c3d_path)
        if idx is None:
            continue
        hinted = tsv_by_index.get(idx) or []
        if hinted:
            out[int(match.get("match_id") or 0)] = [rec.path for rec in hinted]
    return out


def _build_c3d_tsv_seed_pairs(
    c3d_records: Sequence[SyncRecord],
    tsv_records: Sequence[SyncRecord],
) -> List[Tuple[SyncRecord, SyncRecord]]:
    tsv_by_index: Dict[int, List[SyncRecord]] = {}
    for rec in tsv_records:
        idx = _file_numeric_index(rec.path)
        if idx is None:
            continue
        tsv_by_index.setdefault(idx, []).append(rec)
    out: List[Tuple[SyncRecord, SyncRecord]] = []
    used_tsv: set[str] = set()
    for c3d in c3d_records:
        idx = _file_numeric_index(c3d.path)
        if idx is None:
            continue
        candidates = [rec for rec in (tsv_by_index.get(idx) or []) if rec.path not in used_tsv]
        if len(candidates) != 1:
            continue
        out.append((c3d, candidates[0]))
        used_tsv.add(candidates[0].path)
    return out


def _derive_preferred_pairs_from_matches(matches: Sequence[Dict[str, Any]]) -> List[Dict[str, Any]]:
    seen: set[Tuple[str, str, str]] = set()
    out: List[Dict[str, Any]] = []
    for match in matches:
        alignment = match.get("alignment") or {}
        tsv_channel = str(alignment.get("raw_label_match_tsv") or "").strip()
        c3d_channel = str(alignment.get("raw_label_match_c3d") or "").strip()
        c3d_kind = str(alignment.get("raw_label_match_c3d_kind") or "analog").strip().lower() or "analog"
        if not tsv_channel or not c3d_channel:
            continue
        key = (tsv_channel, c3d_channel, c3d_kind)
        if key in seen:
            continue
        seen.add(key)
        out.append(
            {
                "kind": "raw",
                "tsv_channel": tsv_channel,
                "c3d_channel": c3d_channel,
                "c3d_kind": c3d_kind,
                "label_match": "derived_from_triplet",
            }
        )
    return out


def analyze_folder(folder: Path, match_options: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    folder = folder.resolve()
    _apply_sync_channel_overrides(match_options)
    _apply_tracebio_paths_root_override(match_options)
    log_lines: List[str] = []
    log_lines.append(f"[{_now_iso()}] Scan start: {folder}")
    if (match_options or {}).get("sync_channel_map"):
        log_lines.append(
            f"[sync] channel map override in effect: OTB4/C3D dedicated sync={SYNC_OTB_DEVICE} {SYNC_OTB_SUBTITLE} <-> {SYNC_C3D_LABEL}; "
            f"TSV bridge sync=C3D {SYNC_C3D_TSV_BRIDGE_LABEL} (default otherwise: {_SYNC_CHANNEL_DEFAULTS['SYNC_OTB_SUBTITLE']} / {_SYNC_CHANNEL_DEFAULTS['SYNC_C3D_LABEL']} / {_SYNC_CHANNEL_DEFAULTS['SYNC_C3D_TSV_BRIDGE_LABEL']})."
        )
    preferred_pairs = _normalize_global_pair_specs((match_options or {}).get("preferred_channel_pairs"))
    configured_sync_pulse_duration_ms = (match_options or {}).get("sync_pulse_duration_ms")
    plausible_sync_pulse_durations_ms = [
        float(v) for v in ((match_options or {}).get("plausible_sync_pulse_durations_ms") or []) if v not in (None, "")
    ]
    configured_sync_decrement_ms = (match_options or {}).get("sync_decrement_ms")
    plausible_sync_decrements_ms = [
        float(v) for v in ((match_options or {}).get("plausible_sync_decrements_ms") or []) if v not in (None, "")
    ]
    if preferred_pairs:
        log_lines.append(f"[pairing] preferred global raw pairs: {json.dumps(preferred_pairs, ensure_ascii=False)}")
    if configured_sync_pulse_duration_ms not in (None, ""):
        log_lines.append(
            f"[sync] configured SyncMini / Syncstation TTL duration={float(configured_sync_pulse_duration_ms):g} ms "
            f"(plausible from sampled data: {', '.join(f'{v:g}' for v in plausible_sync_pulse_durations_ms) or 'not available'} ms)."
        )
    if configured_sync_decrement_ms not in (None, ""):
        log_lines.append(
            f"[sync] configured SyncMini decrement={float(configured_sync_decrement_ms):g} ms "
            f"(plausible from sampled data: {', '.join(f'{v:g}' for v in plausible_sync_decrements_ms) or 'not available'} ms)."
        )
    filename_clock_offset_sec = _infer_root_filename_clock_offset_sec(folder) or 0.0
    log_lines.append(
        f"[timing] filename clock offset={filename_clock_offset_sec:.3f}s ({filename_clock_offset_sec / 3600.0:.6f}h) "
        f"derived from file modification times."
    )

    otb4_records: List[SyncRecord] = []
    c3d_records: List[SyncRecord] = []
    tsv_records: List[SyncRecord] = []
    unmatched: List[Dict[str, Any]] = []

    for path in _iter_source_files(folder, ".otb4", excluded_dir_names=("matched", "accepted", "__pycache__", ".git")):
        rec = _extract_otb4_record(path, include_probe_sync_diagnostics=False)
        otb4_records.append(rec)
        log_lines.append(
            f"[otb4] {path.name}: sync={rec.sync_present} quality={rec.sync_quality} "
            f"channel={rec.sync_channel} edges={rec.edge_count}"
        )
        for note in rec.notes:
            log_lines.append(f"  - {note}")
        _log_ttl_session_bounds("otb4", path, log_lines)

    for path in _iter_source_files(folder, ".c3d", excluded_dir_names=("matched", "accepted", "__pycache__", ".git")):
        rec = _extract_c3d_record(path)
        c3d_records.append(rec)
        log_lines.append(
            f"[c3d] {path.name}: sync={rec.sync_present} quality={rec.sync_quality} "
            f"channel={rec.sync_channel} edges={rec.edge_count}"
        )
        for note in rec.notes:
            log_lines.append(f"  - {note}")
        _log_ttl_session_bounds("c3d", path, log_lines)

    for path in _iter_source_files(folder, ".tsv", excluded_dir_names=("matched", "accepted", "__pycache__", ".git")):
        rec = _extract_tsv_record(path)
        tsv_records.append(rec)
        log_lines.append(
            f"[tsv] {path.name}: sync={rec.sync_present} quality={rec.sync_quality} "
            f"channel={rec.sync_channel} edges={rec.edge_count}"
        )
        for note in rec.notes:
            log_lines.append(f"  - {note}")
        _log_ttl_session_bounds("tsv", path, log_lines)

    pair_matches: List[Dict[str, Any]] = []
    matched_tsv: List[Dict[str, Any]] = []
    if otb4_records and c3d_records:
        otb4_to_c3d = _pair_records(otb4_records, c3d_records)
        fallback_pairs = _channel3_pairing_fallback(otb4_records, c3d_records, otb4_to_c3d, folder, log_lines)
        if fallback_pairs:
            otb4_to_c3d = otb4_to_c3d + fallback_pairs
        otb4_to_c3d = _channel3_weak_pair_rescue(otb4_records, c3d_records, otb4_to_c3d, folder, log_lines)
        otb4_to_c3d.sort(key=lambda t: t[0].path)

        pair_id = 1
        for otb, c3d, cost in otb4_to_c3d:
            certainty = _summarize_pair_cost(cost)
            alignment = {
                "source_mode": "otb4_c3d_tsv",
                "sync_channel": "shared TTL",
                "configured_sync_pulse_duration_ms": float(configured_sync_pulse_duration_ms) if configured_sync_pulse_duration_ms not in (None, "") else None,
                "plausible_sync_pulse_durations_ms": plausible_sync_pulse_durations_ms,
                "configured_sync_decrement_ms": float(configured_sync_decrement_ms) if configured_sync_decrement_ms not in (None, "") else None,
                "plausible_sync_decrements_ms": plausible_sync_decrements_ms,
                "overlap_start_sec": max(
                    otb.edge_times_sec[0] if otb.edge_times_sec else 0.0,
                    c3d.edge_times_sec[0] if c3d.edge_times_sec else 0.0,
                ),
                "overlap_end_sec": min(
                    otb.edge_times_sec[-1] if otb.edge_times_sec else 0.0,
                    c3d.edge_times_sec[-1] if c3d.edge_times_sec else 0.0,
                ),
            }
            triplet = _triplet_spike_agreement([otb.to_json(), c3d.to_json()])
            alignment["sync_triplet_quality"] = triplet["quality"]
            alignment["sync_triplet_spike_mean_abs_ms"] = triplet["mean_abs_delta_ms"]
            alignment["sync_triplet_spike_max_abs_ms"] = triplet["max_abs_delta_ms"]
            alignment["sync_triplet_spike_count"] = triplet["spike_count"]
            alignment["sync_triplet_pairwise"] = triplet["pairwise"]
            log_lines.append(
                f"[pair] {pair_id:03d} otb4={Path(otb.path).name} c3d={Path(c3d.path).name} "
                f"cost={cost:.6f} certainty={certainty} spikes={triplet['quality']} "
                f"mean_abs={triplet['mean_abs_delta_ms']}ms max_abs={triplet['max_abs_delta_ms']}ms"
            )
            pair_matches.append(
                {
                    "match_id": pair_id,
                    "certainty": certainty,
                    "pair_cost": cost,
                    "otb4": otb.to_json(),
                    "c3d": c3d.to_json(),
                    "tsv": None,
                    "alignment": alignment,
                }
            )
            pair_id += 1

        for match in pair_matches:
            match.setdefault("alignment", {})["otb4_repair_evaluated"] = False
        log_lines.append("[repair] OTB4 repair evaluation deferred until review selection or MAT export.")
        seed_hints = _build_triplet_seed_hints(pair_matches, tsv_records)
        if seed_hints:
            seeded_pair_matches = [match for match in pair_matches if int(match.get("match_id") or 0) in set(sorted(seed_hints)[:TRIPLET_SEED_LIMIT])]
            log_lines.append(
                f"[triplet-seed] found {sum(len(v) for v in seed_hints.values())} hinted TSV candidate(s) "
                f"for {len(seed_hints)} OTB4/C3D pair(s) by shared file index; "
                f"evaluating the first {len(seeded_pair_matches)} to derive raw matching rules."
            )
            matched_tsv.extend(
                _match_tsv_records(
                    seeded_pair_matches,
                    tsv_records,
                    log_lines,
                    filename_clock_offset_sec=filename_clock_offset_sec,
                    preferred_pairs=preferred_pairs,
                    candidate_paths_by_match=seed_hints,
                    restrict_to_hints=True,
                )
            )
        derived_pairs = _derive_preferred_pairs_from_matches([match for match in pair_matches if match.get("tsv")])
        second_pass_pairs = derived_pairs or preferred_pairs
        unresolved_pairs = [match for match in pair_matches if not match.get("tsv")]
        if unresolved_pairs:
            used_tsv_paths = [str((match.get("tsv") or {}).get("path") or "") for match in pair_matches if match.get("tsv")]
            if derived_pairs:
                log_lines.append(f"[pairing] derived raw pairs from matched triplets: {json.dumps(derived_pairs, ensure_ascii=False)}")
            elif preferred_pairs:
                log_lines.append("[pairing] no triplet-derived pairs were available; falling back to initial raw rules for unresolved doublets.")
            matched_tsv.extend(
                _match_tsv_records(
                    unresolved_pairs,
                    tsv_records,
                    log_lines,
                    filename_clock_offset_sec=filename_clock_offset_sec,
                    preferred_pairs=second_pass_pairs,
                    initially_used_paths=used_tsv_paths,
                    candidate_paths_by_match=seed_hints,
                    restrict_to_hints=bool(seed_hints),
                )
            )
            unresolved_pairs = [match for match in pair_matches if not match.get("tsv")]
            used_tsv_paths = [str((match.get("tsv") or {}).get("path") or "") for match in pair_matches if match.get("tsv")]
        if unresolved_pairs and not derived_pairs:
            matched_tsv.extend(
                _match_tsv_records(
                    unresolved_pairs,
                    tsv_records,
                    log_lines,
                    filename_clock_offset_sec=filename_clock_offset_sec,
                    preferred_pairs=preferred_pairs,
                    initially_used_paths=used_tsv_paths,
                )
            )
    elif c3d_records and tsv_records:
        seeded_pairs = _build_c3d_tsv_seed_pairs(c3d_records, tsv_records)[:TRIPLET_SEED_LIMIT]
        seeded_matches: List[Dict[str, Any]] = []
        used_c3d_paths: set[str] = set()
        used_tsv_paths: set[str] = set()
        if seeded_pairs:
            log_lines.append(
                f"[triplet-seed] found {len(seeded_pairs)} hinted C3D/TSV pair(s) by shared file index for initial raw matching."
            )
            for match_id, (c3d, tsv) in enumerate(seeded_pairs, start=1):
                eval_info = _evaluate_c3d_tsv_candidate(c3d, tsv, preferred_pairs=preferred_pairs)
                if eval_info is None:
                    continue
                match = _build_c3d_tsv_match_from_eval(eval_info, match_id=match_id)
                _apply_review_defaults(match)
                seeded_matches.append(match)
                used_c3d_paths.add(c3d.path)
                used_tsv_paths.add(tsv.path)
                raw_result = eval_info.get("raw_result") or {}
                log_lines.append(
                    f"[c3d-tsv-seed] {match_id:03d} c3d={Path(c3d.path).name} tsv={Path(tsv.path).name} "
                    f"certainty={match.get('certainty')} raw={raw_result.get('quality')} "
                    f"corr={raw_result.get('corr')} lag={raw_result.get('lag_sec')}s"
                )
        derived_pairs = _derive_preferred_pairs_from_matches(seeded_matches)
        remaining_c3d = [rec for rec in c3d_records if rec.path not in used_c3d_paths]
        remaining_tsv = [rec for rec in tsv_records if rec.path not in used_tsv_paths]
        fallback_pairs = derived_pairs or preferred_pairs
        pair_matches = list(seeded_matches)
        if remaining_c3d and remaining_tsv:
            if derived_pairs:
                log_lines.append(f"[pairing] derived raw pairs from seeded C3D/TSV matches: {json.dumps(derived_pairs, ensure_ascii=False)}")
            elif preferred_pairs:
                log_lines.append("[pairing] no seeded C3D/TSV derivations were available; falling back to initial raw rules for remaining doublets.")
            pair_matches.extend(
                _match_c3d_tsv_records(
                    remaining_c3d,
                    remaining_tsv,
                    log_lines,
                    preferred_pairs=fallback_pairs,
                )
            )
        log_lines.append(f"[mode] C3D+TSV matching mode active (OTB4 absent).")
    else:
        log_lines.append("[mode] No supported file combination found for matching.")
    pair_matches.sort(key=_c3d_review_sort_key)
    for idx, match in enumerate(pair_matches, start=1):
        match["match_id"] = idx
        _apply_review_defaults(match)
    certain_triplets = [match for match in pair_matches if match.get("tsv") and match.get("otb4")]
    pair_only_matches = [match for match in pair_matches if not match.get("tsv")]
    used_otb_paths = {str((match.get("otb4") or {}).get("path") or "") for match in pair_matches}
    used_c3d_paths = {str((match.get("c3d") or {}).get("path") or "") for match in pair_matches}
    startup_messages: List[str] = []
    if otb4_records and c3d_records and not tsv_records:
        startup_messages.append(
            "Two-file review mode: OTB4 and C3D were found, TSV is absent. Pair-only matches can still be reviewed and accepted."
        )
    if c3d_records and tsv_records and not otb4_records:
        startup_messages.append(
            "Two-file review mode: C3D and TSV were found, OTB4 is absent. Matches use the exact or configured [raw] channel pair(s) only."
        )
    if configured_sync_pulse_duration_ms not in (None, ""):
        startup_messages.append(
            f"Configured SyncMini / Syncstation TTL duration: {float(configured_sync_pulse_duration_ms):g} ms "
            f"(plausible sampled durations: {', '.join(f'{v:g}' for v in plausible_sync_pulse_durations_ms) or 'not available'} ms)."
        )
    if configured_sync_decrement_ms not in (None, ""):
        startup_messages.append(
            f"Configured SyncMini decrement: {float(configured_sync_decrement_ms):g} ms "
            f"(plausible sampled decrements: {', '.join(f'{v:g}' for v in plausible_sync_decrements_ms) or 'not available'} ms)."
        )
    if pair_only_matches:
        startup_messages.append(
            f"{len(pair_only_matches)} certain OTB4/C3D pair(s) are included in review without a TSV match."
        )
        for match in pair_only_matches:
            reason = (match.get("alignment") or {}).get("tsv_skip_reason") or "No TSV reason recorded."
            startup_messages.append(f"{Path(match['c3d']['path']).name}: {reason}")
    for rec in tsv_records:
        if rec.path not in {item["path"] for item in matched_tsv}:
            if rec.sync_quality == "certain" and rec.edge_count >= 4:
                log_lines.append(
                    f"[tsv-candidate] {Path(rec.path).name}: sync present but not selected as a certain match."
                )
            else:
                log_lines.append(
                    f"[tsv-missing] {Path(rec.path).name}: sync channel missing or too weak for a certain match."
                )

    for match in pair_matches:
        if not (match.get("otb4") and match.get("c3d")):
            continue
        if (match.get("alignment") or {}).get("otb4_c3d_edge_alignment"):
            continue
        # Pairs with no TSV attached never went through _match_tsv_records,
        # so the channel-2/channel-3 diagnosis has not run for them yet --
        # run it now so it is logged and available at scan time, not only
        # lazily the first time someone opens the match in the review UI.
        edge_align = _select_otb4_c3d_edge_alignment(match)
        match.setdefault("alignment", {})["otb4_c3d_edge_alignment"] = edge_align
        if edge_align.get("diagnostic_note"):
            log_lines.append(f"[sync-diag] match {match['match_id']:03d}: {edge_align['diagnostic_note']}")
        dedicated = _dedicated_sync_agreement_for_edge_alignment(match, edge_align)
        match["alignment"]["dedicated_sync_quality"] = dedicated.get("quality")
        match["alignment"]["dedicated_sync_pair_quality"] = dedicated.get("pair_quality")
        match["alignment"]["dedicated_sync_mean_abs_ms"] = dedicated.get("mean_abs_delta_ms")
        match["alignment"]["dedicated_sync_max_abs_ms"] = dedicated.get("max_abs_delta_ms")
        match["alignment"]["dedicated_sync_spike_count"] = dedicated.get("spike_count")
        match["alignment"]["dedicated_sync_pairwise"] = dedicated.get("pairwise")
        match["alignment"]["sync_triplet_quality"] = dedicated.get("quality")
        match["alignment"]["sync_triplet_spike_mean_abs_ms"] = dedicated.get("mean_abs_delta_ms")
        match["alignment"]["sync_triplet_spike_max_abs_ms"] = dedicated.get("max_abs_delta_ms")
        match["alignment"]["sync_triplet_spike_count"] = dedicated.get("spike_count")
        match["alignment"]["sync_triplet_pairwise"] = dedicated.get("pairwise")
        match["alignment"]["plot_time_shifts_sec"] = _match_plot_shifts(match)
        match["alignment"]["inner_merge"] = _build_inner_merge_alignment(match)

    summary = {
        "otb4_count": len(otb4_records),
        "c3d_count": len(c3d_records),
        "tsv_count": len(tsv_records),
        "pair_count": len(pair_matches),
        "certain_pair_count": sum(1 for match in pair_matches if match.get("certainty") == "certain"),
        "certain_tsv_count": sum(1 for match in pair_matches if match.get("tsv")),
        "certain_triplet_count": len(certain_triplets),
        "auto_accept_count": sum(1 for match in pair_matches if (match.get("review") or {}).get("auto_accept")),
        "filename_clock_offset_sec": round(float(filename_clock_offset_sec), 6),
        "match_mode": "otb4_c3d_tsv" if otb4_records and c3d_records else "c3d_tsv" if c3d_records and tsv_records else "unsupported",
        "preferred_channel_pairs": preferred_pairs,
        "sync_pulse_duration_ms": float(configured_sync_pulse_duration_ms) if configured_sync_pulse_duration_ms not in (None, "") else None,
        "plausible_sync_pulse_durations_ms": plausible_sync_pulse_durations_ms,
        "sync_decrement_ms": float(configured_sync_decrement_ms) if configured_sync_decrement_ms not in (None, "") else None,
        "plausible_sync_decrements_ms": plausible_sync_decrements_ms,
    }
    log_lines.append(f"[summary] {json.dumps(summary, ensure_ascii=False)}")
    log_lines.append(f"[{_now_iso()}] Scan complete.")
    mapping = {
        "source_root": str(folder),
        "created_at": _now_iso(),
        "summary": summary,
        "matches": pair_matches,
        "triplet_matches": certain_triplets,
        "pair_only_matches": pair_only_matches,
        "tsv_candidates": matched_tsv,
        "unmatched": unmatched,
        "startup_messages": startup_messages,
        "filename_clock_offset_sec": round(float(filename_clock_offset_sec), 6),
        "match_options": {
            "preferred_channel_pairs": preferred_pairs,
            "sync_pulse_duration_ms": float(configured_sync_pulse_duration_ms) if configured_sync_pulse_duration_ms not in (None, "") else None,
            "plausible_sync_pulse_durations_ms": plausible_sync_pulse_durations_ms,
            "sync_decrement_ms": float(configured_sync_decrement_ms) if configured_sync_decrement_ms not in (None, "") else None,
            "plausible_sync_decrements_ms": plausible_sync_decrements_ms,
        },
        "source_records": {
            "otb4": [rec.to_json() for rec in otb4_records],
            "c3d": [rec.to_json() for rec in c3d_records],
            "tsv": [rec.to_json() for rec in tsv_records],
        },
        "unmatched_c3d_records": [rec.to_json() for rec in c3d_records if str(rec.path) not in used_c3d_paths],
        "unmatched_otb4_records": [rec.to_json() for rec in otb4_records if str(rec.path) not in used_otb_paths],
    }
    return {"mapping": mapping, "log_lines": log_lines}


def _write_text(path: Path, lines: Sequence[str]) -> None:
    path.write_text("\n".join(lines) + "\n", encoding="utf-8")


def _write_repair_jsons(export_dir: Path, mapping: Dict[str, Any]) -> None:
    repair_dir = export_dir / "matched"
    repair_dir.mkdir(exist_ok=True, parents=True)
    for existing in repair_dir.glob("*_repair.json"):
        try:
            existing.unlink()
        except Exception:
            pass
    for match in mapping.get("matches", []):
        alignment = match.get("alignment") or {}
        repair = alignment.get("otb4_repair")
        device_repairs = alignment.get("otb4_device_repairs") or {}
        if not isinstance(repair, dict) and not isinstance(device_repairs, dict):
            continue
        path = (repair.get("json_path") if isinstance(repair, dict) else None) or ((match.get("export_plan") or {}).get("repair_json") or {}).get("path")
        if not path:
            continue
        out_path = Path(path)
        out_path.parent.mkdir(exist_ok=True, parents=True)
        payload = {
            **(repair if isinstance(repair, dict) else {}),
            "device_repairs": device_repairs if isinstance(device_repairs, dict) else {},
        }
        out_path.write_text(json.dumps(payload, indent=2, ensure_ascii=False), encoding="utf-8")


def _safe_copy(src: Path, dst: Path) -> None:
    dst.parent.mkdir(parents=True, exist_ok=True)
    shutil.copy2(src, dst)


def _clean_output_dir(path: Path) -> None:
    path.mkdir(exist_ok=True, parents=True)
    for existing in list(path.iterdir()):
        if existing.is_dir():
            shutil.rmtree(existing)
        else:
            existing.unlink()


def _clean_output_dir_except(path: Path, keep_suffixes: Sequence[str]) -> None:
    path.mkdir(exist_ok=True, parents=True)
    keep = {suffix.lower() for suffix in keep_suffixes}
    for existing in list(path.iterdir()):
        if existing.is_dir():
            shutil.rmtree(existing)
        elif existing.suffix.lower() not in keep:
            existing.unlink()


def _planned_copy_name(match: Dict[str, Any], key: str, saved_stamp: str) -> Optional[str]:
    item = match.get(key)
    if not item:
        return None
    src = Path(item["path"])
    return f"{_match_base_name(match, saved_stamp)}{src.suffix.lower()}"


def _tsv_sidecar_json_path(match: Dict[str, Any]) -> Optional[Path]:
    tsv = match.get("tsv") or {}
    tsv_path = tsv.get("path")
    if not tsv_path:
        return None
    sidecar = Path(str(tsv_path)).with_suffix(".json")
    return sidecar if sidecar.exists() else None


def _repair_json_name(match: Dict[str, Any], saved_stamp: str) -> str:
    return f"{_match_base_name(match, saved_stamp)}_repair.json"


def _mat_export_name(match: Dict[str, Any], saved_stamp: str) -> str:
    return f"{_match_base_name(match, saved_stamp)}.mat"


def _match_source_keys(match: Dict[str, Any]) -> Tuple[str, ...]:
    return tuple(key for key in ("otb4", "c3d", "tsv") if match.get(key))


def _mat_export_supported(match: Dict[str, Any]) -> bool:
    return len(_match_source_keys(match)) >= 2


def _tracebio_reconstruction_supported(match: Dict[str, Any]) -> bool:
    return bool(match.get("c3d") and match.get("tsv"))


def _pipe_export_supported(match: Dict[str, Any]) -> bool:
    return bool(match.get("otb4") and match.get("c3d"))


def _match_base_name(match: Dict[str, Any], saved_stamp: str) -> str:
    stamp = saved_stamp
    tsv = match.get("tsv") or {}
    tsv_path = tsv.get("path")
    if tsv_path:
        tsv_dt = _parse_timestamp_from_name(Path(str(tsv_path)))
        if tsv_dt is not None:
            stamp = tsv_dt.strftime("%Y%m%d_%H%M%S")
    c3d = match.get("c3d") or {}
    c3d_path = c3d.get("path")
    if c3d_path:
        stem = Path(str(c3d_path)).stem
        if stem:
            return f"{stem}_{stamp}"
    return f"m{int(match['match_id']):03d}_{stamp}"


def _match_export_plan(match: Dict[str, Any], export_dir: Path, saved_stamp: str) -> Dict[str, Any]:
    mat_name = _mat_export_name(match, saved_stamp)
    mat_path = export_dir / "matched" / mat_name
    pipe_mat_path = _pipe_mat_path(mat_path)
    pipe_json_path = _pipe_json_path(pipe_mat_path)
    repair_json_name = _repair_json_name(match, saved_stamp)
    repair_dir_path = export_dir / "matched" / repair_json_name
    plan: Dict[str, Any] = {
        "matched": {},
        "mat": {
            "filename": mat_name,
            "path": str(mat_path),
        },
        "pipe_mat": {
            "filename": pipe_mat_path.name,
            "path": str(pipe_mat_path),
        },
        "pipe_json": {
            "filename": pipe_json_path.name,
            "path": str(pipe_json_path),
        },
        "repair_json": {
            "filename": repair_json_name,
            "path": str(repair_dir_path),
        },
    }
    for key in ["otb4", "c3d", "tsv"]:
        item = match.get(key)
        if not item:
            continue
        src = Path(item["path"])
        matched_name = _planned_copy_name(match, key, saved_stamp)
        plan["matched"][key] = {
            "original_path": str(src),
            "original_filename": src.name,
            "renamed_filename": matched_name,
            "renamed_path": str(export_dir / "matched" / matched_name) if matched_name else None,
        }
    sidecar_json = _tsv_sidecar_json_path(match)
    if sidecar_json is not None:
        matched_json_name = f"{_match_base_name(match, saved_stamp)}_traceBioRTFB.json"
        plan["matched"]["tsv_json"] = {
            "original_path": str(sidecar_json),
            "original_filename": sidecar_json.name,
            "renamed_filename": matched_json_name,
            "renamed_path": str(export_dir / "matched" / matched_json_name),
        }
    if (match.get("alignment") or {}).get("otb4_repair"):
        plan["matched"]["repair_json"] = {
            "original_path": str(repair_dir_path),
            "original_filename": repair_json_name,
            "renamed_filename": repair_json_name,
            "renamed_path": str(export_dir / "matched" / repair_json_name),
        }
    return plan


def _attach_export_plan(match: Dict[str, Any], export_dir: Path, saved_stamp: str) -> None:
    match["saved_at"] = saved_stamp
    match["export_plan"] = _match_export_plan(match, export_dir, saved_stamp)
    repair = (match.get("alignment") or {}).get("otb4_repair")
    if isinstance(repair, dict):
        repair["json_path"] = ((match.get("export_plan") or {}).get("repair_json") or {}).get("path")
    for key in ["otb4", "c3d", "tsv"]:
        item = match.get(key)
        if not item:
            continue
        src = Path(item["path"])
        item["original_filename"] = src.name
        item["planned_matched_filename"] = (
            ((match.get("export_plan") or {}).get("matched") or {}).get(key, {}).get("renamed_filename")
        )


def _has_user_input(mapping: Dict[str, Any]) -> bool:
    for match in mapping.get("matches", []):
        review = match.get("review") or {}
        if review.get("user_decision") is not None or review.get("user_touched"):
            return True
    return False


def _review_complete(mapping: Dict[str, Any]) -> bool:
    reviewed, total = _review_progress(mapping)
    return total > 0 and reviewed == total


def _copy_match_group(match: Dict[str, Any], target_dir: Path, saved_stamp: str) -> Dict[str, Optional[str]]:
    copied = {"otb4": None, "c3d": None, "tsv": None, "tsv_json": None, "repair_json": None}
    plan_group = ((match.get("export_plan") or {}).get("matched") or {})
    for key in ["otb4", "c3d", "tsv", "tsv_json", "repair_json"]:
        if key in {"otb4", "c3d", "tsv"}:
            item = match.get(key)
            if not item:
                continue
            src = Path(item["path"])
        else:
            entry = plan_group.get(key) or {}
            src_path = entry.get("original_path")
            if not src_path or not Path(src_path).exists():
                continue
            src = Path(src_path)
        entry = plan_group.get(key) or {}
        filename = entry.get("renamed_filename")
        if not filename:
            continue
        dst = target_dir / filename
        try:
            if src.resolve() != dst.resolve():
                _safe_copy(src, dst)
        except Exception:
            _safe_copy(src, dst)
        copied[key] = str(dst)
    return copied


def _write_review_outputs(export_dir: Path, mapping: Dict[str, Any], saved_stamp: str) -> Tuple[Path, Path]:
    export_dir = export_dir.resolve()
    matched_dir = export_dir / "matched"
    legacy_accepted_dir = export_dir / "accepted"
    if legacy_accepted_dir.exists():
        shutil.rmtree(legacy_accepted_dir, ignore_errors=True)
        if not _review_complete(mapping):
            matched_dir.mkdir(exist_ok=True, parents=True)
    else:
        matched_dir.mkdir(exist_ok=True, parents=True)
        for match in mapping.get("matches", []):
            if not (match.get("review") or {}).get("final_accept"):
                continue
            copied = _copy_match_group(match, matched_dir, saved_stamp)
            match.setdefault("review_outputs", {})["matched_copied"] = copied
            repair = (match.get("alignment") or {}).get("otb4_repair")
            if isinstance(repair, dict) and copied.get("repair_json"):
                matched_repair_path = str(copied["repair_json"])
                repair["json_path"] = matched_repair_path
                export_plan = match.setdefault("export_plan", {})
                if isinstance(export_plan.get("repair_json"), dict):
                    export_plan["repair_json"]["path"] = matched_repair_path
                matched_group = export_plan.setdefault("matched", {})
                if isinstance(matched_group.get("repair_json"), dict):
                    matched_group["repair_json"]["renamed_path"] = matched_repair_path

    accepted_matches = [
        match for match in mapping.get("matches", [])
        if (match.get("review") or {}).get("final_accept")
    ]
    accepted_mapping = {
        "source_root": mapping["source_root"],
        "created_at": mapping["created_at"],
        "saved_at": saved_stamp,
        "summary": {
            **mapping.get("summary", {}),
            "accepted_count": len(accepted_matches),
            "reviewed_count": sum(1 for match in mapping.get("matches", []) if (match.get("review") or {}).get("reviewed")),
        },
        "matches": accepted_matches,
    }
    accepted_json_path = export_dir / "accepted_matches.json"
    accepted_json_path.write_text(json.dumps(accepted_mapping, indent=2, ensure_ascii=False), encoding="utf-8")
    return accepted_json_path, matched_dir


def export_results(source_folder: Path, export_dir: Path, mapping: Dict[str, Any], log_lines: Sequence[str]) -> Tuple[Path, Path, Path]:
    export_dir = export_dir.resolve()
    matched_dir = export_dir / "matched"
    legacy_accepted_dir = export_dir / "accepted"
    if matched_dir.exists():
        shutil.rmtree(matched_dir, ignore_errors=True)
    if legacy_accepted_dir.exists():
        shutil.rmtree(legacy_accepted_dir, ignore_errors=True)
    saved_stamp = _format_file_stamp()

    mapping_path = export_dir / "matched_files.json"
    log_path = export_dir / "alignment.log"

    safe_mapping = {
        "source_root": mapping["source_root"],
        "created_at": mapping["created_at"],
        "summary": mapping["summary"],
        "matches": [],
        "triplet_matches": [],
        "pair_only_matches": [],
        "tsv_candidates": mapping.get("tsv_candidates", []),
        "unmatched": mapping.get("unmatched", []),
        "startup_messages": list(mapping.get("startup_messages", [])),
        "source_records": mapping.get("source_records", {}),
        "unmatched_c3d_records": mapping.get("unmatched_c3d_records", []),
        "unmatched_otb4_records": mapping.get("unmatched_otb4_records", []),
    }

    for match in mapping["matches"]:
        out_match = dict(match)
        _apply_review_defaults(out_match)
        _attach_export_plan(out_match, export_dir, saved_stamp)
        safe_mapping["matches"].append(out_match)
        if out_match.get("tsv"):
            safe_mapping["triplet_matches"].append(out_match)
        else:
            safe_mapping["pair_only_matches"].append(out_match)

    _ensure_unique_source_assignments(safe_mapping["matches"])
    _refresh_mapping_summary(safe_mapping)
    safe_mapping["saved_at"] = saved_stamp
    safe_mapping["export_root"] = str(export_dir)
    _write_repair_jsons(export_dir, safe_mapping)
    mapping_path.write_text(json.dumps(safe_mapping, indent=2, ensure_ascii=False), encoding="utf-8")
    _write_text(log_path, log_lines)
    _write_review_outputs(export_dir, safe_mapping, saved_stamp)
    return mapping_path, log_path, matched_dir


def run_scan(folder: Path, export_dir: Optional[Path] = None, match_options: Optional[Dict[str, Any]] = None) -> Tuple[Path, Path, Path]:
    result = analyze_folder(folder, match_options=match_options)
    return export_results(folder, export_dir or folder, result["mapping"], result["log_lines"])


# ---------------- Viewer ----------------
def _load_mapping(mapping_path: Path) -> Dict[str, Any]:
    with open(mapping_path, "r", encoding="utf-8") as f:
        mapping = json.load(f)
    mapping["export_root"] = str(mapping_path.parent.resolve())
    return mapping


@lru_cache(maxsize=256)
def _load_otb4_channel_base(path: Path, channel_name: str) -> Tuple[np.ndarray, np.ndarray]:
    if channel_name == SYNC_OTB_LABEL:
        t, x, _meta = _load_otb4_aux_channel(path, device=SYNC_OTB_DEVICE, subtitle=SYNC_OTB_SUBTITLE)
        return np.asarray(t, dtype=float), np.asarray(x, dtype=float)
    data, _time, descs, fs, _name, _size = load_otb4_file(str(path))
    flat = []
    for d in descs:
        try:
            flat.append(str(d[0][0]))
        except Exception:
            flat.append(str(d))
    idx = flat.index(channel_name)
    x = np.asarray(data[idx], dtype=float).reshape(-1)
    t = np.arange(len(x), dtype=float) / float(fs)
    return t, x


def _load_otb4_channel(path: Path, channel_name: str, repair_zones: Optional[Sequence[Tuple[int, int]]] = None) -> Tuple[np.ndarray, np.ndarray]:
    t, x = _load_otb4_channel_base(path, channel_name)
    t = np.asarray(t, dtype=float)
    x = np.asarray(x, dtype=float)
    if repair_zones:
        x = _insert_nan_holes_signal(x, repair_zones)
        if t.size >= 2:
            dt = float(np.nanmedian(np.diff(t)))
            if np.isfinite(dt) and dt > 0.0:
                t = np.arange(len(x), dtype=float) * dt
            else:
                t = np.arange(len(x), dtype=float)
        else:
            t = np.arange(len(x), dtype=float)
    return t, x


@lru_cache(maxsize=128)
def _c3d_metadata(path: Path) -> Dict[str, Any]:
    c3d = ezc3d.c3d(str(path), extract_forceplat_data=False)
    analog_labels = list(c3d["parameters"]["ANALOG"]["LABELS"]["value"])
    point_labels = list(c3d["parameters"].get("POINT", {}).get("LABELS", {}).get("value", []))
    if "LABELS2" in c3d["parameters"].get("POINT", {}):
        point_labels += list(c3d["parameters"]["POINT"]["LABELS2"]["value"])
    analog_rate = float(c3d["parameters"]["ANALOG"]["RATE"]["value"][0])
    point_rate = float(c3d["parameters"]["POINT"]["RATE"]["value"][0]) if "POINT" in c3d["parameters"] else None
    return {
        "c3d": c3d,
        "analog_labels": analog_labels,
        "point_labels": point_labels,
        "analog_rate": analog_rate,
        "point_rate": point_rate,
    }


@lru_cache(maxsize=512)
def _load_c3d_analog_channel(path: Path, channel_name: str) -> Tuple[np.ndarray, np.ndarray]:
    meta = _c3d_metadata(path)
    labels = meta["analog_labels"]
    idx = labels.index(channel_name)
    arr = np.asarray(meta["c3d"]["data"]["analogs"], dtype=float)
    subframes, n_channels, n_frames = arr.shape
    x = np.transpose(arr, (2, 0, 1)).reshape(n_frames * subframes, n_channels)[:, idx]
    fs = float(meta["analog_rate"])
    t = np.arange(len(x), dtype=float) / fs
    return t, x


@lru_cache(maxsize=512)
def _load_otb4_track_series(path: Path, device: str, subtitle: str) -> Tuple[np.ndarray, np.ndarray]:
    for _offset, track, raw_arr in _load_otb4_track_data(path):
        if int(track.get("NumberOfChannels", 0) or 0) != 1:
            continue
        if str(track.get("Device", "")).strip() != str(device).strip():
            continue
        if str(track.get("SubTitle", "")).strip() != str(subtitle).strip():
            continue
        raw = np.asarray(raw_arr[0], dtype=float).reshape(-1)
        x = raw * float(_track_conversion_factor(track))
        fs = float(track.get("SamplingFrequency") or 0.0)
        t = np.arange(len(x), dtype=float) / fs if fs > 0 else np.arange(len(x), dtype=float)
        if str(subtitle).strip() == "Ramp":
            x = _to_ascending_ramp(raw).astype(float)
        return t, x
    raise ValueError(f"Missing OTB4 track {device} {subtitle}")


@lru_cache(maxsize=512)
def _load_c3d_point_channel(path: Path, channel_name: str) -> Tuple[np.ndarray, np.ndarray]:
    meta = _c3d_metadata(path)
    labels = meta["point_labels"]
    if "." not in channel_name:
        raise ValueError(f"Point channel must include a coordinate suffix: {channel_name}")
    base, coord = channel_name.rsplit(".", 1)
    idx = labels.index(base)
    coord_idx = {"x": 0, "y": 1, "z": 2, "residual": 3}.get(coord.lower())
    if coord_idx is None:
        raise ValueError(f"Unsupported C3D point coordinate: {coord}")
    arr = np.asarray(meta["c3d"]["data"]["points"], dtype=float)
    if arr.ndim != 3 or arr.shape[0] < 4:
        raise ValueError("Unexpected C3D point data shape.")
    x = arr[coord_idx, idx, :]
    fs = float(meta["point_rate"] or meta["analog_rate"])
    t = np.arange(len(x), dtype=float) / fs
    return t, x


@lru_cache(maxsize=512)
def _load_tsv_channel(path: Path, channel_name: str) -> Tuple[np.ndarray, np.ndarray]:
    _cols, df = _read_tsv_table(path)
    if channel_name in df.columns:
        x = pd.to_numeric(df[channel_name], errors="coerce").to_numpy(dtype=float)
    elif channel_name.strip().lower() == "performed":
        synth = _synth_tsv_performed_values(path, df)
        if synth is None:
            raise KeyError(f"Missing TSV channel: {channel_name}")
        x = np.asarray(synth, dtype=float)
    else:
        raise KeyError(f"Missing TSV channel: {channel_name}")
    if channel_name.strip().lower() == "performed" and not np.any(np.isfinite(x)):
        synth = _synth_tsv_performed_values(path, df)
        if synth is not None and np.any(np.isfinite(synth)):
            x = np.asarray(synth, dtype=float)
    med = np.nanmedian(x) if np.any(np.isfinite(x)) else 0.0
    x = np.nan_to_num(x, nan=med)
    if "t_rel" in df.columns:
        t = pd.to_numeric(df["t_rel"], errors="coerce").to_numpy(dtype=float)
        if not np.all(np.isfinite(t)) or len(t) != len(x):
            t = np.arange(len(x), dtype=float)
    else:
        t = np.arange(len(x), dtype=float)
    return t, x


def _channel_list_for_record(record: Dict[str, Any]) -> List[str]:
    names = record.get("channel_names") or []
    if record["kind"] == "tsv":
        return [n for n in names if n.lower() not in {"ts", "t_rel"}]
    return names


def _otb4_probe_track_options(record: Dict[str, Any]) -> List[Tuple[str, Dict[str, Any]]]:
    options: List[Tuple[str, Dict[str, Any]]] = []
    diag = dict(record.get("probe_sync_diagnostics") or {})
    if not diag:
        path = str(record.get("path") or "")
        if path:
            cached = _OTB4_PROBE_DIAG_CACHE.get(_otb4_probe_diag_cache_key(path, None))
            if cached:
                diag = dict(cached)
                record["probe_sync_diagnostics"] = dict(cached)
            else:
                try:
                    diag = _extract_otb4_probe_sync_diagnostics(Path(path))
                except Exception:
                    diag = {}
                if diag:
                    _OTB4_PROBE_DIAG_CACHE[_otb4_probe_diag_cache_key(path, None)] = dict(diag)
                    record["probe_sync_diagnostics"] = dict(diag)
    for probe in diag.get("probes") or []:
        device = str(probe.get("device") or "").strip()
        if not device:
            continue
        options.append(
            (
                f"OTB4 probe buffer: {device}",
                {"source": "otb4", "channel": f"{device} Buffer", "kind": "probe_buffer", "device": device, "subtitle": "Buffer"},
            )
        )
        options.append(
            (
                f"OTB4 probe ramp: {device}",
                {"source": "otb4", "channel": f"{device} Ramp", "kind": "probe_ramp", "device": device, "subtitle": "Ramp"},
            )
        )
    return options


def _channel_options_for_record(record: Dict[str, Any]) -> List[Tuple[str, Dict[str, Any]]]:
    options: List[Tuple[str, Dict[str, Any]]] = []
    kind = record["kind"]
    if kind == "otb4":
        for ch in _channel_list_for_record(record):
            options.append((f"OTB4: {ch}", {"source": "otb4", "channel": ch, "kind": "sync" if ch == record.get("sync_channel") else "otb4"}))
        options.extend(_otb4_probe_track_options(record))
    elif kind == "c3d":
        for ch in ("copx", "copy"):
            options.append((f"C3D CoP: {ch}", {"source": "c3d", "channel": ch, "kind": "cop"}))
        for ch in record.get("channel_names") or []:
            options.append((f"C3D analog: {ch}", {"source": "c3d", "channel": ch, "kind": "analog"}))
        for ch in record.get("point_channel_names") or []:
            for coord in ("x", "y", "z", "residual"):
                options.append((f"C3D point: {ch}.{coord}", {"source": "c3d", "channel": f"{ch}.{coord}", "kind": "point"}))
    elif kind == "tsv":
        for ch in _channel_list_for_record(record):
            options.append((f"TSV: {ch}", {"source": "tsv", "channel": ch, "kind": "tsv"}))
    return options


_SYNC_CHANNEL_BAND_HEIGHT = 1.2
# OTB4-internal probe/control-vs-AUX2 diagnosis (_expected_sync_markers).
_SYNC_CHANNEL_MARKER_Y = -0.25
# Channel-3 (3_Sync_50ms) OTB4<->C3D cross-machine match diagnosis (_channel3_match_markers).
_SYNC_CHANNEL3_MARKER_Y = -0.5


def _sync_channel_band_offset(channel_num: int) -> float:
    """Vertical band offset for a channel-1/2/3 trace normalized to 0..1
    (see _load_series_for_spec): 1_TTL highest, 2_Sync middle,
    3_Sync_50ms lowest.
    """
    return float(3 - int(channel_num)) * _SYNC_CHANNEL_BAND_HEIGHT


def _tsv_column_by_suffix(match: Dict[str, Any], suffix: str) -> Optional[str]:
    names = ((match.get("tsv") or {}).get("channel_names")) or []
    return next((str(name) for name in names if str(name).endswith(suffix)), None)


def _sync_series_specs(match: Dict[str, Any]) -> List[Dict[str, Any]]:
    """Every source's channel 1 (1_TTL), channel 2 (2_Sync), and channel 3
    (3_Sync_50ms) trace, so a reviewer can visually compare all three
    dedicated sync signals regardless of which one the pairing/alignment
    actually used. Each spec carries "sync_channel_num" (1/2/3), which
    _load_series_for_spec uses to stack same-numbered channels at the same
    plotted height across sources (see _sync_channel_band_offset).
    """
    specs: List[Dict[str, Any]] = []
    for source in ("otb4", "c3d", "tsv"):
        rec = match.get(source)
        if rec and rec.get("sync_present") and rec.get("sync_channel"):
            # TSV's own dedicated sync is always the channel-3 bridge; OTB4/C3D's is channel 2.
            specs.append(
                {
                    "source": source,
                    "kind": "sync",
                    "channel": rec["sync_channel"],
                    "sync_channel_num": 3 if source == "tsv" else 2,
                }
            )
    if (match.get("otb4") or {}).get("path"):
        specs.append(
            {
                "source": "otb4",
                "kind": "sync_ch3",
                "channel": f"{SYNC_OTB_DEVICE} {SYNC_OTB_TSV_BRIDGE_SUBTITLE} (3_Sync_50ms)",
                "otb4_device": SYNC_OTB_DEVICE,
                "otb4_subtitle": SYNC_OTB_TSV_BRIDGE_SUBTITLE,
                "sync_channel_num": 3,
            }
        )
        specs.append(
            {
                "source": "otb4",
                "kind": "sync_ch1",
                "channel": f"{SYNC_OTB_DEVICE} {SYNC_OTB_TTL_SUBTITLE} (1_TTL)",
                "otb4_device": SYNC_OTB_DEVICE,
                "otb4_subtitle": SYNC_OTB_TTL_SUBTITLE,
                "sync_channel_num": 1,
            }
        )
    if (match.get("c3d") or {}).get("path"):
        specs.append({"source": "c3d", "kind": "sync_ch3", "channel": SYNC_C3D_TSV_BRIDGE_LABEL, "sync_channel_num": 3})
        specs.append({"source": "c3d", "kind": "sync_ch1", "channel": SYNC_C3D_TTL_LABEL, "sync_channel_num": 1})
    tsv_ttl_col = _tsv_column_by_suffix(match, SYNC_TSV_TTL_SUFFIX)
    if tsv_ttl_col:
        specs.append({"source": "tsv", "kind": "sync_ch1", "channel": tsv_ttl_col, "sync_channel_num": 1})
    return specs


def _probe_detail_series_specs(match: Dict[str, Any], device: str) -> List[Dict[str, Any]]:
    specs: List[Dict[str, Any]] = []
    diag = _otb4_probe_sync_diagnostics(match)
    probe = next((item for item in (diag.get("probes") or []) if str(item.get("device") or "") == str(device)), None)
    if probe is None:
        return specs
    specs.append({"source": "otb4", "channel": f"{device} Buffer", "kind": "probe_buffer", "device": device, "subtitle": "Buffer"})
    specs.append({"source": "otb4", "channel": f"{device} Ramp", "kind": "probe_ramp", "device": device, "subtitle": "Ramp"})
    return specs


def _raw_series_specs(match: Dict[str, Any]) -> List[Dict[str, Any]]:
    alignment = match.get("alignment") or {}
    tsv_channel = alignment.get("raw_label_match_tsv")
    c3d_channel = alignment.get("raw_label_match_c3d")
    c3d_kind = alignment.get("raw_label_match_c3d_kind") or "analog"
    specs: List[Dict[str, Any]] = []
    if c3d_channel:
        specs.append({"source": "c3d", "kind": "raw", "channel": c3d_channel, "c3d_kind": c3d_kind})
    if tsv_channel:
        specs.append({"source": "tsv", "kind": "raw", "channel": tsv_channel})
    return specs


def _load_series_for_spec(match: Dict[str, Any], spec: Dict[str, Any]) -> Tuple[np.ndarray, np.ndarray]:
    source = spec["source"]
    probe_shift_sec = 0.0
    if source == "otb4":
        if spec.get("kind") in {"probe_buffer", "probe_ramp"} and spec.get("device") and spec.get("subtitle"):
            t, y = _load_otb4_track_series(Path(match[source]["path"]), str(spec.get("device")), str(spec.get("subtitle")))
            diag = _otb4_probe_sync_diagnostics(match)
            probe = next((item for item in (diag.get("probes") or []) if str(item.get("device") or "") == str(spec.get("device"))), None)
            probe_shift_sec = -float((probe or {}).get("optimal_lag_sec") or 0.0)
        elif spec.get("kind") in {"sync_ch1", "sync_ch3"}:
            # Neither AUX 1 (channel 1) nor AUX 3 (channel 3) is looked up by
            # a flat channel-name string like the branch below (that only
            # special-cases channel 2's SYNC_OTB_LABEL) -- same direct AUX
            # loader the channel-3 edge extraction (_otb4_channel_edge_times)
            # and the TTL bounds check (_ttl_channel_bounds) use.
            default_subtitle = SYNC_OTB_TTL_SUBTITLE if spec.get("kind") == "sync_ch1" else SYNC_OTB_TSV_BRIDGE_SUBTITLE
            t, x, _meta = _load_otb4_aux_channel(
                Path(match[source]["path"]),
                device=str(spec.get("otb4_device") or SYNC_OTB_DEVICE),
                subtitle=str(spec.get("otb4_subtitle") or default_subtitle),
            )
            t, y = np.asarray(t, dtype=float), np.asarray(x, dtype=float)
        else:
            device = _otb_label_device(spec["channel"])
            t, y = _load_otb4_channel(
                Path(match[source]["path"]),
                spec["channel"],
                repair_zones=_repair_zones_for_match(match, device=device),
            )
    elif source == "c3d":
        t, y = _load_c3d_series(Path(match[source]["path"]), spec.get("c3d_kind") or spec.get("kind") or "analog", spec["channel"])
    elif source == "tsv":
        t, y = _load_tsv_channel(Path(match[source]["path"]), spec["channel"])
    else:
        raise ValueError(source)
    shift = float(_match_plot_shifts(match).get(source, 0.0))
    channel_num = spec.get("sync_channel_num")
    if isinstance(channel_num, int):
        # Per-trace independent 0..1 normalization (different sensors/
        # sources, so sharing a raw voltage scale isn't meaningful) plus a
        # shared per-channel-number offset, so e.g. OTB4's and C3D's channel
        # 2 traces plot at the *same* height even though their raw voltage
        # ranges differ -- "same-signal data at the same y-axis height".
        y = _normalize_unit_interval(y) + _sync_channel_band_offset(channel_num)
    return t + shift + probe_shift_sec, y


def _mat_field_name(label: str, used: set[str]) -> str:
    text = re.sub(r"[^0-9A-Za-z_]+", "_", str(label).strip())
    text = re.sub(r"_+", "_", text).strip("_")
    if not text:
        text = "field"
    if text[0].isdigit():
        text = f"f_{text}"
    base = text[:63]
    candidate = base
    suffix = 1
    while candidate in used:
        suffix_text = f"_{suffix}"
        candidate = f"{base[: max(1, 63 - len(suffix_text))]}{suffix_text}"
        suffix += 1
    used.add(candidate)
    return candidate


def _crop_aligned_series(t: np.ndarray, y: np.ndarray, start_sec: float, end_sec: float) -> Tuple[np.ndarray, np.ndarray]:
    mask = np.isfinite(t) & (t >= start_sec) & (t <= end_sec)
    if not np.any(mask):
        return np.asarray([], dtype=float), np.asarray([], dtype=float)
    return np.asarray(t[mask], dtype=float), np.asarray(y[mask], dtype=float)


def _relative_time(t: np.ndarray, start_sec: float) -> np.ndarray:
    return np.asarray(t, dtype=float) - float(start_sec)


def _build_otb4_mat_struct(match: Dict[str, Any], start_sec: float, end_sec: float) -> Dict[str, Any]:
    record = match["otb4"]
    path = Path(record["path"])
    data, _time, descs, fs, _name, _size = load_otb4_file(str(path))
    repair_zones = _repair_zones_for_match(match)
    if repair_zones:
        data = _insert_nan_holes_matrix(np.asarray(data, dtype=float), repair_zones)
    labels: List[str] = []
    for d in descs:
        try:
            labels.append(str(d[0][0]))
        except Exception:
            labels.append(str(d))
    used: set[str] = set()
    label_map: Dict[str, str] = {}
    out: Dict[str, Any] = {}
    shift = float(_match_plot_shifts(match).get("otb4", 0.0))
    base_t = np.arange(np.asarray(data).shape[1], dtype=float) / float(fs) + shift
    frames = None
    for idx, label in enumerate(labels):
        y = np.asarray(data[idx], dtype=float).reshape(-1)
        t_crop, y_crop = _crop_aligned_series(base_t, y, start_sec, end_sec)
        if t_crop.size == 0:
            continue
        if frames is None:
            frames = np.arange(t_crop.size, dtype=np.int64)
            out["time"] = _relative_time(t_crop, start_sec)
            out["frames"] = frames
        field = _mat_field_name(label, used)
        out[field] = y_crop
        label_map[field] = label
    if SYNC_OTB_LABEL not in labels:
        t_sync, y_sync = _load_otb4_channel(path, SYNC_OTB_LABEL, repair_zones=repair_zones)
        t_sync = t_sync + shift
        t_crop, y_crop = _crop_aligned_series(t_sync, y_sync, start_sec, end_sec)
        if t_crop.size:
            if "time" not in out:
                out["time"] = _relative_time(t_crop, start_sec)
                out["frames"] = np.arange(t_crop.size, dtype=np.int64)
            field = _mat_field_name(SYNC_OTB_LABEL, used)
            out[field] = y_crop
            label_map[field] = SYNC_OTB_LABEL
    out["label_map"] = label_map
    out["sample_rate"] = float(record.get("sample_rate") or fs)
    return out


def _build_c3d_mat_struct(match: Dict[str, Any], start_sec: float, end_sec: float) -> Dict[str, Any]:
    record = match["c3d"]
    path = Path(record["path"])
    meta = _c3d_metadata(path)
    shift = float(_match_plot_shifts(match).get("c3d", 0.0))
    out: Dict[str, Any] = {"analog": {}, "point": {}, "cop": {}}

    analog_used: set[str] = set()
    analog_map: Dict[str, str] = {}
    for label in record.get("channel_names") or []:
        t, y = _load_c3d_analog_channel(path, label)
        t = t + shift
        t_crop, y_crop = _crop_aligned_series(t, y, start_sec, end_sec)
        if t_crop.size == 0:
            continue
        if "time" not in out["analog"]:
            out["analog"]["time"] = _relative_time(t_crop, start_sec)
            out["analog"]["frames"] = np.arange(t_crop.size, dtype=np.int64)
        field = _mat_field_name(label, analog_used)
        out["analog"][field] = y_crop
        analog_map[field] = label
    out["analog"]["label_map"] = analog_map
    out["analog"]["sample_rate"] = float(meta["analog_rate"])

    point_used: set[str] = set()
    point_map: Dict[str, str] = {}
    for label in record.get("point_channel_names") or []:
        tx, x = _load_c3d_point_channel(path, f"{label}.x")
        ty, y = _load_c3d_point_channel(path, f"{label}.y")
        tz, z = _load_c3d_point_channel(path, f"{label}.z")
        tx = tx + shift
        mask = np.isfinite(tx) & (tx >= start_sec) & (tx <= end_sec)
        if not np.any(mask):
            continue
        t_crop = np.asarray(tx[mask], dtype=float)
        xyz = np.column_stack([x[mask], y[mask], z[mask]])
        if "time" not in out["point"]:
            out["point"]["time"] = _relative_time(t_crop, start_sec)
            out["point"]["frames"] = np.arange(t_crop.size, dtype=np.int64)
        field = _mat_field_name(label, point_used)
        out["point"][field] = xyz
        point_map[field] = label
    out["point"]["label_map"] = point_map
    if meta.get("point_rate") is not None:
        out["point"]["sample_rate"] = float(meta["point_rate"])

    cop_used: set[str] = set()
    cop_map: Dict[str, str] = {}
    for label in ("copx", "copy", "copz"):
        try:
            t, y = _load_c3d_cop_channel(path, label)
        except Exception:
            continue
        t = t + shift
        t_crop, y_crop = _crop_aligned_series(t, y, start_sec, end_sec)
        if t_crop.size == 0:
            continue
        if "time" not in out["cop"]:
            out["cop"]["time"] = _relative_time(t_crop, start_sec)
            out["cop"]["frames"] = np.arange(t_crop.size, dtype=np.int64)
        field = _mat_field_name(label, cop_used)
        out["cop"][field] = y_crop
        cop_map[field] = label
    out["cop"]["label_map"] = cop_map
    return out


def _build_tsv_mat_struct(match: Dict[str, Any], start_sec: float, end_sec: float) -> Dict[str, Any]:
    record = match["tsv"]
    path = Path(record["path"])
    used: set[str] = set()
    label_map: Dict[str, str] = {}
    out: Dict[str, Any] = {}
    channels = _channel_list_for_record(record)
    shift = float(_match_plot_shifts(match).get("tsv", 0.0))
    for label in channels:
        try:
            t, y = _load_tsv_channel(path, label)
        except Exception:
            continue
        t = np.asarray(t, dtype=float) + shift
        y = np.nan_to_num(y, nan=np.nanmedian(y) if np.any(np.isfinite(y)) else 0.0)
        t_crop, y_crop = _crop_aligned_series(t, y, start_sec, end_sec)
        if t_crop.size == 0:
            continue
        if "time" not in out:
            out["time"] = _relative_time(t_crop, start_sec)
            out["frames"] = np.arange(t_crop.size, dtype=np.int64)
        field = _mat_field_name(label, used)
        out[field] = y_crop
        label_map[field] = label
    out["label_map"] = label_map
    return out


def _mat_safe(value: Any) -> Any:
    if value is None:
        return ""
    if isinstance(value, Path):
        return str(value)
    if isinstance(value, dict):
        return {str(k): _mat_safe(v) for k, v in value.items()}
    if isinstance(value, (list, tuple)):
        return [_mat_safe(v) for v in value]
    return value


def _merge_info_path(mat_path: Path) -> Path:
    return mat_path.with_name(f"{mat_path.stem}_mergeInfo.txt")


def _write_merge_info_txt(mat_path: Path, match: Dict[str, Any]) -> Path:
    alignment = match.get("alignment") or {}
    inner_merge = alignment.get("inner_merge") or {}
    lines = [
        f"match_id={int(match['match_id']):03d}",
        f"mat_file={mat_path.name}",
        f"certainty={match.get('certainty')}",
        f"saved_at={match.get('saved_at') or ''}",
        f"inner_merge_start_sec={inner_merge.get('inner_merge_start_sec')}",
        f"inner_merge_end_sec={inner_merge.get('inner_merge_end_sec')}",
        f"inner_merge_duration_sec={inner_merge.get('inner_merge_duration_sec')}",
        f"otb4_file={Path(match['otb4']['path']).name if match.get('otb4') else ''}",
        f"otb4_path={Path(match['otb4']['path']).resolve() if match.get('otb4') else ''}",
        f"c3d_file={Path(match['c3d']['path']).name if match.get('c3d') else ''}",
        f"c3d_path={Path(match['c3d']['path']).resolve() if match.get('c3d') else ''}",
        f"tsv_file={Path(match['tsv']['path']).name if match.get('tsv') else ''}",
        f"tsv_path={Path(match['tsv']['path']).resolve() if match.get('tsv') else ''}",
        f"otb4_sync={match.get('otb4', {}).get('sync_channel') if match.get('otb4') else ''}",
        f"c3d_sync={match.get('c3d', {}).get('sync_channel') if match.get('c3d') else ''}",
        f"tsv_sync={match.get('tsv', {}).get('sync_channel') if match.get('tsv') else ''}",
        f"raw_tsv={alignment.get('raw_label_match_tsv')}",
        f"raw_c3d={alignment.get('raw_label_match_c3d')}",
        f"raw_alignment_quality={alignment.get('raw_alignment_quality')}",
        f"raw_alignment_corr={alignment.get('raw_alignment_corr')}",
        f"otb4_c3d_sync_pair={json.dumps((alignment.get('dedicated_sync_pairwise') or {}).get('otb4_vs_c3d') or {}, ensure_ascii=False)}",
        f"repair_json_path={((match.get('export_plan') or {}).get('repair_json') or {}).get('path') or ''}",
    ]
    txt_path = _merge_info_path(mat_path)
    txt_path.write_text("\n".join(lines) + "\n", encoding="utf-8")
    return txt_path


def export_match_mat(match: Dict[str, Any], export_root: Path) -> Path:
    inner_merge = ((match.get("alignment") or {}).get("inner_merge") or {})
    start_sec = inner_merge.get("inner_merge_start_sec")
    end_sec = inner_merge.get("inner_merge_end_sec")
    if not isinstance(start_sec, (int, float)) or not isinstance(end_sec, (int, float)) or end_sec <= start_sec:
        raise ValueError("Common matched time window is unavailable.")
    if not _mat_export_supported(match):
        raise ValueError("MAT export requires at least two synchronized source files.")
    saved_stamp = match.get("saved_at") or _format_file_stamp()
    file_name = (((match.get("export_plan") or {}).get("mat") or {}).get("filename") or _mat_export_name(match, saved_stamp))
    out_path = Path(export_root) / file_name
    out_path.parent.mkdir(parents=True, exist_ok=True)
    otb4_struct = _build_otb4_mat_struct(match, float(start_sec), float(end_sec)) if match.get("otb4") else {}
    c3d_struct = _build_c3d_mat_struct(match, float(start_sec), float(end_sec)) if match.get("c3d") else {}
    tsv_struct = _build_tsv_mat_struct(match, float(start_sec), float(end_sec)) if match.get("tsv") else {}
    tracebio_struct = (
        _build_tracebio_fullrate_struct(match, float(start_sec), float(end_sec))
        if _tracebio_reconstruction_supported(match)
        else {}
    )
    mat_dict = {
        "meta": {
            "match_id": int(match["match_id"]),
            "exported_at": _now_iso(),
            "time_window_sec": np.array([float(start_sec), float(end_sec)], dtype=float),
            "duration_sec": float(end_sec - start_sec),
            "common_period_aligned": True,
            "aligned_to_single_common_timebase": False,
            "per_source_timebases": True,
            "resampled": False,
            "certainty": str(match.get("certainty") or ""),
            "original_files": {
                key: {
                    "path": str(match[key]["path"]),
                    "filename": str(Path(match[key]["path"]).name),
                }
                for key in ("otb4", "c3d", "tsv")
                if match.get(key)
            },
            "renamed_files": {
                key: value.get("renamed_filename")
                for key, value in (((match.get("export_plan") or {}).get("matched") or {}).items())
            },
        },
        "alignment": {
            "plot_time_shifts_sec": (match.get("alignment") or {}).get("plot_time_shifts_sec") or {},
            "inner_merge": inner_merge,
            "otb4_repair": (match.get("alignment") or {}).get("otb4_repair") or {},
        },
    }
    if otb4_struct:
        mat_dict["otb4"] = otb4_struct
    if c3d_struct:
        mat_dict["c3d_analog"] = c3d_struct["analog"]
        mat_dict["c3d_point"] = c3d_struct["point"]
        mat_dict["c3d_cop"] = c3d_struct["cop"]
    if tsv_struct:
        mat_dict["tsv"] = tsv_struct
    if tracebio_struct:
        mat_dict["tsv_reconstructed"] = tracebio_struct
    savemat(str(out_path), _mat_safe(mat_dict), long_field_names=True, do_compression=True)
    _write_merge_info_txt(out_path, match)
    return out_path


def _export_match_mat_task(args: Tuple[Dict[str, Any], str]) -> Dict[str, str]:
    match, export_root = args
    export_root_path = Path(export_root)
    base_mat = export_match_mat(match, export_root_path)
    outputs = {
        "mat_export": str(base_mat),
    }
    if _pipe_export_supported(match):
        pipe_mat, pipe_json = export_match_pipe_bundle(match, export_root_path)
        outputs["pipe_mat_export"] = str(pipe_mat)
        outputs["pipe_json_export"] = str(pipe_json)
    return outputs


def _pipe_mat_path(mat_path: Path) -> Path:
    return mat_path.with_name(f"{mat_path.stem}_4pipe.mat")


def _pipe_json_path(pipe_mat_path: Path) -> Path:
    return pipe_mat_path.with_suffix(".json")


def _description_texts(descs: Sequence[Any]) -> List[str]:
    labels: List[str] = []
    for d in descs:
        try:
            labels.append(str(d[0][0]))
        except Exception:
            labels.append(str(d))
    return labels


def _infer_otb_grids(labels: Sequence[str]) -> List[Dict[str, Any]]:
    grid_pattern = re.compile(r"HD(\d{2})MM(\d{2})(\d{2})")
    muscle_pattern = re.compile(r"\[MUSCLE:(.*?)\]")
    grids: List[Dict[str, Any]] = []
    current: Optional[Dict[str, Any]] = None
    for idx, label in enumerate(labels):
        m = grid_pattern.search(label)
        if m:
            scale, rows, cols = map(int, m.groups())
            muscle_match = muscle_pattern.search(label)
            muscle = muscle_match.group(1).strip() if muscle_match else None
            if (
                current is not None
                and current["scale"] == scale
                and current["rows"] == rows
                and current["cols"] == cols
                and current.get("muscle") == muscle
                and idx == current["emg_indices"][-1] + 1
            ):
                current["emg_indices"].append(idx)
            else:
                current = {
                    "grid_uid": str(uuid.uuid4()),
                    "grid_key": f"{scale}mm_{rows}x{cols}",
                    "scale": scale,
                    "rows": rows,
                    "cols": cols,
                    "muscle": muscle,
                    "emg_indices": [idx],
                    "ref_indices": [],
                }
                grids.append(current)
        elif current is not None:
            current["ref_indices"].append(idx)
    for grid in grids:
        block = grid["emg_indices"] + grid["ref_indices"]
        grid["block_end"] = max(block) if block else max(grid["emg_indices"])
    return grids


def _otb_track_is_emg(track: Dict[str, Any]) -> bool:
    if bool(track.get("IsControl")):
        return False
    if str(track.get("Device") or "").strip() == "Syncstation":
        return False
    subtitle = str(track.get("SubTitle") or "").strip().upper()
    desc_name = str(track.get("DescriptionName") or "").strip().upper()
    grid_name = str((track.get("GridInfo") or {}).get("Name") or "").strip().upper()
    candidate = grid_name or desc_name or subtitle
    return candidate.startswith("HD") or candidate == "CDE-C"


def _infer_otb_emg_groups(otb_path: Path) -> List[Dict[str, Any]]:
    tmpdir, tracks = _extract_otb4_tracks(otb_path)
    try:
        groups: List[Dict[str, Any]] = []
        signal_paths = sorted({str(track.get("SignalStreamPath") or "") for track in tracks})
        for signal_path in signal_paths:
            if not signal_path:
                continue
            for offset, track in _otb4_track_offsets(tracks, signal_path):
                if not _otb_track_is_emg(track):
                    continue
                nchan = int(track.get("NumberOfChannels") or 0)
                if nchan <= 0:
                    continue
                device = str(track.get("Device") or "").strip()
                grid_info = track.get("GridInfo") or {}
                grid_name = str(grid_info.get("Name") or track.get("DescriptionName") or track.get("SubTitle") or "").strip()
                rows = int(grid_info.get("NRow") or 1)
                cols = int(grid_info.get("NColumn") or nchan)
                ied = int(grid_info.get("IED") or 0)
                muscle = str(track.get("Muscle") or "").strip() or None
                if grid_name.upper().startswith("HD"):
                    grid_key = f"{ied}mm_{rows}x{cols}"
                else:
                    grid_key = f"{device}_{grid_name}".replace(" ", "_")
                indices = list(range(offset, offset + nchan))
                if (
                    groups
                    and groups[-1]["device"] == device
                    and groups[-1]["grid_key"] == grid_key
                    and groups[-1]["emg_indices"][-1] + 1 == indices[0]
                ):
                    groups[-1]["emg_indices"].extend(indices)
                else:
                    groups.append(
                        {
                            "grid_uid": str(uuid.uuid4()),
                            "grid_key": grid_key,
                            "device": device,
                            "label": grid_name,
                            "rows": rows,
                            "cols": cols,
                            "scale": ied,
                            "muscle": muscle,
                            "emg_indices": indices,
                            "ref_indices": [],
                        }
                    )
        return groups
    finally:
        _release_otb4_tmpdir(tmpdir)


def _resample_to_target_time(target_t: np.ndarray, source_t: np.ndarray, source_y: np.ndarray) -> np.ndarray:
    source_t = np.asarray(source_t, dtype=float)
    source_y = np.asarray(source_y, dtype=float)
    mask = np.isfinite(source_t) & np.isfinite(source_y)
    if np.count_nonzero(mask) < 2:
        fill = float(np.nanmean(source_y[mask])) if np.count_nonzero(mask) else 0.0
        return np.full(target_t.shape, fill, dtype=float)
    source_t = source_t[mask]
    source_y = source_y[mask]
    order = np.argsort(source_t)
    source_t = source_t[order]
    source_y = source_y[order]
    uniq_t, uniq_idx = np.unique(source_t, return_index=True)
    uniq_y = source_y[uniq_idx]
    if uniq_t.size < 2:
        return np.full(target_t.shape, float(uniq_y[0]), dtype=float)
    return np.interp(target_t, uniq_t, uniq_y, left=float(uniq_y[0]), right=float(uniq_y[-1]))


def _preferred_tsv_path_columns(record: Dict[str, Any]) -> Tuple[Optional[str], Optional[str]]:
    names = record.get("channel_names") or []
    performed = next((c for c in names if c.strip().lower() == "performed"), None)
    if performed is None:
        raw_col, offset_col = _find_tsv_raw_offset_pair([str(c) for c in names])
        if raw_col and offset_col:
            performed = "performed"
    original = next((c for c in names if c.strip().lower() == "desired"), None)
    return performed, original


def _build_pipe_extra_specs(match: Dict[str, Any]) -> List[Tuple[str, Dict[str, Any]]]:
    specs: List[Tuple[str, Dict[str, Any]]] = []
    tsv_record = match.get("tsv") or {}
    c3d_record = match.get("c3d") or {}
    performed_col, original_col = _preferred_tsv_path_columns(tsv_record)
    if performed_col:
        specs.append(("Performed Path", {"source": "tsv", "channel": performed_col}))
    if original_col:
        specs.append(("Original Path", {"source": "tsv", "channel": original_col}))

    if tsv_record.get("kind") == "tsv":
        for ch in _channel_list_for_record(tsv_record):
            if ch in {performed_col, original_col}:
                continue
            specs.append((f"TSV {ch}", {"source": "tsv", "channel": ch}))

    for ch in c3d_record.get("channel_names") or []:
        specs.append((f"C3D Analog {ch}", {"source": "c3d", "channel": ch, "kind": "analog"}))
    for ch in ("copx", "copy", "copz"):
        try:
            _load_c3d_cop_channel(Path(c3d_record["path"]), ch)
        except Exception:
            continue
        specs.append((f"C3D CoP {ch}", {"source": "c3d", "channel": ch, "kind": "cop"}))
    for ch in c3d_record.get("point_channel_names") or []:
        for coord in ("x", "y", "z"):
            specs.append((f"C3D Point {ch}.{coord}", {"source": "c3d", "channel": f"{ch}.{coord}", "kind": "point"}))
    return specs


def _load_aligned_series(match: Dict[str, Any], spec: Dict[str, Any]) -> Tuple[np.ndarray, np.ndarray]:
    source = spec["source"]
    channel = spec["channel"]
    if source == "tsv":
        t, y = _load_tsv_channel(Path(match["tsv"]["path"]), channel)
    elif source == "c3d":
        kind = spec.get("kind") or "analog"
        t, y = _load_c3d_series(Path(match["c3d"]["path"]), kind, channel)
    else:
        raise ValueError(source)
    shift = float(_match_plot_shifts(match).get(source, 0.0))
    return t + shift, y


def _parse_tracebio_scalar(value: Any) -> Any:
    if isinstance(value, str):
        text = value.strip()
        if not text:
            return text
        text = text.replace(",", ".")
        try:
            if any(ch in text for ch in (".", "e", "E")):
                return float(text)
            return int(text)
        except Exception:
            return value
    return value


def _tracebio_bool(value: Any) -> bool:
    if isinstance(value, bool):
        return value
    if isinstance(value, str):
        text = value.strip().lower()
        if text in {"true", "1", "yes", "y", "on"}:
            return True
        if text in {"false", "0", "no", "n", "off", ""}:
            return False
    return bool(value)


def _tracebio_finite_float(value: Any) -> Optional[float]:
    parsed = _parse_tracebio_scalar(value)
    if isinstance(parsed, (int, float, np.integer, np.floating)):
        out = float(parsed)
        if np.isfinite(out):
            return out
    return None


def _tracebio_settings_path(match: Dict[str, Any]) -> Optional[Path]:
    override = _tracebio_settings_path_override(match)
    if override is not None:
        return override
    export_plan = match.get("export_plan") or {}
    matched_json = ((export_plan.get("matched") or {}).get("tsv_json") or {})
    for key in ("renamed_path", "original_path"):
        candidate = matched_json.get(key)
        if candidate:
            path = Path(str(candidate))
            if path.exists():
                return path
    path = _tsv_sidecar_json_path(match)
    if path is not None and path.exists():
        return path
    return None


def _load_tracebio_settings(match: Dict[str, Any]) -> Dict[str, Any]:
    path = _tracebio_settings_path(match)
    if path is None:
        raise FileNotFoundError("traceBio settings JSON not found for matched TSV.")
    return json.loads(path.read_text(encoding="utf-8-sig"))


def _tracebio_settings_path_override(match: Dict[str, Any]) -> Optional[Path]:
    tracebio_state = ((match.get("export_plan") or {}).get("tracebio") or {})
    candidate = tracebio_state.get("settings_json_override")
    if not candidate:
        return None
    path = Path(str(candidate))
    return path if path.exists() else None


def _sync_tracebio_settings_export_plan(match: Dict[str, Any], path: Path) -> None:
    matched = match.setdefault("export_plan", {}).setdefault("matched", {})
    plan = matched.setdefault("tsv_json", {})
    plan["original_path"] = str(path)
    plan["original_filename"] = path.name


def _set_tracebio_settings_path_override(match: Dict[str, Any], path: Path) -> None:
    resolved = Path(path)
    match.setdefault("export_plan", {}).setdefault("tracebio", {})["settings_json_override"] = str(resolved)
    _sync_tracebio_settings_export_plan(match, resolved)


def _tracebio_selected_path_override(match: Dict[str, Any]) -> Optional[Path]:
    tracebio_state = ((match.get("export_plan") or {}).get("tracebio") or {})
    candidate = tracebio_state.get("selected_path_override")
    if not candidate:
        return None
    path = Path(str(candidate))
    return path if path.exists() else None


def _tracebio_settings_search_roots(match: Dict[str, Any], path_file: Optional[Path] = None) -> List[Path]:
    roots: List[Path] = []

    def _add(root: Optional[Path]) -> None:
        if root is None:
            return
        try:
            resolved = root.resolve()
        except Exception:
            resolved = root
        if resolved.exists() and resolved.is_dir() and all(str(resolved).lower() != str(existing).lower() for existing in roots):
            roots.append(resolved)

    settings_override = _tracebio_settings_path_override(match)
    if settings_override is not None:
        _add(settings_override.parent)

    settings_path = _tracebio_settings_path(match)
    if settings_path is not None:
        _add(settings_path.parent)

    tsv_path = Path(str((match.get("tsv") or {}).get("path") or "")).resolve() if (match.get("tsv") or {}).get("path") else None
    if tsv_path is not None:
        _add(tsv_path.parent)
        _add(tsv_path.parent / "settings")
        _add(tsv_path.parent.parent / "settings")

    if path_file is not None:
        try:
            selected_path = Path(path_file).resolve()
        except Exception:
            selected_path = Path(path_file)
        _add(selected_path.parent)
        _add(selected_path.parent / "settings")
        _add(selected_path.parent.parent / "settings")

    source_root = match.get("source_root")
    if source_root:
        _add(Path(str(source_root)) / "settings")
    return roots


def _tracebio_find_settings_for_path(match: Dict[str, Any], path_file: Path) -> Optional[Path]:
    selected_name = path_file.name.strip().lower()
    if not selected_name:
        return None
    for root in _tracebio_settings_search_roots(match, path_file=path_file):
        for candidate in root.glob("*.json"):
            try:
                data = json.loads(candidate.read_text(encoding="utf-8-sig"))
            except Exception:
                continue
            configured = Path(str(data.get("SelectedPath") or "")).name.strip().lower()
            if configured and configured == selected_name:
                return candidate
    return None


def _set_tracebio_selected_path_override(match: Dict[str, Any], path: Path) -> None:
    resolved = Path(path)
    tracebio_state = match.setdefault("export_plan", {}).setdefault("tracebio", {})
    tracebio_state["selected_path_override"] = str(resolved)
    inferred_settings = _tracebio_find_settings_for_path(match, resolved)
    if inferred_settings is not None:
        tracebio_state["settings_json_override"] = str(inferred_settings)
        _sync_tracebio_settings_export_plan(match, inferred_settings)


def _tracebio_paths_roots(match: Dict[str, Any]) -> List[Path]:
    roots: List[Path] = []

    def _add_file_related_roots(candidate: Any) -> None:
        if not candidate:
            return
        try:
            path = Path(str(candidate))
        except Exception:
            return
        candidates = [path.parent / "paths", path.parent.parent / "paths"]
        for root in candidates:
            try:
                resolved = root.resolve()
            except Exception:
                resolved = root
            if resolved.exists() and resolved.is_dir() and all(str(resolved).lower() != str(existing).lower() for existing in roots):
                roots.append(resolved)

    override = _tracebio_selected_path_override(match)
    if override is not None:
        override_root = override.parent.resolve()
        roots.append(override_root)

    export_plan = match.get("export_plan") or {}
    matched_plan = export_plan.get("matched") or {}
    for branch in ("tsv_json", "tsv_file"):
        data = matched_plan.get(branch) or {}
        _add_file_related_roots(data.get("original_path"))
        _add_file_related_roots(data.get("renamed_path"))

    settings_path = _tracebio_settings_path(match)
    if settings_path is not None:
        _add_file_related_roots(settings_path)

    _add_file_related_roots((match.get("tsv") or {}).get("path"))

    if TRACEBIO_PATHS_ROOT:
        try:
            shared_root = Path(TRACEBIO_PATHS_ROOT).resolve()
        except Exception:
            shared_root = Path(TRACEBIO_PATHS_ROOT)
        if (
            shared_root.exists()
            and shared_root.is_dir()
            and all(str(shared_root).lower() != str(existing).lower() for existing in roots)
        ):
            roots.append(shared_root)

    return roots


def _tracebio_axis_hint(settings: Dict[str, Any]) -> str:
    signal = str(settings.get("SelectedSignal") or "").strip().lower()
    if "/cop/cy " in signal:
        return "ap"
    if "/cop/cx " in signal:
        return "ml"
    return ""


def _tracebio_name_tokens(text: str) -> List[str]:
    return re.findall(r"[a-z0-9]+", str(text).lower())


def _tracebio_selected_path_file(match: Dict[str, Any], settings: Dict[str, Any]) -> Path:
    override = _tracebio_selected_path_override(match)
    if override is not None:
        return override

    selected = str(settings.get("SelectedPath") or "").strip()
    if not selected:
        raise FileNotFoundError("traceBio settings JSON does not contain SelectedPath.")

    roots = _tracebio_paths_roots(match)
    tried: List[str] = []
    for root in roots:
        direct = root / selected
        tried.append(str(direct))
        if direct.exists():
            return direct

    axis_hint = _tracebio_axis_hint(settings)
    target_tokens = set(_tracebio_name_tokens(Path(selected).stem))
    target_numbers = {token for token in target_tokens if token.isdigit()}
    best_path: Optional[Path] = None
    best_score: Optional[Tuple[int, int, int, int, str]] = None
    for root in roots:
        for candidate in root.glob("*.tsv"):
            candidate_tokens = set(_tracebio_name_tokens(candidate.stem))
            overlap = len(target_tokens & candidate_tokens)
            number_overlap = len(target_numbers & {token for token in candidate_tokens if token.isdigit()})
            axis_match = 1 if axis_hint and axis_hint in candidate.stem.lower() else 0
            if overlap <= 0 and number_overlap <= 0:
                continue
            score = (-axis_match, -number_overlap, -overlap, len(candidate.name), candidate.name.lower())
            if best_score is None or score < best_score:
                best_score = score
                best_path = candidate
    if best_path is not None:
        return best_path

    tried_text = "\n".join(tried[:8])
    suffix = f"\nTried:\n{tried_text}" if tried_text else ""
    raise FileNotFoundError(f"SelectedPath not found in paths folder for '{selected}'.{suffix}")


def _load_tracebio_path_vertices(path: Path) -> Tuple[np.ndarray, np.ndarray]:
    df = pd.read_csv(path, sep="\t", decimal=",", encoding="utf-8-sig")
    if not {"seconds", "value"}.issubset(df.columns):
        raise ValueError(f"Path file {path} does not contain required columns: seconds, value")
    t = pd.to_numeric(df["seconds"], errors="coerce").to_numpy(dtype=float)
    y = pd.to_numeric(df["value"], errors="coerce").to_numpy(dtype=float)
    mask = np.isfinite(t) & np.isfinite(y)
    if np.count_nonzero(mask) < 2:
        raise ValueError(f"Path file {path} does not contain at least two valid vertices.")
    t = t[mask]
    y = y[mask]
    order = np.argsort(t)
    return t[order], y[order]


def _tracebio_offset_segment_line(
    t0: float,
    y0: float,
    t1: float,
    y1: float,
    radius: float,
    side: float,
) -> Dict[str, float]:
    dt = float(t1) - float(t0)
    dy = float(y1) - float(y0)
    seg_len = float(np.hypot(dt, dy))
    if not np.isfinite(seg_len) or seg_len <= 1e-12:
        seg_len = 1.0
    nx = -dy / seg_len
    ny = dt / seg_len
    mx = 0.5 * (float(t0) + float(t1))
    my = 0.5 * (float(y0) + float(y1))
    ox = mx + float(side) * float(radius) * nx
    oy = my + float(side) * float(radius) * ny
    a = -dy
    b = dt
    d = a * ox + b * oy
    return {
        "a": float(a),
        "b": float(b),
        "d": float(d),
        "nx": float(nx),
        "ny": float(ny),
        "t0": float(t0),
        "y0": float(y0),
        "t1": float(t1),
        "y1": float(y1),
    }


def _tracebio_intersect_vertical(line: Dict[str, float], x: float, radius: float, side: float, t_base: float, y_base: float) -> Tuple[float, float]:
    a = float(line["a"])
    b = float(line["b"])
    d = float(line["d"])
    if np.isfinite(b) and abs(b) > 1e-12:
        y = (d - a * float(x)) / b
        if np.isfinite(y):
            return float(x), float(y)
    return (
        float(t_base) + float(side) * float(radius) * float(line["nx"]),
        float(y_base) + float(side) * float(radius) * float(line["ny"]),
    )


def _tracebio_build_offset_path(path_t: np.ndarray, path_y: np.ndarray, radius: float, side: float) -> Tuple[np.ndarray, np.ndarray]:
    t = np.asarray(path_t, dtype=float).reshape(-1)
    y = np.asarray(path_y, dtype=float).reshape(-1)
    if t.size != y.size or t.size < 2:
        raise ValueError("traceBio offset path requires at least two path vertices.")
    if not np.isfinite(radius):
        raise ValueError("traceBio corridor half-width is not finite.")

    segment_lines = [
        _tracebio_offset_segment_line(t[idx], y[idx], t[idx + 1], y[idx + 1], float(radius), float(side))
        for idx in range(t.size - 1)
    ]

    out_t = np.empty(t.size, dtype=float)
    out_y = np.empty(y.size, dtype=float)
    out_t[0], out_y[0] = _tracebio_intersect_vertical(segment_lines[0], float(t[0]), radius, side, float(t[0]), float(y[0]))
    out_t[-1], out_y[-1] = _tracebio_intersect_vertical(segment_lines[-1], float(t[-1]), radius, side, float(t[-1]), float(y[-1]))

    for idx in range(1, t.size - 1):
        prev_line = segment_lines[idx - 1]
        next_line = segment_lines[idx]
        a1, b1, d1 = float(prev_line["a"]), float(prev_line["b"]), float(prev_line["d"])
        a2, b2, d2 = float(next_line["a"]), float(next_line["b"]), float(next_line["d"])
        det = a1 * b2 - a2 * b1
        if np.isfinite(det) and abs(det) > 1e-12:
            x = (d1 * b2 - d2 * b1) / det
            yy = (a1 * d2 - a2 * d1) / det
            if np.isfinite(x) and np.isfinite(yy):
                out_t[idx] = float(x)
                out_y[idx] = float(yy)
                continue

        ax = float(prev_line["nx"]) + float(next_line["nx"])
        ay = float(prev_line["ny"]) + float(next_line["ny"])
        alen = float(np.hypot(ax, ay))
        if not np.isfinite(alen) or alen <= 1e-12:
            ax = float(prev_line["nx"])
            ay = float(prev_line["ny"])
            alen = float(np.hypot(ax, ay))
        if not np.isfinite(alen) or alen <= 1e-12:
            ax, ay, alen = 0.0, 1.0, 1.0
        ax /= alen
        ay /= alen
        out_t[idx] = float(t[idx]) + float(side) * float(radius) * ax
        out_y[idx] = float(y[idx]) + float(side) * float(radius) * ay

    return out_t, out_y


def _tracebio_sample_offset_path(offset_t: np.ndarray, offset_y: np.ndarray, query_t: np.ndarray) -> np.ndarray:
    xs = np.asarray(offset_t, dtype=float).reshape(-1)
    ys = np.asarray(offset_y, dtype=float).reshape(-1)
    q = np.asarray(query_t, dtype=float).reshape(-1)
    if xs.size != ys.size or xs.size == 0:
        return np.full(q.shape, np.nan, dtype=float)
    if xs.size == 1:
        return np.full(q.shape, float(ys[0]), dtype=float)

    out = np.empty(q.shape, dtype=float)
    segment_mins = np.minimum(xs[:-1], xs[1:])
    segment_maxs = np.maximum(xs[:-1], xs[1:])
    segment_mids = 0.5 * (xs[:-1] + xs[1:])
    monotonic = bool(np.all(np.diff(xs) >= 0.0) or np.all(np.diff(xs) <= 0.0))

    for idx, qt in enumerate(q):
        if not np.isfinite(qt):
            out[idx] = np.nan
            continue
        if monotonic:
            out[idx] = float(np.interp(float(qt), xs, ys, left=float(ys[0]), right=float(ys[-1])))
            continue

        candidates: List[Tuple[float, float]] = []
        for seg_idx in range(xs.size - 1):
            lo = float(segment_mins[seg_idx])
            hi = float(segment_maxs[seg_idx])
            if float(qt) < lo or float(qt) > hi:
                continue
            x0 = float(xs[seg_idx])
            x1 = float(xs[seg_idx + 1])
            y0 = float(ys[seg_idx])
            y1 = float(ys[seg_idx + 1])
            if abs(x1 - x0) <= 1e-12:
                yq = 0.5 * (y0 + y1)
            else:
                alpha = (float(qt) - x0) / (x1 - x0)
                yq = y0 + alpha * (y1 - y0)
            candidates.append((abs(float(qt) - float(segment_mids[seg_idx])), float(yq)))
        if candidates:
            candidates.sort(key=lambda item: item[0])
            out[idx] = candidates[0][1]
            continue
        nearest_idx = int(np.argmin(np.abs(xs - float(qt))))
        out[idx] = float(ys[nearest_idx])
    return out


def _tracebio_zero_offset_m(
    tsv_raw: np.ndarray,
    tsv_offset: np.ndarray,
    raw_m: np.ndarray,
    *,
    tsv_time_aligned: Optional[np.ndarray] = None,
    raw_time_aligned: Optional[np.ndarray] = None,
) -> float:
    if tsv_time_aligned is not None and raw_time_aligned is not None:
        t_tsv = np.asarray(tsv_time_aligned, dtype=float).reshape(-1)
        t_raw = np.asarray(raw_time_aligned, dtype=float).reshape(-1)
        raw_arr = np.asarray(raw_m, dtype=float).reshape(-1)
        offset_arr = np.asarray(tsv_offset, dtype=float).reshape(-1)
        if t_tsv.size == offset_arr.size and t_raw.size == raw_arr.size and t_raw.size >= 2:
            valid_raw = np.isfinite(t_raw) & np.isfinite(raw_arr)
            valid_tsv = np.isfinite(t_tsv) & np.isfinite(offset_arr)
            if int(np.sum(valid_raw)) >= 2 and int(np.sum(valid_tsv)) >= 2:
                t_raw_valid = t_raw[valid_raw]
                raw_valid = raw_arr[valid_raw]
                order = np.argsort(t_raw_valid)
                t_raw_valid = t_raw_valid[order]
                raw_valid = raw_valid[order]
                in_range = valid_tsv & (t_tsv >= float(t_raw_valid[0])) & (t_tsv <= float(t_raw_valid[-1]))
                if int(np.sum(in_range)) >= 2:
                    raw_at_tsv = np.interp(t_tsv[in_range], t_raw_valid, raw_valid)
                    delta = raw_at_tsv - offset_arr[in_range]
                    finite_delta = delta[np.isfinite(delta)]
                    if finite_delta.size:
                        return float(np.nanmedian(finite_delta))

    delta = np.asarray(tsv_raw, dtype=float) - np.asarray(tsv_offset, dtype=float)
    finite_delta = delta[np.isfinite(delta)]
    if finite_delta.size:
        return float(np.nanmedian(finite_delta))
    finite_raw = np.asarray(raw_m, dtype=float)
    finite_raw = finite_raw[np.isfinite(finite_raw)]
    if finite_raw.size:
        return float(np.nanmedian(finite_raw))
    return 0.0


def _tracebio_resolve_record_limits(
    settings: Dict[str, Any],
    *,
    offset_m: np.ndarray,
    tsv_offset: np.ndarray,
) -> Tuple[float, float]:
    record_min_m = float(_parse_tracebio_scalar(settings.get("RecordMin")))
    record_max_m = float(_parse_tracebio_scalar(settings.get("RecordMax")))
    if np.isfinite(record_min_m) and np.isfinite(record_max_m) and record_max_m > record_min_m:
        return float(record_min_m), float(record_max_m)

    finite_tsv_offset = np.asarray(tsv_offset, dtype=float)
    finite_tsv_offset = finite_tsv_offset[np.isfinite(finite_tsv_offset)]
    if finite_tsv_offset.size >= 2:
        lo = float(np.nanmin(finite_tsv_offset))
        hi = float(np.nanmax(finite_tsv_offset))
        if np.isfinite(lo) and np.isfinite(hi) and hi > lo:
            return lo, hi

    finite_offset = np.asarray(offset_m, dtype=float)
    finite_offset = finite_offset[np.isfinite(finite_offset)]
    if finite_offset.size >= 2:
        lo = float(np.nanmin(finite_offset))
        hi = float(np.nanmax(finite_offset))
        if np.isfinite(lo) and np.isfinite(hi) and hi > lo:
            return lo, hi

    center = float(np.nanmedian(finite_offset)) if finite_offset.size else 0.0
    return center - 0.5, center + 0.5


def _tracebio_relative_performed_percent(
    offset_m: np.ndarray,
    target_t: np.ndarray,
    tsv_df: pd.DataFrame,
    match: Dict[str, Any],
) -> Optional[np.ndarray]:
    if "performed" not in tsv_df.columns or "t_rel" not in tsv_df.columns:
        return None
    tsv_performed = _tsv_numeric_column(tsv_df, "performed")
    tsv_t = pd.to_numeric(tsv_df["t_rel"], errors="coerce").to_numpy(dtype=float)
    tsv_t = tsv_t + float(_match_plot_shifts(match).get("tsv", 0.0))
    target_t = np.asarray(target_t, dtype=float).reshape(-1)
    offset_m = np.asarray(offset_m, dtype=float).reshape(-1)
    valid_target = np.isfinite(target_t) & np.isfinite(offset_m)
    valid_tsv = np.isfinite(tsv_t) & np.isfinite(tsv_performed)
    if int(np.sum(valid_target)) < 2 or int(np.sum(valid_tsv)) < 10:
        return None
    target_valid_t = target_t[valid_target]
    target_valid_offset = offset_m[valid_target]
    order = np.argsort(target_valid_t)
    target_valid_t = target_valid_t[order]
    target_valid_offset = target_valid_offset[order]
    in_range = valid_tsv & (tsv_t >= float(target_valid_t[0])) & (tsv_t <= float(target_valid_t[-1]))
    if int(np.sum(in_range)) < 10:
        return None
    offset_at_tsv = np.interp(tsv_t[in_range], target_valid_t, target_valid_offset)
    y = tsv_performed[in_range]
    fit_mask = np.isfinite(offset_at_tsv) & np.isfinite(y)
    if int(np.sum(fit_mask)) < 10 or float(np.nanstd(offset_at_tsv[fit_mask])) <= 1e-12:
        return None
    design = np.column_stack([offset_at_tsv[fit_mask], np.ones(int(np.sum(fit_mask)), dtype=float)])
    coef, *_ = np.linalg.lstsq(design, y[fit_mask], rcond=None)
    out = coef[0] * offset_m + coef[1]
    return np.clip(out, 0.0, 100.0)


def _tracebio_sidecar_performed_transform(settings: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    version = _tracebio_finite_float(settings.get("PerformedTransformVersion"))
    if version is None or version < 2:
        return None
    if not _tracebio_bool(settings.get("RelativeMode")):
        return None

    performed_input = str(settings.get("PerformedInput") or "").strip().lower()
    supported_inputs = {
        "",
        "offset",
        "offset_m",
        "selected_offset_m",
        "smoothed_offset_m",
        "smoothed_selected_offset_m",
        "raw_m_minus_zero_offset_m",
    }
    if performed_input not in supported_inputs:
        return None

    clamp_min = _tracebio_finite_float(settings.get("PerformedClampMin"))
    clamp_max = _tracebio_finite_float(settings.get("PerformedClampMax"))
    if clamp_min is None:
        clamp_min = 0.0
    if clamp_max is None:
        clamp_max = 100.0
    if clamp_max <= clamp_min:
        return None

    range_min = _tracebio_finite_float(settings.get("ActiveRelativeRangeMin"))
    range_max = _tracebio_finite_float(settings.get("ActiveRelativeRangeMax"))
    gain = _tracebio_finite_float(settings.get("PerformedPercentGain"))
    bias = _tracebio_finite_float(settings.get("PerformedPercentBias"))

    if gain is None or bias is None:
        if range_min is None or range_max is None or range_max <= range_min:
            return None
        gain = (clamp_max - clamp_min) / (range_max - range_min)
        bias = clamp_min - (range_min * gain)
    elif abs(gain) <= 1e-12:
        return None

    if range_min is None or range_max is None or range_max <= range_min:
        if gain <= 0:
            return None
        range_min = (clamp_min - bias) / gain
        range_max = (clamp_max - bias) / gain
        if not np.isfinite(range_min) or not np.isfinite(range_max) or range_max <= range_min:
            return None

    source = str(settings.get("ActiveRelativeRangeSource") or "sidecar_v2").strip() or "sidecar_v2"
    return {
        "version": int(round(version)),
        "performed_input": performed_input or "offset_m",
        "range_min_m": float(range_min),
        "range_max_m": float(range_max),
        "source": source,
        "gain": float(gain),
        "bias": float(bias),
        "clamp_min": float(clamp_min),
        "clamp_max": float(clamp_max),
    }


def _build_common_c3d_target(match: Dict[str, Any]) -> Dict[str, Any]:
    inner_merge = ((match.get("alignment") or {}).get("inner_merge") or {})
    start_sec = inner_merge.get("inner_merge_start_sec")
    end_sec = inner_merge.get("inner_merge_end_sec")
    if not isinstance(start_sec, (int, float)) or not isinstance(end_sec, (int, float)) or end_sec <= start_sec:
        raise ValueError("Common matched time window is unavailable.")

    c3d_record = match.get("c3d") or {}
    first_label = next(iter(c3d_record.get("channel_names") or []), None)
    if not first_label:
        raise ValueError("C3D analog labels are unavailable.")
    c3d_path = Path(c3d_record["path"])
    t_native, _y = _load_c3d_analog_channel(c3d_path, first_label)
    target_fs = float(_c3d_metadata(c3d_path)["analog_rate"])
    aligned_time = np.asarray(t_native, dtype=float) + float(_match_plot_shifts(match).get("c3d", 0.0))
    mask = np.isfinite(aligned_time) & (aligned_time >= float(start_sec)) & (aligned_time <= float(end_sec))
    if not np.any(mask):
        raise ValueError("No C3D analog samples in common matched time window.")

    target_t = aligned_time[mask]
    otb_path: Optional[Path] = None
    otb_data = np.empty((0, 0), dtype=float)
    labels: List[str] = []
    full_len = 0
    otb_aligned_time = np.empty(0, dtype=float)
    if match.get("otb4"):
        otb_path = Path(match["otb4"]["path"])
        loaded_otb_data, _otb_time, descs, otb_fs, _name, _size = load_otb4_file(str(otb_path))
        otb_data = np.asarray(loaded_otb_data, dtype=float)
        labels = _description_texts(descs)
        full_len = _max_otb_repaired_length(match, int(otb_data.shape[1]), labels)
        otb_aligned_time = np.arange(full_len, dtype=float) / float(otb_fs) + float(_match_plot_shifts(match).get("otb4", 0.0))
    return {
        "start_sec": float(start_sec),
        "end_sec": float(end_sec),
        "fs": float(target_fs),
        "path": otb_path,
        "data": otb_data,
        "labels": labels,
        "full_len": int(full_len),
        "mask": mask,
        "target_t": target_t,
        "out_time": target_t - float(start_sec),
        "c3d_path": c3d_path,
        "otb_aligned_time": otb_aligned_time,
    }


def _build_tracebio_fullrate_struct(match: Dict[str, Any], start_sec: float, end_sec: float) -> Dict[str, Any]:
    if not match.get("tsv") or not match.get("c3d"):
        return {}
    settings = _load_tracebio_settings(match)
    path_file = _tracebio_selected_path_file(match, settings)
    path_t, path_y = _load_tracebio_path_vertices(path_file)
    bundle = _build_common_c3d_target(match)
    target_t = np.asarray(bundle["target_t"], dtype=float)
    out_time = np.asarray(bundle["out_time"], dtype=float)
    c3d_path = Path((match.get("c3d") or {})["path"])
    c3d_shift = float(_match_plot_shifts(match).get("c3d", 0.0))

    selected_signal = str(settings.get("SelectedSignal") or "").strip()
    signal_key = selected_signal.lower()
    if "/cop/cy " in signal_key:
        c3d_cop_label = "copy"
    elif "/cop/cx " in signal_key:
        c3d_cop_label = "copx"
    else:
        raise ValueError(f"Unsupported traceBio SelectedSignal: {selected_signal}")

    t_cop, cop_m = _load_c3d_cop_channel(c3d_path, c3d_cop_label)
    t_cop = t_cop + c3d_shift
    raw_m = _resample_to_target_time(target_t, t_cop, cop_m)

    tsv_path = Path((match.get("tsv") or {})["path"])
    _cols, tsv_df = _read_tsv_table(tsv_path)
    raw_column = f"{selected_signal} [raw]"
    offset_column = f"{selected_signal} [offset]"
    if raw_column not in tsv_df.columns or offset_column not in tsv_df.columns:
        raw_column, offset_column = _find_tsv_raw_offset_pair(list(tsv_df.columns))
    if raw_column is None or offset_column is None:
        raise ValueError("TSV raw/offset columns for traceBio reconstruction are unavailable.")
    tsv_raw = _tsv_numeric_column(tsv_df, raw_column)
    tsv_offset = _tsv_numeric_column(tsv_df, offset_column)
    tsv_time_aligned: Optional[np.ndarray] = None
    if "t_rel" in tsv_df.columns:
        tsv_time_aligned = pd.to_numeric(tsv_df["t_rel"], errors="coerce").to_numpy(dtype=float)
        tsv_time_aligned = tsv_time_aligned + float(_match_plot_shifts(match).get("tsv", 0.0))
    zero_offset_m = _tracebio_zero_offset_m(
        tsv_raw,
        tsv_offset,
        raw_m,
        tsv_time_aligned=tsv_time_aligned,
        raw_time_aligned=target_t,
    )
    offset_m = raw_m - zero_offset_m

    relative_mode = _tracebio_bool(settings.get("RelativeMode"))
    sidecar_transform = _tracebio_sidecar_performed_transform(settings)
    performed_percent_source = "record_limits"
    performed_transform_version = int(sidecar_transform["version"]) if sidecar_transform else 1
    performed_transform_gain = np.nan
    performed_transform_bias = np.nan
    performed_transform_range_source = ""
    performed_transform_input = ""
    performed_transform_clamp_min = 0.0
    performed_transform_clamp_max = 100.0

    if sidecar_transform is not None:
        record_min_m = float(sidecar_transform["range_min_m"])
        record_max_m = float(sidecar_transform["range_max_m"])
        performed_transform_gain = float(sidecar_transform["gain"])
        performed_transform_bias = float(sidecar_transform["bias"])
        performed_transform_range_source = str(sidecar_transform["source"])
        performed_transform_input = str(sidecar_transform["performed_input"])
        performed_transform_clamp_min = float(sidecar_transform["clamp_min"])
        performed_transform_clamp_max = float(sidecar_transform["clamp_max"])
        performed_percent_unsmoothed = np.clip(
            (performed_transform_gain * offset_m) + performed_transform_bias,
            performed_transform_clamp_min,
            performed_transform_clamp_max,
        )
        performed_percent_source = "sidecar_v2_transform"
    else:
        record_min_m, record_max_m = _tracebio_resolve_record_limits(settings, offset_m=offset_m, tsv_offset=tsv_offset)
        performed_percent_unsmoothed = np.clip(100.0 * (offset_m - record_min_m) / (record_max_m - record_min_m), 0.0, 100.0)
        if relative_mode:
            relative_performed = _tracebio_relative_performed_percent(offset_m, target_t, tsv_df, match)
            if relative_performed is not None:
                performed_percent_unsmoothed = relative_performed
                performed_percent_source = "tsv_fit_fallback"

    if "t_rel" in tsv_df.columns:
        tsv_rel = pd.to_numeric(tsv_df["t_rel"], errors="coerce").to_numpy(dtype=float)
        tsv_rel = tsv_rel[np.isfinite(tsv_rel)]
        tsv_path_start_aligned = float(_match_plot_shifts(match).get("tsv", 0.0)) + (float(tsv_rel[0]) if tsv_rel.size else 0.0)
    else:
        tsv_path_start_aligned = float(_match_plot_shifts(match).get("tsv", 0.0))
    path_relative_time = target_t - tsv_path_start_aligned
    desired = np.interp(path_relative_time, path_t, path_y, left=float(path_y[0]), right=float(path_y[-1]))
    corridor_half_width = float(_parse_tracebio_scalar(settings.get("CorridorHalfWidth")))
    upper_t, upper_y = _tracebio_build_offset_path(path_t, path_y, corridor_half_width, +1.0)
    lower_t, lower_y = _tracebio_build_offset_path(path_t, path_y, corridor_half_width, -1.0)
    sampled_upper = _tracebio_sample_offset_path(upper_t, upper_y, path_relative_time)
    sampled_lower = _tracebio_sample_offset_path(lower_t, lower_y, path_relative_time)
    desired_upper = np.maximum(sampled_upper, sampled_lower)
    desired_lower = np.minimum(sampled_upper, sampled_lower)

    label_map = {
        "performed_percent_unsmoothed": "Full-rate C3D force-platform COP-derived non-smoothed performed path in percent",
        "desired": "Exact desired path from SelectedPath vertices",
        "desired_upper": "Desired upper corridor bound from exact offset-polyline construction",
        "desired_lower": "Desired lower corridor bound from exact offset-polyline construction",
        "raw_m": c3d_cop_label,
        "offset_m": offset_column,
        "performed_percent_source": "sidecar_v2_transform when PerformedTransformVersion>=2 is usable; otherwise legacy TSV-fit or record-limit fallback",
    }
    return {
        "time": out_time,
        "frames": np.arange(target_t.size, dtype=np.int64),
        "sample_rate": float(bundle["fs"]),
        "performed_percent_unsmoothed": performed_percent_unsmoothed,
        "desired": desired,
        "desired_upper": desired_upper,
        "desired_lower": desired_lower,
        "raw_m": raw_m,
        "offset_m": offset_m,
        "zero_offset_m": float(zero_offset_m),
        "record_min_m": float(record_min_m),
        "record_max_m": float(record_max_m),
        "selected_signal": selected_signal,
        "selected_path": str(settings.get("SelectedPath") or ""),
        "selected_path_source": str(path_file),
        "corridor_half_width": float(corridor_half_width),
        "relative_mode": bool(relative_mode),
        "smoothing_method": str(settings.get("SmoothingMethod") or ""),
        "smoothing_frames": int(_parse_tracebio_scalar(settings.get("SmoothingFrames")) or 0),
        "performed_percent_source": performed_percent_source,
        "performed_transform_version": int(performed_transform_version),
        "performed_transform_input": performed_transform_input,
        "performed_transform_range_source": performed_transform_range_source,
        "performed_transform_gain": float(performed_transform_gain),
        "performed_transform_bias": float(performed_transform_bias),
        "performed_transform_clamp_min": float(performed_transform_clamp_min),
        "performed_transform_clamp_max": float(performed_transform_clamp_max),
        "label_map": label_map,
    }


def _build_common_aligned_mat_struct(match: Dict[str, Any]) -> Dict[str, Any]:
    bundle = _build_common_c3d_target(match)
    target_t = np.asarray(bundle["target_t"], dtype=float)
    out_time = np.asarray(bundle["out_time"], dtype=float)
    fs = float(bundle["fs"])
    otb_aligned_time = np.asarray(bundle["otb_aligned_time"], dtype=float)
    aligned: Dict[str, Any] = {
        "time": out_time,
        "frames": np.arange(target_t.size, dtype=np.int64),
        "sample_rate": fs,
        "otb4": {},
        "c3d_analog": {},
        "c3d_point": {},
        "c3d_cop": {},
        "tsv": {},
    }

    otb_used: set[str] = set()
    otb_map: Dict[str, str] = {}
    for idx, label in enumerate(bundle["labels"]):
        device = _otb_label_device(label)
        row_zones = _repair_zones_for_match(match, device=device)
        row = np.asarray(bundle["data"][idx], dtype=float).reshape(-1)
        if row_zones:
            row = _insert_nan_holes_signal(row, row_zones)
        if row.size < bundle["full_len"]:
            row = np.pad(row, (0, int(bundle["full_len"] - row.size)), constant_values=np.nan)
        elif row.size > bundle["full_len"]:
            row = row[: int(bundle["full_len"])]
        field = _mat_field_name(label, otb_used)
        aligned["otb4"][field] = _resample_to_target_time(target_t, otb_aligned_time, row)
        otb_map[field] = label
    aligned["otb4"]["label_map"] = otb_map

    c3d_record = match.get("c3d") or {}
    analog_used: set[str] = set()
    analog_map: Dict[str, str] = {}
    for label in c3d_record.get("channel_names") or []:
        t, y = _load_c3d_analog_channel(Path(c3d_record["path"]), label)
        t = t + float(_match_plot_shifts(match).get("c3d", 0.0))
        field = _mat_field_name(label, analog_used)
        aligned["c3d_analog"][field] = _resample_to_target_time(target_t, t, y)
        analog_map[field] = label
    aligned["c3d_analog"]["label_map"] = analog_map

    cop_used: set[str] = set()
    cop_map: Dict[str, str] = {}
    for label in ("copx", "copy", "copz"):
        try:
            t, y = _load_c3d_cop_channel(Path(c3d_record["path"]), label)
        except Exception:
            continue
        t = t + float(_match_plot_shifts(match).get("c3d", 0.0))
        field = _mat_field_name(label, cop_used)
        aligned["c3d_cop"][field] = _resample_to_target_time(target_t, t, y)
        cop_map[field] = label
    aligned["c3d_cop"]["label_map"] = cop_map

    point_used: set[str] = set()
    point_map: Dict[str, str] = {}
    for label in c3d_record.get("point_channel_names") or []:
        base_field = _mat_field_name(label, point_used)
        point_map[base_field] = label
        for coord in ("x", "y", "z"):
            t, y = _load_c3d_point_channel(Path(c3d_record["path"]), f"{label}.{coord}")
            t = t + float(_match_plot_shifts(match).get("c3d", 0.0))
            aligned["c3d_point"][f"{base_field}_{coord}"] = _resample_to_target_time(target_t, t, y)
    aligned["c3d_point"]["label_map"] = point_map

    tsv_record = match.get("tsv") or {}
    tsv_used: set[str] = set()
    tsv_map: Dict[str, str] = {}
    for label in _channel_list_for_record(tsv_record):
        t, y = _load_tsv_channel(Path(tsv_record["path"]), label)
        t = t + float(_match_plot_shifts(match).get("tsv", 0.0))
        field = _mat_field_name(label, tsv_used)
        aligned["tsv"][field] = _resample_to_target_time(target_t, t, y)
        tsv_map[field] = label
    aligned["tsv"]["label_map"] = tsv_map
    return aligned


def _build_pipe_bundle(match: Dict[str, Any]) -> Tuple[np.ndarray, np.ndarray, np.ndarray, float, Dict[str, Any]]:
    bundle = _build_common_c3d_target(match)
    otb_path = Path(bundle["path"])
    otb_data = np.asarray(bundle["data"], dtype=float)
    labels = list(bundle["labels"])
    fs = float(bundle["fs"])
    path_grids = _infer_otb_grids(labels)
    emg_groups = _infer_otb_emg_groups(otb_path)
    target_t = np.asarray(bundle["target_t"], dtype=float)
    out_time = np.asarray(bundle["out_time"], dtype=float)
    target_fs = float(fs)
    otb_aligned_time = np.asarray(bundle["otb_aligned_time"], dtype=float)
    data_out: List[np.ndarray] = []
    desc_out: List[str] = []
    json_means: Dict[str, Any] = {"filename": _pipe_mat_path(Path((((match.get("export_plan") or {}).get("mat") or {}).get("path") or "out.mat"))).name}
    tracebio_fullrate = _build_tracebio_fullrate_struct(match, float(bundle["start_sec"]), float(bundle["end_sec"])) if match.get("tsv") else {}

    grid_by_end = {grid["block_end"]: grid for grid in path_grids}
    original_to_output: Dict[int, int] = {}
    for idx, label in enumerate(labels):
        device = _otb_label_device(label)
        row_zones = _repair_zones_for_match(match, device=device)
        row = np.asarray(otb_data[idx], dtype=float).reshape(-1)
        if row_zones:
            row = _insert_nan_holes_signal(row, row_zones)
        if row.size < bundle["full_len"]:
            row = np.pad(row, (0, int(bundle["full_len"] - row.size)), constant_values=np.nan)
        elif row.size > bundle["full_len"]:
            row = row[: int(bundle["full_len"])]
        col = _resample_to_target_time(target_t, otb_aligned_time, row).astype(float, copy=True)
        data_out.append(col)
        out_idx = len(data_out) - 1
        desc_out.append(label)
        original_to_output[idx] = out_idx
        if idx in grid_by_end and tracebio_fullrate:
            if "Performed Path" not in desc_out:
                data_out.append(np.asarray(tracebio_fullrate["performed_percent_unsmoothed"], dtype=float))
                desc_out.append("Performed Path")
            if "Desired Path" not in desc_out:
                data_out.append(np.asarray(tracebio_fullrate["desired"], dtype=float))
                desc_out.append("Desired Path")
            if "Desired Upper Path" not in desc_out:
                data_out.append(np.asarray(tracebio_fullrate["desired_upper"], dtype=float))
                desc_out.append("Desired Upper Path")
            if "Desired Lower Path" not in desc_out:
                data_out.append(np.asarray(tracebio_fullrate["desired_lower"], dtype=float))
                desc_out.append("Desired Lower Path")

    for label, spec in _build_pipe_extra_specs(match):
        if label in {"Performed Path", "Original Path", "Desired Path", "Desired Upper Path", "Desired Lower Path"}:
            continue
        t, y = _load_aligned_series(match, spec)
        data_out.append(_resample_to_target_time(target_t, t, y))
        desc_out.append(label)

    data_matrix = np.column_stack(data_out).astype(np.float64, copy=False)
    for grid in emg_groups:
        entries: List[Dict[str, Any]] = []
        for original_idx in grid["emg_indices"]:
            out_idx = original_to_output[original_idx]
            mean_before = float(np.nanmean(data_matrix[:, out_idx]))
            data_matrix[:, out_idx] = data_matrix[:, out_idx] - mean_before
            mean_after = float(np.nanmean(data_matrix[:, out_idx]))
            entries.append(
                {
                    "channel_index": int(out_idx),
                    "method": "mean",
                    "mean_before": mean_before,
                    "mean_after": mean_after,
                }
            )
        json_means[grid["grid_uid"]] = entries

    desc_array = np.asarray(desc_out, dtype=object).reshape(-1, 1)
    return data_matrix, out_time, desc_array, target_fs, json_means


def export_match_pipe_bundle(match: Dict[str, Any], export_root: Path) -> Tuple[Path, Path]:
    saved_stamp = match.get("saved_at") or _format_file_stamp()
    base_mat_name = (((match.get("export_plan") or {}).get("mat") or {}).get("filename") or _mat_export_name(match, saved_stamp))
    base_mat_path = Path(export_root) / base_mat_name
    pipe_mat_path = _pipe_mat_path(base_mat_path)
    pipe_json_path = _pipe_json_path(pipe_mat_path)
    pipe_mat_path.parent.mkdir(parents=True, exist_ok=True)

    data, time, description, fs, json_means = _build_pipe_bundle(match)
    savemat(
        str(pipe_mat_path),
        {
            "Data": data,
            "Time": np.asarray(time, dtype=float),
            "Description": description,
            "SamplingFrequency": np.asarray([[float(fs)]], dtype=float),
        },
        do_compression=True,
        long_field_names=True,
    )
    pipe_json_path.write_text(json.dumps(json_means, indent=2), encoding="utf-8")
    return pipe_mat_path, pipe_json_path


def _series_label(spec: Dict[str, Any]) -> str:
    source = spec["source"]
    channel = spec["channel"]
    prefix = {"otb4": "OTB4", "c3d": "C3D", "tsv": "TSV"}.get(source, source.upper())
    if spec.get("kind") == "probe_buffer":
        return f"{prefix} probe buffer: {spec.get('device')}"
    if spec.get("kind") == "probe_ramp":
        return f"{prefix} probe ramp: {spec.get('device')}"
    if spec.get("kind") == "point":
        return f"{prefix} point: {channel}"
    if spec.get("kind") == "cop":
        return f"{prefix} CoP: {channel}"
    if spec.get("kind") == "sync":
        return f"{prefix} sync: {channel}"
    if spec.get("kind") == "sync_ch3":
        return f"{prefix} sync ch3 (3_Sync_50ms)"
    if spec.get("kind") == "sync_ch1":
        return f"{prefix} sync ch1 (1_TTL)"
    if spec.get("kind") == "raw":
        return f"{prefix} raw: {channel}"
    return f"{prefix}: {channel}"


# Matplotlib's "tab10" categorical palette -- 10 maximally-distinct hues
# used throughout plotting instead of hand-picked colors, so traces stay
# visually distinguishable at a glance regardless of how many overlap.
_TAB10_PALETTE = [
    "#1f77b4",  # blue
    "#ff7f0e",  # orange
    "#2ca02c",  # green
    "#d62728",  # red
    "#9467bd",  # purple
    "#8c564b",  # brown
    "#e377c2",  # pink
    "#7f7f7f",  # gray
    "#bcbd22",  # olive
    "#17becf",  # cyan
]


def _source_plot_color(source: str) -> str:
    return {
        "c3d": _TAB10_PALETTE[0],
        "otb4": _TAB10_PALETTE[1],
        "tsv": _TAB10_PALETTE[4],
    }.get(str(source or "").lower(), _TAB10_PALETTE[7])


def _series_color(spec: Dict[str, Any]) -> str:
    if spec.get("kind") == "probe_buffer":
        return _TAB10_PALETTE[8]
    if spec.get("kind") == "probe_ramp":
        return _TAB10_PALETTE[3]
    if spec.get("kind") == "sync":
        return _source_plot_color(str(spec.get("source") or ""))
    if spec.get("kind") == "point":
        return _TAB10_PALETTE[6]
    if spec.get("kind") == "cop":
        return _TAB10_PALETTE[0]
    if spec.get("kind") == "raw":
        return _source_plot_color(str(spec.get("source") or ""))
    return {"otb4": _TAB10_PALETTE[1], "c3d": _TAB10_PALETTE[7], "tsv": _TAB10_PALETTE[4]}.get(spec["source"], _TAB10_PALETTE[7])


def _series_identity_key(spec: Dict[str, Any]) -> str:
    return "|".join(
        [
            str(spec.get("source") or ""),
            str(spec.get("kind") or ""),
            str(spec.get("channel") or ""),
            str(spec.get("device") or ""),
            str(spec.get("subtitle") or ""),
        ]
    )


def _stable_series_palette_color(spec: Dict[str, Any]) -> str:
    # Tab10 cycle, keyed by a stable hash of the series identity so the same
    # channel always gets the same color across refreshes/matches. Line
    # style (see PlotRowWidget.refresh) already distinguishes channel 1/2/3
    # when traces overlap, so a plain tab10 hash -- rather than a per-source
    # sub-palette -- keeps colors maximally distinct without the risk of
    # any one hue family (e.g. all-green) dominating.
    key = _series_identity_key(spec)
    checksum = sum((idx + 1) * ord(ch) for idx, ch in enumerate(key))
    return _TAB10_PALETTE[checksum % len(_TAB10_PALETTE)]


def _overlay_series_color(spec: Dict[str, Any], idx: int, total: int) -> str:
    kind = str(spec.get("kind") or "")
    if kind in {"probe_buffer", "probe_ramp", "sync", "point", "cop", "raw"}:
        return _series_color(spec)
    return _stable_series_palette_color(spec)


def _raw_overlay_summary(match: Dict[str, Any]) -> str:
    alignment = match.get("alignment") or {}
    raw_tsv = alignment.get("raw_label_match_tsv") or "missing"
    raw_c3d = alignment.get("raw_label_match_c3d") or "missing"
    quality = alignment.get("raw_alignment_quality") or "missing"
    corr = alignment.get("raw_alignment_corr")
    lag_sec = alignment.get("raw_alignment_lag_sec")
    extra = f"quality={quality}"
    if isinstance(corr, (int, float)):
        extra += f" corr={corr:.3f}"
    if isinstance(lag_sec, (int, float)):
        extra += f" lag={lag_sec:.3f}s"
    return f"Matched raw overlay | {extra} | C3D: {raw_c3d} | TSV: {raw_tsv}"


def _sync_annotation_text(match: Dict[str, Any], dedicated: Dict[str, Any]) -> str:
    alignment = match.get("alignment") or {}
    lines = [f"basis: {alignment.get('tsv_alignment_basis') or 'raw_only'}"]
    if dedicated.get("mean_abs_delta_ms") is not None:
        lines.append(
            f"dedicated sync: {dedicated['quality']}  mean={dedicated['mean_abs_delta_ms']:.3f} ms  "
            f"max={dedicated['max_abs_delta_ms']:.3f} ms  n={dedicated['spike_count']}"
        )
    else:
        lines.append(f"dedicated sync: {dedicated['quality']}")
    if dedicated.get("tsv_sync_missing"):
        lines.append(f"TSV dedicated sync missing; OTB4/C3D pair quality={dedicated.get('pair_quality')}")
    pair_bits = []
    for key, info in (dedicated.get("pairwise") or {}).items():
        pair_bits.append(f"{key} {info.get('matched_spikes_50ms', 0)}/{info.get('count', 0)} spikes<=50ms")
    if pair_bits:
        lines.append(" | ".join(pair_bits))
    raw_corr = alignment.get("raw_alignment_corr")
    if isinstance(raw_corr, (int, float)):
        lines.append(f"used raw alignment: {alignment.get('raw_alignment_quality')}  corr={raw_corr:.3f}  lag={alignment.get('raw_alignment_lag_sec'):.3f}s")
    lines.append(_otb4_probe_sync_annotation_text(match))
    return "\n".join(lines)


def _sync_status_text(match: Dict[str, Any], dedicated: Dict[str, Any]) -> str:
    alignment = match.get("alignment") or {}
    raw_corr = alignment.get("raw_alignment_corr")
    raw_text = f"raw {alignment.get('raw_alignment_quality')}"
    if isinstance(raw_corr, (int, float)):
        raw_text += f" corr {raw_corr:.3f}"
    if not match.get("otb4"):
        return f"C3D/TSV raw-correlation alignment | {raw_text}"
    if dedicated.get("tsv_sync_missing"):
        base = f"Dedicated sync missing in TSV | OTB4/C3D {dedicated.get('pair_quality')} | {raw_text}"
    else:
        base = f"Dedicated sync {dedicated.get('quality')} | {raw_text}"
    return base + " | " + _otb4_probe_sync_summary_text(match)


def _raw_annotation_text(match: Dict[str, Any]) -> str:
    alignment = match.get("alignment") or {}
    corr = alignment.get("raw_alignment_corr")
    lag_sec = alignment.get("raw_alignment_lag_sec")
    if not isinstance(corr, (int, float)) or not isinstance(lag_sec, (int, float)):
        return "raw alignment unavailable"
    return (
        f"raw alignment: {alignment.get('raw_alignment_quality')}  "
        f"corr={corr:.6f}  lag={lag_sec:.3f}s  plotted_range=[0,1]\n"
        f"C3D {alignment.get('raw_label_match_c3d')}  <->  TSV {alignment.get('raw_label_match_tsv')}"
    )


def _raw_status_text(match: Dict[str, Any]) -> str:
    alignment = match.get("alignment") or {}
    corr = alignment.get("raw_alignment_corr")
    if isinstance(corr, (int, float)):
        return f"Raw overlay {alignment.get('raw_alignment_quality')} | corr {corr:.6f} | lag {alignment.get('raw_alignment_lag_sec'):.3f}s | plotted [0,1]"
    return "Raw overlay unavailable."


def _match_files_line(match: Dict[str, Any]) -> str:
    return (
        "Merged files: "
        f"OTB4={Path(str((match.get('otb4') or {}).get('path') or '')).name or 'missing'} | "
        f"C3D={Path(str((match.get('c3d') or {}).get('path') or '')).name or 'missing'} | "
        f"TSV={Path(str((match.get('tsv') or {}).get('path') or '')).name if match.get('tsv') else 'missing'}"
    )


def _pairwise_sync_metric_text(dedicated: Dict[str, Any], plotted_sources: Sequence[str]) -> str:
    pairwise = dedicated.get("pairwise") or {}
    labels: List[str] = []
    for idx, left in enumerate(plotted_sources):
        for right in plotted_sources[idx + 1:]:
            info = pairwise.get(f"{left}_vs_{right}") or pairwise.get(f"{right}_vs_{left}") or {}
            if not info:
                continue
            labels.append(
                f"{left.upper()}/{right.upper()} {int(info.get('matched_spikes_50ms') or 0)}/{int(info.get('count') or 0)}<=50ms"
            )
    return " | ".join(labels)


def _plot_source_files_text(match: Dict[str, Any], row_role: str, series_specs: Sequence[Dict[str, Any]]) -> str:
    if row_role == "sync":
        source_order = [source for source in ("otb4", "c3d", "tsv") if match.get(source) and any(spec.get("source") == source for spec in series_specs)]
    elif row_role == "raw":
        source_order = [source for source in ("c3d", "tsv") if match.get(source) and any(spec.get("source") == source for spec in series_specs)]
    else:
        source_order = []
        for spec in series_specs:
            source = str(spec.get("source") or "")
            if source in {"otb4", "c3d", "tsv"} and source not in source_order and match.get(source):
                source_order.append(source)
    if not source_order:
        return "Files: none"
    parts = [f"{source.upper()}:{Path(str((match.get(source) or {}).get('path') or '')).name}" for source in source_order]
    return "Files: " + " | ".join(parts)


def _sync_plot_metric_text(match: Dict[str, Any], series_specs: Sequence[Dict[str, Any]]) -> str:
    dedicated = _dedicated_sync_agreement_for_edge_alignment(match)
    plotted_sources = [str(spec.get("source") or "") for spec in series_specs if spec.get("kind") == "sync"]
    plotted_sources = [source for idx, source in enumerate(plotted_sources) if source and source not in plotted_sources[:idx]]
    parts = [f"Sync {dedicated.get('quality') or 'missing'}"]
    mean_abs = dedicated.get("mean_abs_delta_ms")
    max_abs = dedicated.get("max_abs_delta_ms")
    spike_count = dedicated.get("spike_count")
    if isinstance(mean_abs, (int, float)):
        parts.append(f"mean {float(mean_abs):.1f} ms")
    if isinstance(max_abs, (int, float)):
        parts.append(f"max {float(max_abs):.1f} ms")
    if isinstance(spike_count, (int, float)):
        parts.append(f"n={int(spike_count)}")
    pair_text = _pairwise_sync_metric_text(dedicated, plotted_sources)
    if pair_text:
        parts.append(pair_text)
    parts.append(_otb4_probe_sync_summary_text(match))
    return " | ".join(parts)


def _probe_detail_plot_metric_text(match: Dict[str, Any], device: str) -> str:
    diag = _otb4_probe_sync_diagnostics(match)
    probe = next((item for item in (diag.get("probes") or []) if str(item.get("device") or "") == str(device)), None)
    if not probe:
        return "Probe sync detail unavailable."
    ref_summary = probe.get("reference_summary") or {}
    ref_expected = int((diag.get("reference_pattern") or {}).get("expected_event_count") or 0)
    optimal_lag_sec = float(probe.get("optimal_lag_sec") or 0.0)
    return (
        f"{device} | {probe.get('sync_status')} | "
        f"ok={int(ref_summary.get('matched_count') or 0)}/{ref_expected} | "
        f"miss={int(ref_summary.get('unmatched_ref') or 0)} | extra={int(ref_summary.get('unmatched_other') or 0)} | "
        f"shift={optimal_lag_sec * 1000.0:.1f} ms | "
        f"{probe.get('sample_status')}"
    )


def _raw_plot_metric_text(match: Dict[str, Any]) -> str:
    alignment = match.get("alignment") or {}
    corr = alignment.get("raw_alignment_corr")
    lag_sec = alignment.get("raw_alignment_lag_sec")
    quality = alignment.get("raw_alignment_quality") or "missing"
    if not isinstance(corr, (int, float)) or not isinstance(lag_sec, (int, float)):
        return "Raw unavailable"
    return (
        f"Raw {quality} | r={float(corr):.3f} | lag={float(lag_sec) * 1000.0:.1f} ms | "
        f"{alignment.get('raw_label_match_c3d') or 'C3D?'} vs {alignment.get('raw_label_match_tsv') or 'TSV?'}"
    )


def _plot_decision_context_text(match: Dict[str, Any], row_role: str, series_specs: Sequence[Dict[str, Any]]) -> str:
    kinds = {str(spec.get("kind") or "") for spec in series_specs}
    lines: List[str] = []
    if row_role == "sync" or "sync" in kinds:
        lines.append(_sync_plot_metric_text(match, series_specs))
    if row_role == "raw" or "raw" in kinds:
        lines.append(_raw_plot_metric_text(match))
    if row_role == "probe_detail":
        device = str(next((spec.get("device") for spec in series_specs if spec.get("device")), "") or "")
        lines.append(_probe_detail_plot_metric_text(match, device))
    if not lines:
        lines.append("Context only; sync/raw rows carry the decision metrics.")
    return " || ".join(lines)


def _repair_gap_regions(match: Dict[str, Any]) -> List[Tuple[float, float]]:
    repair = _repair_info_for_match(match) or {}
    regions: List[Tuple[float, float]] = []
    for container in [repair, *((_device_repairs_for_match(match) or {}).values())]:
        for zone in container.get("zones") or []:
            start = zone.get("aligned_start_sec")
            end = zone.get("aligned_end_sec")
            if isinstance(start, (int, float)) and isinstance(end, (int, float)) and end > start:
                regions.append((float(start), float(end)))
    regions.sort()
    merged: List[Tuple[float, float]] = []
    for start, end in regions:
        if not merged or start > merged[-1][1]:
            merged.append((start, end))
        else:
            merged[-1] = (merged[-1][0], max(merged[-1][1], end))
    return merged


def _repair_gap_style(match: Dict[str, Any]) -> Tuple[Tuple[int, int, int, int], str]:
    repair = _repair_info_for_match(match)
    if repair and repair.get("applied"):
        return (255, 214, 214, 28), "#E7A5A5"
    return (255, 240, 199, 28), "#D1A24A"


def _repair_status_text(match: Dict[str, Any]) -> str:
    repair = _repair_info_for_match(match)
    device_repairs = _device_repairs_for_match(match)
    if not repair and not device_repairs:
        return "OTB4 repair: no gap zones detected."
    device_count = len([value for value in device_repairs.values() if (value.get("zones") or [])])
    if not repair:
        return f"OTB4 device-specific gap candidates detected on {device_count} device(s)."
    if not repair.get("applied"):
        return (
            f"OTB4 gap candidate via {repair.get('device')} {repair.get('subtitle')} | "
            f"gaps {len(repair.get('zones') or [])} | +{int(repair.get('samples_added') or 0)} samples | "
            f"mean {repair.get('base_mean_abs_ms')} -> {repair.get('candidate_mean_abs_ms')} ms | "
            f"device candidates {device_count} | not auto-applied"
        )
    return (
        f"OTB4 repair applied via {repair.get('device')} {repair.get('subtitle')} | "
        f"gaps {len(repair.get('zones') or [])} | +{int(repair.get('samples_added') or 0)} samples | "
        f"mean {repair.get('base_mean_abs_ms')} -> {repair.get('repaired_mean_abs_ms')} ms | "
        f"device candidates {device_count}"
    )


def _y_axis_label(row_role: str, series_specs: Sequence[Dict[str, Any]]) -> Tuple[str, Optional[str]]:
    if row_role == "raw":
        return "Normalized value", None
    if row_role == "probe_detail":
        return "Probe sync / ramp", None
    if len(series_specs) == 1 and series_specs[0].get("kind") in {"cop", "raw"}:
        return "Position", "m"
    return "Value", None


AUTO_ACCEPT_COLOR = "#CFEFD2"
USER_ACCEPT_COLOR = "#1E6B2D"
AUTO_REJECT_COLOR = "#F2CACA"
USER_REJECT_COLOR = "#8B1E1E"
NEUTRAL_BUTTON_COLOR = "#D9D9D9"


def _review_status_key_from_review(review: Dict[str, Any]) -> str:
    if review.get("user_decision") is True:
        return "user_accept"
    if review.get("user_decision") is False:
        return "user_reject"
    return "auto_accept" if review.get("auto_accept") else "auto_reject"


def _review_status_label_from_review(review: Dict[str, Any]) -> str:
    return {
        "auto_accept": "AUTO-ACCEPT",
        "user_accept": "USER-ACCEPT",
        "auto_reject": "AUTO-REJECT",
        "user_reject": "USER-REJECT",
    }[_review_status_key_from_review(review)]


def _review_status_key(match: Dict[str, Any]) -> str:
    review = match.get("review") or {}
    return _review_status_key_from_review(review)


def _review_status_label(match: Dict[str, Any]) -> str:
    review = match.get("review") or {}
    return _review_status_label_from_review(review)


def _decision_reason_text(match: Dict[str, Any]) -> str:
    if match.get("otb4") and match.get("c3d") and not ((match.get("alignment") or {}).get("otb4_c3d_edge_alignment")):
        # Ensure the channel-2/channel-3 diagnosis has run at least once for
        # this match, so pairs that never went through TSV matching (no TSV
        # attached) still get a real diagnosis here instead of "unavailable".
        _dedicated_sync_agreement_for_edge_alignment(match)
    alignment = match.get("alignment") or {}
    review = match.get("review") or {}
    pairwise = alignment.get("dedicated_sync_pairwise") or {}
    otb_c3d = pairwise.get("otb4_vs_c3d") or pairwise.get("c3d_vs_otb4") or {}
    raw_quality = alignment.get("raw_alignment_quality") or "missing"
    raw_corr = alignment.get("raw_alignment_corr")
    raw_lag = alignment.get("raw_alignment_lag_sec")
    edge_align = alignment.get("otb4_c3d_edge_alignment") or {}
    lines: List[str] = []
    lines.append(f"Automatic suggestion: {_review_status_label(match)}")
    lines.append(f"Decision source: {review.get('decision_source') or 'automatic'}")
    lines.append(f"Triplet certainty: {match.get('certainty')}")
    if match.get("manual_selection") or alignment.get("manual_selection"):
        lines.append("Manual assembly: this candidate was created by user-selected C3D/OTB4/TSV sources and should be confirmed visually.")
    if alignment.get("manual_reassignment"):
        lines.append(f"Manual reassignment: {alignment.get('manual_reassignment_note') or 'A source file was reassigned and this candidate now needs confirmation.'}")

    if isinstance(raw_corr, (int, float)) and isinstance(raw_lag, (int, float)):
        lines.append(
            f"Raw C3D/TSV match: {raw_quality} | corr={float(raw_corr):.6f} | lag={float(raw_lag):.3f}s"
        )
    else:
        lines.append(f"Raw C3D/TSV match: {raw_quality}")

    if otb_c3d:
        mean_ms = otb_c3d.get("mean_abs_ms")
        max_ms = otb_c3d.get("max_abs_ms")
        matched = int(otb_c3d.get("matched_spikes_50ms") or 0)
        count = int(otb_c3d.get("count") or 0)
        lines.append(
            f"OTB4/C3D sync: mean={mean_ms} ms | max={max_ms} ms | spikes within 50 ms={matched}/{count}"
        )
        if edge_align.get("basis") == "late_c3d_raw_bridge":
            lines.append(
                f"Sync bridge used: late C3D start inferred from raw alignment; skipped {int(edge_align.get('otb4_skip') or 0)} leading OTB4 sync pulse(s)."
            )
        elif edge_align.get("basis") == "channel2_refined":
            lines.append(
                "Sync basis: channel 2 matching pulses found after widening the leading-edge search "
                f"(skipped {int(edge_align.get('otb4_skip') or 0)} OTB4 / {int(edge_align.get('c3d_skip') or 0)} "
                f"C3D edge(s)); refined to mean={float(edge_align.get('mean_abs_ms') or 0.0):.2f}ms."
            )
        elif edge_align.get("diagnostic_note"):
            lines.append(f"Sync diagnosis: {edge_align['diagnostic_note']}")
    else:
        if match.get("otb4"):
            lines.append("OTB4/C3D sync: unavailable")
            if edge_align.get("diagnostic_note"):
                lines.append(f"Sync diagnosis: {edge_align['diagnostic_note']}")
        else:
            lines.append("Dedicated sync: not used for C3D/TSV doublets; raw C3D/TSV correlation is the alignment basis.")

    auto_accept = bool(review.get("auto_accept"))
    if auto_accept:
        if match.get("otb4"):
            lines.append("Why accepted: the match is certain, the raw C3D/TSV channel agrees strongly, and the OTB4/C3D sync pulses are within the auto-accept tolerance.")
        else:
            lines.append("Why accepted: the match is certain and the raw C3D/TSV channel agrees strongly.")
    else:
        fail_reasons: List[str] = []
        if match.get("certainty") != "certain":
            fail_reasons.append("pairing certainty is below 'certain'")
        raw_ok = raw_quality == "excellent" or (
            raw_quality == "good" and isinstance(raw_corr, (int, float)) and abs(float(raw_corr)) >= 0.995
        )
        if not raw_ok:
            fail_reasons.append("raw C3D/TSV agreement did not reach the auto-accept threshold")
        if otb_c3d:
            mean_ms = otb_c3d.get("mean_abs_ms")
            max_ms = otb_c3d.get("max_abs_ms")
            matched = int(otb_c3d.get("matched_spikes_50ms") or 0)
            count = int(otb_c3d.get("count") or 0)
            sync_ok = False
            if count > 0 and matched >= count:
                sync_ok = True
            elif isinstance(mean_ms, (int, float)) and isinstance(max_ms, (int, float)):
                sync_ok = float(mean_ms) <= 20.0 and float(max_ms) <= 50.0
            if not sync_ok:
                fail_reasons.append("OTB4/C3D sync stayed outside the auto-accept limit (mean <= 20 ms and max <= 50 ms, or all spikes matched)")
        if fail_reasons:
            lines.append("Why rejected: " + " ".join(fail_reasons))

    if match.get("otb4"):
        lines.append("Guide: accept if OTB4/C3D sync and the raw C3D/TSV overlay are physically consistent across the green common time window.")
    else:
        lines.append("Guide: accept C3D/TSV doublets from the raw overlay; TSV/C3D sync pulses are diagnostic only and are not required to match.")
    return "\n".join(lines)


def _decision_reason_rich_text(match: Dict[str, Any]) -> str:
    green = "#1F5E2E"
    red = "#7A1F1F"
    parts: List[str] = []
    for line in _decision_reason_text(match).splitlines():
        escaped = html.escape(line)
        color: Optional[str] = None
        if line.startswith("Automatic suggestion:"):
            if "ACCEPT" in line:
                color = green
            elif "REJECT" in line:
                color = red
        elif line.startswith("Why accepted:"):
            color = green
        elif line.startswith("Why rejected:"):
            color = red
        if color:
            parts.append(f'<span style="color: {color}; font-weight: 700;">{escaped}</span>')
        else:
            parts.append(escaped)
    return "<br>".join(parts)


def _review_status_color_from_review(review: Dict[str, Any]) -> str:
    return {
        "auto_accept": AUTO_ACCEPT_COLOR,
        "user_accept": USER_ACCEPT_COLOR,
        "auto_reject": AUTO_REJECT_COLOR,
        "user_reject": USER_REJECT_COLOR,
    }[_review_status_key_from_review(review)]


def _review_status_color(match: Dict[str, Any]) -> str:
    return _review_status_color_from_review(match.get("review") or {})


def _review_queue_background_color(match: Dict[str, Any]) -> str:
    return {
        "auto_accept": "#E4F4E6",
        "user_accept": "#D7F0DD",
        "auto_reject": "#F8E4E4",
        "user_reject": "#F4D9D9",
    }[_review_status_key(match)]


def _review_queue_text_color(match: Dict[str, Any], selected: bool = False) -> str:
    return {
        "auto_accept": "#123A20",
        "user_accept": "#123A20",
        "auto_reject": "#5B1F1F",
        "user_reject": "#5B1F1F",
    }[_review_status_key(match)]


def _style_button(button, bg_color: str, fg_color: str) -> None:
    button.setStyleSheet(
        f"QPushButton {{ background-color: {bg_color}; color: {fg_color}; font-weight: 600; padding: 6px 10px; }}"
    )


def _html_badge(text: str, bg: str, fg: str = "#FFFFFF") -> str:
    return (
        f'<span style="background:{bg}; color:{fg}; border:1px solid {bg}; '
        f'border-radius:10px; padding:3px 8px; font-weight:700;">{html.escape(text)}</span>'
    )


def _html_muted(text: str) -> str:
    return f'<span style="color:#5F6B7A;">{html.escape(text)}</span>'


def _report_label_style(bg: str, border: str, fg: str = "#17212B") -> str:
    return (
        "QLabel {"
        f"background:{bg}; color:{fg}; border:1px solid {border}; border-radius:10px; "
        "padding:10px 12px;"
        "}"
    )


def _review_status_badge(match: Dict[str, Any]) -> str:
    key = _review_status_key(match)
    mapping = {
        "auto_accept": ("AUTO-ACCEPT", "#D7F0DD", "#123A20"),
        "user_accept": ("USER-ACCEPT", "#1E6B2D", "#FFFFFF"),
        "auto_reject": ("AUTO-REJECT", "#F6D9D9", "#5B1F1F"),
        "user_reject": ("USER-REJECT", "#8B1E1E", "#FFFFFF"),
    }
    text, bg, fg = mapping[key]
    return _html_badge(text, bg, fg)


def _certainty_badge(certainty: Any) -> str:
    text = str(certainty or "unknown")
    if text == "certain":
        return _html_badge(f"Certainty: {text}", "#D7F0DD", "#123A20")
    if text == "probable":
        return _html_badge(f"Certainty: {text}", "#FFF0C7", "#6A4D00")
    return _html_badge(f"Certainty: {text}", "#F6D9D9", "#5B1F1F")


def _exportable_badge(match: Dict[str, Any]) -> str:
    exportable = _mat_export_supported(match)
    return _html_badge(
        "Exportable MAT" if exportable else "Review only",
        "#DCEEFF" if exportable else "#F6D9D9",
        "#154463" if exportable else "#5B1F1F",
    )


def _probe_health_badge(match: Dict[str, Any]) -> str:
    diag = _otb4_probe_sync_diagnostics(match)
    non_sync = int(diag.get("non_sync_probe_count") or 0)
    total = len(diag.get("probes") or [])
    if total <= 0:
        return _html_badge("Probe sync: unavailable", "#E8EDF2", "#44515E")
    if non_sync <= 0:
        return _html_badge(f"Probe sync: {total}/{total} clean", "#D7F0DD", "#123A20")
    return _html_badge(f"Probe sync: {non_sync} off-pattern", "#FFF0C7", "#6A4D00")


def _header_rich_text(match: Dict[str, Any]) -> str:
    alignment = match.get("alignment") or {}
    inner_merge = alignment.get("inner_merge") or {}
    review = match.get("review") or {}
    merge_start = inner_merge.get("inner_merge_start_sec")
    merge_end = inner_merge.get("inner_merge_end_sec")
    merge_duration = inner_merge.get("inner_merge_duration_sec")
    merge_text = "Common time window unavailable."
    if isinstance(merge_start, (int, float)) and isinstance(merge_end, (int, float)) and isinstance(merge_duration, (int, float)):
        merge_text = f"Common time window: {merge_start:.3f}s to {merge_end:.3f}s ({merge_duration:.3f}s)"
    match_title = f"Match {int(match.get('match_id') or 0):03d}"
    line1 = " ".join(
        [
            _review_status_badge(match),
            _certainty_badge(match.get("certainty")),
            _exportable_badge(match),
            _probe_health_badge(match),
        ]
    )
    line2 = (
        f"{_html_muted('Decision source')} <b>{html.escape(str(review.get('decision_source') or 'automatic'))}</b>"
        f" &nbsp;&nbsp; {_html_muted('Merge window')} <b>{html.escape(merge_text)}</b>"
    )
    return (
        f'<div style="font-size:18px; font-weight:700; color:#13202E;">{html.escape(match_title)}</div>'
        f'<div style="margin-top:6px;">{line1}</div>'
        f'<div style="margin-top:8px; font-size:13px;">{line2}</div>'
    )


def _progress_rich_text(
    reviewed_count: int,
    total_count: int,
    user_accept_count: int,
    user_reject_count: int,
    free_c3d: int,
    free_otb4: int,
    free_tsv: int,
) -> str:
    parts = [
        _html_badge(f"Reviewed {reviewed_count}/{total_count}", "#DCEEFF", "#154463"),
        _html_badge(f"User accepted {user_accept_count}", "#D7F0DD", "#123A20"),
        _html_badge(f"User rejected {user_reject_count}", "#F6D9D9", "#5B1F1F"),
        _html_badge(f"Free C3D {free_c3d}", "#EEF2F6", "#44515E"),
        _html_badge(f"Free OTB4 {free_otb4}", "#EEF2F6", "#44515E"),
        _html_badge(f"Free TSV {free_tsv}", "#EEF2F6", "#44515E"),
    ]
    helper = _html_muted("Auto-accept expects excellent raw agreement and strong OTB4/C3D sync.")
    return f'<div style="line-height:1.8;">{" ".join(parts)}</div><div style="margin-top:6px;">{helper}</div>'


def _scan_notes_rich_text(notes: Sequence[str]) -> str:
    if not notes:
        return '<span style="color:#5F6B7A;">No scan notes were recorded for this review.</span>'
    items = "".join(
        f'<li style="margin:4px 0;">{html.escape(str(note))}</li>'
        for note in notes
        if str(note).strip()
    )
    return f'<div style="font-weight:700; color:#13202E;">Important scan notes</div><ul style="margin:8px 0 0 18px;">{items}</ul>'


def _sync_info_rich_text(match: Dict[str, Any], dedicated: Dict[str, Any]) -> str:
    alignment = match.get("alignment") or {}
    quality = str(dedicated.get("quality") or "missing")
    pair_quality = str(dedicated.get("pair_quality") or "insufficient")
    mean_abs = dedicated.get("mean_abs_delta_ms")
    max_abs = dedicated.get("max_abs_delta_ms")
    spike_count = int(dedicated.get("spike_count") or 0)
    diag = _otb4_probe_sync_diagnostics(match)
    non_sync = int(diag.get("non_sync_probe_count") or 0)
    if not match.get("otb4"):
        bits = ["<b>Dedicated sync:</b> not used for C3D/TSV doublets"]
    else:
        bits = [f"<b>Dedicated sync:</b> {html.escape(quality)}"]
    if isinstance(mean_abs, (int, float)):
        bits.append(f"<b>Mean abs:</b> {float(mean_abs):.3f} ms")
    if isinstance(max_abs, (int, float)):
        bits.append(f"<b>Max abs:</b> {float(max_abs):.3f} ms")
    if spike_count:
        bits.append(f"<b>Spikes:</b> {spike_count}")
    if match.get("otb4"):
        bits.append(f"<b>Pair quality:</b> {html.escape(pair_quality)}")
    if non_sync:
        bits.append(f"<b>Probe warning:</b> {non_sync} off-pattern")
    helper = html.escape(_repair_status_text(match))
    if not match.get("otb4"):
        helper += "<br><span style='color:#3D4955;'>C3D/TSV alignment uses raw-channel cross-correlation; sync pulses are diagnostic only.</span>"
    return (
        '<div style="font-size:14px; font-weight:700; color:#123A20;">Sync evidence</div>'
        f'<div style="margin-top:6px; line-height:1.7;">{" &nbsp;&nbsp; ".join(bits)}</div>'
        f'<div style="margin-top:8px; color:#3D4955;">{helper}</div>'
    )


def _raw_info_rich_text(match: Dict[str, Any], missing_reason: Optional[str] = None) -> str:
    alignment = match.get("alignment") or {}
    if missing_reason:
        return (
            '<div style="font-size:14px; font-weight:700; color:#7A1F1F;">Raw evidence unavailable</div>'
            f'<div style="margin-top:6px; color:#4B5563;">{html.escape(missing_reason)}</div>'
        )
    corr = alignment.get("raw_alignment_corr")
    lag_sec = alignment.get("raw_alignment_lag_sec")
    quality = str(alignment.get("raw_alignment_quality") or "missing")
    bits = [f"<b>Raw match:</b> {html.escape(quality)}"]
    if isinstance(corr, (int, float)):
        bits.append(f"<b>Corr:</b> {float(corr):.6f}")
    if isinstance(lag_sec, (int, float)):
        bits.append(f"<b>Lag:</b> {float(lag_sec):.3f}s")
    bits.append(f"<b>C3D:</b> {html.escape(str(alignment.get('raw_label_match_c3d') or 'missing'))}")
    bits.append(f"<b>TSV:</b> {html.escape(str(alignment.get('raw_label_match_tsv') or 'missing'))}")
    return (
        '<div style="font-size:14px; font-weight:700; color:#154463;">Raw evidence</div>'
        f'<div style="margin-top:6px; line-height:1.7;">{" &nbsp;&nbsp; ".join(bits)}</div>'
    )


def _queue_summary_rich_text(mapping: Dict[str, Any], matches: Sequence[Dict[str, Any]]) -> str:
    total = len(matches)
    user_accept = sum(1 for match in matches if _review_status_key(match) == "user_accept")
    user_reject = sum(1 for match in matches if _review_status_key(match) == "user_reject")
    auto_accept = sum(1 for match in matches if _review_status_key(match) == "auto_accept")
    auto_reject = sum(1 for match in matches if _review_status_key(match) == "auto_reject")
    return (
        '<div style="line-height:1.8;">'
        + " ".join(
            [
                _html_badge(f"Total {total}", "#DCEEFF", "#154463"),
                _html_badge(f"Auto accept {auto_accept}", "#D7F0DD", "#123A20"),
                _html_badge(f"Auto reject {auto_reject}", "#F6D9D9", "#5B1F1F"),
                _html_badge(f"User accept {user_accept}", "#1E6B2D", "#FFFFFF"),
                _html_badge(f"User reject {user_reject}", "#8B1E1E", "#FFFFFF"),
            ]
        )
        + "</div>"
    )


def _queue_code_legend_text() -> str:
    return (
        "Queue codes:\n"
        "AA = auto-accepted\n"
        "AR = auto-rejected\n"
        "UA = user-accepted\n"
        "UR = user-rejected\n"
        "RV = review/manual state\n"
        "M = manual create/reassignment involved\n"
        "[C] = certain, [U] = uncertain, [P] = possible\n"
        "S: = dedicated sync quality\n"
        "R: = raw-alignment quality\n"
        "P!: = non-sync probe count"
    )


def _review_item_text(match: Dict[str, Any]) -> str:
    status = _review_status_label(match)
    quality = (match.get("alignment") or {}).get("dedicated_sync_quality")
    raw_q = (match.get("alignment") or {}).get("raw_alignment_quality")
    certainty = str(match.get("certainty") or "?")
    diag = _otb4_probe_sync_diagnostics(match)
    probe_warn = int(diag.get("non_sync_probe_count") or 0)
    manual = " M" if (
        match.get("manual_selection")
        or ((match.get("alignment") or {}).get("manual_selection"))
        or ((match.get("alignment") or {}).get("manual_reassignment"))
    ) else ""
    status_short = {
        "AUTO-ACCEPT": "AA",
        "AUTO-REJECT": "AR",
        "USER-ACCEPT": "UA",
        "USER-REJECT": "UR",
        "REVIEW": "RV",
    }.get(status, status[:2])
    certainty_short = {
        "certain": "C",
        "uncertain": "U",
        "possible": "P",
    }.get(certainty.lower(), certainty[:1].upper() if certainty else "?")
    primary_name = (
        Path(str((match.get("otb4") or {}).get("path") or "")).name
        or Path(str((match.get("c3d") or {}).get("path") or "")).name
        or "missing"
    )
    text = (
        f"{match['match_id']:03d} {status_short}{manual} [{certainty_short}] "
        f"S:{quality or '-'} R:{raw_q or '-'} P!:{probe_warn} | {primary_name}"
    )
    if match.get("tsv"):
        text += f" | {Path(match['tsv']['path']).name}"
    else:
        text += " | TSV:-"
    return text


def _save_mapping_bundle(mapping_path: Path, mapping: Dict[str, Any], *, write_review_outputs: bool = True) -> None:
    saved_at = mapping.get("saved_at") or _format_file_stamp()
    mapping["saved_at"] = saved_at
    export_root = Path(mapping.get("export_root") or mapping_path.parent)
    for match in mapping.get("matches", []):
        _attach_export_plan(match, export_root, saved_at)
    _write_repair_jsons(export_root, mapping)
    mapping_path.write_text(json.dumps(mapping, indent=2, ensure_ascii=False), encoding="utf-8")
    if write_review_outputs:
        _write_review_outputs(export_root, mapping, saved_at)
    mapping_path.write_text(json.dumps(mapping, indent=2, ensure_ascii=False), encoding="utf-8")


def _prefetch_match_plot_data(match: Dict[str, Any]) -> None:
    """Warm the cheap, reusable per-match state (repair, review defaults,
    probe diagnostics) for the next couple of rows in the background.

    Deliberately does *not* also pre-load full plot series data here (via
    _load_series_for_spec): that costs roughly 2s/match of real CPU work
    on the background thread pool, which was found to visibly stutter the
    UI during review even though it never blocks the main thread directly.
    Actual series loading happens on demand in PlotRowWidget.refresh() when
    a match is opened.
    """
    try:
        _ensure_otb4_repair_applied(match, [])
    except Exception:
        pass
    try:
        _apply_review_defaults(match)
    except Exception:
        pass
    try:
        _otb4_probe_sync_diagnostics(match)
    except Exception:
        pass


def _save_mapping_bundle_snapshot(mapping_path: Path, mapping_snapshot: Dict[str, Any], *, write_review_outputs: bool) -> None:
    _save_mapping_bundle(mapping_path, mapping_snapshot, write_review_outputs=write_review_outputs)


def _review_progress(mapping: Dict[str, Any]) -> Tuple[int, int]:
    matches = mapping.get("matches", [])
    reviewed = sum(1 for match in matches if (match.get("review") or {}).get("reviewed"))
    return reviewed, len(matches)


def _refresh_mapping_summary(mapping: Dict[str, Any]) -> None:
    matches = mapping.get("matches", []) or []
    summary = mapping.setdefault("summary", {})
    summary["pair_count"] = len(matches)
    summary["certain_pair_count"] = sum(1 for match in matches if match.get("certainty") == "certain")
    summary["certain_triplet_count"] = sum(1 for match in matches if match.get("tsv"))
    summary["final_accept_count"] = sum(1 for match in matches if (match.get("review") or {}).get("final_accept"))
    source_records = mapping.get("source_records", {}) or {}
    used_paths = {
        key: {
            _match_source_path(match, key)
            for match in matches
            if _match_source_path(match, key)
        }
        for key in ("otb4", "c3d", "tsv")
    }
    summary["unmatched_c3d_count"] = sum(
        1 for rec in (source_records.get("c3d", []) or [])
        if str(rec.get("path") or "") and str(rec.get("path") or "") not in used_paths["c3d"]
    )
    summary["unmatched_otb4_count"] = sum(
        1 for rec in (source_records.get("otb4", []) or [])
        if str(rec.get("path") or "") and str(rec.get("path") or "") not in used_paths["otb4"]
    )
    summary["unmatched_tsv_count"] = sum(
        1 for rec in (source_records.get("tsv", []) or [])
        if str(rec.get("path") or "") and str(rec.get("path") or "") not in used_paths["tsv"]
    )


def _match_source_path(match: Dict[str, Any], key: str) -> str:
    return str(((match.get(key) or {}).get("path")) or "")


def _duplicate_source_assignments(matches: Sequence[Dict[str, Any]]) -> Dict[str, Dict[str, List[int]]]:
    dupes: Dict[str, Dict[str, List[int]]] = {"otb4": {}, "c3d": {}, "tsv": {}}
    for key in ("otb4", "c3d", "tsv"):
        seen: Dict[str, List[int]] = {}
        for idx, match in enumerate(matches):
            path = _match_source_path(match, key)
            if not path:
                continue
            seen.setdefault(path, []).append(idx)
        dupes[key] = {path: rows for path, rows in seen.items() if len(rows) > 1}
    return dupes


def _duplicate_assignment_lines(matches: Sequence[Dict[str, Any]]) -> List[str]:
    lines: List[str] = []
    dupes = _duplicate_source_assignments(matches)
    for key, mapping in dupes.items():
        for path, rows in mapping.items():
            refs = ", ".join(f"{int(matches[row].get('match_id') or row + 1):03d}" for row in rows)
            lines.append(f"{key}: {Path(path).name} used by matches {refs}")
    return lines


def _ensure_unique_source_assignments(matches: Sequence[Dict[str, Any]]) -> None:
    problem_lines = _duplicate_assignment_lines(matches)
    if problem_lines:
        raise RuntimeError("Duplicate source assignments detected:\n" + "\n".join(problem_lines))


_PICKER_CANCEL = object()
_PICKER_KEEP_CURRENT = object()
_PICKER_CLEAR = object()


class PlotRowWidget:
    def __init__(self, viewer, title: str, series_specs: Optional[List[Dict[str, Any]]] = None, row_role: str = "custom", *, auto_generated: bool = False, context: Optional[Dict[str, Any]] = None):
        from PySide6 import QtWidgets
        import pyqtgraph as pg

        self.viewer = viewer
        self.title = title
        self.row_role = row_role
        self.auto_generated = bool(auto_generated)
        self.context = dict(context or {})
        self.series_specs: List[Dict[str, Any]] = list(series_specs or [])
        self.match: Optional[Dict[str, Any]] = None
        self.widget = QtWidgets.QFrame()
        self.widget.setFrameShape(QtWidgets.QFrame.Shape.StyledPanel)
        self.widget.setSizePolicy(QtWidgets.QSizePolicy.Policy.Preferred, QtWidgets.QSizePolicy.Policy.Maximum)
        layout = QtWidgets.QVBoxLayout(self.widget)
        top = QtWidgets.QHBoxLayout()
        self.label = QtWidgets.QLabel(title)
        self.label.setWordWrap(True)
        top.addWidget(self.label, 1)
        self.add_row_btn = QtWidgets.QPushButton("+ Row")
        self.add_overlay_btn = QtWidgets.QPushButton("+ Overlay")
        top.addWidget(self.add_row_btn)
        top.addWidget(self.add_overlay_btn)
        layout.addLayout(top)
        self.plot = pg.PlotWidget()
        self.plot.showGrid(x=True, y=True, alpha=0.25)
        self.plot.setMinimumHeight(250)
        layout.addWidget(self.plot)
        self.status = QtWidgets.QLabel("")
        self.status.setWordWrap(True)
        self.status.setStyleSheet("QLabel { color: #404040; padding-top: 2px; font-size: 11px; line-height: 1.05em; }")
        layout.addWidget(self.status)
        self.add_row_btn.clicked.connect(self._request_new_row)
        self.add_overlay_btn.clicked.connect(self._request_overlay)

    def _request_new_row(self):
        if self.viewer is not None:
            self.viewer.add_plot_row()

    def _request_overlay(self):
        if self.viewer is not None:
            self.viewer.add_series_to_row(self)

    def set_match(self, match: Dict[str, Any]) -> None:
        self.match = match
        if self.row_role == "sync":
            self.series_specs = _sync_series_specs(match)
        elif self.row_role == "raw":
            self.series_specs = _raw_series_specs(match)
        self.refresh()

    def refresh(self) -> None:
        from PySide6 import QtCore
        import pyqtgraph as pg

        self.plot.clear()
        self.plot.addLegend()
        if self.match is None:
            self.label.setText(self.title)
            self.status.setText("No match selected.")
            return

        if self.row_role == "sync":
            text = (
                "Dedicated sync overlay | channel 1 (1_TTL) top, 2 (2_Sync) middle, 3 (3_Sync_50ms) bottom "
                "| circles: filled green=confirmed, filled amber=partial, open white=missing (unmatched) "
                "-- row at y=-0.25 is OTB4-internal probe/control diagnosis, row at y=-0.5 is the channel-3 "
                "(3_Sync_50ms) OTB4<->C3D cross-machine sync diagnosis | green bars=start/end"
            )
            if _repair_gap_regions(self.match):
                text += " | pink/amber bands = OTB4 repaired or detected gap zones"
            self.label.setText(text)
        elif self.row_role == "raw":
            text = "Matched raw overlay | green bars=start/end of common matched time window"
            if _repair_gap_regions(self.match):
                text += " | pink/amber bands = OTB4 repaired or detected gap zones"
            self.label.setText(text)
        elif self.row_role == "probe_detail":
            device = str(self.context.get("device") or "")
            self.label.setText(
                f"Probe sync detail | {device} buffer + ramp | dotted expected lines: green=detected, red=missing | green bars=start/end"
            )
        else:
            series_names = ", ".join(_series_label(spec) for spec in self.series_specs) if self.series_specs else "No channels selected"
            self.label.setText(f"{self.title} | {series_names}")

        self.status.setText("")
        x_min: Optional[float] = None
        x_max: Optional[float] = None
        y_max: Optional[float] = None
        missing: List[str] = []
        plotted = 0
        for spec in self.series_specs:
            try:
                t, y = _load_series_for_spec(self.match, spec)
            except Exception as exc:
                missing.append(f"{_series_label(spec)} unavailable: {exc}")
                continue
            if len(t) == 0:
                missing.append(f"{_series_label(spec)} unavailable: empty data")
                continue
            if self.row_role in {"raw", "probe_detail"}:
                y = _normalize_unit_interval(y)
            color = _overlay_series_color(spec, plotted, len(self.series_specs))
            pen = pg.mkPen(color=color, width=1.4)
            # Channel 1/2/3 traces can end up close together or overlapping
            # in the banded sync plot (row_role == "sync") -- give each
            # channel number a distinct line style so they stay
            # distinguishable even where color alone wouldn't be enough.
            channel_num = spec.get("sync_channel_num")
            if channel_num == 1:
                pen.setStyle(QtCore.Qt.PenStyle.DotLine)
            elif channel_num == 2:
                pen.setStyle(QtCore.Qt.PenStyle.CustomDashLine)
                pen.setDashPattern([3, 3])
            elif channel_num == 3:
                pen.setStyle(QtCore.Qt.PenStyle.CustomDashLine)
                pen.setDashPattern([10, 6])
            self.plot.plot(t, y, pen=pen, name=_series_label(spec))
            plotted += 1
            lo = float(np.nanmin(t))
            hi = float(np.nanmax(t))
            x_min = lo if x_min is None else min(x_min, lo)
            x_max = hi if x_max is None else max(x_max, hi)
            y_hi = float(np.nanmax(y))
            y_max = y_hi if y_max is None else max(y_max, y_hi)

        footer_lines: List[str] = []
        if plotted:
            self.plot.setLabel("bottom", "Aligned time", units="s")
            y_label, y_units = _y_axis_label(self.row_role, self.series_specs)
            self.plot.setLabel("left", y_label, units=y_units)
            self.plot.setMinimumHeight(320 if self.row_role == "probe_detail" else 280)
            if x_min is not None and x_max is not None and np.isfinite(x_min) and np.isfinite(x_max) and x_max > x_min:
                self.plot.setXRange(x_min, x_max, padding=0.03)
            else:
                self.plot.autoRange()
            inner_merge = ((self.match.get("alignment") or {}).get("inner_merge") or {})
            merge_start = inner_merge.get("inner_merge_start_sec")
            merge_end = inner_merge.get("inner_merge_end_sec")
            if isinstance(merge_start, (int, float)) and isinstance(merge_end, (int, float)) and merge_end > merge_start:
                region = pg.LinearRegionItem(values=(merge_start, merge_end), movable=False, brush=(190, 240, 190, 28))
                region.setZValue(-20)
                for line in region.lines:
                    line.setPen(pg.mkPen(color="#9FD89F", width=1.0, style=QtCore.Qt.PenStyle.DashLine))
                self.plot.addItem(region)
                for boundary in (float(merge_start), float(merge_end)):
                    boundary_line = pg.InfiniteLine(
                        pos=boundary,
                        angle=90,
                        movable=False,
                        pen=pg.mkPen(color="#1F7A4D", width=3.0),
                    )
                    boundary_line.setZValue(-5)
                    self.plot.addItem(boundary_line)
            gap_brush, gap_line = _repair_gap_style(self.match)
            for gap_start, gap_end in _repair_gap_regions(self.match):
                region = pg.LinearRegionItem(values=(gap_start, gap_end), movable=False, brush=gap_brush)
                region.setZValue(-19)
                for line in region.lines:
                    line.setPen(pg.mkPen(color=gap_line, width=1.0, style=QtCore.Qt.PenStyle.DashLine))
                self.plot.addItem(region)
            if self.row_role == "probe_detail":
                marker_colors = {
                    "confirmed": "#1F7A4D",
                    "partial": "#A06A00",
                    "missing": "#B42318",
                }
                shift = float(_match_plot_shifts(self.match).get("otb4", 0.0))
                device = str(self.context.get("device") or "")
                for marker in _expected_sync_markers(self.match, device=device):
                    status = str(marker.get("status") or "missing")
                    line = pg.InfiniteLine(
                        pos=float(marker.get("time_sec") or 0.0) + shift,
                        angle=90,
                        movable=False,
                        pen=pg.mkPen(
                            color=marker_colors.get(status, "#7D8597"),
                            width=2.0,
                            style=QtCore.Qt.PenStyle.DotLine,
                        ),
                    )
                    line.setZValue(-6)
                    self.plot.addItem(line)
            elif self.row_role == "sync":
                # Matched-pulse status as filled circles at fixed negative y
                # rows instead of full-height vertical lines: green=confirmed,
                # amber=partial, open white circle=missing (unmatched). Two
                # independent rows: the OTB4-internal probe/control-vs-AUX2
                # diagnosis (_expected_sync_markers) at -0.25, and the
                # channel-3 (3_Sync_50ms) OTB4<->C3D cross-machine sync
                # diagnosis (_channel3_match_markers) at -0.5.
                shift = float(_match_plot_shifts(self.match).get("otb4", 0.0))
                fill_colors = {"confirmed": "#1F7A4D", "partial": "#D9A400"}

                def _add_marker_row(markers: List[Dict[str, Any]], y_value: float) -> None:
                    xs: List[float] = []
                    brushes = []
                    pens = []
                    for marker in markers:
                        status = str(marker.get("status") or "missing")
                        xs.append(float(marker.get("time_sec") or 0.0) + shift)
                        if status in fill_colors:
                            color = fill_colors[status]
                            brushes.append(pg.mkBrush(color))
                            pens.append(pg.mkPen(color, width=1.5))
                        else:
                            brushes.append(pg.mkBrush("#FFFFFF"))
                            pens.append(pg.mkPen("#7D8597", width=1.5))
                    if not xs:
                        return
                    scatter = pg.ScatterPlotItem(
                        x=xs,
                        y=[y_value] * len(xs),
                        size=10,
                        symbol="o",
                        brush=brushes,
                        pen=pens,
                    )
                    scatter.setZValue(-4)
                    self.plot.addItem(scatter)

                _add_marker_row(_expected_sync_markers(self.match), _SYNC_CHANNEL_MARKER_Y)
                _add_marker_row(_channel3_match_markers(self.match), _SYNC_CHANNEL3_MARKER_Y)
            footer_lines.append(_plot_source_files_text(self.match, self.row_role, self.series_specs))
            footer_lines.append(_plot_decision_context_text(self.match, self.row_role, self.series_specs))
        else:
            footer_lines.append("No channels plotted.")

        if missing:
            footer_lines.append("Unavailable: " + " | ".join(missing))
        self.status.setText("\n".join(line for line in footer_lines if line))
        base_height = 365 if self.row_role == "probe_detail" else 330
        extra_lines = max(0, self.status.text().count("\n"))
        self.widget.setMinimumHeight(base_height + extra_lines * 16)
        self.widget.updateGeometry()


